import re

_VERSION_RE = re.compile(r'([0-9]+(?:\.[0-9]+)*)(?:-([0-9A-Za-z]+))?')


def compare_versions(a: str, b: str) -> int:
    def _part_key(part: str):
        part = part.lstrip('0')
        return (len(part), part) if part else (0, '')

    def _parse(v: str):
        if not isinstance(v, str):
            raise ValueError('version must be a string')
        m = _VERSION_RE.fullmatch(v)
        if m is None:
            raise ValueError('invalid version: %r' % (v,))
        keys = [_part_key(p) for p in m.group(1).split('.')]
        return keys, m.group(2)

    a_keys, a_tag = _parse(a)
    b_keys, b_tag = _parse(b)

    n = max(len(a_keys), len(b_keys))
    zero = (0, '')
    a_keys.extend([zero] * (n - len(a_keys)))
    b_keys.extend([zero] * (n - len(b_keys)))

    if a_keys < b_keys:
        return -1
    if a_keys > b_keys:
        return 1

    if a_tag is None and b_tag is None:
        return 0
    if a_tag is None:
        return 1
    if b_tag is None:
        return -1
    if a_tag < b_tag:
        return -1
    if a_tag > b_tag:
        return 1
    return 0
