from typing import List, Tuple, Union

Number = Union[int, float]


def _tokenize(s: str) -> List[Tuple[str, object]]:
    tokens: List[Tuple[str, object]] = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            if j < n and s[j] == '.':
                k = j + 1
                if k >= n or not ('0' <= s[k] <= '9'):
                    raise ValueError("malformed decimal literal")
                while k < n and '0' <= s[k] <= '9':
                    k += 1
                tokens.append(('num', float(s[i:k])))
                i = k
            else:
                tokens.append(('num', int(s[i:j])))
                i = j
            continue
        if c in '+-*/^()':
            tokens.append(('op', c))
            i += 1
            continue
        raise ValueError("unknown character: %r" % (c,))
    return tokens


class _Parser:
    def __init__(self, tokens: List[Tuple[str, object]]) -> None:
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Tuple[str, object]:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return ('eof', None)

    def accept(self, ch: str) -> bool:
        kind, value = self.peek()
        if kind == 'op' and value == ch:
            self.pos += 1
            return True
        return False

    def parse(self) -> Number:
        value = self.expression()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected trailing token")
        return value

    def expression(self) -> Number:
        value = self.term()
        while True:
            if self.accept('+'):
                value = value + self.term()
            elif self.accept('-'):
                value = value - self.term()
            else:
                return value

    def term(self) -> Number:
        value = self.unary()
        while True:
            if self.accept('*'):
                value = value * self.unary()
            elif self.accept('/'):
                rhs = self.unary()
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
            else:
                return value

    def unary(self) -> Number:
        if self.accept('-'):
            return -self.unary()
        return self.power()

    def power(self) -> Number:
        base = self.atom()
        if self.accept('^'):
            exponent = self.unary()
            return base ** exponent
        return base

    def atom(self) -> Number:
        kind, value = self.peek()
        if kind == 'num':
            self.pos += 1
            return value
        if kind == 'op' and value == '(':
            self.pos += 1
            inner = self.expression()
            if not self.accept(')'):
                raise ValueError("unbalanced parentheses")
            return inner
        raise ValueError("expected a number or '('")


def evaluate(expr: str) -> Number:
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    try:
        return _Parser(tokens).parse()
    except ZeroDivisionError:
        raise ValueError("division by zero")
