from typing import Optional


def earliest_slot(
    busy: list[tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest free start time within [start, end), or None."""
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, even if the window cannot fit the meeting.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("each busy interval must have begin < finish")

    candidate = start
    if candidate + duration > end:
        return None

    # sorted() creates a new list, leaving the input unchanged.
    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        # Equality is allowed because the intervals are half-open.
        if candidate + duration <= begin:
            return candidate

        # This interval overlaps the proposed meeting.
        candidate = finish
        if candidate + duration > end:
            return None

    return candidate
