def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return a number (int or float).

    Supports integer and decimal literals, the binary operators + - * / ^
    (^ is right-associative and highest precedence; + - lowest), parentheses,
    and unary minus (which binds less tightly than ^ but may start an exponent).
    Whitespace between tokens is ignored. Raises ValueError for malformed
    input or division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    DIGITS = "0123456789"

    # ---------------- Tokenizer ----------------
    tokens = []  # list of (kind, value); kinds: NUM, OP, LPAREN, RPAREN
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in DIGITS:
            j = i
            while j < n and expr[j] in DIGITS:
                j += 1
            if j + 1 < n and expr[j] == "." and expr[j + 1] in DIGITS:
                j += 1
                while j < n and expr[j] in DIGITS:
                    j += 1
                tokens.append(("NUM", float(expr[i:j])))
            else:
                tokens.append(("NUM", int(expr[i:j])))
            i = j
            continue
        if c == "(":
            tokens.append(("LPAREN", None))
            i += 1
            continue
        if c == ")":
            tokens.append(("RPAREN", None))
            i += 1
            continue
        if c in "+-*/^":
            tokens.append(("OP", c))
            i += 1
            continue
        raise ValueError("unexpected character: %r" % (c,))

    # ---------------- Recursive-descent parser ----------------
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():  # handles + and - (lowest precedence, left-assoc)
        value = parse_term()
        while True:
            kind, op = peek()
            if kind == "OP" and op in "+-":
                advance()
                rhs = parse_term()
                value = value + rhs if op == "+" else value - rhs
            else:
                return value

    def parse_term():  # handles * and / (left-assoc)
        value = parse_unary()
        while True:
            kind, op = peek()
            if kind == "OP" and op in "*/":
                advance()
                rhs = parse_unary()
                if op == "*":
                    value = value * rhs
                else:
                    try:
                        value = value / rhs
                    except ZeroDivisionError:
                        raise ValueError("division by zero") from None
            else:
                return value

    def parse_unary():  # unary minus binds less tightly than ^
        kind, op = peek()
        if kind == "OP" and op == "-":
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():  # ^ is right-associative and highest precedence
        base = parse_atom()
        kind, op = peek()
        if kind == "OP" and op == "^":
            advance()
            exponent = parse_unary()  # exponent may itself start with unary minus
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        return base

    def parse_atom():  # number or parenthesized expression
        kind, val = peek()
        if kind == "NUM":
            advance()
            return val
        if kind == "LPAREN":
            advance()
            value = parse_expr()
            k2, _ = peek()
            if k2 != "RPAREN":
                raise ValueError("unbalanced parentheses: expected ')'")
            advance()
            return value
        if kind is None:
            raise ValueError("unexpected end of expression")
        raise ValueError("expected a number or '('")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token after end of expression")
    return result
