import re
from bisect import bisect_right
from calendar import monthrange
from datetime import datetime, timedelta


_ITEM_RE = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_AFTER_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")


def _capped_decimal(text: str, cap: int) -> int:
    """Return min(int(text), cap), without converting arbitrarily large integers."""
    text = text.lstrip("0") or "0"
    limit = str(cap)
    if len(text) > len(limit):
        return cap
    if len(text) == len(limit) and text >= limit:
        return cap
    return int(text)


def _parse_field(field: str, minimum: int, maximum: int) -> set:
    values = set()

    def parse_value(text: str) -> int:
        value = _capped_decimal(text, maximum + 1)
        if not minimum <= value <= maximum:
            raise ValueError("Cron value outside its field's range")
        return value

    for item in field.split(","):
        match = _ITEM_RE.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item")

        base, step_text = match.groups()
        if step_text is None:
            step = 1
        else:
            # Steps larger than the field's span all select only the start.
            step = _capped_decimal(step_text, maximum - minimum + 1)
            if step == 0:
                raise ValueError("Cron step must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            left, right = base.split("-")
            start, end = parse_value(left), parse_value(right)
            if start > end:
                raise ValueError("Cron range must be ascending")
        else:
            start = parse_value(base)
            end = maximum if step_text is not None else start

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    """Return the next firing, including the five-year calendar boundary.

    If the boundary falls on February 29 in a non-leap year, use February 28
    at the same time. Only a literal '*' makes a day field unrestricted.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must contain exactly five fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, bounds)
    ]

    if _AFTER_RE.fullmatch(after) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    start = datetime(
        int(after[0:4]),
        int(after[5:7]),
        int(after[8:10]),
        int(after[11:13]),
        int(after[14:16]),
    )

    if start.year + 5 <= 9999:
        end_year = start.year + 5
        end_day = min(start.day, monthrange(end_year, start.month)[1])
        deadline = start.replace(year=end_year, day=end_day)
    else:
        # No later year is representable in the required four-digit format.
        deadline = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    current_day = start.date()
    final_day = deadline.date()
    start_minute = start.hour * 60 + start.minute

    while current_day <= final_day:
        if current_day.month in months:
            dom_matches = current_day.day in month_days
            dow_matches = (current_day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect_right(times, start_minute)
                    if current_day == start.date()
                    else 0
                )
                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(
                        current_day.year,
                        current_day.month,
                        current_day.day,
                        hour,
                        minute,
                    )
                    if candidate <= deadline:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {candidate.hour:02d}:"
                            f"{candidate.minute:02d}"
                        )

        if current_day == final_day:
            break
        current_day += timedelta(days=1)

    raise ValueError("No matching time exists within five years after after")
