from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    # Words are runs of characters delimited by U+0020 only.
    words = [word for word in text.split(" ") if word]

    lines: List[str] = []
    current = ""

    for word in words:
        if len(word) <= width:
            if current == "":
                current = word
            elif len(current) + 1 + len(word) <= width:
                current = current + " " + word
            else:
                lines.append(current)
                current = word
        else:
            # A word longer than width always starts on a new line.
            if current != "":
                lines.append(current)
                current = ""
            # Split into consecutive pieces of exactly `width` characters;
            # the final piece may be shorter and can still be extended.
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current = pieces[-1]

    if current != "":
        lines.append(current)

    return lines
