def _parse(pattern: str) -> List[Tuple]:
    """Turn a glob pattern into a list of tokens.

    Token kinds:
        ('lit', ch)              -- a literal character
        ('any',)                 -- '?'  : one char that is not '/'
        ('star',)                -- '*'  : any run of chars without '/'
        ('gstar',)               -- '**' : any run of chars, '/' included
        ('set', negated, items)  -- '[...]'; items are ('c', ch) or ('r', lo, hi)
    """
    tokens: List[Tuple] = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('gstar',))
                i += 2
            else:
                tokens.append(('star',))
                i += 1
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '[':
            i += 1
            negated = False
            if i < n and pattern[i] == '!':
                negated = True
                i += 1
            items = []
            first = True
            closed = False
            while i < n:
                if pattern[i] == ']' and not first:
                    closed = True
                    i += 1
                    break
                if pattern[i] == '\\':
                    if i + 1 >= n:
                        raise ValueError("pattern ends with a backslash")
                    ch = pattern[i + 1]
                    i += 2
                else:
                    ch = pattern[i]
                    i += 1
                first = False
                if i < n and pattern[i] == '-' and i + 1 < n and pattern[i + 1] != ']':
