                    if pattern[i] == '\\':
                        if i + 1 >= n:
                            raise ValueError("pattern ends with a backslash")
                        ch2 = pattern[i + 1]
                        i += 2
                    else:
                        ch2 = pattern[i]
                        i += 1
                    items.append(('r', ch, ch2))
                else:
                    items.append(('c', ch))
            if not closed:
                raise ValueError("unterminated character set in pattern")
            tokens.append(('set', negated, tuple(items)))
        else:
            tokens.append(('lit', c))
            i += 1
    return tokens


def _set_contains(token: Tuple, ch: str) -> bool:
    negated = token[1]
    hit = False
    for item in token[2]:
        if item[0] == 'c':
            if ch == item[1]:
                hit = True
                break
        else:
            if item[1] <= ch <= item[2]:
                hit = True
                break
    return hit != negated


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of *name* matches the glob *pattern*."""
    tokens = _parse(pattern)
    nt = len(tokens)
    m = len(name)

    seen = set()
    stack = [(0, 0)]
    while stack:
        ti, si = stack.pop()
        if (ti, si) in seen:
            continue
        seen.add((ti, si))

        if ti == nt:
            if si == m:
                return True
            continue

        token = tokens[ti]
        kind = token[0]

        if kind == 'lit':
            if si < m and name[si] == token[1]:
                stack.append((ti + 1, si + 1))
        elif kind == 'any':
            if si < m and name[si] != '/':
                stack.append((ti + 1, si + 1))
        elif kind == 'set':
            if si < m and _set_contains(token, name[si]):
                stack.append((ti + 1, si + 1))
        elif kind == 'star':
            j = si
            while True:
                stack.append((ti + 1, j))
                if j >= m or name[j] == '/':
                    break
                j += 1
        else:  # 'gstar'
            for j in range(si, m + 1):
                stack.append((ti + 1, j))

    return False
