def flatten(nested, depth=None):
    """Flatten nested lists by at most `depth` levels.

    depth=None  -> fully recursive flatten
    depth=0     -> shallow copy of the top-level list
    Only items whose type is exactly `list` are expanded.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be None or a non-negative integer")

    if depth == 0:
        return list(nested)

    result = []
    inner = None if depth is None else depth - 1
    for item in nested:
        if type(item) is list:
            result.extend(flatten(item, inner))
        else:
            result.append(item)
    return result
