def _is_uint(text):
    """True only for a non-empty string of plain ASCII digits."""
    if not text:
        return False
    for ch in text:
        if ch < "0" or ch > "9":
            return False
    return True


def _parse_field(field, lo, hi):
    """Expand one cron field into the set of integers it matches."""
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item in field %r" % (field,))

        has_step = "/" in item
        if has_step:
            base, _, step_text = item.partition("/")
            if "/" in step_text or not _is_uint(step_text):
                raise ValueError("malformed item %r" % (item,))
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1 in %r" % (item,))
        else:
            base, step = item, 1

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            bounds = base.split("-")
            if len(bounds) != 2 or not _is_uint(bounds[0]) or not _is_uint(bounds[1]):
                raise ValueError("malformed item %r" % (item,))
            start, end = int(bounds[0]), int(bounds[1])
            if start > end:
                raise ValueError("reversed range in %r" % (item,))
        else:
            if not _is_uint(base):
                raise ValueError("malformed item %r" % (item,))
            start = int(base)
            # "a" alone means just a; "a/n" means a, a+n, ... up to the maximum.
            end = hi if has_step else start

        if start < lo or start > hi or end < lo or end > hi:
            raise ValueError("value out of range in %r" % (item,))
        values.update(range(start, end + 1, step))
    return values


def next_cron(expr: str, after: str) -> str:
    if not isinstance(expr, str):
        raise ValueError("expr must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % (len(fields),))

    minutes = _parse_field(fields[0], *_MINUTE)
    hours = _parse_field(fields[1], *_HOUR)
    dom = _parse_field(fields[2], *_DOM)
    months = _parse_field(fields[3], *_MONTH)
    dow = _parse_field(fields[4], *_DOW)

    # "Restricted" means the field is not literally "*".
    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    if not isinstance(after, str):
        raise ValueError("after must be a string")
    try:
        start = datetime.strptime(after.strip(), "%Y-%m-%d %H:%M")
    except ValueError:
        raise ValueError("after must be 'YYYY-MM-DD HH:MM'")

    try:
        deadline = start.replace(year=start.year + 5)
    except ValueError:  # 29 February -> 5 years later has no such day
        deadline = start.replace(year=start.year + 5, day=28)

    hours_sorted = sorted(hours)
    minutes_sorted = sorted(minutes)

    day = start.date()
    last_day = deadline.date()
    while day <= last_day:
        if day.month in months:
            dom_ok = day.day in dom
            dow_ok = ((day.weekday() + 1) % 7) in dow  # Python Monday=0 -> cron Sunday=0
            if dom_star and dow_star:
                day_ok = True
            elif dom_star:
                day_ok = dow_ok
            elif dow_star:
