"""Path-aware glob matching (Python 3.9, standard library only)."""


def _parse_class(pattern: str, i: int, n: int):
    """Parse a bracket expression; ``pattern[i] == '['``.

    Returns ``((negate, items), next_index)`` where ``items`` holds
    ``('c', ch)`` single characters and ``('r', lo, hi)`` ranges.
    Raises ValueError for an unterminated class or a trailing backslash.
    """
    i += 1  # step over '['
    negate = False
    if i < n and pattern[i] == "!":
        negate = True
        i += 1

    items = []
    first = True  # True right after '[' or '[!', where ']' is literal
    while True:
        if i >= n:
            raise ValueError("unterminated character class in pattern")
        c = pattern[i]
        if c == "]" and not first:
            i += 1
            break
        first = False
        i += 1
        if c == "\\":
            if i >= n:
                raise ValueError("trailing backslash in pattern")
            items.append(("c", pattern[i]))
            i += 1
            continue
        # a '-' starts a range only if something other than the closing
        # ']' follows it; otherwise it is a literal '-'
        if i < n and pattern[i] == "-":
            j = i + 1
            if j < n and pattern[j] != "]":
                if pattern[j] == "\\":
                    if j + 1 >= n:
                        raise ValueError("trailing backslash in pattern")
                    hi = pattern[j + 1]
                    i = j + 2
                else:
                    hi = pattern[j]
                    i = j + 1
                items.append(("r", c, hi))
                continue
        items.append(("c", c))
    return (negate, items), i


def _tokenize(pattern: str):
    """Turn the pattern into tokens, raising ValueError on bad syntax."""
    tokens = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash in pattern")
            tokens.append(("lit", pattern[i + 1]))
            i += 2
        elif c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                tokens.append(("dstar",))
                i += 2
            else:
                tokens.append(("star",))
                i += 1
        elif c == "?":
            tokens.append(("q",))
            i += 1
        elif c == "[":
            (negate, items), i = _parse_class(pattern, i, n)
            tokens.append(("cls", negate, items))
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def _class_matches(negate: bool, items, ch: str) -> bool:
    hit = False
    for item in items:
        if item[0] == "c":
            if item[1] == ch:
                hit = True
                break
        else:
            if item[1] <= ch <= item[2]:
                hit = True
                break
    return hit != negate


def glob_match(pattern: str, name: str) -> bool:
    """Test whether the whole of ``name`` matches the glob ``pattern``.

    ``*`` matches any run without ``/``, ``**`` any run (including ``/``),
    ``?`` a single non-``/`` character, ``[...]`` a set/range (``!``
    negates, a leading ``]`` is literal), ``\\`` escapes the next
    character.  An unterminated ``[`` or a trailing ``\\`` raises
    ValueError.
    """
    tokens = _tokenize(pattern)
    tcount = len(tokens)
    n = len(name)

    # row[ni] == "tokens[ti:] matches name[ni:]"
    nxt = [False] * (n + 1)
    nxt[n] = True  # empty pattern matches empty suffix
    cur = [False] * (n + 1)

    for ti in range(tcount - 1, -1, -1):
        tok = tokens[ti]
        kind = tok[0]
        if kind == "star":
            cur[n] = nxt[n]
            for ni in range(n - 1, -1, -1):
                cur[ni] = nxt[ni] or (name[ni] != "/" and cur[ni + 1])
        elif kind == "dstar":
            cur[n] = nxt[n]
            for ni in range(n - 1, -1, -1):
                cur[ni] = nxt[ni] or cur[ni + 1]
        else:
            cur[n] = False
            if kind == "lit":
                ch = tok[1]
                for ni in range(n - 1, -1, -1):
                    cur[ni] = name[ni] == ch and nxt[ni + 1]
            elif kind == "q":
                for ni in range(n - 1, -1, -1):
                    cur[ni] = name[ni] != "/" and nxt[ni + 1]
            else:
                negate, items = tok[1], tok[2]
                for ni in range(n - 1, -1, -1):
                    cur[ni] = _class_matches(negate, items, name[ni]) and nxt[ni + 1]
        nxt, cur = cur, nxt

    return nxt[0]
