```python
"""Add a whole number of calendar months to an ISO date string."""

_DAYS_IN_MONTH = (31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)


def _is_leap(year: int) -> bool:
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def _days_in_month(year: int, month: int) -> int:
    if month == 2 and _is_leap(year):
        return 29
    return _DAYS_IN_MONTH[month - 1]


def add_months(date_str: str, n: int) -> str:
    """Return date_str (YYYY-MM-DD) shifted by n calendar months.

    The day of month is preserved; if the target month is too short, the
    result is clamped to that month's last day. n may be zero or negative.
    """
    year, month, day = (int(part) for part in date_str.split("-"))

    month_index = year * 12 + (month - 1) + n
    new_year, new_month_index = divmod(month_index, 12)
    new_month = new_month_index + 1

    new_day = min(day, _days_in_month(new_year, new_month))
    return "{:04d}-{:02d}-{:02d}".format(new_year, new_month, new_day)
