import re
from datetime import datetime, timedelta


def _parse_field(field, minimum, maximum):
    values = set()

    for item in field.split(","):
        if not item:
            raise ValueError("empty cron item")

        parts = item.split("/")
        if len(parts) > 2:
            raise ValueError("malformed step")

        base = parts[0]
        step = 1
        if len(parts) == 2:
            if not re.fullmatch(r"[0-9]+", parts[1]):
                raise ValueError("malformed step")
            step = int(parts[1])
            if step < 1:
                raise ValueError("step must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif re.fullmatch(r"[0-9]+", base):
            start = int(base)
            end = maximum if len(parts) == 2 else start
        elif re.fullmatch(r"[0-9]+-[0-9]+", base):
            start_text, end_text = base.split("-")
            start, end = int(start_text), int(end_text)
            if start > end:
                raise ValueError("range start exceeds range end")
        else:
            raise ValueError("malformed cron item")

        if start < minimum or end > maximum:
            raise ValueError("cron value out of range")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    minute_values = _parse_field(fields[0], 0, 59)
    hour_values = _parse_field(fields[1], 0, 23)
    day_values = _parse_field(fields[2], 1, 31)
    month_values = _parse_field(fields[3], 1, 12)
    weekday_values = _parse_field(fields[4], 0, 6)

    day_restricted = fields[2] != "*"
    weekday_restricted = fields[4] != "*"

    if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after):
        raise ValueError("after must have format YYYY-MM-DD HH:MM")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError("invalid after time") from exc

    try:
        cutoff = start.replace(year=start.year + 5)
    except ValueError:
        cutoff = start.replace(year=start.year + 5, day=28)

    candidate_date = start.date()
    last_date = cutoff.date()

    while candidate_date <= last_date:
        month_matches = candidate_date.month in month_values
        dom_matches = candidate_date.day in day_values
        dow = (candidate_date.weekday() + 1) % 7
        dow_matches = dow in weekday_values

        if month_matches:
            if day_restricted and weekday_restricted:
                date_matches = dom_matches or dow_matches
            elif day_restricted:
                date_matches = dom_matches
            elif weekday_restricted:
                date_matches = dow_matches
            else:
                date_matches = True

            if date_matches:
                for hour in sorted(hour_values):
                    for minute in sorted(minute_values):
                        candidate = datetime(
                            candidate_date.year,
                            candidate_date.month,
                            candidate_date.day,
                            hour,
                            minute,
                        )
                        if start < candidate <= cutoff:
                            return candidate.strftime("%Y-%m-%d %H:%M")

        candidate_date += timedelta(days=1)

    raise ValueError("no matching time within five years")
