import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire path-like name matches the glob pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            if i + 1 == len(pattern):
                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i + 1]))
            i += 2
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(r"[\s\S]*")
                i += 2
            else:
                regex.append(r"[^/]*")
                i += 1
        elif char == "?":
            regex.append(r"[^/]")
            i += 1
        elif char == "[":
            start = i
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            units = []
            if i < len(pattern) and pattern[i] == "]":
                units.append(("]", False))
                i += 1

            while i < len(pattern):
                if pattern[i] == "]":
                    break
                if pattern[i] == "\\":
                    if i + 1 == len(pattern):
                        raise ValueError("trailing backslash in pattern")
                    units.append((pattern[i + 1], True))
                    i += 2
                else:
                    units.append((pattern[i], False))
                    i += 1

            if i == len(pattern):
                raise ValueError(f"unclosed character set at position {start}")

            if not units:
                raise ValueError(f"empty character set at position {start}")

            class_parts = []
            j = 0
            while j < len(units):
                if (
                    j + 2 < len(units)
                    and units[j + 1] == ("-", False)
                ):
                    first = units[j][0]
                    last = units[j + 2][0]
                    if ord(first) > ord(last):
                        raise ValueError(f"invalid character range at position {start}")
                    class_parts.append(
                        re.escape(first) + "-" + re.escape(last)
                    )
                    j += 3
                else:
                    class_parts.append(re.escape(units[j][0]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(class_parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    return re.fullmatch("".join(regex), name) is not None
