    if not authority:
        raise ValueError("Authority must be non-empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    if host_port.startswith("["):
        closing = host_port.find("]")
        if closing == -1:
            raise ValueError("Unclosed IPv6 literal")
        host = host_port[1:closing]
        try:
            ipaddress.IPv6Address(host)
        except ValueError as exc:
            raise ValueError("Invalid IPv6 literal") from exc
        port_part = host_port[closing + 1:]
        if port_part and not port_part.startswith(":"):
            raise ValueError("Invalid text after IPv6 literal")
        has_port = bool(port_part)
        port_text = port_part[1:] if has_port else ""
    else:
        host_end = len(host_port)
        for index, char in enumerate(host_port):
            if char == ":":
                host_end = index
                break
            if char in " /?#@[]":
                raise ValueError("Invalid character in host")

        host = host_port[:host_end]
        if not host:
            raise ValueError("Host must be non-empty")

        port_part = host_port[host_end:]
        has_port = bool(port_part)
        port_text = port_part[1:] if has_port else ""

    if has_port:
        if not (1 <= len(port_text) <= 5) or not all(
            "0" <= digit <= "9" for digit in port_text
        ):
            raise ValueError("Invalid port")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Port is out of range")
    else:
        port = None

    if "#" in rest:
        before_fragment, fragment = rest.split("#", 1)
    else:
        before_fragment, fragment = rest, ""

    if "?" in before_fragment:
        path, query = before_fragment.split("?", 1)
    else:
        path, query = before_fragment, ""

    return {
        "scheme": scheme,
        "userinfo": userinfo,
