"""Canonical Roman numeral -> integer conversion.

Accepts only the canonical uppercase representation of 1..3999.
"""

import re

__all__ = ["roman_to_int"]

_SYMBOL_VALUES = {
    "I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000,
}

# Thousands, hundreds, tens, units -- each group is described by a
# canonical-only alternative list, so "IIII", "IC", "VX", "IIV",
# "XXXX" and "MMMM" are all rejected outright.
_CANONICAL_RE = re.compile(
    r"M{0,3}"                  # 1000..3000, never MMMM
    r"(?:CM|CD|D?C{0,3})"      # 900 / 400 / 0..300 + optional 500
    r"(?:XC|XL|L?X{0,3})"      #  90 /  40 / 0..30  + optional  50
    r"(?:IX|IV|V?I{0,3})"      #   9 /   4 / 0..3   + optional   5
)


def _value(numeral: str) -> int:
    """Sum a canonical numeral using standard right-to-left subtraction."""
    total = 0
    previous = 0
    for symbol in reversed(numeral):
        value = _SYMBOL_VALUES[symbol]
        if value < previous:
            total -= value
        else:
            total += value
            previous = value
    return total


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral to an int in 1..3999.

    Raises ValueError for the empty string, lowercase letters, non-strings,
    and non-canonical forms such as "IIII", "IC", "VX", "IIV", "XXXX",
    "MMMM" or anything else outside the canonical range.
    """
    if not isinstance(s, str):
        raise ValueError(
            "expected a str Roman numeral, got %s" % type(s).__name__
        )
    if not s:
        raise ValueError("empty string is not a valid Roman numeral")
    if _CANONICAL_RE.fullmatch(s) is None:
        raise ValueError("%r is not a canonical Roman numeral" % (s,))
    # fullmatch guarantees s is non-empty, so the result is >= 1 and <= 3999.
    return _value(s)
