def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 1024:
        return f"{n} B"
    units = ["KiB", "MiB", "GiB", "TiB"]
    k = 1
    for i in range(1, 5):
        if n >= 1024 ** i:
            k = i
    d = 1024 ** k
    # Exact round-half-up to one decimal: floor(n*10/d + 1/2)
    tenths = (20 * n + d) // (2 * d)
    if tenths >= 10240 and k < 4:
        k += 1
        tenths = 10
    return "{0}.{1} {2}".format(tenths // 10, tenths % 10, units[k - 1])
