"""Semantic version constraint matching (SemVer 2.0 ordering, npm-style ranges).

Standard library only, Python 3.9 compatible.
"""

import re

__all__ = ["semver_satisfies"]


# MAJOR.MINOR.PATCH, optional -prerelease, optional +build (build is ignored).
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?"
)

# Optional operator in front of a bare version.
_OPERATOR_RE = re.compile(r"(\^|~|>=|<=|=|>|<)?(.*)")

_NUMERIC_RE = re.compile(r"[0-9]+")


# --------------------------------------------------------------------------
# Version parsing / ordering
# --------------------------------------------------------------------------

def _parse_version(text):
    """Return (major, minor, patch, pre) with pre a string or None."""
    if not isinstance(text, str):
        raise ValueError("invalid version: {!r}".format(text))
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: {!r}".format(text))

    pre = match.group(4)
    if pre is not None:
        for ident in pre.split("."):
            if _NUMERIC_RE.fullmatch(ident) and len(ident) > 1 and ident[0] == "0":
                raise ValueError(
                    "invalid version (numeric pre-release identifier with "
                    "leading zero): {!r}".format(text)
                )
    return (int(match.group(1)), int(match.group(2)), int(match.group(3)), pre)


def _compare_pre(left, right):
    """Compare two pre-release tags (strings or None)."""
    if left is None and right is None:
        return 0
    if left is None:            # a version without pre-release is higher
        return 1
    if right is None:
        return -1

    left_parts = left.split(".")
    right_parts = right.split(".")
    for a, b in zip(left_parts, right_parts):
        if a == b:
            continue
        a_num = _NUMERIC_RE.fullmatch(a) is not None
        b_num = _NUMERIC_RE.fullmatch(b) is not None
        if a_num and b_num:
            ai, bi = int(a), int(b)
            if ai != bi:
                return -1 if ai < bi else 1
        elif a_num:             # numeric identifiers rank below alphanumeric
            return -1
        elif b_num:
            return 1
        else:
            return -1 if a < b else 1
    if len(left_parts) == len(right_parts):
        return 0
    return -1 if len(left_parts) < len(right_parts) else 1


def _compare(left, right):
    """Full SemVer ordering of two parsed versions."""
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1
    return _compare_pre(left[3], right[3])


# --------------------------------------------------------------------------
# Comparators
# --------------------------------------------------------------------------

class _Comparator:
    """One comparator: a predicate plus the literal version it was written as."""

    __slots__ = ("test", "core", "has_pre")

    def __init__(self, test, core, has_pre):
        self.test = test
        self.core = core          # (major, minor, patch) of the written version
        self.has_pre = has_pre    # written with a pre-release tag?


def _any_comparator():
    # Bare "*": matches everything; no written pre-release, so it never
    # admits a pre-release version (see the pre-release rule below).
    return _Comparator(lambda version: True, None, False)


def _make_comparator(operator, version):
    core = version[:3]
    has_pre = version[3] is not None

    if operator == "=":
        return _Comparator(lambda v: _compare(v, version) == 0, core, has_pre)
    if operator == ">":
        return _Comparator(lambda v: _compare(v, version) > 0, core, has_pre)
    if operator == ">=":
        return _Comparator(lambda v: _compare(v, version) >= 0, core, has_pre)
    if operator == "<":
        return _Comparator(lambda v: _compare(v, version) < 0, core, has_pre)
    if operator == "<=":
        return _Comparator(lambda v: _compare(v, version) <= 0, core, has_pre)

    if operator == "^":
        if core[0] > 0:
            upper = (core[0] + 1, 0, 0, None)
        elif core[1] > 0:
            upper = (0, core[1] + 1, 0, None)
        else:
            upper = (0, 0, core[2] + 1, None)
        return _Comparator(
            lambda v: _compare(v, version) >= 0 and _compare(v, upper) < 0,
            core, has_pre)

    if operator == "~":
        upper = (core[0], core[1] + 1, 0, None)
        return _Comparator(
            lambda v: _compare(v, version) >= 0 and _compare(v, upper) < 0,
            core, has_pre)

    raise ValueError("invalid comparator operator: {!r}".format(operator))


def _parse_comparator(token):
    match = _OPERATOR_RE.fullmatch(token)
    if match is None:
        raise ValueError("invalid comparator: {!r}".format(token))
    operator, rest = match.group(1), match.group(2)

    if operator is None:
        if rest == "*":
            return _any_comparator()
        operator = "="

    if rest == "":
        raise ValueError("invalid comparator (missing version): {!r}".format(token))
    return _make_comparator(operator, _parse_version(rest))


# --------------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------------

def semver_satisfies(version, constraint):
    """True if `version` satisfies `constraint` (npm-style range syntax)."""
    parsed_version = _parse_version(version)

    if not isinstance(constraint, str):
        raise ValueError("invalid constraint: {!r}".format(constraint))

    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty constraint group in {!r}".format(constraint))
        groups.append([_parse_comparator(token) for token in tokens])

    for comparators in groups:
        # Pre-release rule: a pre-release version only matches a group if some
        # comparator in it was written with a pre-release tag on the same core.
        if parsed_version[3] is not None:
            same_core = any(
                comp.has_pre and comp.core == parsed_version[:3]
                for comp in comparators
            )
            if not same_core:
                continue
        if all(comp.test(parsed_version) for comp in comparators):
            return True
    return False
