def shell_split(s: str) -> list[str]:
    r"""Split a command line into words using a subset of POSIX shell rules.

    Outside quotes, spaces and tabs separate words (runs count as one, no
    empty words at the ends).  Outside quotes a backslash makes the next
    character literal.  Inside single quotes everything is literal until
    the next single quote.  Inside double quotes everything is literal
    until the next unescaped double quote, with only \" and \\ acting as
    escapes.  Touching quoted and unquoted pieces form one word; empty
    quotes still produce a (possibly empty) word.  A trailing backslash
    or an unterminated quote raises ValueError.
    """
    words = []
    word = None  # None means "no word started yet"; '' is a real empty word
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ' or c == '\t':
            if word is not None:
                words.append(word)
                word = None
            i += 1
        elif c == '\\':
            if i + 1 >= n:
                raise ValueError("shell_split: backslash at end of input")
            if word is None:
                word = ''
            word += s[i + 1]
            i += 2
        elif c == "'":
            if word is None:
                word = ''
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("shell_split: unterminated single quote")
            word += s[i + 1:j]
            i = j + 1
        elif c == '"':
            if word is None:
                word = ''
            i += 1
            closed = False
            while i < n:
                d = s[i]
                if d == '"':
                    closed = True
                    i += 1
                    break
                if d == '\\':
                    if i + 1 >= n:
                        raise ValueError("shell_split: unterminated double quote")
                    nxt = s[i + 1]
                    if nxt == '"' or nxt == '\\':
                        word += nxt
                    else:
                        word += d
                        word += nxt
                    i += 2
                else:
                    word += d
                    i += 1
            if not closed:
                raise ValueError("shell_split: unterminated double quote")
        else:
            if word is None:
                word = ''
            word += c
            i += 1
    if word is not None:
        words.append(word)
    return words
