import re
import ipaddress

_SCHEME_RE = re.compile(r'^([A-Za-z][A-Za-z0-9+.\-]*)://')
_FORBIDDEN_HOST_CHARS = frozenset(' /?#@:[]')
_DIGITS = frozenset('0123456789')


def _parse_port(raw):
    if not 1 <= len(raw) <= 5 or any(ch not in _DIGITS for ch in raw):
        raise ValueError('invalid port: %r' % (raw,))
    value = int(raw)
    if not 1 <= value <= 65535:
        raise ValueError('port out of range: %r' % (raw,))
    return value


def parse_url(url):
    if not isinstance(url, str):
        raise ValueError('url must be a string')

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError('missing or invalid scheme')
    scheme = match.group(1).lower()

    rest = url[match.end():]

    end = len(rest)
    i = 0
    while i < end and rest[i] not in '/?#':
        i += 1
    authority = rest[:i]
    remainder = rest[i:]

    if not authority:
        raise ValueError('empty authority')

    at = authority.rfind('@')
    if at == -1:
        userinfo = ''
        hostport = authority
    else:
        userinfo = authority[:at]
        hostport = authority[at + 1:]

    if hostport.startswith('['):
        close = hostport.find(']')
        if close == -1:
            raise ValueError('unterminated IPv6 literal')
        literal = hostport[1:close]
        try:
            ipaddress.IPv6Address(literal)
        except ValueError:
            raise ValueError('invalid IPv6 literal: %r' % (literal,))
        host = literal.lower()
        tail = hostport[close + 1:]
        if tail == '':
            port = None
        elif tail[0] == ':':
            port = _parse_port(tail[1:])
        else:
            raise ValueError('unexpected characters after host')
    else:
        colon = hostport.find(':')
        if colon == -1:
            raw_host = hostport
            raw_port = None
        else:
            raw_host = hostport[:colon]
            raw_port = hostport[colon + 1:]
        if not raw_host or any(ch in _FORBIDDEN_HOST_CHARS for ch in raw_host):
            raise ValueError('invalid host: %r' % (raw_host,))
        host = raw_host.lower()
        port = None if raw_port is None else _parse_port(raw_port)

    hash_pos = remainder.find('#')
    if hash_pos == -1:
        fragment = ''
        before = remainder
    else:
        fragment = remainder[hash_pos + 1:]
        before = remainder[:hash_pos]

    query_pos = before.find('?')
    if query_pos == -1:
        query = ''
        path = before
    else:
        query = before[query_pos + 1:]
        path = before[:query_pos]

    return {
        'scheme': scheme,
        'userinfo': userinfo,
        'host': host,
        'port': port,
        'path': path,
        'query': query,
        'fragment': fragment,
    }
