def rle_decode(s: str) -> str:
    parts = []
    i = 0
    total = 0
    n = len(s)

    while i < n:
        if not ("0" <= s[i] <= "9"):
            raise ValueError("missing count")

        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        count_text = s[start:i]
        if count_text == "0" or count_text.startswith("0"):
            raise ValueError("invalid count")

        if i == n:
            raise ValueError("string ends with digits")

        count = 0
        for digit in count_text:
            count = count * 10 + (ord(digit) - ord("0"))
            if count > 10000 - total:
                raise ValueError("decoded length exceeds limit")

        parts.append(s[i] * count)
        total += count
        i += 1

    return "".join(parts)
