import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|[=><^~])?(.+)")


def _parse_version(text):
    if not isinstance(text, str):
        raise ValueError("Version must be a string")

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    core = tuple(int(match.group(i)) for i in (1, 2, 3))
    prerelease = match.group(4)
    identifiers = []

    if prerelease is not None:
        for identifier in prerelease.split("."):
            if identifier.isdigit():
                if len(identifier) > 1 and identifier.startswith("0"):
                    raise ValueError(
                        "Numeric pre-release identifier has leading zeros"
                    )
                identifiers.append((0, int(identifier)))
            else:
                identifiers.append((1, identifier))

    # Numeric identifiers sort before textual ones. The release flag makes
    # a stable release sort after every pre-release with the same core.
    key = core + (prerelease is None, tuple(identifiers))
    return core, prerelease is not None, key


def _comparison_holds(actual, operator, expected):
    if operator == "=":
        return actual == expected
    if operator == ">":
        return actual > expected
    if operator == ">=":
        return actual >= expected
    if operator == "<":
        return actual < expected
    if operator == "<=":
        return actual <= expected
    raise ValueError("Invalid comparator operator: {!r}".format(operator))


def semver_satisfies(version: str, constraint: str) -> bool:
    actual_core, actual_is_prerelease, actual_key = _parse_version(version)

    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("Constraint must be a non-empty string")

    groups = []

    # Parse every group before evaluating, so an invalid comparator raises
    # even when an earlier group would already match.
    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint contains an empty group")

        checks = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            core, is_prerelease, key = _parse_version(match.group(2))

            if is_prerelease:
                prerelease_cores.add(core)

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                checks.append((">=", key))
                checks.append(("<", upper_core + (True, ())))
            else:
                checks.append((operator, key))

        groups.append((checks, prerelease_cores))

    for checks, prerelease_cores in groups:
        if actual_is_prerelease and actual_core not in prerelease_cores:
            continue
        if all(
            _comparison_holds(actual_key, operator, expected)
            for operator, expected in checks
        ):
            return True

    return False
