def evaluate(expr: str):
    WS = " \t\n\r\v\f"

    # ---------- tokenizer ----------
    tokens = []          # (kind, value); kind: 'num' | '+','-','*','/','^','(',')'
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c in WS:
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            if j < n and expr[j] == '.':
                k = j + 1
                if k >= n or not ('0' <= expr[k] <= '9'):
                    raise ValueError("malformed decimal literal")
                while k < n and '0' <= expr[k] <= '9':
                    k += 1
                tokens.append(('num', float(expr[i:k])))
                i = k
            else:
                tokens.append(('num', int(expr[i:j])))
                i = j
            continue
        if c in '+-*/^()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError("unexpected character: %r" % (c,))

    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    # ---------- parser ----------
    # expr    := term (('+' | '-') term)*
    # term    := unary (('*' | '/') unary)*
    # unary   := '-' unary | power
    # power   := primary ('^' unary)?        # right-assoc, exponent may be unary
    # primary := number | '(' expr ')'
    def parse_expr():
        nonlocal pos
        value = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos][0]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        nonlocal pos
        value = parse_unary()
        while peek() in ('*', '/'):
            op = tokens[pos][0]
            pos += 1
            rhs = parse_unary()
            if op == '*':
                value = value * rhs
            else:
                try:
                    value = value / rhs
                except ZeroDivisionError:
                    raise ValueError("division by zero")
        return value

    def parse_unary():
        nonlocal pos
        if peek() == '-':
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_primary()
        if peek() == '^':
            pos += 1
            exponent = parse_unary()
            try:
                return base ** exponent
