import re

_NUM_PART_RE = re.compile(r"[0-9]+")
_TAG_RE = re.compile(r"[A-Za-z0-9]+")


def _parse(version):
    if not isinstance(version, str):
        raise ValueError("version must be a string")

    head, sep, tag = version.partition("-")
    if sep:
        if not _TAG_RE.fullmatch(tag):
            raise ValueError("invalid tag: {!r}".format(version))
    else:
        tag = None

    parts = head.split(".")
    for part in parts:
        if not _NUM_PART_RE.fullmatch(part):
            raise ValueError("invalid version: {!r}".format(version))

    return [int(part) for part in parts], tag


def compare_versions(a: str, b: str) -> int:
    nums_a, tag_a = _parse(a)
    nums_b, tag_b = _parse(b)

    width = max(len(nums_a), len(nums_b))
    nums_a += [0] * (width - len(nums_a))
    nums_b += [0] * (width - len(nums_b))

    if nums_a != nums_b:
        return -1 if nums_a < nums_b else 1

    if tag_a is None and tag_b is None:
        return 0
    if tag_a is None:
        return 1
    if tag_b is None:
        return -1
    if tag_a == tag_b:
        return 0
    return -1 if tag_a < tag_b else 1
