```python
"""Parser for a single CSV line.

Rules implemented:
  * fields are separated by commas; an empty line is one empty field
  * an unquoted field may be empty, is taken literally, and may not
    contain a double quote
  * a quoted field begins with a double quote as the first character of
    the field and ends with a double quote followed by a comma or the
    end of the line; "" inside it means one literal quote and commas
    are literal
  * ValueError on a quote inside an unquoted field, an unterminated
    quoted field, or anything other than a comma after a closing quote
"""


def parse_csv_line(line):
    """Split one CSV line (with no newline) into a list of str fields."""
    if not isinstance(line, str):
        raise TypeError("line must be a str, got %s" % type(line).__name__)

    n = len(line)
    fields = []
    i = 0

    while True:
        if i < n and line[i] == '"':
            # ---- quoted field ----
            i += 1
            chunks = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chunks.append('"')   # "" -> one literal quote
                        i += 2
                    else:
                        i += 1               # consume the closing quote
                        break
                else:
                    chunks.append(ch)        # commas included, literally
                    i += 1
            fields.append("".join(chunks))

            if i == n:
                return fields
            if line[i] != ",":
                raise ValueError(
                    "unexpected %r after closing quote" % line[i]
                )
            i += 1
        else:
            # ---- unquoted field ----
            comma = line.find(",", i)
            end = n if comma == -1 else comma
            chunk = line[i:end]
            if '"' in chunk:
                raise ValueError(
                    "double quote in unquoted field: %r" % chunk
                )
            fields.append(chunk)
            if comma == -1:
                return fields
            i = comma + 1

        if i == n:
            # line ended with a comma: the last field is empty
            fields.append("")
            return fields
