def first_bracket_error(s: str) -> int:
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []  # holds (opening_char, index) for unclosed opening brackets
    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append((ch, i))
        elif ch in ')]}':
            # Closing bracket with no opening bracket, or mismatched with
            # the most recent unclosed opening bracket (top of stack).
            if not stack or stack[-1][0] != pairs[ch]:
                return i
            stack.pop()
    # No bad closing bracket found; report the leftmost still-unclosed
    # opening bracket (bottom of the stack), if any.
    if stack:
        return stack[0][1]
    return -1
