                current = []
                current_len = 0
            full_pieces, rem = divmod(n, width)
            for i in range(full_pieces):
                lines.append(word[i * width:(i + 1) * width])
            if rem:
                current = [word[full_pieces * width:]]
                current_len = rem
        else:
            add = n + 1 if current else n
            if current_len + add <= width:
                current.append(word)
                current_len += add
            else:
                lines.append(' '.join(current))
                current = [word]
                current_len = n

    if current:
