"""Deterministic topological sort (Python 3.9, standard library only)."""

import heapq
from typing import Dict, List


def topo_sort(deps: Dict[str, List[str]]) -> List[str]:
    """Order items so every item comes after all of its dependencies.

    ``deps`` maps an item to the items it depends on.  Every item mentioned
    anywhere (as a key or inside a dependency list) appears exactly once in
    the result.  Duplicates inside a dependency list are ignored.  Among the
    items whose dependencies have all been placed, the lexicographically
    smallest is placed first, making the result deterministic.

    Raises ValueError on a self-dependency or any cycle.
    The input is never modified.
    """
    # Collect every item mentioned anywhere.
    nodes = set(deps)
    for dependency_list in deps.values():
        nodes.update(dependency_list)

    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    # An edge dependency -> item means "dependency must be placed first".
    for item, dependency_list in deps.items():
        seen = set()
        for dependency in dependency_list:
            if dependency in seen:
                continue  # duplicate dependency: ignored
            seen.add(dependency)
            dependents[dependency].append(item)
            indegree[item] += 1

    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)  # a min-heap yields the smallest available item

    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(nodes):
        raise ValueError("dependency graph contains a cycle")

    return result
