def shell_split(s: str) -> list[str]:
    words = []
    cur = []
    have_word = False
    i = 0
    n = len(s)

    def flush():
        nonlocal cur, have_word
        words.append(''.join(cur))
        cur = []
        have_word = False

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            if have_word:
                flush()
            i += 1

        elif c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            cur.append(s[i + 1])
            have_word = True
            i += 2

        elif c == "'":
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            cur.append(s[i + 1:j])
            have_word = True
            i = j + 1

        elif c == '"':
            i += 1
            closed = False
            while i < n:
                d = s[i]
                if d == '\\':
                    if i + 1 < n and (s[i + 1] == '"' or s[i + 1] == '\\'):
                        cur.append(s[i + 1])
                        i += 2
                    else:
                        cur.append('\\')
                        i += 1
                elif d == '"':
                    closed = True
                    i += 1
                    break
                else:
                    cur.append(d)
                    i += 1
            if not closed:
                raise ValueError("unterminated double quote")
            have_word = True

        else:
            cur.append(c)
            have_word = True
            i += 1

    if have_word:
        flush()

