"""npm-style semver constraint matching (Python 3.9, standard library only)."""

import re

_VERSION_RE = re.compile(
    r"^(?P<major>0|[1-9][0-9]*)\."
    r"(?P<minor>0|[1-9][0-9]*)\."
    r"(?P<patch>0|[1-9][0-9]*)"
    r"(?:-(?P<pre>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


def _parse_version(text):
    """Parse a version string into (major, minor, patch, prerelease).

    ``prerelease`` is ``None`` when absent, else a tuple of identifier strings.
    Build metadata is validated structurally but discarded.
    """
    if not isinstance(text, str):
        raise ValueError("version must be a string: {!r}".format(text))
    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError("invalid semantic version: {!r}".format(text))

    prerelease = None
    raw_pre = match.group("pre")
    if raw_pre is not None:
        identifiers = raw_pre.split(".")
        for identifier in identifiers:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError(
                    "invalid numeric pre-release identifier in {!r}".format(text)
                )
        prerelease = tuple(identifiers)

    return (
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        prerelease,
    )


