    """Parse one ``||``-group into a list of ``(operator, parsed_version)`` pairs.

    ``("any", None)`` represents a bare ``*``.  ``^`` and ``~`` are expanded
    into their ``>=`` / ``<`` comparator pairs.
    """
    tokens = text.split()
    if not tokens:
        raise ValueError("empty comparator group: {!r}".format(text))

    comparators = []
    for token in tokens:
        if token == "*":
            comparators.append(("any", None))
            continue

        operator = ""
        remainder = token
        for candidate in _OPERATORS:
            if token.startswith(candidate):
                operator = candidate
                remainder = token[len(candidate):]
