    """True when the version satisfies every comparator in the group."""
    for operator, target in comparators:
        if operator == "any":
            continue
        result = _compare(version, target)
        if operator == "=":
            satisfied = result == 0
        elif operator == ">":
            satisfied = result > 0
        elif operator == ">=":
            satisfied = result >= 0
