def _parse_version(s):
    """Return (numeric_keys, tag) for a valid version string."""
    if not isinstance(s, str):
        raise ValueError("invalid version: %r" % (s,))

    if "-" in s:
        numeric, _, tag = s.partition("-")
        if not tag or any(c not in _ALNUM for c in tag):
            raise ValueError("invalid version: %r" % (s,))
    else:
        numeric, tag = s, None

    keys = []
    for part in numeric.split("."):
        if not part or any(c not in _DIGITS for c in part):
            raise ValueError("invalid version: %r" % (s,))
        stripped = part.lstrip("0")          # "" means zero
        keys.append((len(stripped), stripped))  # compare length first, then lexically
    return keys, tag


_DIGITS = "0123456789"
_ALNUM = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz"
_ZERO = (0, "")


def compare_versions(a, b):
    na, ta = _parse_version(a)
    nb, tb = _parse_version(b)

    width = max(len(na), len(nb))
    ka = tuple(na) + (_ZERO,) * (width - len(na))
    kb = tuple(nb) + (_ZERO,) * (width - len(nb))
    if ka != kb:
        return -1 if ka < kb else 1

    if ta is None and tb is None:
        return 0
    if ta is None:      # no tag beats a tag
        return 1
    if tb is None:
        return -1
    if ta == tb:
        return 0
    return -1 if ta < tb else 1
