"""Semantic-version constraint matching (SemVer 2.0 ordering, npm-style ranges).

Standard library only. Targets Python 3.9.
"""

import re
from typing import List, Optional, Tuple

__all__ = ["semver_satisfies"]

# MAJOR / MINOR / PATCH and numeric pre-release identifiers: no leading zeros.
_NUMERIC_RE = re.compile(r"(?:0|[1-9][0-9]*)\Z")
# Pre-release / build identifier: non-empty, ASCII letters, digits, hyphens only.
_IDENT_RE = re.compile(r"[0-9A-Za-z-]+\Z")
# All-digit identifier, used to tell numeric pre-release ids from alphanumeric.
_DIGITS_RE = re.compile(r"[0-9]+\Z")

# Longest-first so that ">=" is not mis-read as ">".
_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")

# A parsed version: (major, minor, patch, pre) where `pre` is either None or a
# tuple of identifiers.  An identifier is (0, int) when numeric and (1, str)
# otherwise, so tuple ordering gives numeric < alphanumeric for free.
_ParsedVersion = Tuple[int, int, int, Optional[Tuple[Tuple[int, object], ...]]]


def _parse_version(text: str) -> _ParsedVersion:
    """Parse a SemVer 2.0 string, raising ValueError if it is malformed."""
    if not isinstance(text, str) or not text:
        raise ValueError("invalid version: %r" % (text,))

    # Build metadata is syntactically validated but otherwise ignored.
    core, sep, build = text.partition("+")
    if sep:
        if not build or not all(_IDENT_RE.match(i) for i in build.split(".")):
            raise ValueError("invalid build metadata in version: %r" % (text,))

    base, sep, pre_text = core.partition("-")
    pre: Optional[Tuple[Tuple[int, object], ...]] = None
    if sep:
        pre_ids = []
        for ident in pre_text.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError("invalid pre-release in version: %r" % (text,))
            if _DIGITS_RE.match(ident):
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError(
                        "numeric pre-release identifier has a leading zero: %r" % (text,)
                    )
                pre_ids.append((0, int(ident)))
            else:
                pre_ids.append((1, ident))
        pre = tuple(pre_ids)

    parts = base.split(".")
    if len(parts) != 3 or not all(_NUMERIC_RE.match(p) for p in parts):
        raise ValueError("invalid version: %r" % (text,))

    return (int(parts[0]), int(parts[1]), int(parts[2]), pre)


def _compare(a: _ParsedVersion, b: _ParsedVersion) -> int:
    """Return -1, 0 or 1 comparing two parsed versions (build metadata excluded)."""
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1

    pre_a, pre_b = a[3], b[3]
    if pre_a is None or pre_b is None:
        if pre_a is pre_b:
            return 0
        return 1 if pre_a is None else -1  # a release outranks a pre-release

    for id_a, id_b in zip(pre_a, pre_b):
        if id_a != id_b:
            return -1 if id_a < id_b else 1
    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1  # shorter tag is lower


def _caret_upper(bound: _ParsedVersion) -> _ParsedVersion:
    major, minor, patch = bound[0], bound[1], bound[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper(bound: _ParsedVersion) -> _ParsedVersion:
    return (bound[0], bound[1] + 1, 0, None)


def _check(op: str, bound: _ParsedVersion, ver: _ParsedVersion) -> bool:
    """Evaluate a single comparator against a parsed version."""
    c = _compare(ver, bound)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    if op == "^":
        return c >= 0 and _compare(ver, _caret_upper(bound)) < 0
    if op == "~":
        return c >= 0 and _compare(ver, _tilde_upper(bound)) < 0
    raise ValueError("unknown operator: %r" % (op,))  # pragma: no cover


def _group_satisfies(group: List[Tuple[str, Optional[_ParsedVersion]]], ver: _ParsedVersion) -> bool:
    """Evaluate one whitespace-separated group of comparators."""
    if ver[3] is not None:
        # A pre-release may only match if some comparator names a pre-release
        # on the very same MAJOR.MINOR.PATCH.
        if not any(
            bound is not None and bound[3] is not None and bound[:3] == ver[:3]
            for _, bound in group
        ):
            return False

    for op, bound in group:
        if bound is None:  # bare "*": matches any version
            continue
        if not _check(op, bound, ver):
            return False
    return True


def _parse_comparator(token: str) -> Tuple[str, Optional[_ParsedVersion]]:
    """Parse a comparator token into (operator, bound); `*` yields (\"\", None)."""
    if token == "*":
        return ("", None)

    op, rest = "=", token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            op, rest = candidate, token[len(candidate):]
            break

    if not rest:
        raise ValueError("invalid comparator: %r" % (token,))
    return (op, _parse_version(rest))


def semver_satisfies(version: str, constraint: str) -> bool:
    """Return True if `version` satisfies the npm-style `constraint`.

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty constraint.
    """
    ver = _parse_version(version)

    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string: %r" % (constraint,))
    text = constraint.strip()
    if not text:
        raise ValueError("empty constraint: %r" % (constraint,))

    for raw_group in text.split("||"):
        group_text = raw_group.strip()
        if not group_text:
            raise ValueError("invalid constraint: %r" % (constraint,))
        tokens = group_text.split()
        if not tokens:
            raise ValueError("invalid constraint: %r" % (constraint,))
        group = [_parse_comparator(token) for token in tokens]
        if _group_satisfies(group, ver):
            return True
    return False
