def first_bracket_error(s: str) -> int:
    """Return the index of the first bracket error, or -1 if balanced.

    A closing bracket is an error if the stack is empty (nothing to close)
    or if it does not match the most recently unclosed opening bracket.
    Otherwise, once the scan finishes, the leftmost still-unclosed opening
    bracket is the error. If neither occurs, the string is balanced.
    """
    OPEN = "([{"
    MATCH = {")": "(", "]": "[", "}": "{"}
    stack = []  # entries are (opening_char, index), oldest first

    for i, ch in enumerate(s):
        if ch in OPEN:
            stack.append((ch, i))
        elif ch in MATCH:
            if not stack or stack[-1][0] != MATCH[ch]:
                return i
            stack.pop()

    if stack:
        return stack[0][1]
    return -1
