def shell_split(s: str) -> list[str]:
    words = []
    current = []
    word_started = False
    i = 0

    while i < len(s):
        char = s[i]

        if char in " \t":
            if word_started:
                words.append("".join(current))
                current = []
                word_started = False
            i += 1
        elif char == "\\":
            if i + 1 == len(s):
                raise ValueError("trailing backslash")
            current.append(s[i + 1])
            word_started = True
            i += 2
        elif char == "'":
            word_started = True
            i += 1
            while i < len(s) and s[i] != "'":
                current.append(s[i])
                i += 1
            if i == len(s):
                raise ValueError("unterminated single quote")
            i += 1
        elif char == '"':
            word_started = True
            i += 1
            while i < len(s) and s[i] != '"':
                if s[i] == "\\" and i + 1 < len(s) and s[i + 1] in ('"', "\\"):
                    current.append(s[i + 1])
                    i += 2
                else:
                    current.append(s[i])
                    i += 1
            if i == len(s):
                raise ValueError("unterminated double quote")
            i += 1
        else:
            current.append(char)
            word_started = True
            i += 1

    if word_started:
        words.append("".join(current))

    return words
