def normalize_path(p: str) -> str:
    """Normalize a Unix-style path.

    - Empty components and "." are ignored.
    - ".." removes the previous component.
    - Absolute paths: ".." at the root is ignored; any number of
      leading slashes collapses to a single root "/".
    - Relative paths: unresolvable leading ".." components are kept.
    - No trailing slash except for the root itself, which is "/".
    - Empty relative results (including empty input) become ".".
    - Components like "..." are ordinary names.
    """
    is_absolute = p.startswith("/")
    stack = []

    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if is_absolute:
                if stack:
                    stack.pop()
                # else: ".." at the root of an absolute path is ignored
            else:
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    # Unresolvable ".." in a relative path is kept.
                    # (If the top is already "..", it is itself
                    # unresolvable, so this one is unresolvable too.)
                    stack.append("..")
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    return "/".join(stack) if stack else "."
