def leftmost_index(a: list, x: int) -> int:
    """Return the smallest index i such that a[i] == x, or -1 if x is not in a.

    `a` must be a list of integers sorted in non-decreasing order.
    Uses an iterative binary search (lower bound): O(log n) time, O(1) space.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(a) and a[lo] == x else -1
