def is_valid_ipv4(s: str) -> bool:
    """Return True if *s* is a valid dotted-quad IPv4 address, else False.

    Rules:
      * exactly four parts separated by "."
      * each part is 1-3 ASCII digits (0-9), value 0-255
      * no leading zeros unless the part is exactly "0"
      * nothing else allowed: no signs, whitespace, or trailing newline
    """
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        n = len(part)
        if n < 1 or n > 3:
            return False

        # ASCII digits only -- str.isdigit() would accept "١", "１", "²", ...
        for ch in part:
            if ch < "0" or ch > "9":
                return False

        # No leading zeros: "0" is fine, "00"/"01" are not.
        if n > 1 and part[0] == "0":
            return False

        if int(part) > 255:
            return False

    return True
