def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 1024:
        return "{} B".format(n)

    units = ("KiB", "MiB", "GiB", "TiB")

    idx = 0
    for i in range(len(units)):
        if n >= 1024 ** (i + 1):
            idx = i

    while True:
        q = 1024 ** (idx + 1)
        r = (2 * n * 10 + q) // (2 * q)
        if r >= 10240 and idx < len(units) - 1:
            idx += 1
            continue
        return "{}.{} {}".format(r // 10, r % 10, units[idx])
