def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    while i < n:
        if line[i] == '"':
            i += 1
            field = []

            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")

                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        i += 1
                        if i < n and line[i] != ',':
                            raise ValueError("invalid character after closing quote")
                        fields.append("".join(field))
                        if i < n:
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
        else:
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("double quote in unquoted field")
                i += 1

            fields.append(line[start:i])
            if i < n:
                i += 1

    if not fields:
        return [""]

    return fields
