"""Arithmetic expression evaluator.

Recursive-descent parser (stdlib only, Python 3.9) for the grammar:

    expr    := term (('+' | '-') term)*
    term    := unary (('*' | '/') unary)*
    unary   := '-' unary | power
    power   := atom ('^' unary)?          # right-associative, unary binds looser
    atom    := INT | DEC | '(' expr ')'

INT is a run of ASCII digits (-> int); DEC is digits '.' digits (-> float).
Whitespace may appear anywhere between tokens and is otherwise ignored.
"""

from typing import Any, List, Tuple, Union

Number = Union[int, float]
Token = Tuple[str, Any]

_DIGITS = "0123456789"
_BINARY_OPS = "+-*/^"
_PARENS = "()"


def _tokenize(expr: str) -> List[Token]:
    """Split `expr` into ('num', int|float) and ('op', str) tokens."""
    tokens: List[Token] = []
    i, n = 0, len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if ch in _DIGITS:
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            if j < n and expr[j] == ".":  # decimal literal: digits '.' digits
                k = j + 1
                if k >= n or expr[k] not in _DIGITS:
                    raise ValueError("malformed decimal literal")
                while k < n and expr[k] in _DIGITS:
                    k += 1
                tokens.append(("num", float(expr[i:k])))
                i = k
            else:
                tokens.append(("num", int(expr[i:j])))
                i = j
            continue

        if ch in _BINARY_OPS or ch in _PARENS:
            if ch == "*" and i + 1 < n and expr[i + 1] == "*":
                raise ValueError("unsupported operator '**'")
            tokens.append(("op", ch))
            i += 1
            continue

        raise ValueError("unknown character %r" % (ch,))

    return tokens


class _Parser:
    """Index-driven recursive-descent parser over a token list."""

    def __init__(self, tokens: List[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    # ---- token helpers ---------------------------------------------------

    def _peek(self) -> Union[Token, None]:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self) -> Union[Token, None]:
        token = self._peek()
        if token is not None:
            self._pos += 1
        return token

    def _accept_op(self, ops: str) -> Union[str, None]:
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] in ops:
            self._pos += 1
            return token[1]
        return None

    # ---- grammar ---------------------------------------------------------

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected trailing input")
        return value

    def _expr(self) -> Number:
        value = self._term()
        while True:
            op = self._accept_op("+-")
            if op is None:
                return value
            right = self._term()
            value = value + right if op == "+" else value - right

    def _term(self) -> Number:
        value = self._unary()
        while True:
            op = self._accept_op("*/")
            if op is None:
                return value
            right = self._unary()
            if op == "*":
                value = value * right
            else:
                if right == 0:
                    raise ValueError("division by zero")
                value = value / right

    def _unary(self) -> Number:
        if self._accept_op("-") is not None:
            return -self._unary()
        return self._power()

    def _power(self) -> Number:
        base = self._atom()
        if self._accept_op("^") is not None:
            return base ** self._unary()  # right-assoc; exponent may be signed
        return base

    def _atom(self) -> Number:
        token = self._advance()
        if token is None:
            raise ValueError("unexpected end of expression")
        kind, value = token
        if kind == "num":
            return value
        if kind == "op" and value == "(":
            inner = self._expr()
            closing = self._advance()
            if closing is None or closing[0] != "op" or closing[1] != ")":
                raise ValueError("unbalanced parentheses")
            return inner
        raise ValueError("unexpected token %r" % (value,))


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression string and return int or float.

    Raises ValueError on malformed input and on division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = _tokenize(expr)
    try:
        return _Parser(tokens).parse()
    except ZeroDivisionError:  # e.g. 0 ^ -1
        raise ValueError("division by zero") from None
