_FIELD_SPECS = (
    (0, 59),
    (0, 23),
    (1, 31),
    (1, 12),
    (0, 6),
)


def _parse_field(text, minimum, maximum):
    values = set()

    for item in text.split(","):
        if not item:
            raise ValueError("empty cron field item")

        base, slash, step_text = item.partition("/")
        if slash:
            if not re.fullmatch(r"[0-9]+", step_text):
                raise ValueError("invalid step")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be at least 1")
        else:
            step = 1

        if base == "*":
            start, end = minimum, maximum
        elif re.fullmatch(r"[0-9]+", base):
            start = int(base)
            end = maximum if slash else start
        else:
            match = re.fullmatch(r"([0-9]+)-([0-9]+)", base)
            if not match:
                raise ValueError("invalid cron field item")
            start, end = map(int, match.groups())
            if start > end:
                raise ValueError("descending range")

        if start < minimum or start > maximum or end < minimum or end > maximum:
            raise ValueError("cron value out of range")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have five fields")

    parsed = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, _FIELD_SPECS)
    ]
    minutes, hours, month_days, months, week_days = parsed

    if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after):
        raise ValueError("after must be formatted YYYY-MM-DD HH:MM")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError("invalid after time") from exc

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    end_year = min(start.year + 5, 9999)
    end_month = start.month
    end_day = start.day
    while True:
        try:
            deadline = datetime(end_year, end_month, end_day, start.hour, start.minute)
            break
        except ValueError:
            end_day -= 1

    current_day = start.date()
    last_day = deadline.date()

    while current_day <= last_day:
        if current_day.month in months:
            dom_matches = current_day.day in month_days
            dow_matches = (current_day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                for hour in sorted(hours):
                    for minute in sorted(minutes):
                        candidate = datetime(
                            current_day.year,
                            current_day.month,
                            current_day.day,
                            hour,
                            minute,
                        )
                        if start < candidate <= deadline:
                            return candidate.strftime("%Y-%m-%d %H:%M")

        current_day += timedelta(days=1)

    raise ValueError("no matching time within five years")
