def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")

    units = (
        (1, "B"),
        (1024, "KiB"),
        (1024**2, "MiB"),
        (1024**3, "GiB"),
        (1024**4, "TiB"),
    )

    if n < 1024:
        return f"{n} B"

    index = 1
    for i in range(2, len(units)):
        if n >= units[i][0]:
            index = i
        else:
            break

    while True:
        factor, name = units[index]
        tenths = (20 * n + factor) // (2 * factor)
        if tenths < 10240 or index == len(units) - 1:
            whole, decimal = divmod(tenths, 10)
            return f"{whole}.{decimal} {name}"
        index += 1
