            step = _parse_number(step_text)
            if step < 1:
                raise ValueError("step must be >= 1 in cron field: %r" % (item,))
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a_text, _, b_text = base.partition("-")
            start = _parse_number(a_text)
            end = _parse_number(b_text)
            if start > end:
                raise ValueError("invalid range in cron field: %r" % (item,))
        else:
            start = _parse_number(base)
            end = hi if step is not None else start
        if start < lo or end > hi:
            raise ValueError("value out of range in cron field: %r" % (item,))
        if step is None:
            step = 1
        values.update(range(start, end + 1, step))
    return values


