    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")
    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    days_of_month = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    days_of_week = _parse_field(fields[4], 0, 6)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    start = datetime.strptime(after, "%Y-%m-%d %H:%M")

    try:
        limit = start.replace(year=start.year + 5)
    except ValueError:
        limit = start.replace(year=start.year + 5, day=28)

    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)
    last_date = limit.date()
    day = start.date()

    while day <= last_date:
        if day.month in months:
            dom_match = day.day in days_of_month
            dow_match = ((day.weekday() + 1) % 7) in days_of_week
            if dom_restricted and dow_restricted:
                day_matches = dom_match or dow_match
            elif dom_restricted:
                day_matches = dom_match
            elif dow_restricted:
                day_matches = dow_match
            else:
                day_matches = True
            if day_matches:
                for hour in sorted_hours:
                    for minute in sorted_minutes:
                        candidate = datetime(day.year, day.month, day.day, hour, minute)
                        if candidate <= start:
