def _tokenize(expr):
    """Convert the input string into a list of (kind, value) tokens."""
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            if j < n and expr[j] == '.' and j + 1 < n and '0' <= expr[j + 1] <= '9':
                j += 1
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                tokens.append(('num', float(expr[i:j])))
            else:
                tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append((c, None))
            i += 1
            continue
        raise ValueError("unknown character: %r" % (c,))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos][0]
        return None

    def _advance(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def parse(self):
        value = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected token after end of expression")
        return value

    def _expr(self):
        # Lowest precedence: left-associative '+' and '-'
        value = self._term()
        while self._peek() in ('+', '-'):
            op = self._advance()[0]
            rhs = self._term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def _term(self):
        # Middle precedence: left-associative '*' and '/'
        value = self._unary()
        while self._peek() in ('*', '/'):
            op = self._advance()[0]
            rhs = self._unary()
            value = value * rhs if op == '*' else value / rhs
        return value

    def _unary(self):
        # Unary minus binds less tightly than '^', so its operand goes
        # through _unary again (allowing '--') and then _power, which
        # consumes any following '^ ...' chain: -2 ^ 2 == -(2 ^ 2).
        if self._peek() == '-':
            self._advance()
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._primary()
        if self._peek() == '^':
            self._advance()
            # Right-associative; the exponent may itself start with '-'.
            exponent = self._unary()
            return base ** exponent
        return base

    def _primary(self):
        kind = self._peek()
        if kind == 'num':
            return self._advance()[1]
        if kind == '(':
            self._advance()
            value = self._expr()
            if self._peek() != ')':
                raise ValueError("missing closing parenthesis")
            self._advance()
            return value
        raise ValueError("expected a number or '('")


def evaluate(expr: str):
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    try:
        return parser.parse()
    except ZeroDivisionError:
        raise ValueError("division by zero") from None
