def shell_split(s: str) -> list[str]:
    words = []
    cur = []
    has_word = False  # True once we've started the current word (even if it's empty)
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            if has_word:
                words.append(''.join(cur))
                cur = []
                has_word = False
            i += 1

        elif c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            cur.append(s[i + 1])
            has_word = True
            i += 2

        elif c == "'":
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            cur.append(s[i + 1:j])
            has_word = True
            i = j + 1

        elif c == '"':
            i += 1
            closed = False
            while i < n:
                d = s[i]
                if d == '\\':
                    if i + 1 < n and (s[i + 1] == '"' or s[i + 1] == '\\'):
                        cur.append(s[i + 1])
                        i += 2
                    else:
                        cur.append('\\')
                        i += 1
                elif d == '"':
                    closed = True
                    i += 1
                    break
                else:
                    cur.append(d)
                    i += 1
            if not closed:
                raise ValueError("unterminated double quote")
            has_word = True

        else:
            cur.append(c)
            has_word = True
            i += 1

    if has_word:
        words.append(''.join(cur))

    return words
