def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines = []
    current = ""

    for word in text.split(" "):
        if not word:
            continue

        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            full_length = len(word) - (len(word) % width)
            for start in range(0, full_length, width):
                lines.append(word[start:start + width])

            remainder = word[full_length:]
            if remainder:
                current = remainder
            continue

        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
