import ipaddress


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("URL must be a string")

    marker = url.find("://")
    if marker <= 0:
        raise ValueError("URL must start with a scheme followed by ://")

    scheme = url[:marker]
    if not (
        scheme[0].isascii()
        and scheme[0].isalpha()
        and all(
            char.isascii() and (char.isalnum() or char in "+-.")
            for char in scheme[1:]
        )
    ):
        raise ValueError("Invalid scheme")
    scheme = scheme.lower()

    remainder = url[marker + 3:]
    authority_end = len(remainder)
    for delimiter in "/?#":
        index = remainder.find(delimiter)
        if index != -1:
            authority_end = min(authority_end, index)

    authority = remainder[:authority_end]
    rest = remainder[authority_end:]
    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    port = None
    if host_port.startswith("["):
        closing = host_port.find("]")
        if closing == -1:
            raise ValueError("Unclosed IPv6 address")

        host = host_port[1:closing]
        try:
            ipaddress.IPv6Address(host)
        except ValueError as exc:
            raise ValueError("Invalid IPv6 address") from exc

        suffix = host_port[closing + 1:]
        if suffix:
            if not suffix.startswith(":"):
                raise ValueError("Invalid text after IPv6 address")
            port_text = suffix[1:]
            if not (
                1 <= len(port_text) <= 5
                and all("0" <= char <= "9" for char in port_text)
            ):
                raise ValueError("Invalid port")
            port = int(port_text)
            if not 1 <= port <= 65535:
                raise ValueError("Port out of range")
    else:
        colon = host_port.find(":")
        if colon == -1:
            host = host_port
        else:
            host = host_port[:colon]
            port_text = host_port[colon + 1:]
            if not (
                1 <= len(port_text) <= 5
                and all("0" <= char <= "9" for char in port_text)
            ):
                raise ValueError("Invalid port")
            port = int(port_text)
            if not 1 <= port <= 65535:
                raise ValueError("Port out of range")

        if not host or any(
            char in " /?#@:[]"
            for char in host
        ):
            raise ValueError("Invalid host")

    host = host.lower()

    before_fragment, fragment_separator, fragment = rest.partition("#")
    path, query_separator, query = before_fragment.partition("?")

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query if query_separator else "",
        "fragment": fragment if fragment_separator else "",
    }
