import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned, as a key or inside a dependency list.
    items: set[str] = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    # Build the graph with deduplicated edges; count outstanding dependencies.
    successors: dict[str, set[str]] = {item: set() for item in items}
    pending: dict[str, int] = {item: 0 for item in items}
    for item, dep_list in deps.items():
        for dep in dep_list:
            if item not in successors[dep]:
                successors[dep].add(item)
                pending[item] += 1

    # Greedy Kahn's algorithm with a min-heap for the lexicographic tie-break.
    ready: list[str] = [item for item in items if pending[item] == 0]
    heapq.heapify(ready)

    order: list[str] = []
    while ready:
        item = heapq.heappop(ready)
        order.append(item)
        for nxt in successors[item]:
            pending[nxt] -= 1
            if pending[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(order) != len(items):
        raise ValueError("dependency cycle detected")

    return order
