import re
from typing import List, Tuple, Union

_Core = Tuple[int, int, int]
_Identifier = Tuple[int, Union[int, str]]
_PreRelease = Tuple[_Identifier, ...]
_Version = Tuple[_Core, int, _PreRelease]
_Check = Tuple[str, _Version]
_Group = Tuple[List[_Check], List[_Core]]

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|[=><^~])?(.+)")


def _parse_version(text: str) -> _Version:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    core = (int(match[1]), int(match[2]), int(match[3]))
    prerelease = match[4]
    if prerelease is None:
        return core, 1, ()

    identifiers: List[_Identifier] = []
    for identifier in prerelease.split("."):
        if all("0" <= char <= "9" for char in identifier):
            if len(identifier) > 1 and identifier[0] == "0":
                raise ValueError(
                    "Numeric pre-release identifier has a leading zero: {!r}"
                    .format(text)
                )
            identifiers.append((0, int(identifier)))
        else:
            identifiers.append((1, identifier))

    # Tuple ordering implements SemVer ordering: numeric identifiers sort
    # before alphanumeric ones, and releases sort after pre-releases.
    return core, 0, tuple(identifiers)


def _check(version: _Version, operator: str, target: _Version) -> bool:
    if operator == "=":
        return version == target
    if operator == ">":
        return version > target
    if operator == ">=":
        return version >= target
    if operator == "<":
        return version < target
    if operator == "<=":
        return version <= target
    raise ValueError("Invalid comparator operator: {!r}".format(operator))


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a strict SemVer version against the specified constraint syntax."""
    if not isinstance(version, str) or not isinstance(constraint, str):
        raise ValueError("Version and constraint must be strings")

    parsed_version = _parse_version(version)
    groups: List[_Group] = []

    # Parse every group before evaluating, so invalid comparators raise even
    # when an earlier group would already satisfy the constraint.
    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        checks: List[_Check] = []
        prerelease_cores: List[_Core] = []

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match[1] or "="
            target = _parse_version(match[2])
            core, is_release, _ = target

            # Only explicitly written pre-release versions grant eligibility.
            if not is_release:
                prerelease_cores.append(core)

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                checks.append((">=", target))
                checks.append(("<", (upper_core, 1, ())))
            else:
                checks.append((operator, target))

        groups.append((checks, prerelease_cores))

    core, is_release, _ = parsed_version
    for checks, prerelease_cores in groups:
        if not is_release and core not in prerelease_cores:
            continue
        if all(_check(parsed_version, op, target) for op, target in checks):
            return True

    return False
