import re
from datetime import datetime, timedelta

_NUM_RE = re.compile(r"^[0-9]+$")


def _parse_field(text, lo, hi, name):
    """Expand one cron field into the set of allowed values."""
    if not text:
        raise ValueError("empty %s field" % name)

    values = set()

    for item in text.split(","):
        if not item:
            raise ValueError("empty item in %s field" % name)

        base = item
        step = 1
        has_step = "/" in item

        if has_step:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("malformed item %r in %s field" % (item, name))
            base, raw_step = parts
            if not _NUM_RE.match(raw_step):
                raise ValueError("malformed step in %s field" % name)
            step = int(raw_step)
            if step < 1:
                raise ValueError("step must be >= 1 in %s field" % name)

        if base == "*":
            values.update(range(lo, hi + 1, step))
        elif "-" in base:
