import re
from typing import List, Optional, Tuple


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse_version(
    text: str,
) -> Tuple[int, int, int, Optional[Tuple[str, ...]]]:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid semantic version")

    major, minor, patch = (int(match.group(i)) for i in range(1, 4))
    prerelease_text = match.group(4)
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text else None

    if prerelease is not None:
        for identifier in prerelease:
            if identifier.isascii() and identifier.isdigit() and len(identifier) > 1:
                if identifier[0] == "0":
                    raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return major, minor, patch, prerelease


def _compare(
    left: Tuple[int, int, int, Optional[Tuple[str, ...]]],
    right: Tuple[int, int, int, Optional[Tuple[str, ...]]],
) -> int:
    left_core = left[:3]
    right_core = right[:3]
    if left_core < right_core:
        return -1
    if left_core > right_core:
        return 1

    left_pre = left[3]
    right_pre = right[3]
    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for a, b in zip(left_pre, right_pre):
        if a == b:
            continue
        a_numeric = a.isascii() and a.isdigit()
        b_numeric = b.isascii() and b.isdigit()
        if a_numeric and b_numeric:
            return -1 if int(a) < int(b) else 1
        if a_numeric != b_numeric:
            return -1 if a_numeric else 1
        return -1 if a < b else 1

    if len(left_pre) == len(right_pre):
        return 0
    return -1 if len(left_pre) < len(right_pre) else 1


def semver_satisfies(version: str, constraint: str) -> bool:
    parsed_version = _parse_version(version)

    if not constraint or not constraint.strip():
        raise ValueError("constraint must not be empty")

    groups = constraint.split("||")
    satisfies_any_group = False

    for group in groups:
        tokens = group.split()
        if not tokens:
            raise ValueError("constraint contains an empty group")

        comparators = []
        for token in tokens:
            if token == "*":
                comparators.append(("*", None, False))
                continue

            match = re.fullmatch(r"(>=|<=|>|<|=|\^|~)?(.+)", token)
            if match is None:
                raise ValueError("invalid comparator")

            operator = match.group(1) or "="
            operand_text = match.group(2)
            if operand_text == "*":
                raise ValueError("wildcard is only valid as a bare comparator")

            operand = _parse_version(operand_text)
            comparators.append((operator, operand, operand[3] is not None))

        group_matches = True
        has_matching_prerelease_comparator = False

        for operator, operand, has_prerelease in comparators:
            if operator == "*":
                continue

            if has_prerelease and operand[:3] == parsed_version[:3]:
                has_matching_prerelease_comparator = True

            comparison = _compare(parsed_version, operand)

            if operator == "=":
                matches = comparison == 0
            elif operator == ">":
                matches = comparison > 0
            elif operator == ">=":
                matches = comparison >= 0
            elif operator == "<":
                matches = comparison < 0
            elif operator == "<=":
                matches = comparison <= 0
            elif operator == "^":
                major, minor, patch = operand[:3]
                if major > 0:
                    upper = (major + 1, 0, 0, None)
                elif minor > 0:
                    upper = (0, minor + 1, 0, None)
                else:
                    upper = (0, 0, patch + 1, None)
                matches = comparison >= 0 and _compare(parsed_version, upper) < 0
            else:  # "~"
                major, minor, _patch = operand[:3]
                upper = (major, minor + 1, 0, None)
                matches = comparison >= 0 and _compare(parsed_version, upper) < 0

            if not matches:
                group_matches = False
                break

        if (
            group_matches
            and parsed_version[3] is not None
            and not has_matching_prerelease_comparator
        ):
            group_matches = False

        if group_matches:
            satisfies_any_group = True

    return satisfies_any_group
