            # Quoted field: opening quote is the field's first character.
            i += 1
            chars = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    chars.append(ch)
                    i += 1
            fields.append("".join(chars))

            if i >= n:
                break
            if line[i] != ',':
                raise ValueError("unexpected character after closing quote")
            i += 1  # consume comma, continue with next field
        else:
            # Unquoted field: literal, may be empty, quotes are illegal.
            chars = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("double quote in unquoted field")
                chars.append(line[i])
                i += 1
            fields.append("".join(chars))

            if i >= n:
                break
            i += 1  # consume comma, continue with next field

    return fields
