**Requirements & edge cases I need to cover**

- Anchored, case-sensitive, whole-`name` match; pure stdlib, 3.9.
- `*` = run of non-`/` chars (possibly empty); `**` = any run including `/`; `?` = one non-`/` char.
- `[...]`: singles + ranges, `!` negation only right after `[`, leading `]` literal, unterminated `[` → `ValueError`.
- Backslash escapes the next char (also inside classes); trailing `\` → `ValueError`.
- Edge cases: empty pattern/name, `[]]`, `[!]` (leading `]` is literal → unterminated → error), `[a-]` (literal `a` and `-`, not a range), `[a-z-]`, `***` (equivalent to `**`), `\*`, `?` not matching `/`, `**` matching `"a/b"`, `[/]` matching `/`.**Design:** tokenize the pattern once (`lit` / `star` / `any` / `q` / `cls`), then simulate the token stream as an NFA over *sets of consumed-prefix positions* — no recursion, no catastrophic backtracking, and exact semantics for `*` vs `**`.

```python
"""Anchored, case-sensitive glob matching for path-like strings.

Syntax:
    *      any run of characters containing no '/'
    **     any run of characters, including '/' (the empty match included)
    ?      exactly one character that is not '/'
    [...]  one character from a set: single chars, ranges 'a-z', a leading '!'
           negates, a ']' first in the set is a literal ']'
    \\x    the literal character x
Malformed patterns (unterminated '[', trailing backslash) raise ValueError.
"""


def _read_class_char(pattern, i):
    """Return (character, next_index) for one possibly escaped class atom."""
    ch = pattern[i]
    if ch == "\\":
        if i + 1 >= len(pattern):
            raise ValueError("pattern ends with a lone backslash")
        return pattern[i + 1], i + 2
    return ch, i + 1


def _parse_class(pattern, i):
    """Parse the character class starting at pattern[i] == '['.

    Returns ((negated, items), index_after_closing_bracket), where items holds
    ('c', char) for single characters and ('r', lo, hi) for ranges.
    """
    n = len(pattern)
    i += 1                                        # consume '['
    negated = False
    if i < n and pattern[i] == "!":
        negated = True
        i += 1
    items = []
    if i < n and pattern[i] == "]":               # a leading ']' is a literal
        items.append(("c", "]"))
        i += 1
    while True:
        if i >= n:
            raise ValueError("unterminated character class")
        if pattern[i] == "]":
            i += 1
            break
        lo, i = _read_class_char(pattern, i)
        # A range needs '-' plus a following char that is not the closing ']',
        # so '[a-]' is the two characters 'a' and '-'.
        if i < n and pattern[i] == "-" and i + 1 < n and pattern[i + 1] != "]":
            hi, i = _read_class_char(pattern, i + 1)
            items.append(("r", lo, hi))
        else:
            items.append(("c", lo))
    return (negated, items), i


def _tokenize(pattern):
    """Turn a pattern into a flat list of (kind, argument) tokens."""
    tokens = []
    i, n = 0, len(pattern)
    while i < n:
        ch = pattern[i]
        if ch == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with a lone backslash")
            tokens.append(("lit", pattern[i + 1]))
            i += 2
        elif ch == "*":
            j = i
            while j < n and pattern[j] == "*":
                j += 1
            # A run of two or more '*' behaves exactly like '**' (any '*'
            # sequence containing one '**' can swallow any text), one is '*'.
            tokens.append(("any" if j - i >= 2 else "star", None))
            i = j
        elif ch == "?":
            tokens.append(("q", None))
            i += 1
        elif ch == "[":
            cls, i = _parse_class(pattern, i)
            tokens.append(("cls", cls))
        else:
            tokens.append(("lit", ch))
            i += 1
    return tokens


def _in_class(items, negated, ch):
    """True if `ch` is a member of the parsed class (after negation)."""
    hit = False
    for item in items:
        if item[0] == "c":
            if item[1] == ch:
                hit = True
                break
        elif item[1] <= ch <= item[2]:
            hit = True
            break
    return hit != negated


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches `pattern` (anchored)."""
    tokens = _tokenize(pattern)
    end = len(name)
    positions = {0}                    # reachable consumed-prefix lengths
    for kind, arg in tokens:
        reachable = set()
        if kind == "lit":
            for j in positions:
                if j < end and name[j] == arg:
                    reachable.add(j + 1)
        elif kind == "q":
            for j in positions:
                if j < end and name[j] != "/":
                    reachable.add(j + 1)
        elif kind == "cls":
            negated, items = arg
            for j in positions:
                if j < end and _in_class(items, negated, name[j]):
                    reachable.add(j + 1)
        elif kind == "star":
            for j in positions:
                k = j
                reachable.add(k)                       # the empty match
                while k < end and name[k] != "/":
                    k += 1
                    reachable.add(k)
        else:                                          # 'any', i.e. '**'
            if positions:
                for k in range(min(positions), end + 1):
                    reachable.add(k)
        if not reachable:
            return False
        positions = reachable
    return end in positions
