"""Arithmetic expression evaluator.

Grammar (whitespace allowed between any two tokens):

    expression := product (('+' | '-') product)*
    product    := unary (('*' | '/') unary)*
    unary      := '-' unary | power
    power      := atom ('^' unary)?          # right-associative
    atom       := NUMBER | '(' expression ')'

`-` is handled below the power level, so `-2 ^ 2 == -4`, while the
exponent position accepts a unary minus, so `2 ^ -1 == 0.5`.
"""

import re

__all__ = ["evaluate"]

_WHITESPACE = " \t\n\r\f\v"
_SYMBOLS = "+-*/^()"
_NUMBER_RE = re.compile(r"\d+\.\d+|\d+", re.ASCII)


def _tokenize(text):
    """Split `text` into ('number', value) / ('op', char) tokens."""
    tokens = []
    pos = 0
    length = len(text)
    while pos < length:
        char = text[pos]
        if char in _WHITESPACE:
            pos += 1
            continue
        if "0" <= char <= "9":  # ASCII digits only, unlike str.isdigit()
            match = _NUMBER_RE.match(text, pos)
            raw = match.group(0)
            pos = match.end()
            if "." in raw:
                tokens.append(("number", float(raw)))
            else:
                tokens.append(("number", int(raw)))
            continue
        if char in _SYMBOLS:
            tokens.append(("op", char))
            pos += 1
            continue
        raise ValueError(
            "invalid character {!r} in expression {!r}".format(char, text)
        )
    return tokens


def _true_divide(left, right):
    if right == 0:
        raise ValueError("division by zero")
    try:
        return left / right
    except ZeroDivisionError:
        raise ValueError("division by zero") from None


def _power(base, exponent):
    try:
        return base ** exponent
    except ZeroDivisionError:  # e.g. 0 ^ -1
        raise ValueError("division by zero") from None


class _Parser:
    __slots__ = ("_text", "_tokens", "_pos")

    def __init__(self, text, tokens):
        self._text = text
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _take(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _fail(self, message):
        raise ValueError("invalid expression {!r}: {}".format(self._text, message))

    def parse(self):
        if not self._tokens:
            self._fail("empty expression")
        value = self._parse_sum()
        token = self._peek()
        if token is not None:
            self._fail("unexpected token {!r}".format(token[1]))
        return value

    def _parse_sum(self):
        value = self._parse_product()
        while True:
            token = self._peek()
            if token is None or token[0] != "op" or token[1] not in "+-":
                return value
            self._take()
            operand = self._parse_product()
            value = value + operand if token[1] == "+" else value - operand

    def _parse_product(self):
        value = self._parse_unary()
        while True:
            token = self._peek()
            if token is None or token[0] != "op" or token[1] not in "*/":
                return value
            self._take()
            operand = self._parse_unary()
            if token[1] == "*":
                value = value * operand
            else:
                value = _true_divide(value, operand)

    def _parse_unary(self):
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] == "-":
            self._take()
            return -self._parse_unary()
        return self._parse_power()

    def _parse_power(self):
        base = self._parse_atom()
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] == "^":
            self._take()
            # Recursing into the unary level keeps `^` right-associative
            # and lets the exponent begin with a unary minus.
            exponent = self._parse_unary()
            return _power(base, exponent)
        return base

    def _parse_atom(self):
        token = self._peek()
        if token is None:
            self._fail("unexpected end of expression")
        kind, value = token
        if kind == "number":
            self._take()
            return value
        if value == "(":
            self._take()
            inner = self._parse_sum()
            closing = self._peek()
            if closing is None or closing[0] != "op" or closing[1] != ")":
                self._fail("unbalanced parentheses")
            self._take()
            return inner
        self._fail("unexpected token {!r}".format(value))


def evaluate(expr: str):
    """Evaluate an arithmetic expression and return an `int` or `float`.

    Raises `ValueError` for malformed input and for division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError(
            "expression must be a string, got {}".format(type(expr).__name__)
        )
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("invalid expression {!r}: empty expression".format(expr))
    return _Parser(expr, tokens).parse()
