from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]], duration: int, start: int, end: int
) -> Optional[int]:
    """Return the earliest t with start <= t, t + duration <= end, and
    [t, t + duration) disjoint from every busy interval [begin, finish).

    Busy intervals are half-open, may be unsorted, and may overlap or touch.
    The input list is never modified. Returns None if no slot fits.

    Raises ValueError if duration is not a positive integer, or if any busy
    interval has begin >= finish.
    """
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError(f"duration must be a positive integer, got {duration!r}")

    # Validate every interval, then keep only what intersects the window,
    # clipped to [start, end). Work happens on a fresh list.
    clipped: List[Tuple[int, int]] = []
    for interval in busy:
        begin, finish = interval
        if begin >= finish:
            raise ValueError(
                f"busy interval must satisfy begin < finish, got {interval!r}"
            )
        if finish > start and begin < end:
            clipped.append((begin if begin > start else start,
                            finish if finish < end else end))

    clipped.sort()

    t = start
    for begin, finish in clipped:
        if begin > t:
            if begin - t >= duration:
                return t
            t = finish
        elif finish > t:
            t = finish

    if end - t >= duration:
        return t
    return None
