import re

_CANONICAL_RE = re.compile(
    r"M{0,3}"            # thousands: 0-3 M
    r"(CM|CD|D?C{0,3})"  # hundreds
    r"(XC|XL|L?X{0,3})"  # tens
    r"(IX|IV|V?I{0,3})"  # units
)

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1..3999) to an int.

    Raises ValueError for any non-canonical input: "", lowercase, "IIII",
    "IC", "VX", "IIV", "XXXX", "MMMM", junk characters, and so on.
    """
    if not isinstance(s, str):
        raise ValueError(f"expected str, got {type(s).__name__}")
    # fullmatch against the canonical grammar; the empty string fails only
    # because every alternative here permits zero symbols, so check it first.
    if not s or not _CANONICAL_RE.fullmatch(s):
        raise ValueError(f"not a canonical Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _VALUES[ch]
        # subtract when a smaller symbol precedes a larger one
        if i + 1 < len(s) and value < _VALUES[s[i + 1]]:
            total -= value
        else:
            total += value
    return total
