    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        n = len(part)
        # Each part must be 1-3 characters long.
        if n < 1 or n > 3:
            return False
        # Every character must be an ASCII digit (0-9).
        for ch in part:
            if ch < "0" or ch > "9":
                return False
        # No leading zeros unless the part is exactly "0".
        if n > 1 and part[0] == "0":
            return False
        # Value must fit in a byte.
        if int(part) > 255:
            return False

