            raise ValueError("cron item %r out of range %d-%d" % (item, lo, hi))
        values.update(range(start, end + 1, step))
    if not values:
        raise ValueError("cron field %r selects nothing" % text)
    return values


def _day_matches(day, dom, dow, dom_star, dow_star):
    dom_ok = day.day in dom
    dow_ok = ((day.weekday() + 1) % 7) in dow
    if dom_star and dow_star:
        return True
    if dom_star:
        return dow_ok
    if dow_star:
        return dom_ok
    return dom_ok or dow_ok


def next_cron(expr: str, after: str) -> str:
    if not isinstance(expr, str):
        raise ValueError("cron expression must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    dom = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dow = _parse_field(fields[4], 0, 6)
    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    start = datetime.datetime.strptime(after, "%Y-%m-%d %H:%M")
    try:
        limit = start.replace(year=start.year + 5)
    except ValueError:
        limit = start.replace(year=start.year + 5, day=28)

    combos = sorted((h, m) for h in hours for m in minutes)
    skip = bisect_left(combos, (start.hour, start.minute + 1))

    day = start.date()
    last_day = limit.date()
    first = True
    while day <= last_day:
        if day.month in months and _day_matches(day, dom, dow, dom_star, dow_star):
            for h, m in (combos[skip:] if first else combos):
                when = datetime.datetime.combine(day, datetime.time(h, m))
                if when > limit:
                    break
                if when > start:
                    return when.strftime("%Y-%m-%d %H:%M")
        first = False
        day += datetime.timedelta(days=1)

    raise ValueError("no matching time within 5 years for %r" % expr)
