def next_weekday(date_str: str, weekday: int) -> str:
    """Return the first date strictly after ``date_str`` falling on ``weekday``.

    ``date_str`` is 'YYYY-MM-DD'; ``weekday`` is 0 (Monday) .. 6 (Sunday).
    If ``date_str`` already falls on ``weekday``, the result is 7 days later.
    """
    if not isinstance(weekday, int) or isinstance(weekday, bool):
        raise ValueError("weekday must be an int in the range 0 to 6")
    if not 0 <= weekday <= 6:
        raise ValueError("weekday must be in the range 0 to 6")

    start = date.fromisoformat(date_str)
    offset = (weekday - start.weekday()) % 7
    if offset == 0:
        offset = 7
    return (start + timedelta(days=offset)).isoformat()


