def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1..3999) to an int.

    Raises ValueError for anything that is not the canonical form.
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    if not isinstance(s, str) or not s:
        raise ValueError("not a canonical Roman numeral: %r" % (s,))

    for ch in s:
        if ch not in values:
            raise ValueError("not a canonical Roman numeral: %r" % (s,))

    total = 0
    prev = 0
    for ch in reversed(s):
        v = values[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v

    if not 1 <= total <= 3999:
        raise ValueError("out of range: %r" % (s,))

    pairs = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )
    n = total
    parts = []
    for value, numeral in pairs:
        count, n = divmod(n, value)
        if count:
            parts.append(numeral * count)

    if "".join(parts) != s:
        raise ValueError("not a canonical Roman numeral: %r" % (s,))

    return total
