def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 1024:
        return f"{n} B"
    units = ("KiB", "MiB", "GiB", "TiB")
    k = 1
    while k < 4 and n >= 1024 ** (k + 1):
        k += 1
    d = 1024 ** k
    q, r = divmod(n * 10, d)
    if 2 * r >= d:
        q += 1
    while q == 10240 and k < 4:
        k += 1
        d = 1024 ** k
        q, r = divmod(n * 10, d)
        if 2 * r >= d:
            q += 1
    return f"{q // 10}.{q % 10} {units[k - 1]}"
