# Single-character digit values used while scanning.
_DIGIT_VALUE = {
    "I": 1, "V": 5, "X": 10, "L": 50,
    "C": 100, "D": 500, "M": 1000,
}


def _to_roman(n: int) -> str:
    """Greedy canonical representation of 1 <= n <= 3999."""
    parts = []
    for value, symbol in _ROMAN_VALUES:
        count, n = divmod(n, value)
        if count:
            parts.append(symbol * count)
    return "".join(parts)


def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    total = 0
    for i, ch in enumerate(s):
        if ch not in _DIGIT_VALUE:
            raise ValueError("invalid Roman character: %r" % (ch,))
        value = _DIGIT_VALUE[ch]
        nxt = _DIGIT_VALUE.get(s[i + 1], 0) if i + 1 < len(s) else 0
        total += -value if nxt > value else value

    # Reject out-of-range results and non-canonical spellings (IIII, IC, VX, ...).
    if not 1 <= total <= 3999 or _to_roman(total) != s:
        raise ValueError("non-canonical Roman numeral: %r" % (s,))
    return total
