def glob_match(pattern: str, name: str) -> bool:
    L = len(pattern)
    tokens = []
    i = 0
    while i < L:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= L:
                raise ValueError("pattern ends with a lone backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '*':
            if i + 1 < L and pattern[i + 1] == '*':
                tokens.append(('any', None))
                i += 2
            else:
                tokens.append(('star', None))
                i += 1
        elif c == '?':
            tokens.append(('qmark', None))
            i += 1
        elif c == '[':
            j = i + 1
            negate = False
            if j < L and pattern[j] == '!':
                negate = True
                j += 1
            items = []
            if j < L and pattern[j] == ']':
                items.append((']', ']'))
                j += 1
            closed = False
            while j < L:
                ch = pattern[j]
                if ch == ']':
                    j += 1
                    closed = True
                    break
                if ch == '\\':
                    if j + 1 >= L:
                        raise ValueError("unterminated character set")
                    lo = pattern[j + 1]
                    j += 2
                else:
                    lo = ch
                    j += 1
                if j < L and pattern[j] == '-' and j + 1 < L and pattern[j + 1] != ']':
                    if pattern[j + 1] == '\\':
                        if j + 2 >= L:
                            raise ValueError("unterminated character set")
                        hi = pattern[j + 2]
                        j += 3
                    else:
                        hi = pattern[j + 1]
                        j += 2
                    if lo > hi:
                        raise ValueError("invalid character range in set")
                    items.append((lo, hi))
                else:
                    items.append((lo, lo))
            if not closed:
                raise ValueError("unterminated character set")
            tokens.append(('set', (negate, items)))
            i = j
        else:
            tokens.append(('lit', c))
            i += 1

    n = len(name)
    positions = {0}
    for kind, val in tokens:
        nxt = set()
        if kind == 'lit':
            for p in positions:
                if p < n and name[p] == val:
                    nxt.add(p + 1)
        elif kind == 'qmark':
            for p in positions:
                if p < n and name[p] != '/':
                    nxt.add(p + 1)
        elif kind == 'star':
            for p in positions:
                nxt.add(p)
                k = p
                while k < n and name[k] != '/':
                    k += 1
                    nxt.add(k)
        elif kind == 'any':
            nxt = set(range(min(positions), n + 1))
        else:  # 'set'
            negate, items = val
            for p in positions:
                if p < n:
                    ch = name[p]
                    inside = any(lo <= ch <= hi for lo, hi in items)
                    if inside != negate:
                        nxt.add(p + 1)
        positions = nxt
        if not positions:
            return False
    return n in positions
