        )
        self.assertEqual(earliest_slot([(0, 15)], 5, 10, 30), 15)
        self.assertEqual(earliest_slot([(25, 50)], 5, 10, 30), 10)
        self.assertIsNone(earliest_slot([(0, 50)], 5, 10, 30))

    def test_no_sufficient_gap(self):
