        self.assertIsNone(earliest_slot([], 1, 20, 10))

    def test_invalid_duration(self):
        for duration in (0, -1, 1.0, "1", None, True, False):
            with self.subTest(duration=duration):
                with self.assertRaises(ValueError):
                    earliest_slot([], duration, 0, 10)

    def test_invalid_intervals_always_raise(self):
        for busy in ([(5, 5)], [(8, 3)], [(100, 100)],
                     [(20, 30), (100, 90)]):
            for start, end in ((0, 10), (10, 10), (20, 10)):
                with self.subTest(busy=busy, start=start, end=end):
                    with self.assertRaises(ValueError):
                        earliest_slot(busy, 1, start, end)

    def test_input_is_not_modified(self):
        busy = [(20, 30), (5, 15), (10, 25)]
        original = busy.copy()
        self.assertEqual(earliest_slot(busy, 5, 0, 40), 0)
        self.assertEqual(busy, original)

    def test_against_exhaustive_small_reference(self):
        from itertools import combinations

        intervals = [
            (begin, finish)
            for begin in range(-1, 5)
            for finish in range(begin + 1, 6)
        ]
        for count in range(3):
            for busy_tuple in combinations(intervals, count):
                busy = list(reversed(busy_tuple))
                for duration in range(1, 6):
                    expected = next(
                        (
                            t
                            for t in range(0, 5 - duration + 1)
                            if all(
                                t + duration <= begin or t >= finish
                                for begin, finish in busy
                            )
                        ),
                        None,
                    )
                    self.assertEqual(
                        earliest_slot(busy, duration, 0, 5), expected
                    )


def earliest_slot(
    busy: List[Tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest free start time within [start, end), if any."""
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, including those outside the search window.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    candidate = start
    if candidate + duration > end:
        return None

    # Sorting creates a new list, leaving the caller's list unchanged.
    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue
        if candidate + duration <= begin:
            return candidate

        # This interval overlaps the candidate slot; skip its busy time.
        candidate = finish
        if candidate + duration > end:
            return None

    return candidate


