import unittest


def leftmost_index(a, x):
    """Return the smallest index i such that a[i] == x, or -1 if x is not in a.

    `a` is a list of integers sorted in non-decreasing order (duplicates
    allowed, possibly empty). Iterative binary search: O(log len(a)) time,
    O(1) extra space.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo if lo < len(a) and a[lo] == x else -1


