# Requirements:
# 1. Recognize ASCII integers, decimals with digits on both sides of the dot,
#    operators, and parentheses; ignore whitespace between tokens.
# 2. Apply the specified precedence and associativity. Unary minus binds below
#    exponentiation and is allowed at the start of an exponent.
# 3. Preserve Python numeric behavior, using true division and exponentiation.
# 4. Validate the entire expression before evaluating it, and convert division
#    by zero into ValueError.
#
# Edge cases:
# - Reject empty input, unknown characters, incomplete decimals, adjacent
#   operands, implicit multiplication, unary plus, and missing operands.
# - Reject empty or unbalanced parentheses and unsupported operators like **.
# - Support repeated unary minus, negative exponents, and nested parentheses.
# - Use an iterative parser so nesting does not consume Python's call stack.


def evaluate(expr: str):
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3, "^": 4}
    output = []
    operators = []
    expecting_operand = True
    i = 0
    length = len(expr)

    def is_digit(char):
        return "0" <= char <= "9"

    # Convert to postfix notation, checking syntax before doing arithmetic.
    while i < length:
        char = expr[i]

        if char.isspace():
            i += 1
            continue

        if is_digit(char):
            if not expecting_operand:
                raise ValueError("Missing operator between operands")

            start = i
            while i < length and is_digit(expr[i]):
                i += 1

            decimal = i < length and expr[i] == "."
            if decimal:
                i += 1
                if i == length or not is_digit(expr[i]):
                    raise ValueError("Decimal point must be followed by digits")
                while i < length and is_digit(expr[i]):
                    i += 1

            literal = expr[start:i]
            output.append(float(literal) if decimal else int(literal))
            expecting_operand = False
            continue

        if char == "(":
            if not expecting_operand:
                raise ValueError("Implicit multiplication is not allowed")
            operators.append(char)
            i += 1
            continue

        if char == ")":
            if expecting_operand:
                raise ValueError("Missing operand before closing parenthesis")

            while operators and operators[-1] != "(":
                output.append(operators.pop())

            if not operators:
                raise ValueError("Unmatched closing parenthesis")

            operators.pop()
            i += 1
            continue

        if char in "+-*/^":
            if expecting_operand:
                if char != "-":
                    raise ValueError("Expected an operand")
                # A prefix operator never reduces operators to its left.
                # This permits both -2^2 and 2^-1 with the required meanings.
                operators.append("neg")
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] < precedence[char]:
                        break
                    if precedence[top] == precedence[char] and char == "^":
                        break
                    output.append(operators.pop())

                operators.append(char)
                expecting_operand = True

            i += 1
            continue

        raise ValueError("Unknown character: {!r}".format(char))

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        operator = operators.pop()
        if operator == "(":
            raise ValueError("Unmatched opening parenthesis")
        output.append(operator)

    values = []
    try:
        for token in output:
            if not isinstance(token, str):
                values.append(token)
                continue

            if token == "neg":
                values.append(-values.pop())
                continue

            right = values.pop()
            left = values.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:
                result = left ** right

            values.append(result)
    except ZeroDivisionError as exc:
        raise ValueError("Division by zero") from exc

    return values[0]
