def _reference(deps: dict[str, list[str]]) -> list[str]:
    """Slow but obviously correct O(n^2) model of the required rule."""
    mentioned = set(deps)
    for reqs in deps.values():
        mentioned.update(reqs)
    prereqs = {node: set(deps.get(node, ())) for node in mentioned}
    placed: list[str] = []
    placed_set: set[str] = set()
    remaining = set(mentioned)
    while remaining:
        ready = sorted(n for n in remaining if prereqs[n] <= placed_set)
        if not ready:
            raise ValueError("cycle")
        chosen = ready[0]
        placed.append(chosen)
        placed_set.add(chosen)
        remaining.discard(chosen)
    return placed


