# Implementation (written to pass the tests above)
# ---------------------------------------------------------------------------


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """Order items so every item comes after all of its dependencies.

    Ties are broken by picking the lexicographically smallest item that is
    currently ready, which makes the result fully deterministic.  A cycle
    (including a self-dependency) raises ValueError.  The input is not
    modified.
    """
    # 1. Every name mentioned anywhere -- as a key or inside a list.
    nodes: set[str] = set()
    for item, required in deps.items():
        nodes.add(item)
        nodes.update(required)

    # 2. Unique prerequisites per item: duplicates collapse here.
    prereqs: dict[str, set[str]] = {node: set() for node in nodes}
    for item, required in deps.items():
        prereqs[item].update(required)

    # 3. Reverse edges: which items each node is currently blocking.
    dependents: dict[str, list[str]] = {node: [] for node in nodes}
    for item, reqs in prereqs.items():
        for req in reqs:
            dependents[req].append(item)

    # 4. Kahn's algorithm with a min-heap as the ready queue, so the
    #    lexicographically smallest ready item is always emitted first.
    outstanding = {node: len(prereqs[node]) for node in nodes}
    ready = [node for node in nodes if outstanding[node] == 0]
    heapq.heapify(ready)

    order: list[str] = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            outstanding[dependent] -= 1
            if outstanding[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("dependency graph contains a cycle")
    return order


