            if current_words:
                lines.append(" ".join(current_words))
                current_words = []
                current_length = 0

            last_start = ((len(word) - 1) // width) * width
            for start in range(0, last_start, width):
                lines.append(word[start:start + width])

            current_words = [word[last_start:]]
            current_length = len(current_words[0])
        elif not current_words:
            current_words = [word]
            current_length = len(word)
        elif current_length + 1 + len(word) <= width:
            current_words.append(word)
            current_length += 1 + len(word)
        else:
            lines.append(" ".join(current_words))
            current_words = [word]
            current_length = len(word)

    if current_words:
        lines.append(" ".join(current_words))

