def rle_decode(s: str) -> str:
    parts = []
    total_length = 0
    i = 0

    while i < len(s):
        count_start = i
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1

        if i == count_start:
            raise ValueError("missing count")

        count_text = s[count_start:i]
        if count_text[0] == "0":
            raise ValueError("count must be positive and have no leading zeros")

        if i == len(s):
            raise ValueError("input ends with digits")

        count = int(count_text)
        total_length += count
        if total_length > 10000:
            raise ValueError("decoded output exceeds 10000 characters")

        parts.append(s[i] * count)
        i += 1

    return "".join(parts)
