def shell_split(s: str) -> list[str]:
    words: list[str] = []
    buf: list[str] = []
    in_word = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            if in_word:
                words.append(''.join(buf))
                buf = []
                in_word = False
            i += 1

        elif c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            buf.append(s[i + 1])
            in_word = True
            i += 2

        elif c == "'":
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            buf.append(s[i + 1:j])
            in_word = True
            i = j + 1

        elif c == '"':
            i += 1
            closed = False
            while i < n:
                d = s[i]
                if d == '"':
                    closed = True
                    i += 1
                    break
                if d == '\\':
                    if i + 1 < n and s[i + 1] in ('"', '\\'):
                        buf.append(s[i + 1])
                        i += 2
                    else:
                        buf.append('\\')
                        i += 1
                else:
                    buf.append(d)
                    i += 1
            if not closed:
                raise ValueError("unterminated double quote")
            in_word = True

        else:
            buf.append(c)
            in_word = True
            i += 1

    if in_word:
        words.append(''.join(buf))

    return words
