def mask_email(s: str) -> str:
    # Requirement: exactly one "@", with a non-empty local part and domain.
    if s.count("@") != 1:
        raise ValueError("expected exactly one '@' in the string")
    local, domain = s.split("@")
    if not local or not domain:
        raise ValueError("local part and domain must both be non-empty")

    # Edge case: single-character local part is fully masked.
    if len(local) == 1:
        masked = "*"
    # Edge case: two-character local part keeps only the first character.
    elif len(local) == 2:
        masked = local[0] + "*"
    # General case: keep first and last, mask everything in between.
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
