def shell_split(s):
    """Split a command line into words using a small subset of POSIX rules.

    Raises ValueError on a trailing backslash or an unterminated quote.
    """
    words = []
    cur = []
    in_word = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == " " or c == "\t":
            if in_word:
                words.append("".join(cur))
                cur = []
                in_word = False
            i += 1
            continue

        in_word = True

        if c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            cur.append(s[i + 1])
            i += 2

        elif c == "'":
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            cur.append(s[i + 1:j])
            i = j + 1

        elif c == '"':
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                d = s[i]
                if d == '"':
                    i += 1
                    break
                if d == "\\":
                    nxt = s[i + 1] if i + 1 < n else None
                    if nxt == '"' or nxt == "\\":
                        cur.append(nxt)
                        i += 2
                    else:
                        cur.append("\\")
                        i += 1
                else:
                    cur.append(d)
                    i += 1

        else:
            cur.append(c)
            i += 1

    if in_word:
        words.append("".join(cur))

    return words


