# solution.py — complete solution, Python 3.9, standard library only.


def mask_email(s: str) -> str:
    """Mask the local part of an email address, keeping the domain unchanged.

    The local part keeps its first and last characters; every character
    between them is replaced with "*". A one-character local part becomes
    "*", and a two-character local part keeps only its first character.

    Raises:
        ValueError: if ``s`` does not contain exactly one "@" with a
            non-empty local part before it and a non-empty domain after it.
    """
    if s.count("@") != 1:
        raise ValueError("string must contain exactly one '@'")

    local, domain = s.split("@")

    if not local:
        raise ValueError("local part must be non-empty")
    if not domain:
        raise ValueError("domain must be non-empty")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
