def glob_match(pattern: str, name: str) -> bool:
    tokens = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            if i + 1 >= len(pattern):
                raise ValueError("trailing backslash in pattern")
            tokens.append(("literal", pattern[i + 1]))
            i += 2
            continue

        if char == "*":
            start = i
            while i < len(pattern) and pattern[i] == "*":
                i += 1
            tokens.append(("globstar" if i - start >= 2 else "star", None))
            continue

        if char == "?":
            tokens.append(("question", None))
            i += 1
            continue

        if char == "[":
            i += 1
            negated = False

            if i < len(pattern) and pattern[i] == "!":
                negated = True
                i += 1

            atoms = []

            if i < len(pattern) and pattern[i] == "]":
                atoms.append("]")
                i += 1

            while True:
                if i >= len(pattern):
                    raise ValueError("unterminated character class")

                if pattern[i] == "]":
                    i += 1
                    break

                if pattern[i] == "\\":
                    if i + 1 >= len(pattern):
                        raise ValueError("trailing backslash in pattern")
                    atoms.append(pattern[i + 1])
                    i += 2
                else:
                    atoms.append(pattern[i])
                    i += 1

            literals = set()
            ranges = []
            j = 0

            while j < len(atoms):
                if (
                    j + 2 < len(atoms)
                    and atoms[j + 1] == "-"
                    and atoms[j] != "-"
                ):
                    ranges.append((atoms[j], atoms[j + 2]))
                    j += 3
                else:
                    literals.add(atoms[j])
                    j += 1

            tokens.append(("class", (negated, literals, ranges)))
            continue

        tokens.append(("literal", char))
        i += 1

    current = [False] * (len(name) + 1)
    current[0] = True

    for kind, value in tokens:
        next_state = [False] * (len(name) + 1)

        if kind == "literal":
            for position in range(len(name)):
                if current[position] and name[position] == value:
                    next_state[position + 1] = True

        elif kind == "question":
            for position in range(len(name)):
                if current[position] and name[position] != "/":
                    next_state[position + 1] = True

        elif kind == "star":
            next_state[0] = current[0]
            for position in range(1, len(name) + 1):
                if name[position - 1] != "/":
                    next_state[position] = (
                        current[position] or next_state[position - 1]
                    )

        elif kind == "globstar":
            next_state[0] = current[0]
            for position in range(1, len(name) + 1):
                next_state[position] = (
                    current[position] or next_state[position - 1]
                )

        elif kind == "class":
            negated, literals, ranges = value

            for position in range(len(name)):
                if not current[position]:
                    continue

                candidate = name[position]
                matched = candidate in literals or any(
                    start <= candidate <= end for start, end in ranges
                )

                if negated:
                    matched = not matched

                if matched:
                    next_state[position + 1] = True

        current = next_state

    return current[len(name)]
