from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    """Greedily wrap `text` into lines of at most `width` characters.

    Words are runs of characters delimited by one or more U+0020 spaces.
    Words longer than `width` are split into exact `width`-sized pieces,
    the final short piece starting a line that may continue with further words.
    """
    if width < 1:
        raise ValueError("width must be >= 1")

    words = [w for w in text.split(" ") if w]
    lines: List[str] = []
    current = ""

    for word in words:
        if len(word) <= width:
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        else:
            if current:
                lines.append(current)
                current = ""
            full, rest = divmod(len(word), width)
            for i in range(full):
                lines.append(word[i * width:(i + 1) * width])
            if rest:
                current = word[full * width:]

    if current:
        lines.append(current)

    return lines
