import re

_VERSION_RE = re.compile(r"^([0-9]+(?:\.[0-9]+)*)(?:-([A-Za-z0-9]+))?$")


def compare_versions(a: str, b: str) -> int:
    def parse(v):
        if not isinstance(v, str):
            raise ValueError("version must be a string")
        m = _VERSION_RE.match(v)
        if m is None:
            raise ValueError("invalid version: %r" % (v,))
        nums = [int(part) for part in m.group(1).split(".")]
        return nums, m.group(2)

    na, ta = parse(a)
    nb, tb = parse(b)

    width = max(len(na), len(nb))
    na = na + [0] * (width - len(na))
    nb = nb + [0] * (width - len(nb))

    if na < nb:
        return -1
    if na > nb:
        return 1

    if ta is None and tb is None:
        return 0
    if ta is None:
        return 1
    if tb is None:
        return -1
    if ta < tb:
        return -1
    if ta > tb:
        return 1
    return 0
