from datetime import date, timedelta


def next_weekday(date_str: str, weekday: int) -> str:
    """Return the first date strictly after date_str falling on weekday (0=Mon..6=Sun)."""
    if not isinstance(weekday, int) or isinstance(weekday, bool):
        raise ValueError("weekday must be an integer in the range 0 to 6")
    if weekday < 0 or weekday > 6:
        raise ValueError("weekday must be in the range 0 to 6")

    current = date.fromisoformat(date_str)
    days_ahead = (weekday - current.weekday()) % 7
    if days_ahead == 0:
        days_ahead = 7
    return (current + timedelta(days=days_ahead)).isoformat()
