_DATE_PATTERN = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _parse_date(s: str) -> datetime.date:
    if not isinstance(s, str):
        raise ValueError(
            "Date must be a string in YYYY-MM-DD format, got "
            + type(s).__name__
        )
    if _DATE_PATTERN.fullmatch(s) is None:
        raise ValueError(
            "Invalid date format: {0!r} (expected exactly YYYY-MM-DD "
            "with ASCII digits and no extra characters)".format(s)
        )
    year = int(s[0:4])
    month = int(s[5:7])
    day = int(s[8:10])
    try:
        return datetime.date(year, month, day)
    except ValueError as exc:
        raise ValueError("Not a real calendar date: {0!r}".format(s)) from exc


def days_between(a: str, b: str) -> int:
    date_a = _parse_date(a)
    date_b = _parse_date(b)
    return abs((date_b - date_a).days)
