def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}

    # Split only on U+0020; any other whitespace stays inside a token and fails.
    tokens = [tok for tok in s.split(" ") if tok != ""]
    if not tokens:
        raise ValueError("empty duration string")

    seen = set()
    total = 0

    for tok in tokens:
        i = 0
        n = len(tok)
        while i < n:
            j = i
            while j < n and "0" <= tok[j] <= "9":
                j += 1
            if j == i:
                raise ValueError("expected a number")
            if j >= n:
                raise ValueError("number without a unit")
            unit = tok[j]
            if unit not in units:
                raise ValueError("unknown unit: %r" % (unit,))
            if unit in seen:
                raise ValueError("repeated unit: %r" % (unit,))
            seen.add(unit)
            total += int(tok[i:j]) * units[unit]
            i = j + 1

    return total
