```python
"""Semantic version matching: SemVer 2.0 ordering with npm-style constraints."""

import re

__all__ = ["semver_satisfies"]

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."                            # major
    r"(0|[1-9][0-9]*)\."                            # minor
    r"(0|[1-9][0-9]*)"                              # patch
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"    # pre-release (validated further)
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"   # build metadata (ignored)
)

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")
_ANY = "*"


# --------------------------------------------------------------------------- #
# versions
# --------------------------------------------------------------------------- #

def _parse_version(text):
    """Return (major, minor, patch, pre_release).

    ``pre_release`` is a tuple of identifiers, or None when the version has no
    pre-release tag.  Build metadata is discarded.
    """
    if not isinstance(text, str):
        raise ValueError("version must be a string, got %r" % (text,))
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))
    major, minor, patch = (int(match.group(i)) for i in (1, 2, 3))
    raw_pre = match.group(4)
    pre_release = None
    if raw_pre is not None:
        identifiers = raw_pre.split(".")
        for identifier in identifiers:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("invalid numeric pre-release identifier: %r" % (text,))
        pre_release = tuple(identifiers)
    return (major, minor, patch, pre_release)


def _compare_identifiers(left, right):
    left_numeric = left.isdigit()
    right_numeric = right.isdigit()
    if left_numeric and right_numeric:
        left_value, right_value = int(left), int(right)
        return (left_value > right_value) - (left_value < right_value)
    if left_numeric:
        return -1
    if right_numeric:
        return 1
    return (left > right) - (left < right)


def _compare_pre_releases(left, right):
    if left is None and right is None:
        return 0
    if left is None:
        return 1                       # no pre-release sorts higher
    if right is None:
        return -1
    for left_id, right_id in zip(left, right):
        result = _compare_identifiers(left_id, right_id)
        if result:
            return result
    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left, right):
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1
    return _compare_pre_releases(left[3], right[3])


# --------------------------------------------------------------------------- #
# constraints
# --------------------------------------------------------------------------- #

def _parse_comparator(token):
    """Return (operator, version, written_with_pre_release); operator ^ / ~ stay as-is."""
    if token == _ANY:
        return (_ANY, None, False)
    operator = "="
    remainder = token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            operator = candidate
            remainder = token[len(candidate):]
            break
    if remainder == "":
        raise ValueError("invalid comparator: %r" % (token,))
    version = _parse_version(remainder)
    return (operator, version, version[3] is not None)


def _parse_constraint(constraint):
    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string, got %r" % (constraint,))
    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty constraint: %r" % (constraint,))
        groups.append([_parse_comparator(token) for token in tokens])
    return groups


def _caret_upper(version):
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper(version):
    return (version[0], version[1] + 1, 0, None)


def _comparator_matches(operator, version, candidate):
    if operator == _ANY:
        return True
    if operator == "=":
        return _compare_versions(candidate, version) == 0
    if operator == ">":
        return _compare_versions(candidate, version) > 0
    if operator == ">=":
        return _compare_versions(candidate, version) >= 0
    if operator == "<":
        return _compare_versions(candidate, version) < 0
    if operator == "<=":
        return _compare_versions(candidate, version) <= 0
    if operator == "^":
        return (_compare_versions(candidate, version) >= 0
                and _compare_versions(candidate, _caret_upper(version)) < 0)
    if operator == "~":
        return (_compare_versions(candidate, version) >= 0
                and _compare_versions(candidate, _tilde_upper(version)) < 0)
    raise ValueError("unknown operator: %r" % (operator,))


def _group_matches(comparators, candidate):
    for operator, version, _written_with_pre in comparators:
        if not _comparator_matches(operator, version, candidate):
            return False
    if candidate[3] is not None:
        # A pre-release version needs a comparator that itself carries a
        # pre-release tag on the very same MAJOR.MINOR.PATCH.
        for operator, version, written_with_pre in comparators:
            if operator != _ANY and written_with_pre and version[:3] == candidate[:3]:
                return True
        return False
    return True


def semver_satisfies(version, constraint):
    """Return True when ``version`` satisfies ``constraint``.

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty constraint (or group).
    """
    candidate = _parse_version(version)
    groups = _parse_constraint(constraint)
    return any(_group_matches(group, candidate) for group in groups)
