from typing import Optional


def earliest_slot(
    busy: list[tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest available start time, or None if no slot fits."""
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, even if the meeting cannot fit in the window.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    latest_start = end - duration
    if start > latest_start:
        return None

    candidate = start

    # sorted() creates a new list and leaves the input unchanged.
    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        if candidate + duration <= begin:
            return candidate

        candidate = finish
        if candidate > latest_start:
            return None

    return candidate
