from typing import List, Optional, Tuple


def earliest_slot(busy: List[Tuple[int, int]], duration: int, start: int, end: int) -> Optional[int]:
    """Earliest t with start <= t and t + duration <= end such that [t, t + duration)
    overlaps no busy interval ([begin, finish) half-open). None if there is no such t."""
    # --- validation -------------------------------------------------------
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    intervals = list(busy)  # copy: the caller's list is never mutated
    for begin, finish in intervals:
        if begin >= finish:
            raise ValueError("each busy interval must satisfy begin < finish")

    if start + duration > end:  # window too small for any slot
        return None

    # --- clip busy intervals to the window, drop the ones outside it ------
    clipped = []
    for begin, finish in intervals:
        if begin < start:
            begin = start
        if finish > end:
            finish = end
        if begin < finish:  # still a non-empty overlap with [start, end)
            clipped.append((begin, finish))

    clipped.sort()

    # --- sweep: advance past each busy block, return the first gap that fits
    candidate = start
    for begin, finish in clipped:
        if candidate + duration <= begin:
            return candidate
        if finish > candidate:
            candidate = finish

    return candidate if candidate + duration <= end else None
