        i += 1

    if i == n:
        raise ValueError("duration must contain at least one part")

    while i < n:
        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if i == start or i == n or s[i] not in units:
            raise ValueError("expected an integer followed immediately by a unit")

        unit = s[i]
        if unit in seen:
            raise ValueError("repeated unit")
        seen.add(unit)

        total += int(s[start:i]) * units[unit]
        i += 1

        while i < n and s[i] == " ":
            i += 1

        if i < n and not ("0" <= s[i] <= "9"):
            raise ValueError("invalid character")

    return total
