def mask_email(s: str) -> str:
    """Mask the local part of an email address, keeping the domain intact.

    The first and last characters of the local part are preserved; every
    character between them becomes ``*``.  Local parts of length 1 become
    ``*``; local parts of length 2 keep the first character and mask the
    second.  Raises ValueError unless the input has exactly one ``@`` with
    a non-empty local part and a non-empty domain.
    """
    if not isinstance(s, str):
        raise ValueError("email address must be a string")

    if s.count("@") != 1:
        raise ValueError("email address must contain exactly one '@'")

    local, domain = s.split("@")

    if not local:
        raise ValueError("email address must have a non-empty local part")
    if not domain:
        raise ValueError("email address must have a non-empty domain")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
