import re


_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_OPERATORS = ("<=", ">=", "=", "<", ">", "^", "~")


def _parse_version(version):
    if not isinstance(version, str):
        raise ValueError("invalid version")

    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid version")

    major, minor, patch = (int(match.group(i)) for i in (1, 2, 3))
    prerelease_text = match.group(4)

    prerelease = None
    if prerelease_text is not None:
        prerelease = []
        for identifier in prerelease_text.split("."):
            if identifier.isdigit():
                if len(identifier) > 1 and identifier[0] == "0":
                    raise ValueError("invalid version")
                prerelease.append((True, int(identifier)))
            else:
                prerelease.append((False, identifier))
        prerelease = tuple(prerelease)

    return (major, minor, patch, prerelease)


def _compare_versions(left, right):
    left_core = left[:3]
    right_core = right[:3]

    if left_core < right_core:
        return -1
    if left_core > right_core:
        return 1

    left_pre = left[3]
    right_pre = right[3]

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    for left_identifier, right_identifier in zip(left_pre, right_pre):
        left_numeric, left_value = left_identifier
        right_numeric, right_value = right_identifier

        if left_numeric and right_numeric:
            if left_value < right_value:
                return -1
            if left_value > right_value:
                return 1
        elif left_numeric != right_numeric:
            return -1 if left_numeric else 1
        else:
            if left_value < right_value:
                return -1
            if left_value > right_value:
                return 1

    if len(left_pre) < len(right_pre):
        return -1
    if len(left_pre) > len(right_pre):
        return 1
    return 0


def _make_version(major, minor, patch):
    return (major, minor, patch, None)


def _parse_comparator(token):
    if token == "*":
        return ("*", None)

    operator = "="
    value = token

    for candidate in _OPERATORS:
        if token.startswith(candidate):
            operator = candidate
            value = token[len(candidate):]
            break

    if not value or value == "*":
        raise ValueError("invalid comparator")

    return (operator, _parse_version(value))


def _comparator_matches(version, comparator):
    operator, target = comparator

    if operator == "*":
        return True

    if operator == "^":
        major, minor, patch, _ = target
        if major > 0:
            upper = _make_version(major + 1, 0, 0)
        elif minor > 0:
            upper = _make_version(0, minor + 1, 0)
        else:
            upper = _make_version(0, 0, patch + 1)

        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, upper) < 0
        )

    if operator == "~":
        major, minor, _, _ = target
        upper = _make_version(major, minor + 1, 0)
        return (
            _compare_versions(version, target) >= 0
            and _compare_versions(version, upper) < 0
        )

    comparison = _compare_versions(version, target)

    if operator == "=":
        return comparison == 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0

    raise ValueError("invalid comparator")


def semver_satisfies(version: str, constraint: str) -> bool:
    if not isinstance(version, str):
        raise ValueError("invalid version")
    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("invalid constraint")

    parsed_version = _parse_version(version)
    groups = constraint.split("||")

    if any(not group.strip() for group in groups):
        raise ValueError("invalid constraint")

    for group in groups:
        tokens = group.split()
        if not tokens:
            raise ValueError("invalid constraint")

        comparators = [_parse_comparator(token) for token in tokens]

        if not all(
            _comparator_matches(parsed_version, comparator)
            for comparator in comparators
        ):
            continue

        prerelease = parsed_version[3]
        if prerelease is not None:
            major, minor, patch, _ = parsed_version
            has_matching_prerelease_comparator = any(
                comparator[1] is not None
                and comparator[1][3] is not None
                and comparator[1][:3] == (major, minor, patch)
                for comparator in comparators
            )
            if not has_matching_prerelease_comparator:
                continue

        return True

    return False
