def shell_split(s: str) -> list[str]:
    words = []
    current = []
    quote = None
    token_started = False
    i = 0

    while i < len(s):
        char = s[i]

        if quote == "'":
            if char == "'":
                quote = None
            else:
                current.append(char)
            i += 1
            continue

        if quote == '"':
            if char == '"':
                quote = None
                i += 1
            elif char == "\\" and i + 1 < len(s) and s[i + 1] in ('"', "\\"):
                current.append(s[i + 1])
                i += 2
            else:
                current.append(char)
                i += 1
            continue

        if char in (" ", "\t"):
            if token_started:
                words.append("".join(current))
                current = []
                token_started = False
            i += 1
        elif char == "\\":
            if i + 1 == len(s):
                raise ValueError("trailing backslash")
            current.append(s[i + 1])
            token_started = True
            i += 2
        elif char in ("'", '"'):
            quote = char
            token_started = True
            i += 1
        else:
            current.append(char)
            token_started = True
            i += 1

    if quote is not None:
        raise ValueError("unterminated quote")

    if token_started:
        words.append("".join(current))

    return words
