import re

_NUMBER_RE = re.compile(r'-?[0-9]+(?:\.[0-9]+)?')


def _add_one(digits: str) -> str:
    """Add 1 to a non-negative decimal string; may grow by one digit."""
    out = list(digits)
    i = len(out) - 1
    while i >= 0:
        if out[i] == '9':
            out[i] = '0'
            i -= 1
        else:
            out[i] = chr(ord(out[i]) + 1)
            return ''.join(out)
    return '1' + ''.join(out)


def round_half_up(x: str, ndigits: int) -> str:
    if not isinstance(ndigits, int) or isinstance(ndigits, bool):
        raise TypeError("ndigits must be an int")
    if ndigits < 0:
        raise ValueError("ndigits must be non-negative")

    if not isinstance(x, str) or _NUMBER_RE.fullmatch(x) is None:
        raise ValueError("x must be a decimal number: -?[0-9]+(.[0-9]+)?")

    negative = x.startswith('-')
    body = x[1:] if negative else x
    if '.' in body:
        int_part, frac_part = body.split('.')
    else:
        int_part, frac_part = body, ''

    if ndigits >= len(frac_part):
        # Nothing to round away: just pad with zeros.
        int_out = int_part
        frac_out = frac_part + '0' * (ndigits - len(frac_part))
    else:
        digits = int_part + frac_part
        keep = len(int_part) + ndigits
        tail = digits[keep:]
        combined = digits[:keep]
        # Half away from zero: round up iff the first dropped digit is >= 5.
        if tail[0] >= '5':
            combined = _add_one(combined)
        if ndigits:
            int_out = combined[:-ndigits] or '0'
            frac_out = combined[-ndigits:]
        else:
            int_out = combined
            frac_out = ''

    int_out = int_out.lstrip('0') or '0'
    result = int_out + ('.' + frac_out if ndigits else '')
    if negative and (int_out != '0' or frac_out.strip('0')):
        result = '-' + result
    return result
