"""Text wrapping utilities (Python 3.9+, standard library only)."""

from typing import List

__all__ = ["wrap_text"]


def wrap_text(text: str, width: int) -> List[str]:
    """Greedily wrap ``text`` into lines of at most ``width`` characters.

    Words are maximal runs of characters separated by one or more U+0020
    spaces.  A word longer than ``width`` is split into consecutive pieces
    of exactly ``width`` characters, the first of which always begins a new
    line; its (possibly shorter) last piece starts a line that may continue
    with following words when they fit.

    Returns a list of lines with no leading or trailing spaces.  Empty or
    space-only input yields an empty list.  Raises ValueError if width < 1.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: List[str] = []
    current = ""

    for word in text.split(" "):
        if not word:
            continue

        if not current:
            # Nothing on the current line yet: start it with this word.
            if len(word) > width:
                pieces = [word[i:i + width] for i in range(0, len(word), width)]
                lines.extend(pieces[:-1])
                current = pieces[-1]
            else:
                current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            # The word does not fit: break the line first.
            lines.append(current)
            if len(word) > width:
                pieces = [word[i:i + width] for i in range(0, len(word), width)]
                lines.extend(pieces[:-1])
                current = pieces[-1]
            else:
                current = word

    if current:
        lines.append(current)

    return lines
