def is_valid_ipv4(s: str) -> bool:
    """Return True iff s is a valid dotted-quad IPv4 address literal.

    Rules: exactly four dot-separated parts; each part is 1-3 ASCII digits
    (0-9) with numeric value 0-255; no leading zeros unless the part is "0".
    Never raises for a str input.
    """
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        n = len(part)
        if n < 1 or n > 3:
            return False
        # ASCII digits only (rejects signs, spaces, newlines, Unicode digits)
        for ch in part:
            if ch < "0" or ch > "9":
                return False
        if n > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False

    return True
