import ipaddress
import re


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("URL must be a string")

    scheme_match = re.match(r"([A-Za-z][A-Za-z0-9+.-]*)://", url)
    if scheme_match is None:
        raise ValueError("URL must begin with a valid scheme followed by '://'")

    scheme = scheme_match.group(1).lower()
    authority_start = scheme_match.end()
    authority_end = len(url)

    for delimiter in "/?#":
        position = url.find(delimiter, authority_start)
        if position != -1:
            authority_end = min(authority_end, position)

    authority = url[authority_start:authority_end]
    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_and_port = authority.rsplit("@", 1)
    else:
        userinfo = ""
        host_and_port = authority

    port_text = None

    if host_and_port.startswith("["):
        closing_bracket = host_and_port.find("]")
        if closing_bracket == -1:
            raise ValueError("IPv6 literal must have a closing bracket")

        host = host_and_port[1:closing_bracket]
        try:
            ipaddress.IPv6Address(host)
        except ValueError as exc:
            raise ValueError("Invalid IPv6 literal") from exc

        suffix = host_and_port[closing_bracket + 1:]
        if suffix:
            if not suffix.startswith(":"):
                raise ValueError("Unexpected characters after IPv6 literal")
            port_text = suffix[1:]
    else:
        host, separator, suffix = host_and_port.partition(":")
        if not host or any(character in " /?#@:[]" for character in host):
            raise ValueError("Invalid host")
        if separator:
            port_text = suffix

    port = None
    if port_text is not None:
        if re.fullmatch(r"[0-9]{1,5}", port_text) is None:
            raise ValueError("Port must contain 1 to 5 ASCII digits")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Port must be between 1 and 65535")

    remainder = url[authority_end:]
    before_fragment, _, fragment = remainder.partition("#")
    path, _, query = before_fragment.partition("?")

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
