"""Semantic-version constraint matching (SemVer 2.0 ordering, npm-style ranges).

Python 3.9+, standard library only.
"""

import re

__all__ = ["semver_satisfies"]

# MAJOR.MINOR.PATCH with no leading zeros, optional -prerelease, optional +build.
_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_TWO_CHAR_OPERATORS = (">=", "<=")
_ONE_CHAR_OPERATORS = ("=", ">", "<", "^", "~")
_DIGITS = frozenset("0123456789")


def _parse_version(text):
    """Return (major, minor, patch, pre) for a version string.

    `pre` is None for a release version, otherwise a tuple of identifier
    tuples: (0, int_value) for numeric identifiers, (1, text) for
    alphanumeric ones.  Build metadata is validated and then discarded.
    """
    if not isinstance(text, str):
        raise ValueError("version must be a string: {!r}".format(text))
    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError("invalid version: {!r}".format(text))

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    raw_pre = match.group(4)

    if raw_pre is None:
        pre = None
    else:
        identifiers = []
        for chunk in raw_pre.split("."):
            if not chunk:
                raise ValueError("invalid version: {!r}".format(text))
            if all(char in _DIGITS for char in chunk):
                if len(chunk) > 1 and chunk[0] == "0":
                    raise ValueError(
                        "numeric pre-release identifier has a leading zero: "
                        "{!r}".format(text)
                    )
                identifiers.append((0, int(chunk)))
            else:
                identifiers.append((1, chunk))
        pre = tuple(identifiers)

    return (major, minor, patch, pre)


def _compare(left, right):
    """Order two parsed versions: -1, 0 or 1."""
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1

    left_pre = left[3]
    right_pre = right[3]
    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        if left_id != right_id:
            # (0, n) sorts before (1, text), so numeric < alphanumeric.
            return -1 if left_id < right_id else 1
    if len(left_pre) != len(right_pre):
        return -1 if len(left_pre) < len(right_pre) else 1
    return 0


def _parse_comparator(token):
    """Expand one comparator token into a list of (operator, version) pairs."""
    if token == "*":
        return []

    if token[:2] in _TWO_CHAR_OPERATORS:
        operator, rest = token[:2], token[2:]
    elif token[:1] in _ONE_CHAR_OPERATORS:
        operator, rest = token[:1], token[1:]
    else:
        operator, rest = "=", token

    target = _parse_version(rest)

    if operator == "^":
        major, minor, patch = target[0], target[1], target[2]
        if major > 0:
            upper = (major + 1, 0, 0, None)
        elif minor > 0:
            upper = (0, minor + 1, 0, None)
        else:
            upper = (0, 0, patch + 1, None)
        return [(">=", target), ("<", upper)]

    if operator == "~":
        upper = (target[0], target[1] + 1, 0, None)
        return [(">=", target), ("<", upper)]

    return [(operator, target)]


def _compile_group(text):
    tokens = text.split()
    if not tokens:
        raise ValueError("empty constraint group: {!r}".format(text))
    comparators = []
    for token in tokens:
        comparators.extend(_parse_comparator(token))
    return comparators


def _satisfies_group(version, comparators):
    # Pre-release gate: a pre-release version needs at least one comparator
    # written with a pre-release tag on the same MAJOR.MINOR.PATCH.
    if version[3] is not None:
        allowed = False
        for _operator, target in comparators:
            if target[3] is not None and target[:3] == version[:3]:
                allowed = True
                break
        if not allowed:
            return False

    for operator, target in comparators:
        ordering = _compare(version, target)
        if operator == "=":
            if ordering != 0:
                return False
        elif operator == ">":
            if ordering <= 0:
                return False
        elif operator == ">=":
            if ordering < 0:
                return False
        elif operator == "<":
            if ordering >= 0:
                return False
        elif operator == "<=":
            if ordering > 0:
                return False
    return True


def semver_satisfies(version, constraint):
    """Return True if `version` satisfies `constraint`.

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty constraint.
    """
    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string: {!r}".format(constraint))

    parsed_version = _parse_version(version)

    if not constraint.strip():
        raise ValueError("empty constraint")

    # Compile every group up front so a malformed group always raises,
    # even when an earlier group already matches.
    groups = [_compile_group(text) for text in constraint.split("||")]

    for comparators in groups:
        if _satisfies_group(parsed_version, comparators):
            return True
    return False
