```python
def wrap_text(text: str, width: int) -> list:
    """Greedily wrap `text` into lines of at most `width` characters.

    Words are runs of characters separated by one or more U+0020 spaces.
    A word longer than `width` starts on a fresh line and is hard-split into
    pieces of exactly `width` characters; its (possibly shorter) last piece
    begins a line that may continue with the following words.
    """
    if width < 1:
        raise ValueError("width must be a positive integer")

    words = [word for word in text.split(" ") if word]
    lines = []
    current = None  # None means no line is in progress

    for word in words:
        if len(word) <= width:
            if current is None:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current = current + " " + word
            else:
                lines.append(current)
                current = word
        else:
            # A word longer than width always starts on its own new line.
            if current is not None:
                lines.append(current)
                current = None

            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current = pieces[-1]

    if current is not None:
        lines.append(current)

    return lines
