def mask_email(s: str) -> str:
    # Require exactly one "@", with non-empty local and domain parts.
    if s.count("@") != 1:
        raise ValueError("Expected exactly one '@'")

    local, domain = s.split("@")
    if not local or not domain:
        raise ValueError("Local part and domain must be non-empty")

    # Length 1 becomes "*"; length 2 keeps the first character; longer
    # local parts keep their first and last characters.
    if len(local) == 1:
        masked_local = "*"
    elif len(local) == 2:
        masked_local = local[0] + "*"
    else:
        masked_local = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked_local + "@" + domain
