import re

_SCHEME_RE = re.compile(r'([A-Za-z][A-Za-z0-9+.\-]*)://')
_PORT_RE = re.compile(r'[0-9]{1,5}')
_IPV6_RE = re.compile(r'[0-9A-Fa-f:.]+')

_HOST_FORBIDDEN = frozenset(' /?#@:[]')


def parse_url(url: str) -> dict:
    """Split a URL into scheme, userinfo, host, port, path, query, fragment.

    Raises ValueError on any input that does not follow the accepted grammar.
    """
    if not isinstance(url, str):
        raise ValueError('url must be a string')

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError('missing or invalid scheme: %r' % (url,))
    scheme = match.group(1).lower()
    rest = url[match.end():]

    # The authority runs up to the first '/', '?' or '#' (or the end).
    cut = len(rest)
    for i, ch in enumerate(rest):
        if ch in '/?#':
            cut = i
            break
    authority = rest[:cut]
    tail = rest[cut:]

    if not authority:
        raise ValueError('empty authority')

    # Everything before the LAST '@' is the userinfo.
    if '@' in authority:
        at = authority.rindex('@')
        userinfo = authority[:at]
        hostport = authority[at + 1:]
    else:
        userinfo = ''
        hostport = authority

    if hostport.startswith('['):
        close = hostport.find(']')
        if close == -1:
            raise ValueError('unterminated bracketed host')
        host = hostport[1:close]
        if not host or not _IPV6_RE.fullmatch(host):
            raise ValueError('invalid IPv6 literal: %r' % (host,))
        remainder = hostport[close + 1:]
        if remainder and not remainder.startswith(':'):
            raise ValueError('unexpected characters after host: %r' % (remainder,))
        port_part = remainder[1:] if remainder else None
    else:
        if ':' in hostport:
            host, _, port_part = hostport.partition(':')
        else:
            host, port_part = hostport, None
        if not host:
            raise ValueError('empty host')
        for ch in host:
            if ch in _HOST_FORBIDDEN:
                raise ValueError('invalid character in host: %r' % (ch,))

    host = host.lower()

    port = None
    if port_part is not None:
        if not _PORT_RE.fullmatch(port_part):
            raise ValueError('invalid port: %r' % (port_part,))
        port = int(port_part)
        if not 1 <= port <= 65535:
            raise ValueError('port out of range: %r' % (port_part,))

    # The first '#' opens the fragment; before it, the first '?' opens the query.
    if '#' in tail:
        before_fragment, _, fragment = tail.partition('#')
    else:
        before_fragment, fragment = tail, ''

    if '?' in before_fragment:
        path, _, query = before_fragment.partition('?')
    else:
        path, query = before_fragment, ''

    return {
        'scheme': scheme,
        'userinfo': userinfo,
        'host': host,
        'port': port,
        'path': path,
