def parse_duration(s: str) -> int:
    unit_seconds = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen = set()
    total = 0
    i = 0
    n = len(s)

    while i < n and s[i] == " ":
        i += 1

    if i == n:
        raise ValueError("duration must contain at least one part")

    while i < n:
        if not ("0" <= s[i] <= "9"):
            raise ValueError("expected a number")

        value = 0
        while i < n and "0" <= s[i] <= "9":
            value = value * 10 + (ord(s[i]) - ord("0"))
            i += 1

        if i == n or s[i] == " ":
            raise ValueError("number must be immediately followed by a unit")

        unit = s[i]
        if unit not in unit_seconds:
            raise ValueError("unknown unit")
        if unit in seen:
            raise ValueError("repeated unit")

        seen.add(unit)
        total += value * unit_seconds[unit]
        i += 1

        if i < n and s[i] != " " and not ("0" <= s[i] <= "9"):
            raise ValueError("invalid character")

        while i < n and s[i] == " ":
            i += 1

    return total
