def shell_split(s: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    started = False  # True once a word has begun, even if it is still empty
    i = 0
    n = len(s)

    def flush() -> None:
        nonlocal current, started
        words.append(''.join(current))
        current = []
        started = False

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            if started:
                flush()
            i += 1

        elif c == "'":
            started = True
            i += 1
            while i < n and s[i] != "'":
                current.append(s[i])
                i += 1
            if i >= n:
                raise ValueError("unterminated single quote")
            i += 1  # skip the closing quote

        elif c == '"':
            started = True
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                d = s[i]
                if d == '"':
                    i += 1
                    break
                if d == '\\':
                    if i + 1 >= n:
                        raise ValueError("unterminated double quote")
                    nxt = s[i + 1]
                    if nxt == '"' or nxt == '\\':
                        current.append(nxt)  # \" -> " and \\ -> \
                    else:
                        current.append('\\')  # every other escape stays verbatim
                        current.append(nxt)
                    i += 2
                else:
                    current.append(d)
                    i += 1

        elif c == '\\':
            started = True
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            current.append(s[i + 1])  # next char is literal
            i += 2

        else:
            started = True
            current.append(c)
            i += 1

    if started:
        flush()

    return words
