from datetime import date, timedelta


def next_weekday(date_str: str, weekday: int) -> str:
    """Return the first YYYY-MM-DD strictly after date_str falling on `weekday`.

    weekday: 0 = Monday ... 6 = Sunday.
    """
    if weekday < 0 or weekday > 6:
        raise ValueError("weekday must be in the range 0..6")

    current = date.fromisoformat(date_str)
    delta = (weekday - current.weekday()) % 7
    if delta == 0:
        delta = 7
    return (current + timedelta(days=delta)).isoformat()


