import re
from bisect import bisect_right
from calendar import monthrange
from datetime import datetime, timedelta


_ITEM = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_TIMESTAMP = re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2}) ([0-9]{2}):([0-9]{2})"
)


def _parse_field(text, minimum, maximum):
    values = set()

    for item in text.split(","):
        match = _ITEM.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item: {!r}".format(item))

        base, step_text = match.groups()
        step = int(step_text) if step_text is not None else 1
        if step < 1:
            raise ValueError("Cron steps must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start, end = map(int, base.split("-"))
        else:
            start = int(base)
            end = maximum if step_text is not None else start

        if not minimum <= start <= end <= maximum:
            raise ValueError("Cron value outside its field's range")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("A cron expression must have exactly five fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, bounds)
    ]

    match = _TIMESTAMP.fullmatch(after)
    if match is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    start = datetime(*map(int, match.groups()))

    # Use a calendar-year horizon, clamping February 29 to February 28
    # when necessary. Search only representable datetime values.
    if start.year <= 9994:
        end_year = start.year + 5
        end_day = min(start.day, monthrange(end_year, start.month)[1])
        deadline = start.replace(year=end_year, day=end_day)
    else:
        deadline = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    day = start.date()
    last_day = deadline.date()

    while True:
        if day.month in months:
            dom_matches = day.day in month_days
            dow_matches = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                threshold = (
                    start.hour * 60 + start.minute
                    if day == start.date()
                    else -1
                )
                index = bisect_right(times, threshold)

                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate <= deadline:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {candidate.hour:02d}:"
                            f"{candidate.minute:02d}"
                        )

        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("No matching time exists within five years after after")
