class TopoSortTests(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(topo_sort({}), [])

    def test_lexicographically_smallest_available_item_first(self):
        self.assertEqual(
            topo_sort({"b": [], "a": [], "c": ["a"]}),
            ["a", "b", "c"],
        )

    def test_dependencies_and_items_mentioned_only_as_dependencies(self):
        self.assertEqual(
            topo_sort({"app": ["lib"], "lib": ["base"]}),
            ["base", "lib", "app"],
        )

    def test_duplicate_dependencies_are_ignored(self):
        self.assertEqual(topo_sort({"app": ["lib", "lib"]}), ["lib", "app"])

    def test_self_dependency_raises(self):
        with self.assertRaises(ValueError):
            topo_sort({"a": ["a"]})

    def test_multi_item_cycle_raises(self):
        with self.assertRaises(ValueError):
            topo_sort({"a": ["b"], "b": ["c"], "c": ["a"]})

    def test_does_not_modify_input(self):
        deps = {"app": ["lib", "lib"]}
        original = {"app": ["lib", "lib"]}
        topo_sort(deps)
        self.assertEqual(deps, original)


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    items = set(deps)
    for dependencies in deps.values():
        items.update(dependencies)

    remaining = {}
    dependents = {item: [] for item in items}

    for item in items:
        unique_dependencies = set(deps.get(item, []))
        remaining[item] = len(unique_dependencies)
        for dependency in unique_dependencies:
            dependents[dependency].append(item)

    ready = [item for item in items if remaining[item] == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents[item]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(items):
        raise ValueError("dependency cycle")

    return result
