    """Mask the local part of an email address.

    The first and last characters of the local part are kept; every
    character between them is replaced by '*'.  A one-character local
    part becomes a single '*'; a two-character local part keeps its
    first character and masks the second.  The domain is returned
    unchanged.

    Raises:
        ValueError: if ``s`` does not contain exactly one '@' with a
            non-empty local part before it and a non-empty domain
            after it.
    """
    if s.count("@") != 1:
        raise ValueError("email must contain exactly one '@'")

    local, domain = s.split("@")

    if not local:
        raise ValueError("local part must be non-empty")
    if not domain:
        raise ValueError("domain must be non-empty")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
