from typing import List, Tuple

__all__ = ["glob_match"]


def _read_char(pattern: str, pos: int) -> Tuple[str, int]:
    """Read one pattern character at `pos`, honouring backslash escapes."""
    if pattern[pos] == "\\":
        if pos + 1 >= len(pattern):
            raise ValueError("pattern ends with a trailing backslash")
        return pattern[pos + 1], pos + 2
    return pattern[pos], pos + 1


def _parse_class(pattern: str, start: int) -> Tuple[bool, List[tuple], int]:
    """Parse a character set beginning at pattern[start] == '['.

    Returns (negated, items, next_index), where items holds
    ('c', ch) literals and ('r', lo, hi) ranges.
    """
    n = len(pattern)
    i = start + 1
    negated = False
    if i < n and pattern[i] == "!":
        negated = True
        i += 1

    items: List[tuple] = []
    first = True
    while True:
        if i >= n:
            raise ValueError("unterminated character set in pattern")
        if pattern[i] == "]" and not first:
            i += 1
            break
        ch, i = _read_char(pattern, i)
        if i < n and pattern[i] == "-" and i + 1 < n and pattern[i + 1] != "]":
            end, i = _read_char(pattern, i + 1)
            items.append(("r", ch, end))
        else:
            items.append(("c", ch))
        first = False
    return negated, items, i


def _parse(pattern: str) -> List[tuple]:
    """Turn a glob pattern into a list of tokens, raising ValueError on errors."""
    tokens: List[tuple] = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == "*":
            j = i
            while j < n and pattern[j] == "*":
                j += 1
            tokens.append(("dstar",) if j - i >= 2 else ("star",))
            i = j
        elif c == "?":
            tokens.append(("any",))
            i += 1
        elif c == "\\":
            lit, i = _read_char(pattern, i)
            tokens.append(("lit", lit))
        elif c == "[":
            negated, items, i = _parse_class(pattern, i)
            tokens.append(("class", negated, items))
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def _class_match(items: List[tuple], negated: bool, ch: str) -> bool:
    hit = False
    for item in items:
        if item[0] == "c":
            if ch == item[1]:
                hit = True
                break
        elif item[1] <= ch <= item[2]:
            hit = True
            break
    return hit != negated


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches the glob `pattern`.

    '*'  -> any run of characters containing no '/'
    '**' -> any run of characters, '/' included, possibly empty
    '?'  -> exactly one character that is not '/'
    "[...]" -> one character from the set ('!' negates, ']' first is literal)
    '\\x' -> the literal character x
    """
    tokens = _parse(pattern)
    length = len(name)

    reach = [False] * (length + 1)
    reach[0] = True

    for tok in tokens:
        kind = tok[0]
        nxt = [False] * (length + 1)

        if kind == "star":
            for i in range(length + 1):
                if reach[i]:
                    nxt[i] = True
            for i in range(length):
                if nxt[i] and name[i] != "/":
                    nxt[i + 1] = True

        elif kind == "dstar":
            start = -1
            for i in range(length + 1):
                if reach[i]:
                    start = i
                    break
            if start >= 0:
                for k in range(start, length + 1):
                    nxt[k] = True

        elif kind == "any":
            for i in range(length):
                if reach[i] and name[i] != "/":
                    nxt[i + 1] = True

        elif kind == "lit":
            ch = tok[1]
            for i in range(length):
                if reach[i] and name[i] == ch:
                    nxt[i + 1] = True

        else:  # "class"
            negated, items = tok[1], tok[2]
            for i in range(length):
                if reach[i] and _class_match(items, negated, name[i]):
                    nxt[i + 1] = True

        reach = nxt

    return reach[length]
