def first_bracket_error(s: str) -> int:
    """Return the index of the first bracket error in ``s``.

    Scans ``s`` left to right, considering only ( ) [ ] { }; every other
    character is ignored.

    Returns:
        * the index of the first closing bracket that does not match the
          most recent unclosed opening bracket (or that appears with no
          opening bracket pending), if one exists;
        * otherwise, the index of the leftmost opening bracket that is
          still unclosed at the end of the string, if any;
        * otherwise -1 (the brackets are balanced).
    """
    match_for_closer = {")": "(", "]": "[", "}": "{"}
    unclosed = []  # stack of (opening bracket, its index)

    for i, ch in enumerate(s):
        if ch in "([{":
            unclosed.append((ch, i))
        elif ch in match_for_closer:
            if not unclosed or unclosed[-1][0] != match_for_closer[ch]:
                return i
            unclosed.pop()

    return unclosed[0][1] if unclosed else -1
