def _is_digits(s):
    return len(s) > 0 and all('0' <= c <= '9' for c in s)


def _is_tag(s):
    return len(s) > 0 and all(
        ('0' <= c <= '9') or ('a' <= c <= 'z') or ('A' <= c <= 'Z') for c in s
    )


def _parse(version):
    if not isinstance(version, str):
        raise ValueError("version must be a string")
    if version.count('-') > 1:
        raise ValueError("invalid version: %r" % (version,))
    if '-' in version:
        num_part, tag = version.split('-')
        if not _is_tag(tag):
            raise ValueError("invalid tag in version: %r" % (version,))
    else:
        num_part, tag = version, None
    parts = num_part.split('.')
    for part in parts:
        if not _is_digits(part):
            raise ValueError("invalid version: %r" % (version,))
    return parts, tag


def _cmp_digits(x, y):
    # numeric comparison of two digit strings without int()
    x = x.lstrip('0') or '0'
    y = y.lstrip('0') or '0'
    if len(x) != len(y):
        return -1 if len(x) < len(y) else 1
    if x == y:
        return 0
    return -1 if x < y else 1


def compare_versions(a, b):
    parts_a, tag_a = _parse(a)
    parts_b, tag_b = _parse(b)

    for i in range(max(len(parts_a), len(parts_b))):
        x = parts_a[i] if i < len(parts_a) else '0'
        y = parts_b[i] if i < len(parts_b) else '0'
        c = _cmp_digits(x, y)
        if c:
            return c

    if tag_a is None and tag_b is None:
        return 0
    if tag_a is None:
        return 1
    if tag_b is None:
        return -1
    if tag_a == tag_b:
        return 0
    return -1 if tag_a < tag_b else 1
