def normalize_path(p: str) -> str:
    is_absolute = p.startswith("/")
    stack = []          # resolved components
    pending_ups = 0     # unresolvable ".." components (relative paths only)

    for component in p.split("/"):
        if component == "" or component == ".":
            continue
        if component == "..":
            if stack:
                stack.pop()
            elif not is_absolute:
                pending_ups += 1
            # For absolute paths, ".." at the root is ignored.
        else:
            stack.append(component)

    if is_absolute:
        return "/" + "/".join(stack)

    parts = [".."] * pending_ups + stack
    return "/".join(parts) if parts else "."
