def shell_split(s: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    in_word = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            # Separator outside quotes: flush current word if one is open.
            if in_word:
                words.append(''.join(current))
                current = []
                in_word = False
            i += 1

        elif c == "'":
            # Single quotes: everything literal until the next single quote.
            in_word = True
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated single quote")
                if s[i] == "'":
                    i += 1
                    break
                current.append(s[i])
                i += 1

        elif c == '"':
            # Double quotes: literal until next unescaped double quote;
            # \" -> " and \\ -> \; any other backslash is kept as is.
            in_word = True
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                ch = s[i]
                if ch == '\\':
                    if i + 1 < n and s[i + 1] in ('"', '\\'):
                        current.append(s[i + 1])
                        i += 2
                    else:
                        current.append('\\')
                        i += 1
                elif ch == '"':
                    i += 1
                    break
                else:
                    current.append(ch)
                    i += 1

        elif c == '\\':
            # Outside quotes: next character is literal, whatever it is.
            if i + 1 >= n:
                raise ValueError("backslash at end of input")
            current.append(s[i + 1])
            in_word = True
            i += 2

        else:
            current.append(c)
            in_word = True
            i += 1

    if in_word:
        words.append(''.join(current))
    return words
