def flatten(nested, depth=None):
    # Validate depth: None means fully flatten, otherwise must be >= 0.
    if depth is not None and depth < 0:
        raise ValueError("depth must be None or a non-negative integer")

    # depth == 0: shallow copy of the top level, no flattening at all.
    if depth == 0:
        return list(nested)

    result = []
    for item in nested:
        # Only flatten objects whose type is *exactly* list
        # (list subclasses, tuples, strings, dicts, etc. stay as single items).
        if type(item) is list:
            if depth is None:
                result.extend(flatten(item, None))
            else:
                result.extend(flatten(item, depth - 1))
        else:
            result.append(item)
    return result
