import re

__all__ = ["semver_satisfies"]

# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------

_CORE = r"(0|[1-9][0-9]*)"
_IDENT = r"[0-9A-Za-z-]+"

_VERSION_RE = re.compile(
    r"\A"
    + _CORE + r"\." + _CORE + r"\." + _CORE
    + r"(?:-(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
    + r"(?:\+(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
    + r"\Z"
)

_ASCII_DIGITS = frozenset("0123456789")


def _is_numeric(identifier):
    """True if the identifier consists only of ASCII digits (and is non-empty)."""
    if not identifier:
        return False
    for ch in identifier:
        if ch not in _ASCII_DIGITS:
            return False
    return True


def _parse_version(text):
    """Return (major, minor, patch, pre_tuple).  Raise ValueError if invalid.

    Build metadata is validated but discarded (ignored for comparison).
    """
    if not isinstance(text, str):
        raise ValueError("version must be a string, got {!r}".format(type(text).__name__))

    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError("invalid version: {!r}".format(text))

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))

    pre_text = match.group(4)
    pre = ()
    if pre_text is not None:
        identifiers = pre_text.split(".")
        for identifier in identifiers:
            # Numeric pre-release identifiers must not have leading zeros.
            if _is_numeric(identifier) and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError(
                    "invalid pre-release identifier (leading zero): {!r}".format(identifier)
                )
        pre = tuple(identifiers)

    return (major, minor, patch, pre)


# ---------------------------------------------------------------------------
# Comparison
# ---------------------------------------------------------------------------

def _compare(a, b):
    """Total order over parsed versions: -1, 0 or 1."""
    if a[0] != b[0]:
        return -1 if a[0] < b[0] else 1
    if a[1] != b[1]:
        return -1 if a[1] < b[1] else 1
    if a[2] != b[2]:
        return -1 if a[2] < b[2] else 1

    pre_a, pre_b = a[3], b[3]
    if not pre_a and not pre_b:
        return 0
    if not pre_a:
        return 1          # no pre-release is higher
    if not pre_b:
        return -1

    for id_a, id_b in zip(pre_a, pre_b):
        num_a = _is_numeric(id_a)
        num_b = _is_numeric(id_b)
        if num_a and num_b:
            val_a = int(id_a)
            val_b = int(id_b)
            if val_a != val_b:
                return -1 if val_a < val_b else 1
        elif num_a:
            return -1      # numeric < alphanumeric
        elif num_b:
            return 1
        elif id_a != id_b:
            return -1 if id_a < id_b else 1   # ASCII string ordering

    if len(pre_a) == len(pre_b):
        return 0
    return -1 if len(pre_a) < len(pre_b) else 1   # shorter tag is lower


# ---------------------------------------------------------------------------
# Comparators
# ---------------------------------------------------------------------------

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")

_WILDCARD = ("*", None)


def _parse_comparator(token):
    """Return (operator, parsed_version) for one whitespace-separated token."""
    if token == "*":
        return _WILDCARD

    operator = "="
    rest = token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            operator = candidate
            rest = token[len(candidate):]
            break

    if not rest:
        raise ValueError("invalid comparator: {!r}".format(token))

    return (operator, _parse_version(rest))


def _caret_upper(version):
    """Exclusive upper bound for '^version'."""
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, ())
    if minor > 0:
        return (0, minor + 1, 0, ())
    return (0, 0, patch + 1, ())


def _tilde_upper(version):
    """Exclusive upper bound for '~version'."""
    return (version[0], version[1] + 1, 0, ())


def _holds(operator, comparator_version, version):
    """True if `version` satisfies this single comparator's ordering checks."""
    if operator == "*":
        return True

    relation = _compare(version, comparator_version)

    if operator == "=":
        return relation == 0
    if operator == ">":
        return relation > 0
    if operator == ">=":
        return relation >= 0
    if operator == "<":
        return relation < 0
    if operator == "<=":
        return relation <= 0
    if operator == "^":
        if relation < 0:
            return False
        return _compare(version, _caret_upper(comparator_version)) < 0
    if operator == "~":
        if relation < 0:
            return False
        return _compare(version, _tilde_upper(comparator_version)) < 0

    raise ValueError("invalid operator: {!r}".format(operator))


def _prerelease_permitted(group, version):
    """Pre-release versions need a matching pre-release comparator in the group."""
    for _operator, comparator_version in group:
        if comparator_version is None:
            continue
        if comparator_version[3] and comparator_version[:3] == version[:3]:
            return True
    return False


