def semver_satisfies(version: str, constraint: str) -> bool:
    """Check `version` against an npm-style `constraint`.

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty constraint (including empty '||' groups).
    """
    if not isinstance(version, str) or not isinstance(constraint, str):
        raise ValueError("version and constraint must both be strings")

    parsed_version = _parse_version(version)

    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty constraint group in {!r}".format(constraint))
        groups.append([_parse_comparator(token) for token in tokens])

    for group in groups:
        if not all(_holds(op, cver, parsed_version) for op, cver in group):
            continue
        if parsed_version[3] and not _prerelease_permitted(group, parsed_version):
            continue
        return True

    return False
