def roman_to_int(s: str) -> int:
    """Convert the canonical uppercase Roman numeral for 1..3999 to an int.

    Raises ValueError for any non-canonical input (empty string, lowercase,
    additive forms like "IIII", wrong subtractive pairs like "IC"/"VX",
    out-of-range values like "MMMM", embedded whitespace, etc.).
    """
    if not isinstance(s, str):
        raise ValueError("Roman numeral must be a string, got %r" % (type(s).__name__,))
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    pairs = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )

    # Greedy left-to-right parse over the canonical symbols.
    total = 0
    i = 0
    for value, symbol in pairs:
        while s.startswith(symbol, i):
            total += value
            i += len(symbol)
    if i != len(s):
        raise ValueError("invalid Roman numeral: %r" % (s,))

    # A string is canonical iff re-encoding its value reproduces it exactly.
    if not 1 <= total <= 3999:
        raise ValueError("value out of range 1..3999: %r" % (s,))
    out = []
    n = total
    for value, symbol in pairs:
        count, n = divmod(n, value)
        out.append(symbol * count)
    if "".join(out) != s:
        raise ValueError("non-canonical Roman numeral: %r" % (s,))

    return total


