    authority = remainder[:authority_end]
    rest = remainder[authority_end:]

    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

