            raise ValueError("Invalid IPv6 literal") from exc

        suffix = host_port[closing + 1:]
        if suffix and not suffix.startswith(":"):
            raise ValueError("Unexpected characters after IPv6 literal")
    else:
        host, separator, port_text = host_port.partition(":")
        if not host or any(char in " /?#@:[]" for char in host):
            raise ValueError("Invalid host")
        suffix = separator + port_text

    port = None
    if suffix:
        port_text = suffix[1:]
        if re.fullmatch(r"[0-9]{1,5}", port_text) is None:
            raise ValueError("Port must contain 1 to 5 ASCII digits")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Port must be between 1 and 65535")

    before_fragment, _, fragment = rest.partition("#")
    path, _, query = before_fragment.partition("?")

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
