def merge_intervals(intervals):
    """Merge overlapping or endpoint-sharing closed intervals.

    Returns a new list of [start, end] lists sorted by start. The input
    list and its inner lists are left untouched.
    """
    if not intervals:
        return []

    items = []
    for interval in intervals:
        start, end = interval[0], interval[1]
        if start > end:
            raise ValueError(
                "invalid interval: start %r is greater than end %r" % (start, end)
            )
        items.append((start, end))

    items.sort()

    merged = []
    for start, end in items:
        if merged and start <= merged[-1][1]:
            # Overlaps or touches the current interval: extend if needed.
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            # Only strictly adjacent integers (start == prev_end + 1) fall here.
            merged.append([start, end])

    return merged
