def shell_split(s: str) -> list[str]:
    """Split a command line into words, following a small POSIX-shell subset.

    Raises ValueError on a trailing backslash or an unterminated quote.
    """
    words: list[str] = []
    cur = None          # None => no word started yet; else a list of pieces
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c == ' ' or c == '\t':
            if cur is not None:
                words.append(''.join(cur))
                cur = None
            i += 1

        elif c == '\\':
            # Outside quotes a backslash makes the next char literal.
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            if cur is None:
                cur = []
            cur.append(s[i + 1])
            i += 2

        elif c == "'":
            # Single quotes: literal until the next single quote.
            if cur is None:
                cur = []
            i += 1
            end = s.find("'", i)
            if end == -1:
                raise ValueError("unterminated single quote")
            cur.append(s[i:end])
            i = end + 1

        elif c == '"':
            # Double quotes: \" -> " and \\ -> \, anything else kept verbatim.
            if cur is None:
                cur = []
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                d = s[i]
                if d == '"':
                    i += 1
                    break
                if d == '\\' and i + 1 < n and s[i + 1] in ('"', '\\'):
                    cur.append(s[i + 1])
                    i += 2
                else:
                    cur.append(d)
                    i += 1

        else:
            if cur is None:
                cur = []
            cur.append(c)
            i += 1

    if cur is not None:
        words.append(''.join(cur))

    return words
