def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    stack = []
    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif absolute:
                continue
            else:
                stack.append("..")
        else:
            stack.append(part)
    if absolute:
        return "/" + "/".join(stack)
    return "/".join(stack) if stack else "."
