import re
from typing import List, NamedTuple, Optional, Tuple


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*)?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|[=><^~])?(.+)")


class _Version(NamedTuple):
    core: Tuple[int, int, int]
    prerelease: Optional[Tuple[str, ...]]


def _parse_version(text: str) -> _Version:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    prerelease = None
    if match.group(4) is not None:
        prerelease = tuple(match.group(4).split("."))
        for identifier in prerelease:
            if identifier.isdigit() and len(identifier) > 1:
                if identifier[0] == "0":
                    raise ValueError(
                        "Numeric prerelease identifiers cannot have leading zeros"
                    )

    return _Version(
        (int(match.group(1)), int(match.group(2)), int(match.group(3))),
        prerelease,
    )


def _compare(left: _Version, right: _Version) -> int:
    if left.core != right.core:
        return 1 if left.core > right.core else -1

    a, b = left.prerelease, right.prerelease
    if a is None:
        return 0 if b is None else 1
    if b is None:
        return -1

    for x, y in zip(a, b):
        if x == y:
            continue

        x_numeric, y_numeric = x.isdigit(), y.isdigit()
        if x_numeric and y_numeric:
            # Canonical numeric identifiers compare by length, then ASCII.
            # This also avoids converting arbitrarily long identifiers to int.
            if len(x) != len(y):
                return 1 if len(x) > len(y) else -1
            return 1 if x > y else -1

        if x_numeric != y_numeric:
            return -1 if x_numeric else 1

        return 1 if x > y else -1

    return (len(a) > len(b)) - (len(a) < len(b))


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a strict SemVer version against the specified constraint grammar.

    Invalid versions, invalid comparators, and empty OR groups raise ValueError.
    Build metadata is validated but does not affect matching.
    """
    candidate = _parse_version(version)

    # Each group stores ordering checks and cores explicitly mentioned with
    # prerelease tags. Validate the entire constraint before matching any group.
    groups: List[
        Tuple[
            List[Tuple[str, _Version]],
            set,
        ]
    ] = []

    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        checks: List[Tuple[str, _Version]] = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            bound = _parse_version(match.group(2))

            if bound.prerelease is not None:
                prerelease_cores.add(bound.core)

            if operator in ("^", "~"):
                major, minor, patch = bound.core
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                checks.append((">=", bound))
                checks.append(("<", _Version(upper_core, None)))
            else:
                checks.append((operator, bound))

        groups.append((checks, prerelease_cores))

    for checks, prerelease_cores in groups:
        if (
            candidate.prerelease is not None
            and candidate.core not in prerelease_cores
        ):
            continue

        for operator, bound in checks:
            result = _compare(candidate, bound)
            if operator == "=":
                holds = result == 0
            elif operator == ">":
                holds = result > 0
            elif operator == ">=":
                holds = result >= 0
            elif operator == "<":
                holds = result < 0
            else:  # <=
                holds = result <= 0

            if not holds:
                break
        else:
            return True

    return False
