def rle_decode(s: str) -> str:
    MAX_LEN = 10000
    parts = []
    total = 0
    i = 0
    n = len(s)

    while i < n:
        # Scan the run of ASCII digits starting at i.
        j = i
        while j < n and '0' <= s[j] <= '9':
            j += 1

        if j == i:
            raise ValueError(
                "missing count at index %d" % i
            )
        if j == n:
            raise ValueError(
                "string ends with digits instead of a character"
            )

        digits = s[i:j]
        if digits[0] == '0':
            raise ValueError("count is zero or has a leading zero: %r" % digits)

        count = int(digits)
        ch = s[j]

        total += count
        if total > MAX_LEN:
            raise ValueError("total decoded length would exceed %d" % MAX_LEN)

        parts.append(ch * count)
        i = j + 1

    return ''.join(parts)
