    authority_end = len(remainder)
    for delimiter in "/?#":
        position = remainder.find(delimiter)
        if position != -1:
            authority_end = min(authority_end, position)

    authority = remainder[:authority_end]
    rest = remainder[authority_end:]
    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    port = None
    if host_port.startswith("["):
        closing = host_port.find("]")
        if closing == -1:
            raise ValueError("Invalid IPv6 literal")
        host = host_port[1:closing]
        try:
            ipaddress.IPv6Address(host)
        except ipaddress.AddressValueError as error:
            raise ValueError("Invalid IPv6 literal") from error

        suffix = host_port[closing + 1:]
        if suffix:
            if not suffix.startswith(":"):
                raise ValueError("Invalid authority")
            port_text = suffix[1:]
            if not port_text:
                raise ValueError("Invalid port")
            port = _parse_port(port_text)
    else:
        if ":" in host_port:
            host, port_text = host_port.split(":", 1)
            if not port_text:
                raise ValueError("Invalid port")
            port = _parse_port(port_text)
        else:
            host = host_port

        if not host or any(
            char in " /?#@:[]"
            for char in host
        ):
            raise ValueError("Invalid host")

    host = host.lower()

    fragment = ""
    if "#" in rest:
        rest, fragment = rest.split("#", 1)

    query = ""
    if "?" in rest:
        path, query = rest.split("?", 1)
    else:
        path = rest

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }


