def earliest_slot(busy: list[tuple[int, int]], duration: int, start: int, end: int):
    """Return the earliest t with start <= t and t + duration <= end such that
    [t, t + duration) overlaps no busy interval; None if no such t exists."""
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, then keep only the portions inside [start, end).
    # New list of new tuples: the caller's list and tuples are never touched.
    clipped = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        if finish <= start or begin >= end:
            continue
        clipped.append((max(begin, start), min(finish, end)))

    clipped.sort()

    # Invariant: `current` is the smallest t that avoids every interval seen so far,
    # so the remaining feasible starts are exactly [current, end - duration].
    current = start
    for begin, finish in clipped:
        if current + duration <= begin:
            return current
        if finish > current:
            current = finish
        if current + duration > end:
            return None

