def is_valid_ipv4(s: str) -> bool:
    """Return True only for a strict dotted-quad IPv4 string, e.g. '192.168.0.1'."""
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    digits = "0123456789"  # ASCII only; str.isdigit() would accept Unicode digits

    for part in parts:
        # 1-3 characters, ASCII digits only
        if not 1 <= len(part) <= 3:
            return False
        for ch in part:
            if ch not in digits:
                return False
        # no leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == "0":
