def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    pos = 0
    length = len(expr)

    def skip_whitespace():
        nonlocal pos
        while pos < length and expr[pos].isspace():
            pos += 1

    def parse_number():
        nonlocal pos
        skip_whitespace()

        start = pos
        while pos < length and "0" <= expr[pos] <= "9":
            pos += 1

        if pos == start:
            raise ValueError("expected a number")

        is_decimal = False
        if pos < length and expr[pos] == ".":
            is_decimal = True
            pos += 1
            fraction_start = pos
            while pos < length and "0" <= expr[pos] <= "9":
                pos += 1
            if pos == fraction_start:
                raise ValueError("malformed decimal literal")

        text = expr[start:pos]
        return float(text) if is_decimal else int(text)

    def parse_primary():
        nonlocal pos
        skip_whitespace()

        if pos < length and expr[pos] == "(":
            pos += 1
            value = parse_additive()
            skip_whitespace()
            if pos >= length or expr[pos] != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value

        return parse_number()

    def parse_power():
        nonlocal pos
        value = parse_primary()
        skip_whitespace()

        if pos < length and expr[pos] == "^":
            pos += 1
            value = value ** parse_unary()

        return value

    def parse_unary():
        nonlocal pos
        skip_whitespace()

        if pos < length and expr[pos] == "-":
            pos += 1
            return -parse_unary()

        return parse_power()

    def parse_multiplicative():
        nonlocal pos
        value = parse_unary()

        while True:
            skip_whitespace()
            if pos >= length or expr[pos] not in "*/":
                return value

            operator = expr[pos]
            pos += 1
            right = parse_unary()

            if operator == "*":
                value *= right
            else:
                try:
                    value /= right
                except ZeroDivisionError as exc:
                    raise ValueError("division by zero") from exc

    def parse_additive():
        nonlocal pos
        value = parse_multiplicative()

        while True:
            skip_whitespace()
            if pos >= length or expr[pos] not in "+-":
                return value

            operator = expr[pos]
            pos += 1
            right = parse_multiplicative()
            value = value + right if operator == "+" else value - right

    try:
        skip_whitespace()
        if pos == length:
            raise ValueError("empty expression")

        result = parse_additive()
        skip_whitespace()
        if pos != length:
            raise ValueError("malformed expression")
        return result
    except ZeroDivisionError as exc:
        raise ValueError("division by zero") from exc
    except RecursionError as exc:
        raise ValueError("expression is too deeply nested") from exc
