    if len(digits) == len(cap_text) and digits > cap_text:
        return cap + 1
    return int(digits)


def _parse_field(text: str, minimum: int, maximum: int) -> Set[int]:
    values: Set[int] = set()

    for item in text.split(","):
        match = _ITEM_PATTERN.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item: {!r}".format(item))

        base, step_text = match.groups()

        if step_text is None:
            step = 1
        else:
            # Any step larger than the field's width selects only its start.
            step = _capped_decimal(step_text, maximum - minimum + 1)
            if step == 0:
                raise ValueError("Cron steps must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start_text, end_text = base.split("-")
            start = _capped_decimal(start_text, maximum)
            end = _capped_decimal(end_text, maximum)
        else:
            start = _capped_decimal(base, maximum)
            end = maximum if step_text is not None else start

        if not (minimum <= start <= end <= maximum):
            raise ValueError("Cron value or range is out of bounds")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    """
    Return the first matching minute strictly after `after`.

    The search includes the five-calendar-year anniversary of `after`.
    If that anniversary is February 29 in a non-leap year, use February 28.
    All input and scheduling times are naive local times.
    """
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("A cron expression must have exactly five fields")

    bounds: List[Tuple[int, int]] = [
        (0, 59), (0, 23), (1, 31), (1, 12), (0, 6)
    ]
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, bounds)
    ]

    match = _TIME_PATTERN.fullmatch(after)
    if match is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    try:
        start = datetime(*(int(part) for part in match.groups()))
    except ValueError as exc:
        raise ValueError("after is not a valid date and time") from exc

    anniversary_year = start.year + 5
    if anniversary_year <= 9999:
        anniversary_day = min(
            start.day,
            calendar.monthrange(anniversary_year, start.month)[1],
        )
        deadline = start.replace(
            year=anniversary_year, day=anniversary_day
        )
    else:
        # No formatted Python datetime can lie beyond this point.
        deadline = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    start_date = start.date()
    last_date = deadline.date()
    current: date = start_date
    one_day = timedelta(days=1)

    while True:
        if current.month in months:
            dom_matches = current.day in month_days
            dow_matches = (current.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect_right(times, start.hour * 60 + start.minute)
                    if current == start_date
                    else 0
                )
                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(
                        current.year, current.month, current.day, hour, minute
                    )
                    if candidate <= deadline:
                        # Explicit formatting preserves four-digit early years
                        # on platforms where strftime("%Y") does not.
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {hour:02d}:{minute:02d}"
                        )

        if current == last_date:
            break
        current += one_day

