def dedupe_keep_order(items):
    """Return a new list with duplicates removed, preserving first occurrences.

    Two items are duplicates when they compare equal with ``==`` (so 1, 1.0
    and True are duplicates of one another).  Items do not need to be
    hashable, and the input list is never modified.
    """
    result = []            # all kept items, in original order
    by_hash = {}           # hash(item) -> list of kept (hashable) items with that hash
    unhashable_kept = []   # kept items for which hash() raised TypeError

    for item in items:
        try:
            key = hash(item)
        except TypeError:
            # Unhashable item (e.g. list, dict): it may be equal to any kept
            # item, so compare it against everything kept so far with ==.
            duplicate = False
            for kept in result:
                if item == kept:
                    duplicate = True
                    break
            if not duplicate:
                unhashable_kept.append(item)
                result.append(item)
            continue

        # Hashable item: it can only be equal to kept items with the same
        # hash, so restrict the scan to that bucket.  Comparison is done with
        # == explicitly (not with `in` on a set, which would also match an
        # identical-but-unequal object such as a NaN compared to itself).
        bucket = by_hash.get(key)
        duplicate = False
        if bucket is not None:
            for kept in bucket:
                if item == kept:
                    duplicate = True
                    break
        # A hashable item may still be == to a kept unhashable item
        # (e.g. frozenset({1}) == {1}), so check those too.
        if not duplicate:
            for kept in unhashable_kept:
                if item == kept:
                    duplicate = True
                    break
        if not duplicate:
            if bucket is None:
                by_hash[key] = [item]
            else:
                bucket.append(item)
            result.append(item)

    return result
