        if peek() == "-":
            position += 1
            return -parse_unary()
        return parse_power()

    def parse_product():
        nonlocal position
        value = parse_unary()
        while peek() in ("*", "/"):
            operator = peek()
            position += 1
            right = parse_unary()
            if operator == "*":
                value *= right
            else:
