def glob_match(pattern: str, name: str) -> bool:
    tokens = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash")
            tokens.append(("literal", pattern[i]))
            i += 1
        elif char == "*":
            double_star = i + 1 < len(pattern) and pattern[i + 1] == "*"
            tokens.append(("star", double_star))
            i += 2 if double_star else 1
        elif char == "?":
            tokens.append(("any",))
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            atoms = []
            if i < len(pattern) and pattern[i] == "]":
                atoms.append(("]", False))
                i += 1

            while i < len(pattern):
                if pattern[i] == "]":
                    break
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash")
                    atoms.append((pattern[i], True))
                    i += 1
                else:
                    atoms.append((pattern[i], False))
                    i += 1

            if i == len(pattern):
                raise ValueError("unclosed character set")
            i += 1

            singles = set()
            ranges = []
            j = 0
            while j < len(atoms):
                if (
                    j + 2 < len(atoms)
                    and atoms[j + 1] == ("-", False)
                ):
                    ranges.append((ord(atoms[j][0]), ord(atoms[j + 2][0])))
                    j += 3
                else:
                    singles.add(atoms[j][0])
                    j += 1

            tokens.append(("class", negate, singles, ranges))
        else:
            tokens.append(("literal", char))
            i += 1

    def matches(token, char):
        kind = token[0]
        if kind == "literal":
            return char == token[1]
        if kind == "any":
            return char != "/"
        if kind == "class":
            _, negate, singles, ranges = token
            found = char in singles or any(
                start <= ord(char) <= end for start, end in ranges
            )
            return not found if negate else found
        return False

    states = [False] * (len(name) + 1)
    states[0] = True

    for token in tokens:
        next_states = [False] * (len(name) + 1)
        if token[0] == "star":
            cross_slash = token[1]
            for j in range(len(name) + 1):
                next_states[j] = states[j] or (
                    j > 0
                    and next_states[j - 1]
                    and (cross_slash or name[j - 1] != "/")
                )
        else:
            for j in range(1, len(name) + 1):
                if states[j - 1] and matches(token, name[j - 1]):
                    next_states[j] = True
        states = next_states

    return states[len(name)]
