import string

_DIGITS = "0123456789"
_WS = " \t\n\r\v\f"
_OPS = "+-*/^()"


def tokenize(src):
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c in _WS:
            i += 1
        elif c in _DIGITS:
            j = i
            while j < n and src[j] in _DIGITS:
                j += 1
            if j < n and src[j] == ".":
                k = j + 1
                if k >= n or src[k] not in _DIGITS:
                    raise ValueError("malformed number literal")
                while k < n and src[k] in _DIGITS:
                    k += 1
                tokens.append(("num", float(src[i:k])))
                i = k
            else:
                tokens.append(("num", int(src[i:j])))
                i = j
        elif c in _OPS:
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError("unexpected character: %r" % c)
    return tokens


class _Parser:
    __slots__ = ("tokens", "pos")

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos][0]
        return None

    def advance(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.advance()[0]
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.unary()
        while self.peek() in ("*", "/"):
            op = self.advance()[0]
            rhs = self.unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    def unary(self):
        if self.peek() == "-":
            self.advance()
            return -self.unary()
        return self.power()

    def power(self):
        base = self.primary()
        if self.peek() == "^":
            self.advance()
            exponent = self.unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero")
        return base

    def primary(self):
        kind = self.peek()
        if kind == "num":
            return self.advance()[1]
        if kind == "(":
            self.advance()
            value = self.expr()
            if self.peek() != ")":
                raise ValueError("unbalanced parentheses")
            self.advance()
            return value
        raise ValueError("unexpected token or missing operand")


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    parser = _Parser(tokens)
    try:
        result = parser.expr()
    except ZeroDivisionError:
        raise ValueError("division by zero")
    if parser.pos != len(tokens):
        raise ValueError("trailing tokens in expression")
    return result
