_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.+)")


def _parse_version(text):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid semantic version")

    major, minor, patch = map(int, match.group(1, 2, 3))
    prerelease = match.group(4)

    if prerelease is not None:
        identifiers = prerelease.split(".")
        if any(
            identifier.isdigit()
            and len(identifier) > 1
            and identifier[0] == "0"
            for identifier in identifiers
        ):
            raise ValueError("invalid numeric prerelease identifier")
        prerelease = tuple(identifiers)

    return (major, minor, patch), prerelease


def _compare_versions(left, right):
    left_core, left_pre = left
    right_core, right_pre = right

    if left_core != right_core:
        return (left_core > right_core) - (left_core < right_core)

    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        if left_id == right_id:
            continue

        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()

        if left_numeric and right_numeric:
            left_value, right_value = int(left_id), int(right_id)
            return (left_value > right_value) - (left_value < right_value)
        if left_numeric != right_numeric:
            return -1 if left_numeric else 1
        return (left_id > right_id) - (left_id < right_id)

    return (len(left_pre) > len(right_pre)) - (len(left_pre) < len(right_pre))


def _parse_comparator(token):
    match = _COMPARATOR_RE.fullmatch(token)
    if match is None:
        raise ValueError("invalid comparator")

    operator = match.group(1) or "="
    version_text = match.group(2)

    if operator == "*" and version_text == "":
        return ("*", None)

    version = _parse_version(version_text)
    core, prerelease = version

    if operator == "^":
        if core[0] > 0:
            upper = ((core[0] + 1, 0, 0), None)
        elif core[1] > 0:
            upper = ((0, core[1] + 1, 0), None)
        else:
            upper = ((0, 0, core[2] + 1), None)
        return ("range", version, upper)

    if operator == "~":
        upper = ((core[0], core[1] + 1, 0), None)
        return ("range", version, upper)

    return (operator, version)


def semver_satisfies(version: str, constraint: str) -> bool:
