def first_bracket_error(s: str) -> int:
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []  # holds (opening_char, index)

    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append((ch, i))
        elif ch in pairs:
            if not stack or stack[-1][0] != pairs[ch]:
                # No unclosed opener, or the most recent one doesn't match.
                return i
            stack.pop()

    if stack:
        # Leftmost still-unclosed opener is at the bottom of the stack.
        return stack[0][1]
    return -1
