_DIGITS = "0123456789"
_OPERATORS = "+-*/^()"
_WHITESPACE = " \t\n\r\f\v"


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos]

    def advance(self):
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    # expr := term (('+' | '-') term)*
    def parse_expr(self):
        value = self.parse_term()
        while True:
            kind = self.peek()[0]
            if kind == "+":
                self.advance()
                value = value + self.parse_term()
            elif kind == "-":
                self.advance()
                value = value - self.parse_term()
            else:
                return value

    # term := unary (('*' | '/') unary)*
    def parse_term(self):
        value = self.parse_unary()
        while True:
            kind = self.peek()[0]
            if kind == "*":
                self.advance()
                value = value * self.parse_unary()
            elif kind == "/":
                self.advance()
                divisor = self.parse_unary()
                if divisor == 0:
                    raise ValueError("division by zero")
                value = value / divisor
            else:
                return value

    # unary := '-' unary | power
    def parse_unary(self):
        if self.peek()[0] == "-":
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    # power := atom ('^' unary)?
    def parse_power(self):
        base = self.parse_atom()
        if self.peek()[0] == "^":
            self.advance()
            exponent = self.parse_unary()
            return base ** exponent
        return base

    # atom := number | '(' expr ')'
    def parse_atom(self):
        kind, text = self.peek()
        if kind == "num":
            self.advance()
            if "." in text:
                return float(text)
            return int(text)
        if kind == "(":
            self.advance()
            value = self.parse_expr()
            if self.peek()[0] != ")":
                raise ValueError("unbalanced parentheses in expression")
            self.advance()
            return value
        raise ValueError("expected a number or '(' but found %r" % (text,))


def _tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch in _WHITESPACE:
            i += 1
            continue
        if ch in _DIGITS:
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            if j < n and expr[j] == ".":
                k = j + 1
                if k < n and expr[k] in _DIGITS:
                    while k < n and expr[k] in _DIGITS:
                        k += 1
                    tokens.append(("num", expr[i:k]))
                    i = k
                    continue
                raise ValueError("invalid number literal in expression")
            tokens.append(("num", expr[i:j]))
            i = j
            continue
        if ch in _OPERATORS:
            tokens.append((ch, ch))
            i += 1
            continue
        raise ValueError("unknown character %r in expression" % (ch,))
    tokens.append(("eof", None))
    return tokens


def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return an int or float."""
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    parser = _Parser(_tokenize(expr))
    value = parser.parse_expr()
    if parser.peek()[0] != "eof":
        raise ValueError("unexpected token in expression")
    return value
