def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:
    """Merge a list of closed [start, end] integer intervals.

    Overlapping intervals and intervals sharing an endpoint are combined
    (e.g. [1, 2] and [2, 3] become [1, 3]). Intervals containing merely
    adjacent integers (e.g. [1, 2] and [3, 4]) are kept separate. The input
    list and its inner lists are not modified; a new list of [start, end]
    lists sorted by start is returned.

    Raises:
        ValueError: if any interval has start > end.
    """
    validated = []
    for start, end in intervals:
        if start > end:
            raise ValueError(
                f"invalid interval [{start}, {end}]: start must not exceed end"
            )
        validated.append((start, end))

    validated.sort()

    merged = []
    for start, end in validated:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
