def wrap_text(text: str, width: int) -> list[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    words = [word for word in text.split(" ") if word]
    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            full_length = (len(word) // width) * width
            for start in range(0, full_length, width):
                piece = word[start:start + width]
                if start + width < len(word):
                    lines.append(piece)
                else:
                    current = piece

            remainder_start = full_length
            if remainder_start < len(word):
                current = word[remainder_start:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
