def rle_decode(s: str) -> str:
    result = []
    total_length = 0
    i = 0

    while i < len(s):
        if not ("0" <= s[i] <= "9"):
            raise ValueError("missing count")

        count_start = i
        count = 0
        while i < len(s) and "0" <= s[i] <= "9":
            if i == count_start and s[i] == "0":
                raise ValueError("count must be positive with no leading zero")
            count = count * 10 + ord(s[i]) - ord("0")
            if count > 10000:
                raise ValueError("decoded output exceeds 10000 characters")
            i += 1

        if count == 0:
            raise ValueError("count must be positive")
        if i == len(s):
            raise ValueError("input ends with digits")

        char = s[i]
        i += 1

        total_length += count
        if total_length > 10000:
            raise ValueError("decoded output exceeds 10000 characters")

        result.append(char * count)

    return "".join(result)
