import re
from datetime import datetime, timedelta

_NUM_RE = re.compile(r"^[0-9]+$")


def _num(text):
    """Parse a non-negative decimal integer, strictly ASCII digits."""
    if not _NUM_RE.match(text):
        raise ValueError("invalid number: %r" % (text,))
    return int(text)


def _parse_field(field, lo, hi):
    """Expand one cron field into the set of values it matches."""
    if field == "":
        raise ValueError("empty field")
    values = set()
    for item in field.split(","):
        pieces = item.split("/")
        if len(pieces) > 2:
            raise ValueError("malformed item: %r" % (item,))
        base = pieces[0]
        has_step = len(pieces) == 2
        step = 1
        if has_step:
            step = _num(pieces[1])
            if step < 1:
                raise ValueError("step must be >= 1: %r" % (item,))

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            bounds = base.split("-")
            if len(bounds) != 2:
                raise ValueError("malformed range: %r" % (base,))
            start = _num(bounds[0])
            end = _num(bounds[1])
            if start > end:
                raise ValueError("reversed range: %r" % (base,))
            if start < lo or end > hi:
                raise ValueError("range out of bounds: %r" % (base,))
        else:
            start = _num(base)
            if start < lo or start > hi:
                raise ValueError("value out of bounds: %r" % (base,))
            end = hi if has_step else start

        values.update(range(start, end + 1, step))
    return values


def _add_years(dt, years):
    year = dt.year + years
    try:
        return dt.replace(year=year)
    except ValueError:               # 29 February -> non-leap target year
        return dt.replace(year=year, month=2, day=28)


def _day_matches(day, doms, dows, dom_restricted, dow_restricted):
    in_dom = day.day in doms
    in_dow = ((day.weekday() + 1) % 7) in dows   # Monday=0 -> Sunday=0
    if dom_restricted and dow_restricted:
        return in_dom or in_dow
    if dom_restricted:
        return in_dom
    if dow_restricted:
        return in_dow
    return True


def next_cron(expr, after):
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected exactly 5 fields, got %d" % (len(fields),))

    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dows = _parse_field(fields[4], 0, 6)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError):
        raise ValueError("invalid 'after' value: %r" % (after,))

    limit = _add_years(start, 5)
    current = start + timedelta(minutes=1)

    ordered_hours = sorted(hours)
    ordered_minutes = sorted(minutes)

    day = current.date()
    last_day = limit.date()
    while day <= last_day:
        if day.month in months and _day_matches(
            day, doms, dows, dom_restricted, dow_restricted
        ):
            for hh in ordered_hours:
                for mm in ordered_minutes:
                    candidate = datetime(day.year, day.month, day.day, hh, mm)
                    if candidate < current or candidate > limit:
                        continue
                    return candidate.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years: %r" % (expr,))
