import re

_VERSION_RE = re.compile(r"([0-9]+(?:\.[0-9]+)*)(?:-([A-Za-z0-9]+))?")


def compare_versions(a: str, b: str) -> int:
    def parse(v: str):
        m = _VERSION_RE.fullmatch(v)
        if m is None:
            raise ValueError("invalid version: %r" % (v,))
        nums = [int(part) for part in m.group(1).split(".")]
        return nums, m.group(2)

    nums_a, tag_a = parse(a)
    nums_b, tag_b = parse(b)

    length = max(len(nums_a), len(nums_b))
    nums_a = nums_a + [0] * (length - len(nums_a))
    nums_b = nums_b + [0] * (length - len(nums_b))

    if nums_a < nums_b:
        return -1
    if nums_a > nums_b:
        return 1

    if tag_a == tag_b:
        return 0
    if tag_a is None:
        return 1
    if tag_b is None:
        return -1
    return -1 if tag_a < tag_b else 1
