def merge_intervals(intervals):
    """Merge overlapping or endpoint-sharing closed integer intervals.

    Returns a new list of ``[start, end]`` lists sorted by start.  The input
    list and its inner lists are never modified.  Raises ``ValueError`` if any
    interval has ``start > end``.
    """
    pairs = []
    for interval in intervals:
        start, end = interval[0], interval[1]
        if start > end:
            raise ValueError(
                "invalid interval: start {0} > end {1}".format(start, end)
            )
        pairs.append((start, end))

    pairs.sort()

    merged = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged


