def dedupe_keep_order(items):
    kept = []
    seen_by_hash = {}
    seen_unhashable = []
    for item in items:
        try:
            h = hash(item)
        except TypeError:
            # Unhashable item: must compare against every kept item,
            # since it may be equal to a hashable one (e.g. set vs frozenset).
            if any(item == k for k in kept):
                continue
            seen_unhashable.append(item)
        else:
            # Hashable item: compare (with ==, not identity) against kept
            # items sharing its hash, plus any kept unhashable items.
            if any(item == k for k in seen_by_hash.get(h, ())) or any(
                item == k for k in seen_unhashable
            ):
                continue
            seen_by_hash.setdefault(h, []).append(item)
        kept.append(item)
    return kept
