def evaluate(expr: str):
    """Evaluate arithmetic using an iterative operator-stack parser."""
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3, "^": 4}

    def apply_operator():
        operator = operators.pop()

        if operator == "neg":
            if not values:
                raise ValueError("Missing operand")
            values.append(-values.pop())
            return

        if len(values) < 2:
            raise ValueError("Missing operand")

        right = values.pop()
        left = values.pop()

        try:
            if operator == "+":
                result = left + right
            elif operator == "-":
                result = left - right
            elif operator == "*":
                result = left * right
            elif operator == "/":
                result = left / right
            else:
                result = left ** right
        except ZeroDivisionError as exc:
            raise ValueError("Division by zero") from exc

        values.append(result)

    index = 0
    expecting_operand = True

    while index < len(expr):
        char = expr[index]

        if char.isspace():
            index += 1
            continue

        if "0" <= char <= "9":
            if not expecting_operand:
                raise ValueError("Missing operator")

            start = index
            while index < len(expr) and "0" <= expr[index] <= "9":
                index += 1

            is_decimal = index < len(expr) and expr[index] == "."
            if is_decimal:
                index += 1
                fraction_start = index
                while index < len(expr) and "0" <= expr[index] <= "9":
                    index += 1
                if index == fraction_start:
                    raise ValueError("Expected digits after decimal point")

            literal = expr[start:index]
            values.append(float(literal) if is_decimal else int(literal))
            expecting_operand = False
            continue

        if char == "(":
            if not expecting_operand:
                raise ValueError("Implicit multiplication is not allowed")
            operators.append("(")

        elif char == ")":
            if expecting_operand:
                raise ValueError("Missing operand before closing parenthesis")

            while operators and operators[-1] != "(":
                apply_operator()

            if not operators:
                raise ValueError("Unbalanced parentheses")
            operators.pop()

        elif char in "+-*/^":
            if expecting_operand:
                if char != "-":
                    raise ValueError("Expected an operand")
                # Prefix minus never pops operators: this permits 2 ^ -1.
                operators.append("neg")
            else:
                # Power is right-associative; other binary operators are left.
                while operators and operators[-1] != "(":
                    top_precedence = precedence[operators[-1]]
                    current_precedence = precedence[char]
                    if top_precedence < current_precedence:
                        break
                    if top_precedence == current_precedence and char == "^":
                        break
                    apply_operator()

                operators.append(char)
                expecting_operand = True

        else:
            raise ValueError("Unknown character: {!r}".format(char))

        index += 1

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        if operators[-1] == "(":
            raise ValueError("Unbalanced parentheses")
        apply_operator()

    if len(values) != 1:
        raise ValueError("Malformed expression")

    return values[0]


