from datetime import date, datetime, timedelta

_DIGITS = frozenset("0123456789")


def _is_num(s):
    return bool(s) and all(ch in _DIGITS for ch in s)


def _parse_field(field, lo, hi):
    """Expand one cron field into the set of matching integer values."""
    if not field:
        raise ValueError("empty cron field")
    values = set()
    for item in field.split(","):
        has_step = "/" in item
        if has_step:
            base, _, step_s = item.partition("/")
            if not _is_num(step_s):
                raise ValueError("invalid step in %r" % (item,))
            step = int(step_s)
            if step < 1:
                raise ValueError("step must be >= 1 in %r" % (item,))
        else:
            base = item
            step = 1

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a, _, b = base.partition("-")
            if "-" in b or not _is_num(a) or not _is_num(b):
                raise ValueError("invalid range in %r" % (item,))
            start, end = int(a), int(b)
            if start > end:
                raise ValueError("reversed range in %r" % (item,))
        else:
            if not _is_num(base):
                raise ValueError("invalid value in %r" % (item,))
            start = int(base)
            # "a/n" runs from a up to the field maximum, "a" is just a
            end = hi if has_step else start

        if start < lo or end > hi:
            raise ValueError("value out of range in %r" % (item,))
        values.update(range(start, end + 1, step))
    return values


def _plus_years(d, n):
    try:
        return d.replace(year=d.year + n)
    except ValueError:          # Feb 29 -> Feb 28
        return date(d.year + n, d.month, 28)


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected exactly 5 fields, got %d" % len(fields))
    minute_f, hour_f, dom_f, mon_f, dow_f = fields

    minutes = sorted(_parse_field(minute_f, 0, 59))
    hours = sorted(_parse_field(hour_f, 0, 23))
    doms = _parse_field(dom_f, 1, 31)
    months = _parse_field(mon_f, 1, 12)
    dows = _parse_field(dow_f, 0, 6)

    dom_restricted = dom_f != "*"
    dow_restricted = dow_f != "*"

    start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    last_day = _plus_years(start.date(), 5)

    def day_matches(d):
        if d.month not in months:
            return False
        cron_dow = (d.weekday() + 1) % 7      # Python: Mon=0 -> cron: Sun=0
        if dom_restricted and dow_restricted:
            return d.day in doms or cron_dow in dows
        if dom_restricted:
            return d.day in doms
        if dow_restricted:
            return cron_dow in dows
        return True

    day = start.date()
    while day <= last_day:
        if day_matches(day):
            for h in hours:
                for m in minutes:
                    t = datetime(day.year, day.month, day.day, h, m)
                    if t > start:
                        return t.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years after %s" % after)
