"""npm-style semantic-version constraint matching.

Implements Semantic Versioning 2.0.0 precedence together with the subset of
npm range syntax described by::

    version    := <major> "." <minor> "." <patch> [ "-" pre ] [ "+" build ]
    constraint := group ( "||" group )*
    group      := comparator ( WS comparator )*
    comparator := ( "=" | ">" | ">=" | "<" | "<=" | "^" | "~" ) version
                | "*"

Build metadata is parsed but never compared.  Only the standard library is
used; the target runtime is Python 3.9+.
"""

import re
from typing import List, Optional, Set, Tuple

__all__ = ["semver_satisfies"]

# A parsed version: (major, minor, patch, ("alpha", "1", ...)).  The fourth
# element is an empty tuple when the version carries no pre-release tag.
_Version = Tuple[int, int, int, Tuple[str, ...]]

# A primitive comparator: (operator, version).  (None, None) is the bare "*"
# wildcard, which every version satisfies subject to the pre-release rule.
_Comparator = Tuple[Optional[str], Optional[_Version]]

# A parsed group: its primitive comparators plus the MAJOR.MINOR.PATCH keys of
# the comparators that were written with a pre-release tag.
_Group = Tuple[List[_Comparator], Set[Tuple[int, int, int]]]

# MAJOR.MINOR.PATCH, numeric parts free of leading zeros, optional pre-release
# tag, optional (ignored) build tag.  Both tags are dot-separated runs of
# non-empty identifiers made of ASCII letters, digits and hyphens.
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)"
    r"\.(0|[1-9][0-9]*)"
    r"\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

# An operator directly followed by a version, e.g. ">=1.2.3".  The operator is
# optional (a bare version means "="); a whitespace-separated operator such as
# "> 1.2.3" does not match and is rejected as an invalid comparator.
_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)")


def _parse_version(text: str) -> _Version:
    """Parse a semantic version string into its comparable tuple form."""
    if not isinstance(text, str):
        raise ValueError("version must be a string, got {!r}".format(text))
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: {!r}".format(text))
    major, minor, patch, prerelease, _build = match.groups()
    if prerelease is None:
        identifiers: Tuple[str, ...] = ()
    else:
        identifiers = tuple(prerelease.split("."))
        for identifier in identifiers:
            if len(identifier) > 1 and identifier[0] == "0" and identifier.isdigit():
                raise ValueError(
                    "numeric pre-release identifier has a leading zero: "
                    "{!r}".format(identifier)
                )
    return (int(major), int(minor), int(patch), identifiers)


def _compare_prerelease(left: Tuple[str, ...], right: Tuple[str, ...]) -> int:
    """Compare two pre-release tag identifier sequences (SemVer 2.0.0)."""
    if not left and not right:
        return 0
    if not left:  # no pre-release outranks any pre-release
        return 1
    if not right:
        return -1
    for left_id, right_id in zip(left, right):
        if left_id == right_id:
            continue
        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()
        if left_numeric and right_numeric:
            return -1 if int(left_id) < int(right_id) else 1
        if left_numeric:  # numeric identifiers rank below alphanumeric ones
            return -1
        if right_numeric:
            return 1
        return -1 if left_id < right_id else 1
    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left: _Version, right: _Version) -> int:
    """Total order over parsed versions: -1, 0 or 1."""
    if left[:3] != right[:3]:
        return -1 if left[:3] < right[:3] else 1
    return _compare_prerelease(left[3], right[3])


def _caret_upper_bound(version: _Version) -> _Version:
    """Exclusive upper bound of ^version."""
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, ())
    if minor > 0:
        return (0, minor + 1, 0, ())
    return (0, 0, patch + 1, ())


def _tilde_upper_bound(version: _Version) -> _Version:
    """Exclusive upper bound of ~version."""
    return (version[0], version[1] + 1, 0, ())


def _parse_group(text: str) -> _Group:
    """Parse one "||"-separated group into primitive comparators."""
    tokens = text.split()
    if not tokens:
        raise ValueError("empty comparator group in constraint: {!r}".format(text))
    comparators: List[_Comparator] = []
    for token in tokens:
        match = _COMPARATOR_RE.fullmatch(token)
        if match is None:
            raise ValueError("invalid comparator: {!r}".format(token))
        operator = match.group(1)
        version_text = match.group(2)
        if operator is None and version_text == "*":
            comparators.append((None, None))
            continue
        if not version_text:
            raise ValueError("invalid comparator: {!r}".format(token))
        version = _parse_version(version_text)
        if operator is None or operator == "=":
            comparators.append(("=", version))
        elif operator in (">", ">=", "<", "<="):
            comparators.append((operator, version))
        elif operator == "^":
            comparators.append((">=", version))
            comparators.append(("<", _caret_upper_bound(version)))
        else:  # "~"
            comparators.append((">=", version))
            comparators.append(("<", _tilde_upper_bound(version)))
    prerelease_keys: Set[Tuple[int, int, int]] = set()
    for _, target in comparators:
        if target is not None and target[3]:
            prerelease_keys.add(target[:3])
    return (comparators, prerelease_keys)


def _satisfies_group(group: _Group, version: _Version) -> bool:
    """Check one group, including the pre-release opt-in rule."""
    comparators, prerelease_keys = group
    for operator, target in comparators:
        if operator is None:  # bare "*"
            continue
        order = _compare_versions(version, target)
        if operator == "=":
            if order != 0:
                return False
        elif operator == ">":
            if order <= 0:
                return False
        elif operator == ">=":
            if order < 0:
                return False
        elif operator == "<":
            if order >= 0:
                return False
        else:  # "<="
            if order > 0:
                return False
    if version[3] and version[:3] not in prerelease_keys:
        # A pre-release version needs an explicit pre-release comparator on the
        # very same MAJOR.MINOR.PATCH inside this group to be considered.
        return False
    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    """Return True if *version* satisfies the npm-style range *constraint*.

    ``version`` must be a full ``MAJOR.MINOR.PATCH`` semantic version with an
    optional pre-release and build tag; build metadata never affects the
    result.  ``constraint`` is one or more whitespace-separated comparator
    groups joined by ``||``; the version satisfies the constraint when it
    satisfies at least one group.

    Raises ``ValueError`` for a malformed version, a malformed comparator, or
    an empty (or empty-group) constraint.
    """
    parsed_version = _parse_version(version)
    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string, got {!r}".format(constraint))
    if not constraint.strip():
        raise ValueError("empty constraint")
    # Parse every group up front so that malformed comparators always raise,
    # even when an earlier group already matches.
    groups = [_parse_group(part) for part in constraint.split("||")]
    return any(_satisfies_group(group, parsed_version) for group in groups)
