def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    i = 0
    n = len(expr)

    def skip_whitespace():
        nonlocal i
        while i < n and expr[i].isspace():
            i += 1

    def parse_sum():
        nonlocal i
        value = parse_product()
        while True:
            skip_whitespace()
            if i < n and expr[i] in "+-":
                op = expr[i]
                i += 1
                right = parse_product()
                value = value + right if op == "+" else value - right
            else:
                return value

    def parse_product():
        nonlocal i
        value = parse_unary()
        while True:
            skip_whitespace()
            if i < n and expr[i] in "*/":
                op = expr[i]
                i += 1
                right = parse_unary()
                if op == "*":
                    value *= right
                else:
                    try:
                        value /= right
                    except ZeroDivisionError:
                        raise ValueError("division by zero") from None
            else:
                return value

    def parse_unary():
        nonlocal i
        skip_whitespace()
        if i < n and expr[i] == "-":
            i += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal i
        value = parse_atom()
        skip_whitespace()
        if i < n and expr[i] == "^":
            i += 1
            value = value ** parse_unary()
        return value

    def parse_atom():
        nonlocal i
        skip_whitespace()
        if i >= n:
            raise ValueError("missing operand")

        if expr[i] == "(":
            i += 1
            value = parse_sum()
            skip_whitespace()
            if i >= n or expr[i] != ")":
                raise ValueError("unbalanced parentheses")
            i += 1
            return value

        if "0" <= expr[i] <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            is_decimal = False
            if i < n and expr[i] == ".":
                is_decimal = True
                i += 1
                fraction_start = i
                while i < n and "0" <= expr[i] <= "9":
                    i += 1
                if i == fraction_start:
                    raise ValueError("invalid decimal literal")
            text = expr[start:i]
            return float(text) if is_decimal else int(text)

        raise ValueError("invalid expression")

    skip_whitespace()
    if i == n:
        raise ValueError("empty expression")

    result = parse_sum()
    skip_whitespace()
    if i != n:
        raise ValueError("invalid expression")
    return result
