def mask_email(s: str) -> str:
    """Mask the local part of an email address, leaving the domain intact.

    Raises ValueError unless `s` contains exactly one "@", with a non-empty
    local part before it and a non-empty domain after it.
    """
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    if s.count("@") != 1:
        raise ValueError("email must contain exactly one '@'")

    local, domain = s.split("@")

    if not local or not domain:
        raise ValueError("email must have a non-empty local part and domain")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
