import re
from typing import List, Union

Token = str
Number = Union[int, float]

_TOKEN_RE = re.compile(r"\d+\.\d+|\d+|[()+\-*/^]")


def _tokenize(expr: str) -> List[Token]:
    tokens: List[Token] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        match = _TOKEN_RE.match(expr, i)
        if match is None:
            raise ValueError("unexpected character {!r} at position {}".format(ch, i))
        tokens.append(match.group())
        i = match.end()
    return tokens


class _Parser:
    def __init__(self, tokens: List[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self) -> Token:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        self._pos += 1
        return tok

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expression()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected token {!r}".format(self._tokens[self._pos]))
        return value

    # expr := term (('+' | '-') term)*
    def _expression(self) -> Number:
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._advance()
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/') unary)*
    def _term(self) -> Number:
        value = self._unary()
        while self._peek() in ("*", "/"):
            op = self._advance()
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            else:
                try:
                    value = value / rhs
                except ZeroDivisionError:
                    raise ValueError("division by zero")
        return value

    # unary := '-' unary | power
    def _unary(self) -> Number:
        if self._peek() == "-":
            self._advance()
            return -self._unary()
        return self._power()

    # power := primary ('^' unary)?     (right-associative)
    def _power(self) -> Number:
        base = self._primary()
        if self._peek() == "^":
            self._advance()
            exponent = self._unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero")
        return base

    def _primary(self) -> Number:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if tok == "(":
            self._advance()
            value = self._expression()
            if self._peek() != ")":
                raise ValueError("unbalanced parentheses")
            self._advance()
            return value
        if not tok[0].isdigit():
            raise ValueError("unexpected token {!r}".format(tok))
        self._advance()
        return float(tok) if "." in tok else int(tok)


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression string and return an int or float.

    Raises ValueError for malformed input and for division by zero.
    """
    return _Parser(_tokenize(expr)).parse()
