def dedupe_keep_order(items):
    """Return a new list: first occurrences only, original order preserved.

    Equality follows ==, so 1, 1.0 and True collapse together, and unhashable
    items (lists, dicts, sets) are supported. The input list is not modified.
    """
    result = []
    by_hash = {}
    unhashables = []

    for item in items:
        try:
            bucket = by_hash.setdefault(hash(item), [])
        except TypeError:
            bucket = unhashables

        # Duplicate within the same hash bucket / among the unhashable items.
        if any(seen == item for seen in bucket):
            continue

        # Cross-check, since e.g. set and frozenset can be == while only one
        # of them is hashable.
        if bucket is unhashables:
            if by_hash and any(seen == item for group in by_hash.values() for seen in group):
                continue
        elif unhashables and any(seen == item for seen in unhashables):
            continue

        result.append(item)
        bucket.append(item)

    return result
