def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    stack = []
    for comp in p.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                stack.append("..")
        else:
            stack.append(comp)

    body = "/".join(stack)
    if absolute:
        return "/" + body if body else "/"
    return body if body else "."
