_WORD_RE = re.compile(r"[A-Za-z]+")


def top_k_words(text: str, k: int):
    """Return the k most frequent ASCII-letter words in *text*.

    Words are maximal runs of [A-Za-z]; every other character (digits,
    apostrophes, underscores, non-ASCII letters, punctuation, whitespace)
    is a separator. Counting is case-insensitive and words are returned
    lowercased. Results are sorted by count descending, then alphabetically
    ascending, and returned as a list of [word, count] pairs.
    """
    if k <= 0:
        return []

    counts = Counter(match.group(0).lower() for match in _WORD_RE.finditer(text))
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [[word, count] for word, count in ordered[:k]]
