import re
from datetime import datetime, timedelta


def next_cron(expr: str, after: str) -> str:
    field_specs = (
        (0, 59),
        (0, 23),
        (1, 31),
        (1, 12),
        (0, 6),
    )
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly five fields")

    parsed = []
    restricted = []

    for field, (minimum, maximum) in zip(fields, field_specs):
        values = set()
        is_restricted = field != "*"

        for item in field.split(","):
            if not item:
                raise ValueError("empty cron item")

            match = re.fullmatch(r"(\*|\d+(?:-\d+)?)(?:/(\d+))?", item)
            if match is None:
                raise ValueError("malformed cron item")

            base, step_text = match.groups()
            step = int(step_text) if step_text is not None else 1
            if step < 1:
                raise ValueError("step must be at least 1")

            if base == "*":
                start, end = minimum, maximum
            elif "-" in base:
                start_text, end_text = base.split("-", 1)
                start, end = int(start_text), int(end_text)
                if start > end:
                    raise ValueError("range start exceeds range end")
            else:
                start = int(base)
                end = maximum if step_text is not None else start

            if start < minimum or start > maximum or end < minimum or end > maximum:
                raise ValueError("cron value out of range")

            values.update(range(start, end + 1, step))

        parsed.append(values)
        restricted.append(is_restricted)

    try:
        current = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except (TypeError, ValueError) as exc:
        raise ValueError("after must be formatted as YYYY-MM-DD HH:MM") from exc

    minute_values, hour_values, dom_values, month_values, dow_values = parsed
    dom_restricted, dow_restricted = restricted[2], restricted[4]

    limit = current + timedelta(days=366 * 5 + 2)
    candidate = current.replace(second=0, microsecond=0) + timedelta(minutes=1)

    while candidate <= limit:
        if candidate.month not in month_values:
            candidate = (candidate.replace(day=1, hour=0, minute=0) + timedelta(days=1))
            continue

        cron_dow = (candidate.weekday() + 1) % 7
        dom_match = candidate.day in dom_values
        dow_match = cron_dow in dow_values

        if dom_restricted and dow_restricted:
            day_match = dom_match or dow_match
        elif dom_restricted:
            day_match = dom_match
        elif dow_restricted:
            day_match = dow_match
        else:
            day_match = True

        if not day_match:
            candidate = (candidate.replace(hour=0, minute=0) + timedelta(days=1))
            continue

        if candidate.hour not in hour_values:
            candidate = candidate.replace(minute=0) + timedelta(hours=1)
            continue

        if candidate.minute not in minute_values:
            candidate = candidate.replace(second=0, microsecond=0) + timedelta(minutes=1)
            continue

        return candidate.strftime("%Y-%m-%d %H:%M")

    raise ValueError("no matching time within five years")
