def earliest_slot(busy, duration, start, end):
    """Return the earliest t with start <= t and t + duration <= end
    such that [t, t + duration) meets no busy interval; None if impossible.

    Busy intervals are half-open (begin, finish) and may be unsorted,
    overlapping, or touching. The input list is never modified.
    """
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Collect the busy intervals clipped to the window [start, end),
    # discarding the parts that fall outside it.
    clipped = []
    for interval in busy:
        begin, finish = interval[0], interval[1]
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        if finish <= start or begin >= end:
            continue
        clipped.append((max(begin, start), min(finish, end)))

    # Sort and merge overlapping/touching intervals.
    clipped.sort()
    merged = []
    for begin, finish in clipped:
        if merged and begin <= merged[-1][1]:
            if finish > merged[-1][1]:
                merged[-1] = (merged[-1][0], finish)
        else:
            merged.append((begin, finish))

    # Scan the free gaps in order.
    cursor = start
    for begin, finish in merged:
        if begin - cursor >= duration:
            return cursor
        if finish > cursor:
            cursor = finish
    if end - cursor >= duration:
        return cursor
    return None
