"""Anchored, case-sensitive glob matching for path-like strings (stdlib only)."""

from functools import lru_cache


def _parse_class(pattern, start):
    """Parse a bracket expression at pattern[start] == '['.

    Returns (token, next_index); token is ('cls', negated, items) where items
    is a list of inclusive (lo, hi) code-point ranges.
    """
    length = len(pattern)
    i = start + 1

    negated = False
    if i < length and pattern[i] == '!':
        negated = True
        i += 1

    items = []
    first = True
    while True:
        if i >= length:
            raise ValueError("unterminated character class: missing ']'")

        if pattern[i] == '\\':
            if i + 1 >= length:
                raise ValueError("pattern ends with a backslash")
            lo = pattern[i + 1]
            i += 2
        elif pattern[i] == ']' and not first:
            i += 1
            break
        else:
            # A ']' in the first position (after '[' or '[!') is a literal ']'.
            lo = pattern[i]
            i += 1
        first = False

        # A '-' forms a range only if it is followed by a character that is
        # not the closing ']' (so a leading or trailing '-' is literal).
        if (i + 1) < length and pattern[i] == '-' and pattern[i + 1] != ']':
            i += 1
            if pattern[i] == '\\':
                if i + 1 >= length:
                    raise ValueError("pattern ends with a backslash")
                hi = pattern[i + 1]
                i += 2
            else:
                hi = pattern[i]
                i += 1
            items.append((lo, hi))          # reversed ranges match nothing
        else:
            items.append((lo, lo))

    if not items:
        raise ValueError("empty character class")

    return ('cls', negated, items), i


def _tokenize(pattern):
    """Turn a pattern into a list of tokens, raising ValueError on errors."""
    tokens = []
    length = len(pattern)
    i = 0
    while i < length:
        ch = pattern[i]
        if ch == '\\':
            if i + 1 >= length:
                raise ValueError("pattern ends with a backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif ch == '*':
            j = i
            while j < length and pattern[j] == '*':
                j += 1
            # A run of two or more '*' is '**' (may cross '/'); a single one is '*'.
            tokens.append(('dstar',) if j - i >= 2 else ('star',))
            i = j
        elif ch == '?':
            tokens.append(('any',))
            i += 1
        elif ch == '[':
            token, i = _parse_class(pattern, i)
            tokens.append(token)
        else:
            tokens.append(('lit', ch))
            i += 1
    return tokens


def _class_match(token, ch):
    negated = token[1]
    hit = False
    for lo, hi in token[2]:
        if lo <= ch <= hi:
            hit = True
            break
    return hit != negated


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches `pattern` (case-sensitive)."""
    tokens = _tokenize(pattern)
    ntokens = len(tokens)
    nlen = len(name)

    @lru_cache(maxsize=None)
    def match(ti, ni):
        while True:
            if ti == ntokens:
                return ni == nlen

            token = tokens[ti]
            kind = token[0]

            if kind == 'lit':
                if ni < nlen and name[ni] == token[1]:
                    ti += 1
                    ni += 1
                    continue
                return False

            if kind == 'any':
                if ni < nlen and name[ni] != '/':
                    ti += 1
                    ni += 1
                    continue
                return False

            if kind == 'cls':
                if ni < nlen and _class_match(token, name[ni]):
                    ti += 1
                    ni += 1
                    continue
                return False

            if kind == 'star':
                if match(ti + 1, ni):
                    return True
                k = ni
                while k < nlen and name[k] != '/':
                    k += 1
                    if match(ti + 1, k):
                        return True
                return False

            if kind == 'dstar':
                for k in range(ni, nlen + 1):
                    if match(ti + 1, k):
                        return True
                return False

            raise AssertionError("unreachable token kind: %r" % (kind,))

    return match(0, 0)
