def parse_duration(s: str) -> int:
    multipliers = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen = set()
    total = 0
    i = 0
    n = len(s)

    while i < n:
        while i < n and s[i] == " ":
            i += 1
        if i == n:
            break

        if not ("0" <= s[i] <= "9"):
            raise ValueError("Expected an ASCII decimal integer")

        value = 0
        while i < n and "0" <= s[i] <= "9":
            value = value * 10 + ord(s[i]) - ord("0")
            i += 1

        if i == n or s[i] not in multipliers:
            raise ValueError("Expected a unit immediately after the number")

        unit = s[i]
        if unit in seen:
            raise ValueError("Repeated unit")

        seen.add(unit)
        total += value * multipliers[unit]
        i += 1

    if not seen:
        raise ValueError("Duration must contain at least one part")

    return total
