def normalize_path(p: str) -> str:
    """Normalize a Unix-style path (lexically, no filesystem access)."""
    absolute = p.startswith("/")
    parts = []
    for comp in p.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not absolute:
                parts.append("..")
            # for absolute paths, ".." at the root is ignored
        else:
            parts.append(comp)

    if absolute:
        return "/" + "/".join(parts)
    if not parts:
        return "."
    return "/".join(parts)
