def earliest_slot(
    busy: list[tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> int | None:
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    relevant: list[tuple[int, int]] = []

    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

        clipped_begin = max(begin, start)
        clipped_finish = min(finish, end)

        if clipped_begin < clipped_finish:
            relevant.append((clipped_begin, clipped_finish))

    relevant.sort()

    merged: list[list[int]] = []
    for begin, finish in relevant:
        if merged and begin <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], finish)
        else:
            merged.append([begin, finish])

    candidate = start

    for begin, finish in merged:
        if candidate + duration <= begin:
            return candidate
        candidate = max(candidate, finish)

    if candidate + duration <= end:
        return candidate

    return None
