import re
from typing import List, NamedTuple, Optional, Set, Tuple


# Requirements:
# 1. Validate complete SemVer versions, including pre-release and build syntax.
# 2. Compare versions using SemVer precedence, ignoring build metadata.
# 3. Parse OR groups containing AND-connected comparators.
# 4. Expand caret and tilde comparators into inclusive/exclusive bounds.
# 5. Apply pre-release eligibility separately within each group.
# 6. Validate the entire constraint before evaluating any group.
#
# Edge cases:
# - Reject empty constraints, empty OR groups, malformed operators, partial
#   versions, leading zeros, empty identifiers, and non-ASCII identifiers.
# - Allow leading zeros in build metadata, which never affects comparisons.
# - A wildcard alone does not admit pre-release versions.
# - Only explicitly written comparator versions grant pre-release eligibility.
# - Invalid comparators raise even when another OR group would match.


_Core = Tuple[int, int, int]


class _Version(NamedTuple):
    core: _Core
    prerelease: Optional[Tuple[str, ...]]


_VERSION_PATTERN = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_COMPARATOR_PATTERN = re.compile(r"(>=|<=|[=<>^~])?(.+)")


def _parse_version(text: str) -> _Version:
    match = _VERSION_PATTERN.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    major, minor, patch, prerelease_text, _build = match.groups()
    prerelease = (
        tuple(prerelease_text.split("."))
        if prerelease_text is not None
        else None
    )

    if prerelease is not None:
        for identifier in prerelease:
            if (
                identifier.isdigit()
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                raise ValueError(
                    "Numeric pre-release identifier has a leading zero: {!r}"
                    .format(text)
                )

    return _Version((int(major), int(minor), int(patch)), prerelease)


def _compare(left: _Version, right: _Version) -> int:
    if left.core != right.core:
        return -1 if left.core < right.core else 1

    left_pre = left.prerelease
    right_pre = right.prerelease

    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        if left_id == right_id:
            continue

        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()

        if left_numeric and right_numeric:
            # Valid numeric identifiers have no leading zeros, so length
            # followed by lexical order is equivalent to numeric order.
            left_key = (len(left_id), left_id)
            right_key = (len(right_id), right_id)
            return -1 if left_key < right_key else 1

        if left_numeric != right_numeric:
            return -1 if left_numeric else 1

        return -1 if left_id < right_id else 1

    return (len(left_pre) > len(right_pre)) - (
        len(left_pre) < len(right_pre)
    )


def semver_satisfies(version: str, constraint: str) -> bool:
    """Return whether version satisfies constraint; reject invalid syntax."""
    candidate = _parse_version(version)

    if not constraint.strip():
        raise ValueError("Constraint must not be empty")

    groups: List[
        Tuple[List[Tuple[str, _Version]], Set[_Core]]
    ] = []

    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint contains an empty group")

        comparisons: List[Tuple[str, _Version]] = []
        prerelease_cores: Set[_Core] = set()

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_PATTERN.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            target = _parse_version(match.group(2))

            if target.prerelease is not None:
                prerelease_cores.add(target.core)

            if operator in ("^", "~"):
                major, minor, patch = target.core

                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                comparisons.append((">=", target))
                comparisons.append(("<", _Version(upper_core, None)))
            else:
                comparisons.append((operator, target))

        groups.append((comparisons, prerelease_cores))

    for comparisons, prerelease_cores in groups:
        if (
            candidate.prerelease is not None
            and candidate.core not in prerelease_cores
        ):
            continue

        for operator, target in comparisons:
            order = _compare(candidate, target)
            if operator == "=":
                satisfied = order == 0
            elif operator == ">":
                satisfied = order > 0
            elif operator == ">=":
                satisfied = order >= 0
            elif operator == "<":
                satisfied = order < 0
            else:  # <=
                satisfied = order <= 0

            if not satisfied:
                break
        else:
            return True

    return False
