import re


_VERSION_RE = re.compile(r"[0-9]+(?:\.[0-9]+)*(?:-[A-Za-z0-9]+)?\Z")


def compare_versions(a: str, b: str) -> int:
    def parse(version: str) -> tuple[list[int], str | None]:
        if not isinstance(version, str) or _VERSION_RE.fullmatch(version) is None:
            raise ValueError(f"Invalid version: {version!r}")

        numeric, separator, tag = version.partition("-")
        parts = [int(part) for part in numeric.split(".")]
        return parts, tag if separator else None

    a_parts, a_tag = parse(a)
    b_parts, b_tag = parse(b)

    for index in range(max(len(a_parts), len(b_parts))):
        a_part = a_parts[index] if index < len(a_parts) else 0
        b_part = b_parts[index] if index < len(b_parts) else 0
        if a_part != b_part:
            return 1 if a_part > b_part else -1

    if a_tag is None and b_tag is not None:
        return 1
    if a_tag is not None and b_tag is None:
        return -1
    if a_tag is None:
        return 0

    return (a_tag > b_tag) - (a_tag < b_tag)
