import re
from bisect import bisect_right
from datetime import datetime, timedelta


_ITEM = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_TIMESTAMP = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")


def _bounded_integer(text: str, limit: int) -> int:
    """Parse a nonnegative integer, returning limit + 1 if it exceeds limit."""
    text = text.lstrip("0") or "0"
    limit_text = str(limit)
    if len(text) > len(limit_text):
        return limit + 1
    return min(int(text), limit + 1)


def _parse_field(field: str, low: int, high: int):
    values = set()

    for item in field.split(","):
        match = _ITEM.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item")

        base, step_text = match.groups()
        if step_text is None:
            step = 1
        else:
            # Larger steps all select only the first value of any interval.
            step = _bounded_integer(step_text, high - low + 1)
            if step == 0:
                raise ValueError("Cron steps must be positive")

        if base == "*":
            start, end = low, high
        elif "-" in base:
            left, right = base.split("-")
            start = _bounded_integer(left, high)
            end = _bounded_integer(right, high)
        else:
            start = _bounded_integer(base, high)
            end = high if step_text is not None else start

        if not (low <= start <= end <= high):
            raise ValueError("Cron value or range is out of bounds")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected exactly five cron fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, low, high)
        for field, (low, high) in zip(fields, bounds)
    ]

    if _TIMESTAMP.fullmatch(after) is None:
        raise ValueError("Expected after in YYYY-MM-DD HH:MM format")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError("Invalid after timestamp") from exc

    # Use the fifth calendar anniversary as the inclusive search limit.
    # A February 29 anniversary in a non-leap year falls on February 28.
    if start.year <= 9994:
        try:
            limit = start.replace(year=start.year + 5)
        except ValueError:
            limit = start.replace(year=start.year + 5, day=28)
    else:
        limit = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    day = start.date()
    last_day = limit.date()

    while day <= last_day:
        if day.month in months:
            dom_matches = day.day in month_days
            dow_matches = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect_right(times, start.hour * 60 + start.minute)
                    if day == start.date()
                    else 0
                )
                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate <= limit:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {candidate.hour:02d}:"
                            f"{candidate.minute:02d}"
                        )

        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("No matching time exists within five years")
