import re

__all__ = ["roman_to_int"]

# Canonical grammar for 1..3999:
#   thousands: M{0,3}
#   hundreds:  CM | CD | D?C{0,3}
#   tens:      XC | XL | L?X{0,3}
#   units:     IX | IV | V?I{0,3}
# fullmatch() plus a non-empty check rejects everything else (empty string,
# lowercase, "IIII", "IC", "VX", "IIV", "XXXX", "MMMM", stray characters).
_CANONICAL = re.compile(r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})")

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral to an integer.

    Accepts only the canonical representation of numbers from 1 to 3999.
    Raises ValueError for anything else: the empty string, lowercase
    letters, non-canonical forms such as "IIII", "IC", "VX", "IIV",
    "XXXX" or "MMMM", stray characters, or non-str input.
    """
    if not isinstance(s, str):
        raise ValueError(f"expected a str, got {type(s).__name__}")
    if not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"not a canonical Roman numeral from 1 to 3999: {s!r}")

    total = 0
    prev = 0
    for ch in reversed(s):
        value = _VALUES[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value
    return total
