import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    items = set(deps)
    for dependencies in deps.values():
        items.update(dependencies)

    indegree = {item: 0 for item in items}
    dependents = {item: [] for item in items}

    for item, dependencies in deps.items():
        for dependency in set(dependencies):
            if dependency == item:
                raise ValueError("self-dependency")
            indegree[item] += 1
            dependents[dependency].append(item)

    ready = [item for item, degree in indegree.items() if degree == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents[item]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(items):
        raise ValueError("cycle")

    return result
