from datetime import date, datetime, time, timedelta


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly five fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    parsed = []

    for field, (minimum, maximum) in zip(fields, bounds):
        values = set()

        for item in field.split(","):
            if not item:
                raise ValueError("empty cron item")

            parts = item.split("/")
            if len(parts) > 2:
                raise ValueError("malformed cron item")

            step = 1
            if len(parts) == 2:
                if not re.fullmatch(r"[0-9]+", parts[1]):
                    raise ValueError("invalid step")
                step = int(parts[1])
                if step < 1:
                    raise ValueError("invalid step")

            base = parts[0]
            if base == "*":
                start, end = minimum, maximum
            elif re.fullmatch(r"[0-9]+", base):
                start = int(base)
                end = maximum if len(parts) == 2 else start
            else:
                match = re.fullmatch(r"([0-9]+)-([0-9]+)", base)
                if not match:
                    raise ValueError("malformed cron item")
                start, end = map(int, match.groups())
                if start > end:
                    raise ValueError("descending range")

            if start < minimum or start > maximum or end < minimum or end > maximum:
                raise ValueError("value outside field range")

            values.update(range(start, end + 1, step))

        parsed.append(values)

    minute_values, hour_values, dom_values, month_values, dow_values = parsed
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
        if start.strftime("%Y-%m-%d %H:%M") != after:
            raise ValueError("invalid datetime format")
    except ValueError:
        raise ValueError("after must be formatted as YYYY-MM-DD HH:MM") from None

    try:
        deadline = start.replace(year=start.year + 5)
    except ValueError:
        deadline = start.replace(year=start.year + 5, day=28)

    day = start.date()
    final_day = deadline.date()

    while day <= final_day:
        if day.month in month_values:
            cron_dow = (day.weekday() + 1) % 7
            dom_matches = day.day in dom_values
            dow_matches = cron_dow in dow_values

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                for hour in sorted(hour_values):
                    for minute in sorted(minute_values):
                        candidate = datetime.combine(day, time(hour, minute))
                        if start < candidate <= deadline:
                            return candidate.strftime("%Y-%m-%d %H:%M")

        day += timedelta(days=1)

    raise ValueError("no matching time within five years")
