def parse_duration(s: str) -> int:
    unit_seconds = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    seen = set()
    total = 0
    i = 0
    length = len(s)

    while True:
        while i < length and s[i] == " ":
            i += 1

        if i == length:
            if not seen:
                raise ValueError("Duration must contain at least one part")
            return total

        if not ("0" <= s[i] <= "9"):
            raise ValueError("Expected an ASCII decimal integer")

        value = 0
        while i < length and "0" <= s[i] <= "9":
            value = value * 10 + (ord(s[i]) - ord("0"))
            i += 1

        if i == length or s[i] not in unit_seconds:
            raise ValueError("Expected a unit immediately after the number")

        unit = s[i]
        if unit in seen:
            raise ValueError("Repeated unit")

        seen.add(unit)
        total += value * unit_seconds[unit]
        i += 1
