def is_valid_ipv4(s: str) -> bool:
    # Defensive guard: never raise on non-string input either.
    if not isinstance(s, str):
        return False

    # Requirement: exactly four parts separated by "."
    parts = s.split(".")
    if len(parts) != 4:
        return False

    ascii_digits = set("0123456789")

    for part in parts:
        # Requirement: each part is 1 to 3 characters
        if not (1 <= len(part) <= 3):
            return False

        # Requirement: ASCII digits only.
        # Explicit membership check rejects Unicode digits (e.g. "٣", "１"),
        # superscripts (e.g. "²"), signs, whitespace, newlines, etc.
        for c in part:
            if c not in ascii_digits:
                return False

        # Requirement: no leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == "0":
            return False

        # Safe: after the digit check, int() cannot raise.
        # Requirement: numeric value 0-255
        if int(part) > 255:
            return False

    return True
