import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.+)")


def _parse_version(version):
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid semantic version")

    major, minor, patch = map(int, match.group(1, 2, 3))
    prerelease = match.group(4)

    if prerelease is not None:
        identifiers = prerelease.split(".")
        for identifier in identifiers:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return (major, minor, patch), prerelease


def _compare_versions(left, right):
    left_core, left_pre = left
    right_core, right_pre = right

    if left_core != right_core:
        return (left_core > right_core) - (left_core < right_core)
    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    left_ids = left_pre.split(".")
    right_ids = right_pre.split(".")
    for a, b in zip(left_ids, right_ids):
        if a == b:
            continue
        a_numeric = a.isdigit()
        b_numeric = b.isdigit()
        if a_numeric and b_numeric:
            return (int(a) > int(b)) - (int(a) < int(b))
        if a_numeric != b_numeric:
            return -1 if a_numeric else 1
        return (a > b) - (a < b)

    return (len(left_ids) > len(right_ids)) - (len(left_ids) < len(right_ids))


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a strict SemVer version against npm-style comparator groups."""
    parsed_version = _parse_version(version)

    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("constraint must not be empty")

    groups = constraint.split("||")
    if any(not group.strip() for group in groups):
        raise ValueError("constraint contains an empty group")

    for group in groups:
        tokens = group.split()
        if not tokens:
            raise ValueError("constraint contains an empty group")

        comparators = []
        for token in tokens:
            if token == "*":
                comparators.append(("*", None))
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError("invalid comparator")

            operator = match.group(1) or "="
            operand = match.group(2)
            parsed_operand = _parse_version(operand)
            comparators.append((operator, parsed_operand))

        group_matches = True
        prerelease_allowed = parsed_version[1] is None

        for operator, target in comparators:
            if operator == "*":
                continue

            target_core, target_pre = target
            if target_pre is not None and target_core == parsed_version[0]:
                prerelease_allowed = True

            comparison = _compare_versions(parsed_version, target)

            if operator == "=":
                matched = comparison == 0
            elif operator == ">":
                matched = comparison > 0
            elif operator == ">=":
                matched = comparison >= 0
            elif operator == "<":
                matched = comparison < 0
            elif operator == "<=":
                matched = comparison <= 0
            elif operator == "^":
                major, minor, patch = target_core
                if major > 0:
                    upper = ((major + 1, 0, 0), None)
                elif minor > 0:
                    upper = ((0, minor + 1, 0), None)
                else:
                    upper = ((0, 0, patch + 1), None)
                matched = comparison >= 0 and _compare_versions(parsed_version, upper) < 0
            else:  # "~"
                major, minor, _ = target_core
                upper = ((major, minor + 1, 0), None)
                matched = comparison >= 0 and _compare_versions(parsed_version, upper) < 0

            if not matched:
                group_matches = False

        if group_matches and prerelease_allowed:
            return True

    return False
