import ipaddress
import re


_SCHEME_RE = re.compile(r"([A-Za-z][A-Za-z0-9+.-]*)://")


def parse_url(url: str) -> dict:
    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("URL must start with a scheme followed by ://")

    scheme = match.group(1).lower()
    remainder = url[match.end():]

    authority_end = len(remainder)
    for delimiter in "/?#":
        index = remainder.find(delimiter)
        if index != -1:
            authority_end = min(authority_end, index)

    authority = remainder[:authority_end]
    rest = remainder[authority_end:]

    if not authority:
        raise ValueError("Authority must be non-empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    if host_port.startswith("["):
        closing_bracket = host_port.find("]")
        if closing_bracket == -1:
            raise ValueError("Invalid IPv6 host")

        host = host_port[1:closing_bracket]
        try:
            ipaddress.IPv6Address(host)
        except ValueError as exc:
            raise ValueError("Invalid IPv6 host") from exc

        suffix = host_port[closing_bracket + 1:]
        if suffix and not suffix.startswith(":"):
            raise ValueError("Invalid authority")
        port_text = suffix[1:] if suffix else None
    else:
        host_end = len(host_port)
        for index, char in enumerate(host_port):
            if char in " :[]":
                host_end = index
                break

        host = host_port[:host_end]
        suffix = host_port[host_end:]
        if any(char in "/?#@[]" for char in host_port) or (
            suffix and not suffix.startswith(":")
        ):
            raise ValueError("Invalid authority")
        port_text = suffix[1:] if suffix else None

    if not host:
        raise ValueError("Host must be non-empty")

    port = None
    if port_text is not None:
        if (
            not port_text
            or len(port_text) > 5
            or any(char < "0" or char > "9" for char in port_text)
        ):
            raise ValueError("Invalid port")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Invalid port")

    fragment = ""
    if "#" in rest:
        rest, fragment = rest.split("#", 1)

    query = ""
    if "?" in rest:
        path, query = rest.split("?", 1)
    else:
        path = rest

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
