def normalize_path(p: str) -> str:
    if p == "":
        return "."

    absolute = p.startswith("/")
    stack = []

    for comp in p.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if stack and stack[-1] != "..":
                # pop the previous real component
                stack.pop()
            elif not absolute:
                # unresolved relative "..": keep it
                stack.append("..")
            # absolute path at root: ignore ".."
        else:
            stack.append(comp)

    if absolute:
        return "/" + "/".join(stack)

    if not stack:
        return "."

    return "/".join(stack)
