def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")

    if n < 1024:
        return "{} B".format(n)

    units = ("KiB", "MiB", "GiB", "TiB")

    # Largest power p in 1..4 with n >= 1024**p
    p = 1
    while p < 4 and n >= 1024 ** (p + 1):
        p += 1

    d = 1024 ** p
    # Exact round-half-up to one decimal, in tenths: floor(10n/d + 1/2)
    tenths = (20 * n + d) // (2 * d)

    # Rounding overflowed the unit: step up (TiB stays put)
    if tenths >= 10240 and p < 4:
        p += 1
        tenths = 10

    return "{}.{} {}".format(tenths // 10, tenths % 10, units[p - 1])
