# Requirements and edge cases:
# - Match the entire name, case-sensitively.
# - * and ? do not match /; ** can match any characters.
# - Character classes support ranges, ! negation, and a leading literal ].
# - Backslash escapes the next character; trailing backslash is an error.
# - An unclosed character class and a descending range are errors.

def glob_match(pattern: str, name: str) -> bool:
    tokens = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash")
            tokens.append(("literal", pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                tokens.append(("globstar",))
                i += 2
            else:
                tokens.append(("star",))
                i += 1
        elif char == "?":
            tokens.append(("question",))
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            items = []
            if i < len(pattern) and pattern[i] == "]":
                items.append(("]", False))
                i += 1

            closed = False
            while i < len(pattern):
                if pattern[i] == "]":
                    closed = True
                    i += 1
                    break

                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash")
                    items.append((pattern[i], True))
                else:
                    items.append((pattern[i], False))
                i += 1

            if not closed:
                raise ValueError("unclosed character class")
            if not items:
                raise ValueError("empty character class")

            ranges = []
            j = 0
            while j < len(items):
                if (
                    j + 2 < len(items)
                    and items[j + 1] == ("-", False)
                ):
                    start, end = items[j][0], items[j + 2][0]
                    if ord(start) > ord(end):
                        raise ValueError("descending character range")
                    ranges.append((start, end))
                    j += 3
                else:
                    ranges.append((items[j][0], items[j][0]))
                    j += 1

            tokens.append(("class", negate, ranges))
        else:
            tokens.append(("literal", char))
            i += 1

    # Dynamic programming keeps matching anchored at both ends.
    matched = {0}
    for token in tokens:
        next_matched = set()

        if token[0] == "literal":
            char = token[1]
            next_matched.update(
                pos + 1 for pos in matched
                if pos < len(name) and name[pos] == char
            )
        elif token[0] == "question":
            next_matched.update(
                pos + 1 for pos in matched
                if pos < len(name) and name[pos] != "/"
            )
        elif token[0] == "class":
            negate, ranges = token[1], token[2]
            for pos in matched:
                if pos < len(name):
                    char = name[pos]
                    contained = any(start <= char <= end for start, end in ranges)
                    if contained != negate:
                        next_matched.add(pos + 1)
        else:
            crosses_slash = token[0] == "globstar"
            for pos in matched:
                end = pos
                while end < len(name) and (crosses_slash or name[end] != "/"):
                    end += 1
                next_matched.update(range(pos, end + 1))

        matched = next_matched
        if not matched:
            return False

    return len(name) in matched
