                if line[i] == '"':
                    if i + 1 < length and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                        continue

                    if i + 1 == length:
                        fields.append("".join(field))
                        return fields

                    if line[i + 1] == ",":
                        fields.append("".join(field))
                        i += 2
                        break

                    raise ValueError("invalid character after closing quote")

                field.append(line[i])
                i += 1
        else:
            start = i

            while i < length and line[i] != ",":
                if line[i] == '"':
                    raise ValueError("double quote in unquoted field")
                i += 1

            fields.append(line[start:i])

            if i < length:
