import re

# scheme: a letter followed by letters, digits, '+', '-' or '.', then '://'
_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+.\-]*)://")

# characters forbidden inside an unbracketed host
_HOST_FORBIDDEN = set(" \t\n\r\f\v/?#@:[]")


def _parse_port(text):
    """Return the port as int, or None if `text` is not a valid port."""
    if not 1 <= len(text) <= 5:
        return None
    for ch in text:
        if not ("0" <= ch <= "9"):      # ASCII digits only
            return None
    value = int(text)
    if 1 <= value <= 65535:
        return value
    return None


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("url must start with a scheme followed by '://'")
    scheme = match.group(1).lower()

    rest = url[match.end():]

    # authority runs up to the first '/', '?' or '#' (or the end)
    end = len(rest)
    for i, ch in enumerate(rest):
        if ch in "/?#":
            end = i
            break
    authority = rest[:end]
    if not authority:
        raise ValueError("empty authority")

    # userinfo is everything before the LAST '@' in the authority, as is
    at = authority.rfind("@")
    if at == -1:
        userinfo = ""
        hostport = authority
    else:
        userinfo = authority[:at]
        hostport = authority[at + 1:]

    # host (with optional :port)
    if hostport.startswith("["):
        close = hostport.find("]")
        if close == -1:
            raise ValueError("unterminated IPv6 literal")
        host = hostport[1:close]
        if not host:
            raise ValueError("empty host")
        remainder = hostport[close + 1:]
        if remainder:
            if not remainder.startswith(":"):
                raise ValueError("unexpected characters after host")
            port = _parse_port(remainder[1:])
            if port is None:
                raise ValueError("invalid port")
        else:
            port = None
    else:
        colon = hostport.find(":")
        if colon == -1:
            host = hostport
            port = None
        else:
            host = hostport[:colon]
            port = _parse_port(hostport[colon + 1:])
            if port is None:
                raise ValueError("invalid port")
        if not host:
            raise ValueError("empty host")
        for ch in host:
            if ch in _HOST_FORBIDDEN:
                raise ValueError("invalid character in host")

    host = host.lower()

    # path / query / fragment: first '#' opens the fragment, then the
    # first '?' before it opens the query; the remainder is the path
    tail = rest[end:]
    hash_at = tail.find("#")
    if hash_at == -1:
        fragment = ""
        before = tail
    else:
        fragment = tail[hash_at + 1:]
        before = tail[:hash_at]

    q_at = before.find("?")
    if q_at == -1:
        query = ""
        path = before
    else:
        query = before[q_at + 1:]
        path = before[:q_at]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
