def mask_email(s: str) -> str:
    """Mask the local part of an email address, leaving the domain intact."""
    if not isinstance(s, str):
        raise ValueError("email address must be a string")
    if s.count("@") != 1:
        raise ValueError("email address must contain exactly one '@'")

    local, domain = s.split("@")
    if not local or not domain:
        raise ValueError("email address must have a non-empty local part and domain")

    n = len(local)
    if n == 1:
        masked = "*"
    elif n == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (n - 2) + local[-1]

    return masked + "@" + domain
