```python
"""Deterministic topological sort.

Orders items so that each one appears after all of its dependencies. Ties are
broken by choosing the lexicographically smallest currently-available item.
"""

import heapq


def topo_sort(deps: dict) -> list:
    """Return items in dependency order.

    ``deps`` maps an item to the list of items it depends on. Every item named
    anywhere (as a key or inside a dependency list) appears in the result
    exactly once. Duplicates inside a dependency list are ignored. Among the
    items whose dependencies are all already placed, the lexicographically
    smallest (plain string comparison) is placed next.

    Raises ValueError if a self-dependency or any other cycle is present.
    The input mapping is not modified.
    """
    # graph[node] = set of direct dependencies of node
    graph: dict = {}
    for item, requirements in deps.items():
        graph.setdefault(item, set())
        for req in requirements:
            graph[item].add(req)
            graph.setdefault(req, set())

    # remaining[node] = number of unplaced dependencies still outstanding
    remaining: dict = {node: len(requires) for node, requires in graph.items()}

    # reverse edges: dependents[n] = nodes that depend on n
    dependents: dict = {node: set() for node in graph}
    for node, requires in graph.items():
        for req in requires:
            dependents[req].add(node)

    ready = [node for node, count in remaining.items() if count == 0]
    heapq.heapify(ready)  # min-heap -> lexicographically smallest first

    ordered: list = []
    while ready:
        node = heapq.heappop(ready)
        ordered.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(ordered) != len(graph):
        raise ValueError("dependency graph contains a cycle")

    return ordered
```

