import re

_TOKEN_RE = re.compile(
    r"(?P<ws>\s+)|(?P<num>\d+\.\d+|\d+)|(?P<op>[-+*/^()])",
    re.ASCII,
)


def _tokenize(expr: str):
    tokens = []
    pos = 0
    for m in _TOKEN_RE.finditer(expr):
        if m.start() != pos:
            raise ValueError(
                "unexpected character %r at position %d" % (expr[pos], pos)
            )
        pos = m.end()
        if m.lastgroup != "ws":
            tokens.append(m.group())
    if pos != len(expr):
        raise ValueError(
            "unexpected character %r at position %d" % (expr[pos], pos)
        )
    if not tokens:
        raise ValueError("empty expression")
    return tokens


class _Parser(object):
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.pos += 1
        return tok

    def parse(self):
        value = self.expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos],))
        return value

    # expr := term (('+' | '-') term)*
    def expr(self):
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.advance()
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/') unary)*
    def term(self):
        value = self.unary()
        while self.peek() in ("*", "/"):
            op = self.advance()
            rhs = self.unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    # unary := '-' unary | power      (so -2 ^ 2 == -(2 ^ 2))
    def unary(self):
        if self.peek() == "-":
            self.advance()
            return -self.unary()
        return self.power()

    # power := atom ('^' unary)?      (right associative, exponent may be signed)
    def power(self):
        base = self.atom()
        if self.peek() == "^":
            self.advance()
            exponent = self.unary()
            return base ** exponent
        return base

    def atom(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("expected a number")
        if tok == "(":
            self.advance()
            value = self.expr()
            if self.peek() != ")":
                raise ValueError("unbalanced parentheses")
            self.advance()
            return value
        if "0" <= tok[0] <= "9":
            self.advance()
            return float(tok) if "." in tok else int(tok)
        raise ValueError("unexpected token %r" % (tok,))


def evaluate(expr: str):
    try:
        return _Parser(_tokenize(expr)).parse()
    except ZeroDivisionError:
        raise ValueError("division by zero")
