import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned anywhere (as a key or inside a list).
    items = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    # Build deduplicated edges and in-degree counts without modifying the input.
    dependents: dict[str, set[str]] = {item: set() for item in items}
    remaining: dict[str, int] = {item: 0 for item in items}

    for item, dep_list in deps.items():
        for dep in set(dep_list):  # ignore duplicates within a dependency list
            if dep == item:
                raise ValueError(f"self-dependency: {item!r} depends on itself")
            dependents[dep].add(item)
            remaining[item] += 1

    # Kahn's algorithm with a min-heap for deterministic (lexicographically
    # smallest first) selection among ready items.
    ready = [item for item in items if remaining[item] == 0]
    heapq.heapify(ready)

    result: list[str] = []
    while ready:
        current = heapq.heappop(ready)
        result.append(current)
        for dependent in dependents[current]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(items):
        raise ValueError("dependency cycle detected")

    return result
