import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire path-like name matches pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("pattern cannot end with a backslash")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(".*")
                i += 2
            else:
                regex.append("[^/]*")
                i += 1
        elif char == "?":
            regex.append("[^/]")
            i += 1
        elif char == "[":
            start = i
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            items = []
            if i < len(pattern) and pattern[i] == "]":
                items.append(("]", False))
                i += 1

            closed = False
            while i < len(pattern):
                if pattern[i] == "]":
                    closed = True
                    i += 1
                    break
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("pattern cannot end with a backslash")
                    items.append((pattern[i], True))
                    i += 1
                else:
                    items.append((pattern[i], False))
                    i += 1

            if not closed:
                raise ValueError(f"unclosed character set at position {start}")

            class_parts = ["^"] if negate else []
            j = 0
            while j < len(items):
                if (
                    j + 2 < len(items)
                    and items[j + 1] == ("-", False)
                    and items[j][0] != "-"
                    and items[j + 2][0] != "-"
                ):
                    low, high = items[j][0], items[j + 2][0]
                    if ord(low) > ord(high):
                        raise ValueError("character range is reversed")
                    class_parts.extend((re.escape(low), "-", re.escape(high)))
                    j += 3
                else:
                    class_parts.append(re.escape(items[j][0]))
                    j += 1

            regex.append("[" + "".join(class_parts) + "]")
        else:
            regex.append(re.escape(char))
            i += 1

    return re.fullmatch("".join(regex), name, flags=re.DOTALL) is not None
