def _parse_field(field, minimum, maximum):
    values = set()

    for item in field.split(","):
        match = _ITEM_RE.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item")

        base, step_text = match.groups()
        step = int(step_text) if step_text is not None else 1
        if step < 1:
            raise ValueError("Cron step must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start, end = map(int, base.split("-"))
        else:
            start = int(base)
            end = maximum if step_text is not None else start

        if not (minimum <= start <= end <= maximum):
            raise ValueError("Cron value or range is out of bounds")

        values.update(range(start, end + 1, step))

    return values


