    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected exactly five cron fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, days, months, weekdays = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, bounds)
    ]

    match = _AFTER_RE.fullmatch(after)
    if match is None:
        raise ValueError("Expected after in YYYY-MM-DD HH:MM format")
    start = datetime(*map(int, match.groups()))

    # The search window includes the fifth calendar anniversary.
    # A February 29 anniversary is clamped to February 28.
    if start.year + 5 <= 9999:
        end_year = start.year + 5
        end_day = min(start.day, monthrange(end_year, start.month)[1])
        deadline = start.replace(year=end_year, day=end_day)
    else:
        deadline = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    current = start.date()
    last_date = deadline.date()
    one_day = timedelta(days=1)

    while current <= last_date:
        if current.month in months:
            dom_matches = current.day in days
            dow_matches = (current.weekday() + 1) % 7 in weekdays

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect_right(times, start.hour * 60 + start.minute)
                    if current == start.date()
                    else 0
