def earliest_slot(busy: list, duration: int, start: int, end: int):
    """Return the earliest t with start <= t, t + duration <= end and
    [t, t + duration) free of any half-open busy interval, else None."""
    # --- validation -------------------------------------------------
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    clipped = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        b = begin if begin > start else start
        f = finish if finish < end else end
        if b < f:                      # keep only the part overlapping the window
            clipped.append((b, f))

    if duration > end - start:
        return None

    # --- merge overlaps / touches, without touching the input --------
    clipped.sort()
    merged = []
    for b, f in clipped:
        if merged and b <= merged[-1][1]:
            if f > merged[-1][1]:
                merged[-1][1] = f
        else:
            merged.append([b, f])

    # --- scan the gaps; a candidate can only start at `start` or at a
    #     merged busy interval's finish ------------------------------
    t = start
    for b, f in merged:
        if b - t >= duration:
            return t
        t = f if f > t else t
    if end - t >= duration:
        return t
    return None
