        unit = s[i]
        if unit not in units:
            raise ValueError("unknown unit")
        if unit in seen:
            raise ValueError("repeated unit")

        seen.add(unit)
        total += value * units[unit]
        i += 1

        while i < n and s[i] == " ":
            i += 1

        if i < n and not ("0" <= s[i] <= "9"):
            raise ValueError("expected a number")

    return total
