**Step 2 — Implementation** (Kahn's algorithm with a min-heap for deterministic tie-breaking):

```python
import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """Order items so every item comes after all of its dependencies.

    - Every item mentioned as a key or inside a dependency list appears
      exactly once in the result.
    - Duplicate entries in dependency lists are ignored.
    - Deterministic tie-breaking: whenever several items have all their
      dependencies already placed, the lexicographically smallest one
      is placed first.
    - Raises ValueError on a self-dependency or any cycle.
    - Does not modify ``deps``.
    """
    # Collect every item mentioned anywhere (as a key or inside a list).
    items = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    # Deduplicated dependency sets for every item; items that never appear
    # as a key have no dependencies of their own.
    dep_sets: dict[str, set[str]] = {item: set() for item in items}
    for item, dep_list in deps.items():
        dep_sets[item].update(dep_list)

    # Inverted edges and remaining-dependency counts.
    dependents: dict[str, set[str]] = {item: set() for item in items}
    remaining: dict[str, int] = {}
    for item, ds in dep_sets.items():
        if item in ds:
            raise ValueError(f"self-dependency: {item!r} depends on itself")
        remaining[item] = len(ds)
        for d in ds:
            dependents[d].add(item)

    # Kahn's algorithm with a min-heap so the lexicographically smallest
    # ready item is always placed next.
    ready = [item for item, count in remaining.items() if count == 0]
    heapq.heapify(ready)

    result: list[str] = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents[item]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(items):
        unresolved = sorted(items.difference(result))
        raise ValueError(f"cycle detected involving: {unresolved}")

    return result
```

