import math


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1

            if i < n and expr[i] == ".":
                i += 1
                fraction_start = i
                while i < n and "0" <= expr[i] <= "9":
                    i += 1
                if i == fraction_start:
                    raise ValueError("malformed decimal literal")
                tokens.append(float(expr[start:i]))
            else:
                tokens.append(int(expr[start:i]))
        elif ch in "+-*/^()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("unknown character")

    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            value = value + right if op == "+" else value - right
        return value

    def parse_term():
        nonlocal pos
        value = parse_unary()
        while pos < len(tokens) and tokens[pos] in ("*", "/"):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == "/":
                if right == 0:
                    raise ValueError("division by zero")
                value = value / right
            else:
                value = value * right
        return value

    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        value = parse_primary()
        if pos < len(tokens) and tokens[pos] == "^":
            pos += 1
            value = value ** parse_unary()
        return value

    def parse_primary():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("missing operand")

        token = tokens[pos]
        if isinstance(token, (int, float)):
            pos += 1
            return token

        if token == "(":
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value

        raise ValueError("expected a number or parenthesis")

    try:
        result = parse_expression()
        if pos != len(tokens):
            raise ValueError("unexpected token")
        return result
    except ZeroDivisionError as exc:
        raise ValueError("division by zero") from exc
