import re

# ASCII-only decimal literal: optional "-", digits, optional "." + digits.
_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def _increment(digits: str) -> str:
    """Add 1 to a non-empty string of decimal digits."""
    buf = list(digits)
    i = len(buf) - 1
    while i >= 0 and buf[i] == "9":
        buf[i] = "0"
        i -= 1
    if i < 0:
        return "1" + "".join(buf)
    buf[i] = chr(ord(buf[i]) + 1)
    return "".join(buf)


def round_half_up(x: str, ndigits: int) -> str:
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError("x must be a decimal string such as '-12.34'")
    if isinstance(ndigits, bool) or not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative int")

    sign = ""
    body = x
    if body.startswith("-"):
        sign, body = "-", body[1:]

    int_part, _, frac_part = body.partition(".")

    if len(frac_part) <= ndigits:
        # Nothing to round; just pad with zeros.
        int_out = int_part
        frac_out = frac_part + "0" * (ndigits - len(frac_part))
    else:
        # Work on the digit string directly: exact, no float, no Decimal context.
        digits = int_part + frac_part
        keep = len(int_part) + ndigits
        head, tail = digits[:keep], digits[keep:]
        if tail[0] >= "5":          # ties (and anything above) go away from zero
            head = _increment(head)
        cut = len(head) - ndigits   # a carry may have grown head by one digit
        int_out, frac_out = head[:cut], head[cut:]

    if not int_out.strip("0") and not frac_out.strip("0"):
        sign = ""                   # never emit "-0.00"

    return sign + int_out + ("." + frac_out if ndigits else "")
