    busy interval.

    Busy intervals are half-open ``(begin, finish)``; the ``finish``
    minute itself is free.  ``busy`` may be unsorted and may contain
    overlapping or touching intervals, and is never modified.

    Returns ``None`` when no slot fits.

    Raises:
        ValueError: if ``duration`` is not a positive integer, or if any
            busy interval satisfies ``begin >= finish``.
    """
    # bool is a subclass of int, but True/False are not durations.
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval up front, even ones outside the window, so
    # that bad input always raises instead of silently succeeding.
    spans = []
    for interval in busy:
        begin, finish = interval
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        spans.append((begin, finish))

    # Clip to the window; busy time outside it cannot affect the answer.
    # A half-open interval that misses the window entirely clips to an
    # empty span and is dropped.
    clipped = []
    for begin, finish in spans:
        b = begin if begin > start else start
        f = finish if finish < end else end
        if b < f:
            clipped.append((b, f))

    clipped.sort()

    # Walk the merged busy time; the gap before each block is the only
    # place a slot can start.
    cursor = start
    for b, f in clipped:
        if b >= cursor:
            if b - cursor >= duration:
                return cursor
            cursor = f
        elif f > cursor:
            cursor = f

    return cursor if end - cursor >= duration else None


