def normalize_path(p: str) -> str:
    """Normalize a Unix-style path.

    - Empty components and "." are dropped.
    - ".." pops the previous component; at the root of an absolute path
      it is ignored, while in a relative path unresolvable ".." are kept.
    - Any number of leading slashes denotes the same root "/".
    - The result has no trailing slash, except the root itself "/".
    - An empty relative result (including empty input) is ".".
    """
    is_absolute = p.startswith("/")
    stack = []

    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            elif not is_absolute:
                stack.append("..")
            # else: ".." at the root of an absolute path is ignored
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)
    if not stack:
        return "."
    return "/".join(stack)
