def rle_decode(s: str) -> str:
    result = []
    total_length = 0
    i = 0

    while i < len(s):
        count_start = i

        if not ("0" <= s[i] <= "9"):
            raise ValueError("missing count")

        if s[i] == "0":
            raise ValueError("count must be positive and have no leading zeros")

        count = 0
        while i < len(s) and "0" <= s[i] <= "9":
            count = count * 10 + (ord(s[i]) - ord("0"))
            if count > 10000:
                raise ValueError("decoded length exceeds 10000")
            i += 1

        if i == count_start or i == len(s):
            raise ValueError("missing group character")

        total_length += count
        if total_length > 10000:
            raise ValueError("decoded length exceeds 10000")

        result.append(s[i] * count)
        i += 1

    return "".join(result)
