```python
"""Order-preserving de-duplication that follows == exactly."""

_EXACT_VALUE_TYPES = frozenset(
    (int, float, bool, complex, str, bytes, type(None), type)
)


def _hashes_match_equality(obj):
    """True when obj's type guarantees equal values have equal hashes."""
    pending = [obj]
    while pending:
        value = pending.pop()
        cls = type(value)
        if cls in _EXACT_VALUE_TYPES:
            continue
        if cls.__eq__ is object.__eq__ and cls.__hash__ is object.__hash__:
            continue  # identity semantics: hash and == agree by construction
        if (cls.__eq__ is tuple.__eq__ and cls.__hash__ is tuple.__hash__) or (
            cls.__eq__ is frozenset.__eq__ and cls.__hash__ is frozenset.__hash__
        ):
            pending.extend(value)  # hash comes from the contents; check them
            continue
        return False
    return True


def dedupe_keep_order(items):
    """New list, first occurrence of each ==-equal item kept, order preserved."""
    result = []
    hashed = {}  # kept items whose type hashes consistently with ==
    linear = []  # every other kept item: unhashable, or hash not trusted

    for item in items:
        if _hashes_match_equality(item):
            if item in hashed:
                continue
            if any(item == other for other in linear):
                continue
            hashed[item] = None
        else:
            if any(item == other for other in result):
                continue
            linear.append(item)
        result.append(item)

    return result
