_SCHEME_RE = re.compile(r"([A-Za-z][A-Za-z0-9+\-.]*)://")
_HOST_RE = re.compile(r"[^ /?#@:\[\]]+\Z")
_PORT_RE = re.compile(r"[0-9]{1,5}\Z")


def _parse_port(text):
    if not _PORT_RE.match(text):
        raise ValueError("invalid port: %r" % (text,))
    port = int(text)
    if not 1 <= port <= 65535:
        raise ValueError("port out of range: %r" % (text,))
    return port


def parse_url(url):
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("missing or malformed scheme")
    scheme = match.group(1).lower()
    rest = url[match.end():]

    cut = len(rest)
    for index, char in enumerate(rest):
        if char in "/?#":
            cut = index
            break
    authority = rest[:cut]
    remainder = rest[cut:]

    if not authority:
        raise ValueError("authority must not be empty")

    if "@" in authority:
        userinfo, hostport = authority.rsplit("@", 1)
    else:
