import re


def roman_to_int(s: str) -> int:
    """Accept canonical uppercase numerals from 1 to 3999; reject empty,
    lowercase, malformed, non-canonical, and non-string inputs with ValueError.
    """
    if not isinstance(s, str) or not re.fullmatch(
        r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})",
        s,
    ) or not s:
        raise ValueError("invalid Roman numeral")

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, char in enumerate(s):
        value = values[char]
        if i + 1 < len(s) and value < values[s[i + 1]]:
            total -= value
        else:
            total += value
    return total
