def dedupe_keep_order(items):
    """Return a new list with duplicates removed, keeping first occurrences.

    Duplicates are decided with ``==`` (so 1, 1.0 and True are duplicates,
    and NaN is not a duplicate of itself). Items need not be hashable, and
    the input is never modified.
    """
    result = []
    for item in items:
        if not any(seen == item for seen in result):
            result.append(item)
    return result


