import re


_WORD_RE = re.compile(r"[A-Za-z]+")


def top_k_words(text: str, k: int) -> list:
    """Return the k most frequent ASCII-letter words in text.

    Each result entry is a [word, count] pair, ordered by count
    descending and then alphabetically ascending. Returns an empty
    list when k <= 0.
    """
    if k <= 0:
        return []

    counts = {}
    for match in _WORD_RE.findall(text):
        word = match.lower()
        counts[word] = counts.get(word, 0) + 1

    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    return [[word, count] for word, count in ordered[:k]]
