import re

_ROMAN_RE = re.compile(
    r"^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
)
_SYMBOLS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1..3999) to an int.

    Raises ValueError for anything that is not the unique canonical form.
    """
    if not isinstance(s, str):
        raise ValueError("Roman numeral must be a string")
    if not s or not _ROMAN_RE.match(s):
        raise ValueError("not a canonical Roman numeral: {!r}".format(s))

    total = 0
    prev = 0
    for ch in reversed(s):
        value = _SYMBOLS[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value

    if not 1 <= total <= 3999:
        raise ValueError("value out of range (1..3999): {!r}".format(s))
    return total
