import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
)

_Version = tuple[tuple[int, int, int], tuple[str, ...]]


def _parse_version(text: str) -> _Version:
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"Invalid semantic version: {text!r}")

    core = tuple(int(match.group(i)) for i in (1, 2, 3))
    prerelease = tuple(match.group(4).split(".")) if match.group(4) else ()

    for identifier in prerelease:
        if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(f"Invalid semantic version: {text!r}")

    return core, prerelease


def _compare_versions(left: _Version, right: _Version) -> int:
    left_core, left_pre = left
    right_core, right_pre = right

    if left_core != right_core:
        return 1 if left_core > right_core else -1

    if not left_pre or not right_pre:
        return (bool(right_pre) > bool(left_pre)) - (
            bool(right_pre) < bool(left_pre)
        )

    for a, b in zip(left_pre, right_pre):
        if a == b:
            continue

        a_numeric = a.isdigit()
        b_numeric = b.isdigit()

        if a_numeric and b_numeric:
            # Valid numeric identifiers have no leading zeros, so comparing
            # lengths first gives numeric order without converting to int.
            if len(a) != len(b):
                return 1 if len(a) > len(b) else -1
            return 1 if a > b else -1
        if a_numeric != b_numeric:
            return -1 if a_numeric else 1
        return 1 if a > b else -1

    return (len(left_pre) > len(right_pre)) - (
        len(left_pre) < len(right_pre)
    )


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a strict SemVer version against the specified constraint syntax."""
    candidate = _parse_version(version)
    groups = []

    # Parse every group before evaluating so invalid comparators always raise,
    # even when an earlier group would satisfy the constraint.
    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        comparisons = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                continue

            operator = "="
            operand = token
            for prefix in (">=", "<=", ">", "<", "=", "^", "~"):
                if token.startswith(prefix):
                    operator = prefix
                    operand = token[len(prefix):]
                    break

            target = _parse_version(operand)
            core, prerelease = target

            if prerelease:
                prerelease_cores.add(core)

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                comparisons.append((">=", target))
                comparisons.append(("<", (upper_core, ())))
            else:
                comparisons.append((operator, target))

        groups.append((comparisons, prerelease_cores))

    for comparisons, prerelease_cores in groups:
        if candidate[1] and candidate[0] not in prerelease_cores:
            continue

        for operator, target in comparisons:
            result = _compare_versions(candidate, target)
            if not (
                (operator == "=" and result == 0)
                or (operator == ">" and result > 0)
                or (operator == ">=" and result >= 0)
                or (operator == "<" and result < 0)
                or (operator == "<=" and result <= 0)
            ):
                break
        else:
            return True

    return False
