def compare_versions(a: str, b: str) -> int:
    """Compare two version strings, returning -1, 0 or 1.

    A version is one or more dot-separated numeric parts (ASCII digits only,
    compared numerically, leading zeros allowed), optionally followed by "-"
    and a tag of one or more ASCII letters/digits.  Missing numeric parts
    count as zero.  A version carrying a tag sorts below the same version
    without one; tags compare as plain strings.
    """
    digits = frozenset("0123456789")
    letters = frozenset("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")

    def parse(version):
        if not isinstance(version, str) or version == "":
            raise ValueError("invalid version: %r" % (version,))

        if "-" in version:
            if version.count("-") != 1:
                raise ValueError("invalid version: %r" % (version,))
            numeric, tag = version.split("-")
            if not tag or any(c not in digits and c not in letters for c in tag):
                raise ValueError("invalid tag: %r" % (version,))
        else:
            numeric, tag = version, None

        parts = numeric.split(".")
        for part in parts:
            if not part or any(c not in digits for c in part):
                raise ValueError("invalid numeric part: %r" % (version,))

        return [int(p) for p in parts], tag

    nums_a, tag_a = parse(a)
    nums_b, tag_b = parse(b)

    width = max(len(nums_a), len(nums_b))
    nums_a += [0] * (width - len(nums_a))
    nums_b += [0] * (width - len(nums_b))

    if nums_a != nums_b:
        return -1 if nums_a < nums_b else 1

    if tag_a is None and tag_b is None:
        return 0
    if tag_a is None:
        return 1          # no tag outranks a tag
    if tag_b is None:
        return -1
    if tag_a == tag_b:
        return 0
    return -1 if tag_a < tag_b else 1
