            ")2(", "(2))", "((2)", "2 ** 3", "2 // 3",
            "2(3)", "(2)3", "(2)(3)", ".5", "5.", "1.2.3",
            "1e3", "0x10", "1_000", "１２", "٢", "+2", "2++3",
            "2 ^", "2 ^^ 3", "2 ^ +3", "2 + ()", "2 + * 3",
        ]
        for expression in expressions:
            with self.subTest(expression=expression):
