        self.assertEqual(evaluate("-" * 2000 + "3"), 3)


def evaluate(expr: str):
    """Evaluate arithmetic using integer, float, and Python numeric semantics."""
    token_pattern = r"[0-9]+(?:\.[0-9]+)?|[+\-*/^()]|\s+"
    tokens = []
    position = 0

    for match in re.finditer(token_pattern, expr):
        if match.start() != position:
            raise ValueError("Invalid character or numeric literal")
        token = match.group()
        if not token.isspace():
            tokens.append(token)
        position = match.end()

    if position != len(expr):
        raise ValueError("Invalid character or numeric literal")
    if not tokens:
        raise ValueError("Empty expression")

    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3, "^": 4}
    expecting_operand = True

    def apply_operator():
        operator = operators.pop()
        if operator == "neg":
            values.append(-values.pop())
            return

        right = values.pop()
        left = values.pop()
        try:
            if operator == "+":
                result = left + right
            elif operator == "-":
                result = left - right
            elif operator == "*":
                result = left * right
            elif operator == "/":
                result = left / right
            else:
                result = left ** right
        except ZeroDivisionError as error:
            raise ValueError("Division by zero") from error
        values.append(result)

    for token in tokens:
        if "0" <= token[0] <= "9":
            if not expecting_operand:
                raise ValueError("Missing operator")
            values.append(float(token) if "." in token else int(token))
            expecting_operand = False

        elif token == "(":
            if not expecting_operand:
                raise ValueError("Implicit multiplication is not allowed")
            operators.append(token)

        elif token == ")":
            if expecting_operand:
                raise ValueError("Missing operand")
            while operators and operators[-1] != "(":
                apply_operator()
            if not operators:
                raise ValueError("Unbalanced parentheses")
            operators.pop()

        elif expecting_operand:
            if token != "-":
                raise ValueError("Expected an operand")
            # Prefix minus must not reduce a preceding exponentiation.
            operators.append("neg")

        else:
            while operators and operators[-1] != "(":
                previous = precedence[operators[-1]]
                current = precedence[token]
                if previous < current or (previous == current and token == "^"):
                    break
                apply_operator()
            operators.append(token)
            expecting_operand = True

    if expecting_operand:
        raise ValueError("Missing operand")

    while operators:
        if operators[-1] == "(":
            raise ValueError("Unbalanced parentheses")
        apply_operator()

    return values[0]


if __name__ == "__main__":
    unittest.main()
