def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 1024:
        return "{} B".format(n)

    units = ("KiB", "MiB", "GiB", "TiB")
    k = 1
    for i in range(1, len(units) + 1):
        if n >= 1024 ** i:
            k = i
    den = 1024 ** k
    num = n * 10
    q, r = divmod(num, den)
    if 2 * r >= den:
        q += 1
    if q == 10240 and k < len(units):
        k += 1
        den = 1024 ** k
        q, r = divmod(num, den)
        if 2 * r >= den:
            q += 1
    return "{}.{} {}".format(q // 10, q % 10, units[k - 1])
