One bug found: the numeric fields were written as non-capturing groups, so the regex had exactly one capture group (the pre-release) — `match.group(2)`/`group(3)`/`group(4)` would have raised `IndexError` on every call. Fixed with named groups.

```python
"""Semantic-version constraint checking (SemVer 2.0 ordering, npm-style rules).

Python 3.9, standard library only.
"""

import re

__all__ = ["semver_satisfies"]

# ---------------------------------------------------------------------------
# Grammar fragments
# ---------------------------------------------------------------------------

# No bare ``-`` inside the version: a bare ``-`` means it is a regex char.
_NUMERIC = r"(?:0|[1-9][0-9]*)"
_IDENTIFIER = r"[0-9A-Za-z-]+"
_IDENTIFIER_LIST = _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*"

_VERSION_RE = re.compile(
    r"(?P<major>" + _NUMERIC + r")\."
    + r"(?P<minor>" + _NUMERIC + r")\."
    + r"(?P<patch>" + _NUMERIC + r")"
    + r"(?:-(?P<prerelease>" + _IDENTIFIER_LIST + r"))?"
    + r"(?:\+" + _IDENTIFIER_LIST + r")?"
)

_OPERATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)(.*)")
_DIGITS_RE = re.compile(r"[0-9]+")

# A parsed version is a 4-tuple: (major, minor, patch, prerelease | None),
# where prerelease is a list of identifier strings.  Build metadata is
# validated but never stored, since it is ignored when comparing.


# ---------------------------------------------------------------------------
# Version parsing
# ---------------------------------------------------------------------------

def _parse_version(text):
    """Parse a SemVer string, raising ValueError when it is malformed."""
    if not isinstance(text, str):
        raise ValueError("version must be a string: %r" % (text,))

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))

    prerelease_text = match.group("prerelease")
    if prerelease_text is None:
        prerelease = None
    else:
        prerelease = prerelease_text.split(".")
        for identifier in prerelease:
            if (
                _DIGITS_RE.fullmatch(identifier) is not None
                and len(identifier) > 1
                and identifier[0] == "0"
            ):
                raise ValueError("invalid version: %r" % (text,))

    return (
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        prerelease,
    )


def _is_numeric(identifier):
    return _DIGITS_RE.fullmatch(identifier) is not None


# ---------------------------------------------------------------------------
# Ordering
# ---------------------------------------------------------------------------

def _compare_prerelease(left, right):
    """Compare two non-empty lists of pre-release identifiers."""
    for a, b in zip(left, right):
        if a == b:
            continue
        a_numeric = _is_numeric(a)
        b_numeric = _is_numeric(b)
        if a_numeric and b_numeric:
            a_value, b_value = int(a), int(b)
            if a_value != b_value:
                return -1 if a_value < b_value else 1
        elif a_numeric:
            return -1
        elif b_numeric:
            return 1
        else:
            return -1 if a < b else 1

    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare(left, right):
    """Return -1, 0 or 1 for the SemVer precedence of two parsed versions."""
    for index in (0, 1, 2):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1

    left_pre, right_pre = left[3], right[3]
    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:            # a release outranks any pre-release
        return 1
    if right_pre is None:
        return -1
    return _compare_prerelease(left_pre, right_pre)


# ---------------------------------------------------------------------------
# Constraint parsing
# ---------------------------------------------------------------------------

def _caret_upper_bound(version):
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper_bound(version):
    return (version[0], version[1] + 1, 0, None)


def _parse_comparator(token):
    """Return ``(operator, bound version or None)`` for one comparator."""
    if token == "*":
        return ("*", None)

