_SPECS = (
    ("minute", 0, 59),
    ("hour", 0, 23),
    ("day-of-month", 1, 31),
    ("month", 1, 12),
    ("day-of-week", 0, 6),
)

_NUM_RE = re.compile(r"[0-9]+")
_RANGE_RE = re.compile(r"([0-9]+)-([0-9]+)")

# Search horizon: 5 years, generous enough to cover every leap-day case.
_MAX_DAYS = 366 * 5


def _parse_item(item, lo, hi, name):
    """Expand one comma-separated item into the set of values it selects."""
    if item == "":
        raise ValueError("empty item in %s field" % name)
    if item.count("/") > 1:
        raise ValueError("malformed item %r in %s field" % (item, name))

    has_step = "/" in item
    if has_step:
        base, step_text = item.split("/")
        if not _NUM_RE.fullmatch(step_text):
            raise ValueError("malformed step in item %r (%s field)" % (item, name))
        step = int(step_text)
        if step < 1:
            raise ValueError("step must be >= 1 in item %r (%s field)" % (item, name))
    else:
        base, step = item, 1

    if base == "*":
        # '*/n' -> every n-th value from the field minimum.
        return set(range(lo, hi + 1, step))

    match = _RANGE_RE.fullmatch(base)
    if match:
        first, last = int(match.group(1)), int(match.group(2))
        if first > last:
            raise ValueError("reversed range in item %r (%s field)" % (item, name))
        if first < lo or last > hi:
            raise ValueError("value out of range in item %r (%s field)" % (item, name))
