def parse_duration(s: str) -> int:
    _UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    _DIGITS = "0123456789"

    stripped = s.strip(" ")
    if not stripped:
        raise ValueError("empty duration string")

    total = 0
    seen = set()
    i = 0
    n = len(stripped)

    while i < n:
        start = i
        while i < n and stripped[i] in _DIGITS:
            i += 1
        if i == start:
            ch = stripped[i]
            if ch in _UNIT_SECONDS:
                raise ValueError("unit without number")
            raise ValueError(f"unexpected character: {ch!r}")
        value = int(stripped[start:i])
        if i >= n:
            raise ValueError("number without unit")
        unit = stripped[i]
        if unit == " ":
            raise ValueError("space between number and unit")
        if unit not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit: {unit!r}")
        if unit in seen:
            raise ValueError(f"repeated unit: {unit!r}")
        seen.add(unit)
        total += value * _UNIT_SECONDS[unit]
        i += 1
        while i < n and stripped[i] == " ":
            i += 1

    return total
