from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]], duration: int, start: int, end: int
) -> Optional[int]:
    """Earliest t with start <= t, t + duration <= end, [t, t+duration) free of busy."""
    # duration must be a genuine positive integer (bool is not accepted as one)
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every busy interval, then keep only those intersecting [start, end).
    # Intervals are half-open: [begin, finish); finish itself is free.
    relevant = []
    for interval in busy:
        begin, finish = interval
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        if finish > start and begin < end:
            relevant.append((begin, finish))

    relevant.sort()  # new list; input is never mutated

    cursor = start
    for begin, finish in relevant:
        # Slot [cursor, cursor + duration) fits before this interval starts.
        if begin >= cursor + duration:
            break
        # This interval overlaps the candidate slot; push the candidate past it.
        if finish > cursor:
            cursor = finish

    if cursor + duration <= end:
        return cursor
    return None
