import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire name matches the glob pattern."""
    regex = []
    i = 0

    def escape_class_char(char: str) -> str:
        if char in r"\^-]":
            return "\\" + char
        return char

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(".*")
                i += 2
            else:
                regex.append("[^/]*")
                i += 1
        elif char == "?":
            regex.append("[^/]")
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            members = []
            if i < len(pattern) and pattern[i] == "]":
                members.append("]")
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in pattern")
                members.append(pattern[i])
                i += 1

            if i == len(pattern):
                raise ValueError("unclosed character class")
            if not members:
                raise ValueError("empty character class")

            class_body = []
            j = 0
            while j < len(members):
                if (
                    j + 2 < len(members)
                    and members[j + 1] == "-"
                    and members[j] != "-"
                    and members[j + 2] != "-"
                ):
                    class_body.append(
                        escape_class_char(members[j])
                        + "-"
                        + escape_class_char(members[j + 2])
                    )
                    j += 3
                else:
                    class_body.append(escape_class_char(members[j]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(class_body) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    try:
        return re.fullmatch("".join(regex), name) is not None
    except re.error as exc:
        raise ValueError("invalid glob pattern") from exc
