        raise ValueError("invalid version: %r" % (text,))
    m = _VER_RE.fullmatch(text)
    if m is None:
        raise ValueError("invalid version: %r" % (text,))
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = None
    if m.group(4) is not None:
        pre = m.group(4).split(".")
        for ident in pre:
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError("invalid version: %r" % (text,))
    return (major, minor, patch, pre)


def _cmp_int(a, b):
    return (a > b) - (a < b)


def _cmp_pre(a, b):
    for x, y in zip(a, b):
        xd, yd = x.isdigit(), y.isdigit()
        if xd and yd:
            c = _cmp_int(int(x), int(y))
        elif xd != yd:
            c = -1 if xd else 1
        else:
            c = _cmp_int(x, y)
        if c:
            return c
    return _cmp_int(len(a), len(b))


def _cmp_versions(v1, v2):
    for i in range(3):
        c = _cmp_int(v1[i], v2[i])
        if c:
            return c
    p1, p2 = v1[3], v2[3]
    if p1 is None and p2 is None:
        return 0
    if p1 is None:
        return 1
    if p2 is None:
        return -1
    return _cmp_pre(p1, p2)


def _parse_comparator(token):
    m = _CMP_RE.fullmatch(token)
    op = m.group(1)
    rest = m.group(2)
    if rest == "*" and op is None:
        return (None, None)
    return (op, _parse_version(rest))


def _expand(op, ver):
    major, minor, patch, pre = ver
    if op is None or op == "=":
        return [("=", ver)]
