    if op == "^":
        if major > 0:
            upper = (major + 1, 0, 0, None)
        elif minor > 0:
            upper = (0, minor + 1, 0, None)
        else:
            upper = (0, 0, patch + 1, None)
        return [(">=", ver), ("<", upper)]
    # op == "~"
    upper = (major, minor + 1, 0, None)
    return [(">=", ver), ("<", upper)]


def _group_satisfies(ver, comparators):
