        allowed = False
        for op, cver in comparators:
            if cver is not None and cver[3] is not None and cver[:3] == ver[:3]:
                allowed = True
                break
        if not allowed:
            return False
    for op, cver in comparators:
        if cver is None:
            continue
        for prim_op, prim_ver in _expand(op, cver):
            c = _cmp_versions(ver, prim_ver)
            if prim_op == "=" and c != 0:
                return False
            if prim_op == ">" and c <= 0:
                return False
            if prim_op == ">=" and c < 0:
                return False
            if prim_op == "<" and c >= 0:
                return False
            if prim_op == "<=" and c > 0:
                return False
    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    ver = _parse_version(version)
    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("empty constraint")
    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("invalid constraint: %r" % (constraint,))
        groups.append([_parse_comparator(tok) for tok in tokens])
    for comparators in groups:
        if _group_satisfies(ver, comparators):
            return True
    return False
