def normalize_path(p: str) -> str:
    is_absolute = p.startswith("/")
    stack = []
    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            elif not is_absolute:
                stack.append("..")
            # For absolute paths, ".." at the root is ignored.
        else:
            stack.append(part)
    if is_absolute:
        return "/" + "/".join(stack)
    if not stack:
        return "."
    return "/".join(stack)
