    body = x[1:] if sign_neg else x
    if '.' in body:
        int_part, frac_part = body.split('.', 1)
    else:
        int_part, frac_part = body, ''

    n = int(int_part + frac_part)
    p = len(frac_part)

    if p >= ndigits:
        divisor = 10 ** (p - ndigits)
        q, r = divmod(n, divisor)
        if 2 * r >= divisor:
            q += 1
    else:
        q = n * (10 ** (ndigits - p))

    if q == 0:
        sign = ''
    elif sign_neg:
        sign = '-'
    else:
        sign = ''

    s = str(q).zfill(ndigits + 1)
    if ndigits == 0:
        return sign + s
