    r"(?P<major>0|[1-9][0-9]*)\."
    r"(?P<minor>0|[1-9][0-9]*)\."
    r"(?P<patch>0|[1-9][0-9]*)"
    r"(?:-(?P<prerelease>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?"
)
_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.+)")


def _parse_version(version: str) -> Tuple[Tuple[str, str, str], Optional[Tuple[str, ...]]]:
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid semantic version")

    prerelease_text = match.group("prerelease")
    prerelease = tuple(prerelease_text.split(".")) if prerelease_text is not None else None
    if prerelease is not None:
        for identifier in prerelease:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("numeric prerelease identifiers must not have leading zeros")

    return (
        (match.group("major"), match.group("minor"), match.group("patch")),
        prerelease,
    )


def _compare_numbers(left: str, right: str) -> int:
    if len(left) != len(right):
        return -1 if len(left) < len(right) else 1
    return (left > right) - (left < right)


def _compare_versions(
    left: Tuple[Tuple[str, str, str], Optional[Tuple[str, ...]]],
    right: Tuple[Tuple[str, str, str], Optional[Tuple[str, ...]]],
) -> int:
    left_core, left_pre = left
    right_core, right_pre = right

    for left_part, right_part in zip(left_core, right_core):
        result = _compare_numbers(left_part, right_part)
        if result:
            return result

    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()
        if left_numeric and right_numeric:
            result = _compare_numbers(left_id, right_id)
        elif left_numeric != right_numeric:
            result = -1 if left_numeric else 1
        else:
            result = (left_id > right_id) - (left_id < right_id)
        if result:
            return result

    return (len(left_pre) > len(right_pre)) - (len(left_pre) < len(right_pre))


def _increment_decimal(value: str) -> str:
    digits = list(value)
    index = len(digits) - 1
    while index >= 0 and digits[index] == "9":
        digits[index] = "0"
        index -= 1
    if index < 0:
        return "1" + "".join(digits)
    digits[index] = chr(ord(digits[index]) + 1)
    return "".join(digits)


