        has_matching_prerelease_comparator = False

        for operator, operand in comparators:
            if operator == "*":
                continue

            assert operand is not None
            operand_core, operand_pre = operand
            version_core, version_pre = parsed_version
            if version_pre is not None and version_core == operand_core and operand_pre is not None:
                has_matching_prerelease_comparator = True

            if operator in ("^", "~"):
