        if not host:
            raise ValueError("Host must not be empty")
        if separator:
            if not re.fullmatch(r"[0-9]{1,5}", port_text):
                raise ValueError("Invalid port")
            port = int(port_text)

    if port is not None and not 1 <= port <= 65535:
        raise ValueError("Port out of range")

    fragment = ""
    if "#" in remainder:
        remainder, fragment = remainder.split("#", 1)

    query = ""
    if "?" in remainder:
        path, query = remainder.split("?", 1)
    else:
        path = remainder

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
