def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly five fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    parsed = []
    unrestricted = []

    for field, (minimum, maximum) in zip(fields, bounds):
        unrestricted.append(field == "*")
        values = set()

        for item in field.split(","):
            match = re.fullmatch(r"(\*|\d+(?:-\d+)?)(?:/(\d+))?", item)
            if not match:
                raise ValueError("malformed cron field")

            base, step_text = match.groups()
            step = int(step_text) if step_text is not None else 1
            if step < 1:
                raise ValueError("step must be at least 1")

            if base == "*":
                start, end = minimum, maximum
            elif "-" in base:
                start_text, end_text = base.split("-", 1)
                start, end = int(start_text), int(end_text)
                if start > end:
                    raise ValueError("range start must not exceed range end")
            else:
                start = int(base)
                end = maximum if step_text is not None else start

            if start < minimum or end > maximum:
                raise ValueError("value outside field range")

            values.update(range(start, end + 1, step))

        if not values:
            raise ValueError("empty cron field")
        parsed.append(sorted(values))

    minutes, hours, month_days, months, week_days = parsed
    dom_restricted = not unrestricted[2]
    dow_restricted = not unrestricted[4]

    try:
        after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
        if after_dt.strftime("%Y-%m-%d %H:%M") != after:
            raise ValueError
    except ValueError as exc:
        raise ValueError("after must be formatted YYYY-MM-DD HH:MM") from exc

    try:
        deadline = after_dt.replace(year=after_dt.year + 5)
    except ValueError:
        deadline = after_dt.replace(
            year=after_dt.year + 5, day=28
        )

    current_day = after_dt.date()
    while current_day <= deadline.date():
        if current_day.month in months:
            dom_match = current_day.day in month_days
            dow = (current_day.weekday() + 1) % 7
            dow_match = dow in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_match or dow_match
            elif dom_restricted:
                day_matches = dom_match
            elif dow_restricted:
                day_matches = dow_match
            else:
                day_matches = True

            if day_matches:
                for hour in hours:
                    for minute in minutes:
                        candidate = datetime.combine(
                            current_day, time(hour, minute)
                        )
                        if after_dt < candidate <= deadline:
                            return candidate.strftime("%Y-%m-%d %H:%M")

        current_day += timedelta(days=1)

    raise ValueError("no matching time within five years")
