def first_bracket_error(s: str) -> int:
    matching = {')': '(', ']': '[', '}': '{'}
    openers = {'(', '[', '{'}
    stack = []  # indices of currently unclosed opening brackets (bottom = leftmost)
    for i, ch in enumerate(s):
        if ch in openers:
            stack.append(i)
        elif ch in matching:
            if not stack:
                # Closing bracket with no opening bracket at all.
                return i
            open_index = stack.pop()
            if s[open_index] != matching[ch]:
                # Closing bracket does not match the most recent unclosed opener.
                return i
    if stack:
        # Some opening brackets never closed; the leftmost is at the stack bottom.
        return stack[0]
    return -1
