import re

_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_OPERATORS = frozenset("+-*/^()")


def _tokenize(expr: str):
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        m = _NUMBER_RE.match(expr, i)
        if m:
            tokens.append(m.group(0))
            i = m.end()
            continue
        if c in _OPERATORS:
            tokens.append(c)
            i += 1
            continue
        raise ValueError("invalid character %r at position %d" % (c, i))
    return tokens


def _truediv(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        raise ValueError("division by zero")


def _power(a, b):
    try:
        return a ** b
    except ZeroDivisionError:
        raise ValueError("division by zero")


class _Parser:
    """Recursive-descent parser.

    expr  := term (('+' | '-') term)*
    term  := unary (('*' | '/') unary)*
    unary := '-' unary | power
    power := atom ('^' unary)?          # right-associative, exponent may be unary
    atom  := number | '(' expr ')'
    """

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _take(self):
        tok = self._peek()
        self.pos += 1
        return tok

    def parse(self):
        if not self.tokens:
            raise ValueError("empty expression")
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos],))
        return value

    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._take()
            right = self._term()
            value = value + right if op == "+" else value - right
        return value

    def _term(self):
        value = self._unary()
        while self._peek() in ("*", "/"):
            op = self._take()
            right = self._unary()
            value = value * right if op == "*" else _truediv(value, right)
        return value

    def _unary(self):
        if self._peek() == "-":
            self._take()
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._atom()
        if self._peek() == "^":
            self._take()
            exponent = self._unary()
            return _power(base, exponent)
        return base

    def _atom(self):
        tok = self._take()
        if tok is None:
            raise ValueError("unexpected end of input")
        if tok == "(":
            value = self._expr()
            if self._take() != ")":
                raise ValueError("expected ')'")
            return value
        if tok in _OPERATORS:
            raise ValueError("unexpected token %r" % (tok,))
        if "." in tok:
            return float(tok)
        return int(tok)


def evaluate(expr: str):
    return _Parser(_tokenize(expr)).parse()
