import re
from datetime import datetime, timedelta

_ITEM_RE = re.compile(r"(\*|(\d+)(?:-(\d+))?)(?:/(\d+))?")


def _parse_field(field, lo, hi):
    """Expand one cron field into the set of allowed integer values."""
    values = set()
    for item in field.split(","):
        m = _ITEM_RE.fullmatch(item)
        if m is None:
            raise ValueError("malformed cron item: {!r}".format(item))
        core, a, b, step_s = m.group(1), m.group(2), m.group(3), m.group(4)
        step = int(step_s) if step_s is not None else 1
        if step < 1:
            raise ValueError("cron step must be >= 1: {!r}".format(item))
        if core == "*":
            start_v, end_v = lo, hi
        elif b is not None:
            start_v, end_v = int(a), int(b)
            if start_v > end_v:
                raise ValueError("cron range start > end: {!r}".format(item))
        else:
            start_v = int(a)
            # "a/n" runs from a up to the field maximum; a bare "a" is just a.
            end_v = start_v if step_s is None else hi
        if start_v < lo or start_v > hi or end_v > hi:
            raise ValueError("cron value out of range: {!r}".format(item))
        values.update(range(start_v, end_v + 1, step))
    return values


def _day_matches(day, doms, dows, dom_restricted, dow_restricted):
    dom_ok = day.day in doms
    dow_ok = ((day.weekday() + 1) % 7) in dows  # Monday=0 -> 1 ... Sunday=6 -> 0
    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    if dom_restricted:
        return dom_ok
    if dow_restricted:
        return dow_ok
    return True


def _add_years(dt, n):
    y = dt.year + n
    try:
        return dt.replace(year=y)
    except ValueError:          # Feb 29 -> Feb 28 in a non-leap target year
        return dt.replace(year=y, day=28)


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dows = _parse_field(fields[4], 0, 6)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    base = datetime.strptime(after, "%Y-%m-%d %H:%M")
    start = base + timedelta(minutes=1)      # strictly later, minute granularity
    limit = _add_years(base, 5)

    s_minutes = sorted(minutes)
    s_hours = sorted(hours)
    start_date = start.date()
    last_date = limit.date()

    day = start_date
    while day <= last_date:
        if day.month in months and _day_matches(day, doms, dows, dom_restricted, dow_restricted):
            if day == start_date:
                h_lo, m_lo = start.hour, start.minute
            else:
                h_lo, m_lo = 0, 0
            for h in s_hours:
                if h < h_lo:
                    continue
                for mi in s_minutes:
                    if h == h_lo and mi < m_lo:
                        continue
                    cand = datetime(day.year, day.month, day.day, h, mi)
                    if cand <= limit:
                        return cand.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years")
