import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    dep_map = {node: set(deps.get(node, ())) for node in nodes}

    dependents = {node: [] for node in nodes}
    indegree = {node: 0 for node in nodes}
    for node, ds in dep_map.items():
        for d in ds:
            if d == node:
                raise ValueError(f"Cycle detected: {node!r} depends on itself")
            indegree[node] += 1
            dependents[d].append(node)

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in dependencies")
    return result
