import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned anywhere (as a key or inside a list).
    nodes = set(deps.keys())
    for dep_list in deps.values():
        nodes.update(dep_list)

    # Build edges: dependency -> items that depend on it.
    # Duplicate entries in dependency lists are ignored (each edge kept once).
    dependents: dict[str, set[str]] = {node: set() for node in nodes}
    indegree: dict[str, int] = {node: 0 for node in nodes}
    for item, dep_list in deps.items():
        for dep in dep_list:
            if item not in dependents[dep]:
                dependents[dep].add(item)
                indegree[item] += 1

    # Kahn's algorithm with a min-heap: whenever several items are ready,
    # the lexicographically smallest one is placed next.
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    # If not every item was placed, there is a cycle
    # (a self-dependency is the length-1 case of this).
    if len(result) != len(nodes):
        raise ValueError("Circular dependency detected")

    return result
