from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    words = [word for word in text.split(" ") if word]
    lines: List[str] = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            full_piece_count, remainder = divmod(len(word), width)
            for index in range(full_piece_count):
                lines.append(word[index * width:(index + 1) * width])

            if remainder:
                current = word[full_piece_count * width:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
