from datetime import datetime, timedelta


def _parse_field(spec, lo, hi):
    """Parse one cron field into a sorted list of ints, or raise ValueError."""
    if not spec:
        raise ValueError("empty field")
    values = set()
    for item in spec.split(","):
        if not item:
            raise ValueError("empty item in field %r" % (spec,))
        base, sep, step_s = item.partition("/")
        if sep:
            if not step_s.isdigit():
                raise ValueError("bad step in %r" % (item,))
            step = int(step_s)
            if step < 1:
                raise ValueError("step must be >= 1 in %r" % (item,))
        else:
            step = 1
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a_s, _, b_s = base.partition("-")
            if not (a_s.isdigit() and b_s.isdigit()):
                raise ValueError("bad range in %r" % (item,))
            start, end = int(a_s), int(b_s)
        else:
            if not base.isdigit():
                raise ValueError("bad value in %r" % (item,))
            start = int(base)
            end = hi if sep else start
        if not (lo <= start <= hi) or not (lo <= end <= hi):
            raise ValueError("value out of range in %r" % (item,))
        if start > end:
            raise ValueError("inverted range in %r" % (item,))
        values.update(range(start, end + 1, step))
    return sorted(values)


def next_cron(expr: str, after: str) -> str:
    """Return the earliest time matching the 5-field cron expression `expr`
    that is strictly later than the naive local time `after`
    ('YYYY-MM-DD HH:MM').  Raises ValueError on bad input or if nothing
    matches within 5 years."""
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % len(fields))
    minute_s, hour_s, dom_s, mon_s, dow_s = fields

    minutes = _parse_field(minute_s, 0, 59)
    hours = _parse_field(hour_s, 0, 23)
    doms = set(_parse_field(dom_s, 1, 31))
    months = set(_parse_field(mon_s, 1, 12))
    dows = set(_parse_field(dow_s, 0, 6))

    dom_restricted = dom_s != "*"
    dow_restricted = dow_s != "*"

    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError:
        raise ValueError("bad 'after' value: %r" % (after,))
    start = start + timedelta(minutes=1)
    deadline = start + timedelta(days=1830)  # ~5 years

    cur = start
    while cur <= deadline:
        if cur.month in months:
            wd = (cur.weekday() + 1) % 7  # cron: 0 = Sunday
            if dom_restricted and dow_restricted:
                day_ok = (cur.day in doms) or (wd in dows)
            elif dom_restricted:
                day_ok = cur.day in doms
            elif dow_restricted:
                day_ok = wd in dows
            else:
                day_ok = True
            if day_ok:
                for h in hours:
                    if h < cur.hour:
                        continue
                    for m in minutes:
                        if h == cur.hour and m < cur.minute:
                            continue
                        cand = cur.replace(hour=h, minute=m, second=0, microsecond=0)
                        if cand < start:
                            continue
                        if cand > deadline:
                            raise ValueError("no matching time within 5 years")
                        return cand.strftime("%Y-%m-%d %H:%M")
        cur = (cur + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)

    raise ValueError("no matching time within 5 years")
