def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    out = []
    for comp in p.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if out:
                out.pop()
            elif not absolute:
                out.append("..")
        else:
            out.append(comp)
    if absolute:
        return "/" + "/".join(out)
