import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire name matches the path-like glob pattern."""
    parts = [r"\A"]
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("pattern cannot end with a backslash")
            parts.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                parts.append(r"[\s\S]*")
                i += 2
            else:
                parts.append(r"[^/]*")
                i += 1
        elif char == "?":
            parts.append(r"[^/]")
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            tokens = []
            if i < len(pattern) and pattern[i] == "]":
                tokens.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                escaped = pattern[i] == "\\"
                if escaped:
                    i += 1
                    if i == len(pattern):
                        raise ValueError("pattern cannot end with a backslash")
                tokens.append((pattern[i], escaped))
                i += 1

            if i == len(pattern):
                raise ValueError("unterminated character set")
            i += 1

            if not tokens:
                raise ValueError("empty character set")

            content = []
            for j, (value, escaped) in enumerate(tokens):
                if value == "-" and not escaped and 0 < j < len(tokens) - 1:
                    content.append("-")
                else:
                    content.append(re.escape(value))

            parts.append("[" + ("^" if negate else "") + "".join(content) + "]")
        else:
            parts.append(re.escape(char))
            i += 1

    parts.append(r"\Z")
    try:
        return re.match("".join(parts), name, re.DOTALL) is not None
    except re.error as exc:
        raise ValueError("invalid glob pattern") from exc
