import re


_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?"
)


def _parse_semver(text):
    """Return a tuple whose native ordering implements SemVer precedence."""
    match = _SEMVER_RE.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    major, minor, patch, prerelease = match.groups()
    identifiers = []

    if prerelease is not None:
        for identifier in prerelease.split("."):
            if all("0" <= char <= "9" for char in identifier):
                if len(identifier) > 1 and identifier[0] == "0":
                    raise ValueError(
                        "Numeric pre-release identifiers cannot have leading zeros"
                    )
                identifiers.append((0, int(identifier)))
            else:
                identifiers.append((1, identifier))

    return (
        int(major),
        int(minor),
        int(patch),
        prerelease is None,
        tuple(identifiers),
    )


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a strict SemVer version against the specified constraint syntax.

    The entire constraint is validated, even when an earlier group matches.
    Build metadata is validated but has no effect on comparisons.
    """
    if not isinstance(version, str) or not isinstance(constraint, str):
        raise ValueError("Version and constraint must be strings")

    candidate = _parse_semver(version)
    groups = []

    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        comparisons = []
        permits_prerelease = False

        for token in tokens:
            if token == "*":
                continue

            operator = "="
            operand = token
            for prefix in (">=", "<=", "=", ">", "<", "^", "~"):
                if token.startswith(prefix):
                    operator = prefix
                    operand = token[len(prefix):]
                    break

            bound = _parse_semver(operand)

            # Only explicitly written pre-release bounds grant eligibility.
            if not bound[3] and bound[:3] == candidate[:3]:
                permits_prerelease = True

            if operator in ("^", "~"):
                major, minor, patch = bound[:3]
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                upper = upper_core + (True, ())
                comparisons.append((">=", bound))
                comparisons.append(("<", upper))
            else:
                comparisons.append((operator, bound))

        groups.append((comparisons, permits_prerelease))

    for comparisons, permits_prerelease in groups:
        if not candidate[3] and not permits_prerelease:
            continue

        matches = True
        for operator, bound in comparisons:
            if operator == "=":
                satisfied = candidate == bound
            elif operator == ">":
                satisfied = candidate > bound
            elif operator == ">=":
                satisfied = candidate >= bound
            elif operator == "<":
                satisfied = candidate < bound
            else:  # <=
                satisfied = candidate <= bound

            if not satisfied:
                matches = False
                break

        if matches:
            return True

    return False
