import heapq


def topo_sort(deps: dict) -> list:
    """Topologically sort items so each comes after all of its dependencies.

    All items (keys or mentioned in dependency lists) appear exactly once.
    Ties are broken by placing the lexicographically smallest ready item first.
    Self-dependencies and cycles raise ValueError.  The input is not modified.
    """
    nodes = set(deps.keys())
    edges = {}
    for item, required in deps.items():
        req = set(required)
        edges[item] = req
        nodes.update(req)
    for node in nodes:
        edges.setdefault(node, set())

    indegree = {node: len(edges[node]) for node in nodes}
    dependents = {node: set() for node in nodes}
    for node, req in edges.items():
        for dep in req:
            dependents[dep].add(node)

    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in sorted(dependents[node]):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")

    return order
