def first_bracket_error(s: str) -> int:
    """Return the index of the first bracket error in `s`, or -1 if balanced.

    A bracket error is either a closing bracket that does not match the most
    recent unclosed opening bracket (or arrives with none open), or, if no such
    closing bracket exists, the leftmost opening bracket still unclosed at the
    end. All non-bracket characters are ignored.
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []  # (opening_char, index)

    for i, ch in enumerate(s):
        if ch in pairs.values():  # opening bracket
            stack.append((ch, i))
        elif ch in pairs:  # closing bracket
            if not stack or stack[-1][0] != pairs[ch]:
                return i
            stack.pop()

    if stack:
        return stack[0][1]
    return -1
