def mask_email(s: str) -> str:
    """Mask the local part of an email address, leaving the domain intact.

    Raises ValueError unless the string contains exactly one "@" with a
    non-empty local part and a non-empty domain.
    """
    if s.count("@") != 1:
        raise ValueError("expected exactly one '@' in the email address")

    local, domain = s.split("@")

    if not local or not domain:
        raise ValueError("local part and domain must both be non-empty")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
