def normalize_path(p: str) -> str:
    """
    Normalize a Unix-style path.

    - Splits on "/", ignoring empty components and ".".
    - ".." removes the previous component.
    - For absolute paths (starting with "/"), ".." at the root is ignored,
      and any number of leading slashes denotes the same root "/".
    - For relative paths, leading ".." components that cannot be resolved
      are kept.
    - No trailing slash, except the root itself "/".
    - Empty relative results (and empty input) yield ".".
    - Components like "..." are treated as ordinary names.
    """
    absolute = p.startswith("/")
    stack = []

    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                stack.append("..")
            # For absolute paths at the root, ".." is ignored.
        else:
            stack.append(part)

    if absolute:
        return "/" + "/".join(stack)
    if not stack:
        return "."
    return "/".join(stack)
