"""Convert canonical uppercase Roman numerals (1-3999) to integers."""

import re

__all__ = ["roman_to_int"]

# Canonical Roman numerals: thousands, hundreds, tens, ones.
# Matches exactly the standard forms in the range 1..3999 (and also the
# empty string, which is rejected separately).
_CANONICAL = re.compile(
    r"M{0,3}"
    r"(CM|CD|D?C{0,3})"
    r"(XC|XL|L?X{0,3})"
    r"(IX|IV|V?I{0,3})"
)

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Return the integer value of the canonical Roman numeral *s*.

    Only canonical uppercase representations of the numbers 1..3999 are
    accepted (e.g. "I" ... "MMMCMXCIX").

    Raises:
        ValueError: if *s* is not a str, is empty, contains lowercase or
            non-Roman characters, or is not in canonical form
            (e.g. "IIII", "IC", "VX", "IIV", "XXXX", "MMMM").
    """
    if not isinstance(s, str) or not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    prev = 0
    for ch in reversed(s):
        value = _VALUES[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value
    return total
