import re


def evaluate(expr: str):
    token_pattern = re.compile(r"[0-9]+(?:\.[0-9]+)?|[+\-*/^()]")
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3, "^": 4}
    values = []
    operators = []
    expecting_operand = True
    position = 0

    def apply_operator():
        operator = operators.pop()

        if operator == "neg":
            values.append(-values.pop())
            return

        right = values.pop()
        left = values.pop()

        try:
            if operator == "+":
                result = left + right
            elif operator == "-":
                result = left - right
            elif operator == "*":
                result = left * right
            elif operator == "/":
                result = left / right
            else:
                result = left ** right
        except ZeroDivisionError as exc:
            raise ValueError("Division by zero") from exc

        values.append(result)

    while position < len(expr):
        if expr[position].isspace():
            position += 1
            continue

        match = token_pattern.match(expr, position)
        if match is None:
            raise ValueError("Invalid token at position {}".format(position))

        token = match.group()
        position = match.end()

        if "0" <= token[0] <= "9":
            if not expecting_operand:
                raise ValueError("Missing operator")
            values.append(float(token) if "." in token else int(token))
            expecting_operand = False

        elif token == "(":
            if not expecting_operand:
                raise ValueError("Missing operator before '('")
            operators.append(token)

        elif token == ")":
            if expecting_operand:
                raise ValueError("Missing operand before ')'")

            while operators and operators[-1] != "(":
                apply_operator()

            if not operators:
                raise ValueError("Unmatched ')'")

            operators.pop()
            expecting_operand = False

        elif expecting_operand:
            if token != "-":
                raise ValueError("Expected an operand")
            # Prefix minus must not reduce a preceding exponentiation.
            operators.append("neg")

        else:
            while operators and operators[-1] != "(":
                previous = operators[-1]
                if precedence[previous] < precedence[token]:
                    break
                if precedence[previous] == precedence[token] and token == "^":
                    break
                apply_operator()

            operators.append(token)
            expecting_operand = True

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        if operators[-1] == "(":
            raise ValueError("Unmatched '('")
        apply_operator()

    return values[0]
