def is_valid_ipv4(s: str) -> bool:
    """Return True iff s is a strict dotted-quad IPv4 address literal."""
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        # Exactly 1-3 ASCII digits, nothing else.
        if not (1 <= len(part) <= 3):
            return False
        for ch in part:
            if ch not in "0123456789":
                return False
        # No leading zeros unless the part is exactly "0".
        if len(part) > 1 and part[0] == "0":
            return False
        # Value must fit in an octet.
        if int(part) > 255:
            return False

    return True
