"""Evaluate arithmetic expressions given as strings.

Grammar (as implemented, precedence low -> high):

    expression := term (("+" | "-") term)*
    term       := unary (("*" | "/") unary)*
    unary      := "-" unary | power            # unary minus binds looser than "^"
    power      := atom ("^" unary)?            # right-associative, exponent may be signed
    atom       := NUMBER | "(" expression ")"

Only integers, decimals of the form <digits>.<digits>, the operators
+ - * / ^, parentheses and whitespace are permitted.  Anything else is
malformed and raises ValueError, as does division by zero.
"""

_DIGITS = "0123456789"
_PUNCT = "+-*/^()"


def _tokenize(expr):
    """Split `expr` into ('num', value) and ('op', char) tokens.

    Whitespace between tokens is skipped.  Raises ValueError on any
    character that is not part of a token.
    """
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _DIGITS:
            # Integer part is mandatory; the fractional part needs a dot
            # followed by at least one digit to be part of the literal.
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            if j + 1 < n and expr[j] == "." and expr[j + 1] in _DIGITS:
                k = j + 1
                while k < n and expr[k] in _DIGITS:
                    k += 1
                tokens.append(("num", float(expr[i:k])))
                i = k
            else:
                tokens.append(("num", int(expr[i:j])))
                i = j
        elif ch in _PUNCT:
            tokens.append(("op", ch))
            i += 1
        else:
            raise ValueError("unexpected character %r at position %d" % (ch, i))
    return tokens


def _power(base, exponent):
    try:
        return base ** exponent
    except ZeroDivisionError:
        raise ValueError("division by zero")
    except OverflowError:
        raise ValueError("numeric overflow")


class _Parser:
    """Recursive-descent parser over the token list."""

    __slots__ = ("tokens", "pos")

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _advance(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        self.pos += 1
        return tok

    def parse(self):
        value = self._parse_additive()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos],))
        return value

    def _parse_additive(self):
        value = self._parse_multiplicative()
        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in "+-":
                return value
            self.pos += 1
            rhs = self._parse_multiplicative()
            value = value + rhs if tok[1] == "+" else value - rhs

    def _parse_multiplicative(self):
        value = self._parse_unary()
        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in "*/":
                return value
            self.pos += 1
            rhs = self._parse_unary()
            if tok[1] == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs

    def _parse_unary(self):
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "-":
            self.pos += 1
            return -self._parse_unary()
        return self._parse_power()

    def _parse_power(self):
        base = self._parse_atom()
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "^":
            self.pos += 1
            exponent = self._parse_unary()
            return _power(base, exponent)
        return base

    def _parse_atom(self):
        tok = self._advance()
        if tok[0] == "num":
            return tok[1]
        if tok[1] == "(":
            value = self._parse_additive()
            closing = self._peek()
            if closing != ("op", ")"):
                raise ValueError("unbalanced parenthesis")
            self.pos += 1
            return value
        raise ValueError("unexpected token %r" % (tok,))


def evaluate(expr: str) -> float:
    """Evaluate the arithmetic expression `expr` and return its value.

    Integers yield int, decimals yield float.  Raises ValueError for any
    malformed input and for division by zero.
    """
    return _Parser(_tokenize(expr)).parse()
