    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest free start time without modifying busy."""
    if (
        not isinstance(duration, int)
        or isinstance(duration, bool)
        or duration <= 0
    ):
        raise ValueError("duration must be a positive integer")

    # Validate every interval, including those outside the search window.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    candidate = start
    if candidate + duration > end:
        return None

    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        if candidate + duration <= begin:
            return candidate

        # This interval overlaps the proposed meeting.
        candidate = finish
        if candidate + duration > end:
            return None

    return candidate


