        raise ValueError("duration must be a positive integer")

    # Validate every interval, including those outside the search window.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    candidate = start
    if candidate + duration > end:
        return None

    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        if candidate + duration <= begin:
            return candidate

        # This interval overlaps the proposed meeting. No earlier start
        # at or after candidate can work before this interval finishes.
        candidate = finish
        if candidate + duration > end:
            return None

    return candidate


