def rle_decode(s: str) -> str:
    parts = []
    total = 0
    i = 0
    n = len(s)

    while i < n:
        if not ("1" <= s[i] <= "9"):
            raise ValueError("Missing count, zero count, or leading zero")

        count = 0
        while i < n and "0" <= s[i] <= "9":
            count = count * 10 + (ord(s[i]) - ord("0"))
            if count > 10000 - total:
                raise ValueError("Decoded length exceeds 10000 characters")
            i += 1

        if i == n:
            raise ValueError("Input ends with digits")

        parts.append(s[i] * count)
        total += count
        i += 1

    return "".join(parts)
