import ipaddress
import re


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("URL must be a string")

    match = re.match(r"([A-Za-z][A-Za-z0-9+.-]*)://", url)
    if match is None:
        raise ValueError("URL must start with a valid scheme followed by '://'")

    scheme = match.group(1).lower()
    remainder = url[match.end():]

    boundary = re.search(r"[/?#]", remainder)
    authority_end = boundary.start() if boundary else len(remainder)
    authority = remainder[:authority_end]
    remainder = remainder[authority_end:]

    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    port_text = None

    if host_port.startswith("["):
        closing = host_port.find("]")
        if closing == -1:
            raise ValueError("IPv6 literal must have a closing bracket")

        host = host_port[1:closing]
        try:
            ipaddress.IPv6Address(host)
        except ValueError as exc:
            raise ValueError("Invalid IPv6 literal") from exc

        suffix = host_port[closing + 1:]
        if suffix:
            if not suffix.startswith(":"):
                raise ValueError("Unexpected characters after IPv6 literal")
            port_text = suffix[1:]
    else:
        host, separator, suffix = host_port.partition(":")
        if not host or any(char in " /?#@:[]" for char in host):
            raise ValueError("Invalid host")
        if separator:
            port_text = suffix

    port = None
    if port_text is not None:
        if re.fullmatch(r"[0-9]{1,5}", port_text) is None:
            raise ValueError("Port must contain 1 to 5 ASCII digits")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Port must be between 1 and 65535")

    before_fragment, _, fragment = remainder.partition("#")
    path, _, query = before_fragment.partition("?")

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
