import heapq
from typing import Dict, List


def topo_sort(deps: Dict[str, List[str]]) -> List[str]:
    # Collect every item mentioned (keys and dependencies).
    nodes = set(deps)
    for lst in deps.values():
        nodes.update(lst)

    # Distinct dependencies per item; duplicates are ignored.
    needs = {n: set(deps.get(n, ())) for n in nodes}

    dependents = {n: set() for n in nodes}
    for item, required in needs.items():
        for dep in required:
            dependents[dep].add(item)

    indegree = {n: len(needs[n]) for n in nodes}

    # Ready items: everything with no unplaced dependencies.
    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        node = heapq.heappop(heap)          # lexicographically smallest ready item
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) != len(nodes):           # cycle (includes self-dependency)
        raise ValueError("cycle detected in dependencies")

    return order
