def is_valid_ipv4(s: str) -> bool:
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        # 1 to 3 characters
        if not (1 <= len(part) <= 3):
            return False
        # ASCII digits only (str.isdigit() would accept Unicode digits)
        for ch in part:
            if ch not in "0123456789":
                return False
        # no leading zeros unless the part is exactly "0"
        if part[0] == "0" and len(part) > 1:
            return False
        # value in 0..255
        if int(part) > 255:
            return False

