import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse_version(version):
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid semantic version")

    major, minor, patch = map(int, match.group(1, 2, 3))
    prerelease_text = match.group(4)

    prerelease = None
    if prerelease_text is not None:
        prerelease = tuple(prerelease_text.split("."))
        for identifier in prerelease:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return (major, minor, patch), prerelease


def _compare_identifiers(left, right):
    left_numeric = left.isdigit()
    right_numeric = right.isdigit()

    if left_numeric and right_numeric:
        left_value, right_value = int(left), int(right)
        return (left_value > right_value) - (left_value < right_value)
    if left_numeric != right_numeric:
        return -1 if left_numeric else 1
    return (left > right) - (left < right)


def _compare_versions(left, right):
    left_core, left_pre = left
    right_core, right_pre = right

    if left_core != right_core:
        return (left_core > right_core) - (left_core < right_core)
    if left_pre is None:
        return 0 if right_pre is None else 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        result = _compare_identifiers(left_id, right_id)
        if result:
            return result
    return (len(left_pre) > len(right_pre)) - (len(left_pre) < len(right_pre))


def semver_satisfies(version: str, constraint: str) -> bool:
    candidate = _parse_version(version)

    if not isinstance(constraint, str) or not constraint:
        raise ValueError("constraint must not be empty")

    groups = constraint.split("||")
    if any(not group.strip() for group in groups):
        raise ValueError("invalid constraint")

    for group in groups:
        tokens = group.split()
        comparators = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                comparators.append(("*", None, None))
                continue

            operator = "="
            version_text = token
            for prefix in (">=", "<=", "^", "~", ">", "<", "="):
                if token.startswith(prefix):
                    operator = prefix
                    version_text = token[len(prefix):]
                    break

            if not version_text:
                raise ValueError("invalid comparator")

            parsed = _parse_version(version_text)
            core, prerelease = parsed
            if prerelease is not None:
                prerelease_cores.add(core)

            comparators.append((operator, parsed, core))

        if not comparators:
            raise ValueError("invalid constraint")

        if candidate[1] is not None and candidate[0] not in prerelease_cores:
            continue

        satisfied = True
        for operator, target, core in comparators:
            if operator == "*":
                continue

            if operator == "^":
                major, minor, patch = core
                if major > 0:
                    upper = ((major + 1, 0, 0), None)
                elif minor > 0:
                    upper = ((0, minor + 1, 0), None)
                else:
                    upper = ((0, 0, patch + 1), None)
                if _compare_versions(candidate, target) < 0 or _compare_versions(candidate, upper) >= 0:
                    satisfied = False
                    break
                continue

            if operator == "~":
                major, minor, _ = core
                upper = ((major, minor + 1, 0), None)
                if _compare_versions(candidate, target) < 0 or _compare_versions(candidate, upper) >= 0:
                    satisfied = False
                    break
                continue

            comparison = _compare_versions(candidate, target)
            if (
                (operator == "=" and comparison != 0)
                or (operator == ">" and comparison <= 0)
                or (operator == ">=" and comparison < 0)
                or (operator == "<" and comparison >= 0)
                or (operator == "<=" and comparison > 0)
            ):
                satisfied = False
                break

        if satisfied:
            return True

    return False
