import re


def evaluate(expr: str):
    number_pattern = re.compile(r"[0-9]+(?:\.[0-9]+)?")
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "neg": 3, "^": 4}
    output = []
    operators = []
    expecting_operand = True
    position = 0

    # Convert to postfix notation, validating the entire expression first.
    while position < len(expr):
        char = expr[position]

        if char.isspace():
            position += 1
            continue

        if "0" <= char <= "9":
            if not expecting_operand:
                raise ValueError("Missing operator")
            match = number_pattern.match(expr, position)
            literal = match.group()
            output.append(float(literal) if "." in literal else int(literal))
            position = match.end()
            expecting_operand = False
            continue

        if char == "(":
            if not expecting_operand:
                raise ValueError("Implicit multiplication is not allowed")
            operators.append(char)

        elif char == ")":
            if expecting_operand:
                raise ValueError("Missing operand")
            while operators and operators[-1] != "(":
                output.append(operators.pop())
            if not operators:
                raise ValueError("Unbalanced parentheses")
            operators.pop()

        elif char in "+-*/^":
            if expecting_operand:
                if char != "-":
                    raise ValueError("Missing operand")
                # Prefix minus must not reduce a preceding exponentiation.
                operators.append("neg")
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] < precedence[char]:
                        break
                    if precedence[top] == precedence[char] and char == "^":
                        break
                    output.append(operators.pop())
                operators.append(char)
                expecting_operand = True

        else:
            raise ValueError("Unknown character: {!r}".format(char))

        position += 1

    if expecting_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        operator = operators.pop()
        if operator == "(":
            raise ValueError("Unbalanced parentheses")
        output.append(operator)

    values = []
    for token in output:
        if not isinstance(token, str):
            values.append(token)
            continue

        if token == "neg":
            values.append(-values.pop())
            continue

        right = values.pop()
        left = values.pop()

        try:
            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:
                result = left ** right
        except ZeroDivisionError as exc:
            raise ValueError("Division by zero") from exc

        values.append(result)

    return values[0]
