def first_bracket_error(s: str) -> int:
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []  # indices of currently unclosed opening brackets
    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append(i)
        elif ch in pairs:
            # Closing bracket: must match the most recent unclosed opener.
            if not stack or s[stack[-1]] != pairs[ch]:
                return i
            stack.pop()
    # No closing-bracket error found; report leftmost unclosed opener if any.
    return stack[0] if stack else -1
