**Requirements**
- 5 fields (minute 0–59, hour 0–23, dom 1–31, month 1–12, dow 0–6); exactly 5 or `ValueError`; 7 rejected for dow.
- Items: `*`, `n`, `a-b` (a≤b), each with optional `/step` (step ≥ 1). `*/n` starts at field min; `a/n` starts at `a` and runs to field max; `a-b/n` steps within the range.
- Out-of-range value, malformed item, empty item, bad step → `ValueError`.
- Day rule: restricted = raw field != `*`. Both restricted → OR; one restricted → it alone; neither → always.
- `after` = `YYYY-MM-DD HH:MM`, return earliest matching time strictly later, same format; nothing within 5 years → `ValueError`.

**Edge cases handled**
- `*/n` vs `a/n` (different start/end semantics), step > range (single value), leading zeros, non-ASCII digits, `+/-` signs rejected.
- Empty field, empty item (`1,,2`), `""`, trailing `/`, double `/`, `1-2-3`, `a>b`, out-of-range, 4 or 6 fields.
- `after` exactly on a firing minute (must move forward), month/day combinations that never exist (`0 0 31 2 *`, `0 0 30 2 *`), Feb 29 spacing, 5-year boundary via calendar-year addition (Feb 29 → Feb 28).
- Search day-by-day (≤ ~1830 iterations) with ascending hour/minute scan, so the first candidate ≥ `start` is the answer; exceeding the limit raises immediately.

```python
"""Find the next time a 5-field cron expression fires."""

from datetime import datetime, timedelta

__all__ = ["next_cron"]

# (name, min, max) for minute, hour, day-of-month, month, day-of-week
_FIELD_SPECS = (
    ("minute", 0, 59),
    ("hour", 0, 23),
    ("day of month", 1, 31),
    ("month", 1, 12),
    ("day of week", 0, 6),
)

_MAX_YEARS = 5


def _to_int(text, name):
    """Strict non-empty ASCII-digit integer, otherwise ValueError."""
    if not (text.isascii() and text.isdigit()):
        raise ValueError("invalid value %r in %s field" % (text, name))
    return int(text)


def _parse_field(raw, name, lo, hi):
    """Expand one cron field into the set of matching values."""
    values = set()
    for item in raw.split(","):
        if not item:
            raise ValueError("empty item in %s field" % name)

        base = item
        step = 1
        has_step = "/" in item
        if has_step:
            pieces = item.split("/")
            if len(pieces) != 2 or not pieces[0]:
                raise ValueError("malformed item %r in %s field" % (item, name))
            base = pieces[0]
            step = _to_int(pieces[1], name)
            if step < 1:
                raise ValueError("step must be >= 1 in %s field" % name)

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            pieces = base.split("-")
            if len(pieces) != 2:
                raise ValueError("malformed item %r in %s field" % (item, name))
            start = _to_int(pieces[0], name)
            end = _to_int(pieces[1], name)
            if start > end:
                raise ValueError("range start > end in %s field: %r" % (name, item))
        else:
            start = _to_int(base, name)
            end = hi if has_step else start

        if start < lo or end > hi:
            raise ValueError("value out of range in %s field: %r" % (name, item))

        values.update(range(start, end + 1, step))

    return values


def _cron_dow(day):
    """Cron day-of-week: 0 = Sunday .. 6 = Saturday."""
    return (day.weekday() + 1) % 7


def _day_matches(day, doms, dows, dom_restricted, dow_restricted):
    if dom_restricted and dow_restricted:
        return day.day in doms or _cron_dow(day) in dows
    if dom_restricted:
        return day.day in doms
    if dow_restricted:
        return _cron_dow(day) in dows
    return True


def _add_years(dt, years):
    try:
        return dt.replace(year=dt.year + years)
    except ValueError:  # Feb 29 with a non-leap target year
        return dt.replace(year=dt.year + years, day=28)


def _format(dt):
    return "%04d-%02d-%02d %02d:%02d" % (dt.year, dt.month, dt.day, dt.hour, dt.minute)


def next_cron(expr, after):
    if not isinstance(expr, str):
        raise ValueError("cron expression must be a string")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(
            "cron expression must have exactly 5 fields, got %d" % len(fields)
        )

    parsed = [
        _parse_field(raw, name, lo, hi)
        for raw, (name, lo, hi) in zip(fields, _FIELD_SPECS)
    ]
    minutes, hours, doms, months, dows = parsed
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    if not isinstance(after, str):
        raise ValueError("'after' must be a string formatted 'YYYY-MM-DD HH:MM'")
    try:
        start_after = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError:
        raise ValueError("'after' must be formatted 'YYYY-MM-DD HH:MM'") from None

    minutes_sorted = sorted(minutes)
    hours_sorted = sorted(hours)

    start = start_after + timedelta(minutes=1)  # strictly later, minute granularity
    limit = _add_years(start_after, _MAX_YEARS)
    end_day = limit.date()

    day = start.date()
    while day <= end_day:
        if day.month in months and _day_matches(
            day, doms, dows, dom_restricted, dow_restricted
        ):
            for hour in hours_sorted:
                for minute in minutes_sorted:
                    cand = datetime(day.year, day.month, day.day, hour, minute)
                    if cand < start:
                        continue
                    if cand > limit:
                        raise ValueError(
                            "no matching time within %d years" % _MAX_YEARS
                        )
                    return _format(cand)
        day += timedelta(days=1)

    raise ValueError("no matching time within %d years" % _MAX_YEARS)
