import re


_VERSION_RE = re.compile(r"([0-9]+(?:\.[0-9]+)*)(?:-([A-Za-z0-9]+))?")


def compare_versions(a: str, b: str) -> int:
    def parse(version: str) -> tuple[list[int], str | None]:
        match = _VERSION_RE.fullmatch(version)
        if match is None:
            raise ValueError(f"Invalid version: {version!r}")
        numbers = [int(part) for part in match.group(1).split(".")]
        return numbers, match.group(2)

    a_numbers, a_tag = parse(a)
    b_numbers, b_tag = parse(b)

    for index in range(max(len(a_numbers), len(b_numbers))):
        a_part = a_numbers[index] if index < len(a_numbers) else 0
        b_part = b_numbers[index] if index < len(b_numbers) else 0
        if a_part != b_part:
            return 1 if a_part > b_part else -1

    if a_tag is None:
        return 0 if b_tag is None else 1
    if b_tag is None:
        return -1
    return (a_tag > b_tag) - (a_tag < b_tag)
