from datetime import date, timedelta


def next_weekday(date_str: str, weekday: int) -> str:
    """Return the first date strictly after ``date_str`` that falls on ``weekday``.

    Args:
        date_str: A valid date in ``YYYY-MM-DD`` format.
        weekday: 0 for Monday through 6 for Sunday.

    Returns:
        The next matching date as a ``YYYY-MM-DD`` string. If ``date_str``
        itself falls on ``weekday``, the date 7 days later is returned.

    Raises:
        ValueError: If ``weekday`` is not in the range 0 through 6.
    """
    if not 0 <= weekday <= 6:
        raise ValueError(
            f"weekday must be in the range 0 (Monday) to 6 (Sunday), got {weekday!r}"
        )
    current = date.fromisoformat(date_str)
    days_ahead = (weekday - current.weekday()) % 7
    if days_ahead == 0:
        # Same weekday: "strictly after" means exactly one week later.
        days_ahead = 7
    return (current + timedelta(days=days_ahead)).isoformat()
