from typing import Optional


def earliest_slot(
    busy: list[tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest free slot's start, or None if no slot fits."""
    if (
        not isinstance(duration, int)
        or isinstance(duration, bool)
        or duration <= 0
    ):
        raise ValueError("duration must be a positive integer")

    # Validate every interval, even when the window cannot fit a meeting.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    latest_start = end - duration
    candidate = start
    if candidate > latest_start:
        return None

    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        if candidate + duration <= begin:
            return candidate

        candidate = finish
        if candidate > latest_start:
            return None

    return candidate
