def _parse_field(text, low, high):
    """Expand one cron field into the set of values it matches."""
    if not text:
        raise ValueError("empty cron field")
    values = set()
    for item in text.split(","):
        if not item:
            raise ValueError("empty item in field {!r}".format(text))

        base, slash, step_text = item.partition("/")
        if slash:
            if "/" in step_text or not step_text.isdigit():
                raise ValueError("invalid step in item {!r}".format(item))
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be >= 1 in item {!r}".format(item))
        else:
            step = 1

        if base == "*":
            start, stop = low, high
        elif "-" in base:
            first, _, last = base.partition("-")
            if not first.isdigit() or not last.isdigit():
                raise ValueError("invalid range in item {!r}".format(item))
            start, stop = int(first), int(last)
            if start > stop:
                raise ValueError("reversed range in item {!r}".format(item))
            if start < low or stop > high:
                raise ValueError("range out of bounds in item {!r}".format(item))
        elif base.isdigit():
            start = int(base)
            if start < low or start > high:
                raise ValueError("value out of bounds in item {!r}".format(item))
            if not slash:
                values.add(start)
                continue
            stop = high  # "a/n": from a up to the field's maximum
        else:
            raise ValueError("invalid item {!r}".format(item))

        values.update(range(start, stop + 1, step))

    return values


def _day_matches(day, days_of_month, days_of_week, dom_restricted, dow_restricted):
    dom_ok = day.day in days_of_month
    dow_ok = ((day.weekday() + 1) % 7) in days_of_week  # cron: 0 = Sunday
    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    if dom_restricted:
        return dom_ok
    if dow_restricted:
        return dow_ok
    return True


def next_cron(expr: str, after: str) -> str:
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected exactly 5 fields, got {}".format(len(fields)))

    minutes = _parse_field(fields[0], *_BOUNDS[0])
    hours = _parse_field(fields[1], *_BOUNDS[1])
    days_of_month = _parse_field(fields[2], *_BOUNDS[2])
    months = _parse_field(fields[3], *_BOUNDS[3])
    days_of_week = _parse_field(fields[4], *_BOUNDS[4])

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    match = _AFTER_RE.fullmatch(after)
    if match is None:
        raise ValueError("invalid 'after' timestamp {!r}".format(after))
    try:
        start = datetime(*(int(group) for group in match.groups()))
    except ValueError:
        raise ValueError("invalid 'after' timestamp {!r}".format(after))

    try:
        candidate = start + timedelta(minutes=1)  # strictly later
    except (ValueError, OverflowError):
        raise ValueError("no matching time within 5 years of {!r}".format(after))

    try:
        limit = start.replace(year=start.year + 5)
    except ValueError:
        try:
            limit = start.replace(year=start.year + 5, day=28)  # Feb 29 -> Feb 28
        except ValueError:
            limit = datetime.max  # +5 years is unrepresentable

    by_hour = sorted(hours)
    by_minute = sorted(minutes)
    day = candidate.date()
    last_day = limit.date()

    while True:
        if day.month in months and _day_matches(
            day, days_of_month, days_of_week, dom_restricted, dow_restricted
        ):
            for hour in by_hour:
                for minute in by_minute:
                    moment = datetime(day.year, day.month, day.day, hour, minute)
                    if moment < candidate:
                        continue
                    if moment > limit:
                        raise ValueError(
                            "no matching time within 5 years of {!r}".format(after)
                        )
                    return "{:04d}-{:02d}-{:02d} {:02d}:{:02d}".format(
                        moment.year, moment.month, moment.day,
                        moment.hour, moment.minute,
                    )
        if day >= last_day:
            break
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years of {!r}".format(after))
