            if current is not None:
                words.append(current)
                current = None
            i += 1
        elif c == "'":
            if current is None:
                current = ''
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated single quote")
                if s[i] == "'":
                    i += 1
                    break
                current += s[i]
                i += 1
        elif c == '"':
            if current is None:
                current = ''
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                ch = s[i]
                if ch == '\\':
                    if i + 1 >= n:
                        raise ValueError("unterminated double quote")
                    nxt = s[i + 1]
                    if nxt == '"':
                        current += '"'
                    elif nxt == '\\':
                        current += '\\'
                    else:
                        current += '\\'
                        current += nxt
                    i += 2
                elif ch == '"':
                    i += 1
                    break
                else:
                    current += ch
                    i += 1
        elif c == '\\':
            if i + 1 >= n:
