from decimal import Decimal, ROUND_HALF_UP


def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be non-negative")
    if n < 1024:
        return f"{n} B"

    units = ("KiB", "MiB", "GiB", "TiB")
    divisor = 1024

    for index, unit in enumerate(units):
        if index < len(units) - 1 and n >= divisor * 1024:
            divisor *= 1024
            continue

        value = (Decimal(n) / Decimal(divisor)).quantize(
            Decimal("0.1"), rounding=ROUND_HALF_UP
        )
        if value == Decimal("1024.0") and index < len(units) - 1:
            divisor *= 1024
            return f"1.0 {units[index + 1]}"
        return f"{value:.1f} {unit}"

    return f"{(Decimal(n) / Decimal(divisor)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP):.1f} TiB"
