    Grammar (recursive descent):
        expr    := term (('+' | '-') term)*          # left-associative
        term    := unary (('*' | '/') unary)*        # left-associative
        unary   := '-' unary | power                 # unary minus
        power   := primary ('^' unary)?              # right-associative
        primary := NUMBER | '(' expr ')'
    """
    digits = "0123456789"

    # --- Tokenizer ---
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in digits:
            start = i
            while i < n and expr[i] in digits:
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                if i >= n or expr[i] not in digits:
                    raise ValueError("malformed number literal")
                while i < n and expr[i] in digits:
                    i += 1
                tokens.append(("num", float(expr[start:i])))
            else:
                tokens.append(("num", int(expr[start:i])))
        elif c in "+-*/^()":
            tokens.append((c, None))
            i += 1
        else:
            raise ValueError("unexpected character %r" % (c,))

    if not tokens:
        raise ValueError("empty expression")

    # --- Parser ---
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expr():
        value = parse_term()
        while True:
            token = peek()
            if token is not None and token[0] in ("+", "-"):
                advance()
                rhs = parse_term()
                value = value + rhs if token[0] == "+" else value - rhs
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            token = peek()
            if token is not None and token[0] in ("*", "/"):
                advance()
                rhs = parse_unary()
                value = value * rhs if token[0] == "*" else value / rhs
            else:
                return value

    def parse_unary():
        token = peek()
        if token is not None and token[0] == "-":
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_primary()
        token = peek()
        if token is not None and token[0] == "^":
            advance()
            # Right-associative; the exponent may carry a unary minus,
            # but a leading '-' binds to the whole power on its left.
            exponent = parse_unary()
            return base ** exponent
        return base

    def parse_primary():
        token = peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        kind = token[0]
        if kind == "num":
            advance()
            return token[1]
        if kind == "(":
            advance()
            value = parse_expr()
            closing = peek()
            if closing is None or closing[0] != ")":
                raise ValueError("missing closing parenthesis")
            advance()
            return value
        raise ValueError("expected a number or '('")

    try:
        result = parse_expr()
    except ZeroDivisionError:
        raise ValueError("division by zero") from None

    if pos != len(tokens):
        raise ValueError("unexpected trailing tokens")

    return result
