    rest = remainder[authority_end:]
    if not authority:
        raise ValueError("Authority must not be empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    if host_port.startswith("["):
        closing_bracket = host_port.find("]")
        if closing_bracket == -1:
            raise ValueError("Unclosed IPv6 literal")

        literal = host_port[1:closing_bracket]
        try:
            ipaddress.IPv6Address(literal)
        except ipaddress.AddressValueError as exc:
            raise ValueError("Invalid IPv6 literal") from exc

        host = literal.lower()
        suffix = host_port[closing_bracket + 1:]
        if suffix and not suffix.startswith(":"):
            raise ValueError("Invalid text after IPv6 literal")
        port_text = suffix[1:] if suffix else None
    else:
        colon = host_port.find(":")
        if colon == -1:
            host, port_text = host_port, None
        else:
            host, port_text = host_port[:colon], host_port[colon + 1:]

        if not host or any(
            char in " /?#@:[ ]" or char == "]" for char in host
        ):
            raise ValueError("Invalid host")
        host = host.lower()

    if port_text is None:
        port = None
    else:
        if not re.fullmatch(r"[0-9]{1,5}", port_text):
            raise ValueError("Invalid port")
        port = int(port_text)
        if not 1 <= port <= 65535:
            raise ValueError("Port out of range")

    fragment = ""
    if "#" in rest:
        rest, fragment = rest.split("#", 1)

    query = ""
    if "?" in rest:
        path, query = rest.split("?", 1)
    else:
        path = rest

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
