def rle_decode(s: str) -> str:
    """Decode count-character groups, rejecting invalid input or output over 10000 chars."""
    result = []
    total_length = 0
    i = 0

    while i < len(s):
        count_start = i
        count = 0

        while i < len(s) and "0" <= s[i] <= "9":
            digit = ord(s[i]) - ord("0")
            if count == 0 and digit == 0:
                raise ValueError("count must be positive with no leading zeros")
            count = count * 10 + digit
            if count > 10000:
                raise ValueError("decoded output exceeds 10000 characters")
            i += 1

        if i == count_start:
            raise ValueError("missing count")
        if i == len(s):
            raise ValueError("input ends with digits")
        if "0" <= s[i] <= "9":
            raise ValueError("missing character after count")

        total_length += count
        if total_length > 10000:
            raise ValueError("decoded output exceeds 10000 characters")

        result.append(s[i] * count)
        i += 1

