        start = i
        while i < len(s) and "0" <= s[i] <= "9":
            i += 1

        if i == start or i == len(s):
            raise ValueError

        digits = s[start:i]
        if digits[0] == "0":
            raise ValueError

        count = int(digits)
        if total + count > 10000:
            raise ValueError

        parts.append(s[i] * count)
        total += count
        i += 1

    return "".join(parts)
