def parse_csv_line(line: str) -> list:
    """Split a single CSV line (no newline characters) into a list of fields.

    Raises ValueError on a quote inside an unquoted field, an unterminated
    quoted field, or any non-comma character after a closing quote.
    """
    fields = []
    n = len(line)
    i = 0

    while True:
        if i < n and line[i] == '"':
            # Quoted field: opening quote is the very first char of the field.
            i += 1
            chars = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')  # escaped quote
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    chars.append(ch)
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError(
                    "unexpected character after closing quote"
                )
            fields.append(''.join(chars))
        else:
            # Unquoted field (possibly empty, whitespace preserved).
            j = i
            while j < n and line[j] != ',':
                if line[j] == '"':
                    raise ValueError("double quote in unquoted field")
                j += 1
            fields.append(line[i:j])
            i = j

        if i >= n:
            break
        i += 1  # skip the comma and start the next field

    return fields
