def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire name matches the path-like glob pattern."""
    tokens = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash")
            tokens.append(("literal", pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                tokens.append(("globstar",))
                i += 2
            else:
                tokens.append(("star",))
                i += 1
        elif char == "?":
            tokens.append(("any",))
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            units = []
            if i < len(pattern) and pattern[i] == "]":
                units.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash")
                    units.append((pattern[i], True))
                else:
                    units.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError("unclosed character set")

            i += 1
            singles = set()
            ranges = []
            j = 0

            while j < len(units):
                if (
                    j + 2 < len(units)
                    and units[j + 1] == ("-", False)
                    and units[j][0] != "-"
                    and units[j + 2][0] != "-"
                ):
                    start = ord(units[j][0])
                    end = ord(units[j + 2][0])
                    if start > end:
                        raise ValueError("descending character range")
                    ranges.append((start, end))
                    j += 3
                else:
                    singles.add(units[j][0])
                    j += 1

            tokens.append(("set", negate, singles, ranges))
        else:
            tokens.append(("literal", char))
            i += 1

    previous = [False] * (len(name) + 1)
    previous[0] = True

    for token in tokens:
        current = [False] * (len(name) + 1)
        kind = token[0]

        if kind in ("star", "globstar"):
            current[0] = previous[0]
            for j, char in enumerate(name, 1):
                allowed = kind == "globstar" or char != "/"
                current[j] = previous[j] or (allowed and current[j - 1])
        else:
            for j, char in enumerate(name, 1):
                if not previous[j - 1]:
                    continue

                if kind == "literal":
                    current[j] = char == token[1]
                elif kind == "any":
                    current[j] = char != "/"
                else:
                    _, negate, singles, ranges = token
                    matched = char in singles or any(
                        start <= ord(char) <= end for start, end in ranges
                    )
                    current[j] = not matched if negate else matched

        previous = current

    return previous[len(name)]
