        raise ValueError("URL must be a string")

    scheme_match = re.match(r"([A-Za-z][A-Za-z0-9+.-]*)://", url)
    if scheme_match is None:
        raise ValueError("URL must start with a valid scheme followed by ://")

    scheme = scheme_match.group(1).lower()
    remainder = url[scheme_match.end():]

    authority_end = len(remainder)
    for delimiter in "/?#":
        position = remainder.find(delimiter)
        if position != -1:
            authority_end = min(authority_end, position)

    authority = remainder[:authority_end]
    rest = remainder[authority_end:]

    if not authority:
        raise ValueError("Authority must be non-empty")

    if "@" in authority:
        userinfo, host_port = authority.rsplit("@", 1)
    else:
        userinfo, host_port = "", authority

    if not host_port:
        raise ValueError("Host must be non-empty")

    port = None

    if host_port.startswith("["):
        closing = host_port.find("]")
        if closing == -1:
            raise ValueError("Unclosed IPv6 literal")

        host = host_port[1:closing]
        try:
            ipaddress.IPv6Address(host)
        except ipaddress.AddressValueError as exc:
            raise ValueError("Invalid IPv6 literal") from exc

