import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    indegree: dict[str, int] = {}
    dependents: dict[str, list[str]] = {}

    for item, dependencies in deps.items():
        indegree.setdefault(item, 0)
        for dependency in set(dependencies):
            indegree.setdefault(dependency, 0)
            indegree[item] += 1
            dependents.setdefault(dependency, []).append(item)

    ready = [item for item, count in indegree.items() if count == 0]
    heapq.heapify(ready)
    result: list[str] = []

    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents.get(item, ()):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(indegree):
        raise ValueError("Dependency graph contains a cycle")

    return result
