```python
"""Glob matching with ``*``, ``**``, ``?`` and ``[...]`` character classes.

Semantics implemented:
  *        any run of characters that contains no ``/`` (possibly empty)
  **       any run of characters, ``/`` included (possibly empty)
  ?        exactly one character that is not ``/``
  [...]    one character from a set (ranges allowed, ``!`` negates,
           a leading ``]`` is literal)
  \\x       literal ``x``
Bad patterns (trailing backslash, unterminated ``[``) raise ``ValueError``.
"""

from typing import List, Set, Tuple

__all__ = ["glob_match"]

_LITERAL = 0
_STAR = 1
_DSTAR = 2
_QMARK = 3
_CLASS = 4


def _parse_class(pattern: str, start: int) -> Tuple[Set[str], bool, int]:
    """Parse ``[...]`` starting at ``pattern[start] == '['``.

    Returns ``(chars, negated, next_index)`` where ``next_index`` points just
    past the closing ``]``.  Raises ``ValueError`` if the class is not closed.
    """
    n = len(pattern)
    i = start + 1
    negated = False
    if i < n and pattern[i] == "!":
        negated = True
        i += 1

    chars: Set[str] = set()
    first = True
    while i < n:
        c = pattern[i]
        if c == "]" and not first:
            return chars, negated, i + 1
        first = False

        if c == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with a trailing backslash")
            lo = pattern[i + 1]
            i += 2
        else:
            lo = c
            i += 1

        # A range is only a range if a '-' follows and is not the closing ']'.
        if i + 1 < n and pattern[i] == "-" and pattern[i + 1] != "]":
            j = i + 1
            if pattern[j] == "\\":
                if j + 1 >= n:
                    raise ValueError("pattern ends with a trailing backslash")
                hi = pattern[j + 1]
                j += 2
            else:
                hi = pattern[j]
                j += 1
            for code in range(ord(lo), ord(hi) + 1):
                chars.add(chr(code))
            i = j
        else:
            chars.add(lo)

    raise ValueError("unterminated character class in pattern")


def _tokenize(pattern: str) -> List[Tuple[int, object]]:
    """Split a pattern into (kind, payload) tokens, validating it as we go."""
    tokens: List[Tuple[int, object]] = []
    n = len(pattern)
    i = 0
    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with a trailing backslash")
            tokens.append((_LITERAL, pattern[i + 1]))
            i += 2
        elif c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                # A run of two or more stars is equivalent to a single "**".
                while i < n and pattern[i] == "*":
                    i += 1
                tokens.append((_DSTAR, None))
            else:
                tokens.append((_STAR, None))
                i += 1
        elif c == "?":
            tokens.append((_QMARK, None))
            i += 1
        elif c == "[":
            chars, negated, i = _parse_class(pattern, i)
            tokens.append((_CLASS, (chars, negated)))
        else:
            tokens.append((_LITERAL, c))
            i += 1
    return tokens


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of *name* matches *pattern* (case-sensitive).

    Raises ``ValueError`` if *pattern* is malformed.
    """
    # Tokenize first so that pattern errors are reported even when the match
    # would fail immediately for other reasons.
    tokens = _tokenize(pattern)

    n = len(name)

    # next_slash[p] == first index >= p holding '/', or n if there is none.
    next_slash = [n] * (n + 1)
    for idx in range(n - 1, -1, -1):
        next_slash[idx] = idx if name[idx] == "/" else next_slash[idx + 1]

    # dp[p] means: the tokens consumed so far can match name[:p].
    dp = bytearray(n + 1)
    dp[0] = 1

    for kind, payload in tokens:
        ndp = bytearray(n + 1)

        if kind == _LITERAL:
            ch = payload
            for p in range(n):
                if dp[p] and name[p] == ch:
                    ndp[p + 1] = 1

        elif kind == _QMARK:
            for p in range(n):
                if dp[p] and name[p] != "/":
                    ndp[p + 1] = 1

        elif kind == _CLASS:
            chars, negated = payload  # type: ignore[misc]
            for p in range(n):
                if dp[p]:
                    hit = name[p] in chars  # type: ignore[operator]
                    if hit != negated:
                        ndp[p + 1] = 1

        elif kind == _STAR:
            # From p a '*' reaches every q in [p, next_slash[p]].
            diff = [0] * (n + 2)
            any_reach = False
            for p in range(n + 1):
                if dp[p]:
                    any_reach = True
                    diff[p] += 1
                    diff[next_slash[p] + 1] -= 1
            if not any_reach:
                return False
            run = 0
            for q in range(n + 1):
                run += diff[q]
                if run > 0:
                    ndp[q] = 1

        else:  # _DSTAR -- reaches every q >= p, slashes included.
            acc = False
            for q in range(n + 1):
                if dp[q]:
                    acc = True
                if acc:
                    ndp[q] = 1

        dp = ndp

    return bool(dp[n])
