def wrap_text(text: str, width: int) -> list[str]:
    """Wrap text into lines of at most `width` characters, greedily.

    Words are runs of characters separated by one or more U+0020 spaces.
    Words longer than `width` are split into chunks of exactly `width`
    characters (each chunk on its own full line); their final, possibly
    shorter chunk starts a line that may be continued by following words.

    Raises ValueError if width < 1.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current: str = ""

    for word in text.split(" "):
        if not word:
            continue  # ignore runs of spaces / empty tokens

        if len(word) > width:
            # A too-long word always starts on a fresh line.
            if current:
                lines.append(current)
                current = ""
            n_full = len(word) // width
            for i in range(n_full):
                lines.append(word[i * width:(i + 1) * width])
            # Remaining (possibly empty) piece starts a new line that
            # following words may join if they fit.
            current = word[n_full * width:]
        else:
            if current and len(current) + 1 + len(word) <= width:
                current = current + " " + word
            else:
                if current:
                    lines.append(current)
                current = word

    if current:
        lines.append(current)

    return lines
