import re

# Canonical Roman numerals from 1 to 3999:
# thousands: M{0,3}
# hundreds:  CM | CD | D?C{0,3}
# tens:      XC | XL | L?X{0,3}
# units:     IX | IV | V?I{0,3}
_ROMAN_RE = re.compile(
    r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"
)

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1-3999) to an integer.

    Raises ValueError for anything that is not such a numeral, including
    the empty string, lowercase letters, and non-canonical forms such as
    "IIII", "IC", "VX", "IIV", "XXXX" or "MMMM".
    """
    if not isinstance(s, str) or not s or _ROMAN_RE.fullmatch(s) is None:
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    prev = 0
    for ch in reversed(s):
        value = _VALUES[ch]
        if value < prev:
            total -= value
        else:
            total += value
            prev = value
    return total
