from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    # Validate duration: must be a positive integer (reject bool-adjacent weirdness is left
    # alone since bool is an int subclass; floats/strings/etc. are rejected).
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate all busy intervals and clip the ones that overlap [start, end).
    clipped: List[Tuple[int, int]] = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("each busy interval must satisfy begin < finish")
        # Anything fully outside the window cannot affect a meeting inside it.
        if finish <= start or begin >= end:
            continue
        clipped.append((max(begin, start), min(finish, end)))

    # Earliest feasible t is either `start` or the right edge of some blocked block,
    # so scanning the (merged) blocked blocks in order is enough.
    clipped.sort()

    cursor = start
    for begin, finish in clipped:
        if cursor + duration <= begin:
            # Whole meeting fits in the gap before this block.
            return cursor
        if finish > cursor:
            cursor = finish

    if cursor + duration <= end:
        return cursor
    return None
