def is_valid_ipv4(s: str) -> bool:
    """Return True iff s is a valid dotted-quad IPv4 address.

    Rules:
      - exactly four "."-separated parts
      - each part is 1-3 ASCII digits (0-9) only; other Unicode digits are invalid
      - numeric value 0-255
      - no leading zeros unless the part is exactly "0"
      - no other characters anywhere (no signs, whitespace, newline, etc.)
    Never raises for any string input.
    """
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        # Length 1-3, and every character must be an ASCII digit 0-9.
        # This rejects empty parts, signs, whitespace, and Unicode digits.
        if not 1 <= len(part) <= 3:
            return False
        if any(ch not in "0123456789" for ch in part):
            return False
        # No leading zeros unless the part is exactly "0".
        if len(part) > 1 and part[0] == "0":
            return False
        # Now safe to convert: 1-3 ASCII digits, so int() cannot fail.
        if int(part) > 255:
            return False

    return True
