import re

__all__ = ["round_half_up"]

_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def _increment(digits: str) -> str:
    """Add one to a non-empty string of ASCII digits."""
    out = list(digits)
    i = len(out) - 1
    while i >= 0:
        if out[i] != "9":
            out[i] = chr(ord(out[i]) + 1)
            return "".join(out)
        out[i] = "0"
        i -= 1
    return "1" + "".join(out)


def round_half_up(x: str, ndigits: int) -> str:
    """Exact decimal rounding, ties away from zero, ndigits places.

    x must look like -?\\d+(\\.\\d+)? (no sign but "-", no exponents, at least
    one digit on each side of the point).
    """
    if isinstance(ndigits, bool) or not isinstance(ndigits, int):
        raise ValueError("ndigits must be a non-negative int")
    if ndigits < 0:
        raise ValueError("ndigits must be non-negative")
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError("x must be a decimal literal such as '-12.34'")

    negative = x[0] == "-"
    body = x[1:] if negative else x
    int_part, _, frac_part = body.partition(".")

    if ndigits >= len(frac_part):
        # Nothing to round off: pad with zeros.
        int_out = int_part.lstrip("0") or "0"
        frac_out = frac_part.ljust(ndigits, "0")
    else:
        # Keep the integer part plus the first `ndigits` fractional digits,
        # then round using the first dropped digit (decimal, not binary).
        kept = int_part + frac_part[:ndigits]
        if frac_part[ndigits] >= "5":
            kept = _increment(kept)
        if ndigits:
            kept = kept.rjust(ndigits + 1, "0")
            int_out, frac_out = kept[:-ndigits], kept[-ndigits:]
        else:
            int_out, frac_out = kept, ""
        int_out = int_out.lstrip("0") or "0"

    # Never emit a negative zero.
    if int_out == "0" and not frac_out.strip("0"):
        negative = False

    return ("-" if negative else "") + int_out + ("." + frac_out if ndigits else "")
