import re


def round_half_up(x: str, ndigits: int) -> str:
    if not isinstance(x, str) or re.fullmatch(r"-?[0-9]+(?:\.[0-9]+)?", x) is None:
        raise ValueError("x must be a decimal number in the specified format")
    if not isinstance(ndigits, int) or isinstance(ndigits, bool) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")

    negative = x.startswith("-")
    value = x[1:] if negative else x
    integer_part, dot, fractional_part = value.partition(".")
    fractional_part = fractional_part if dot else ""

    kept = fractional_part[:ndigits].ljust(ndigits, "0")
    discarded = fractional_part[ndigits:]
    magnitude = integer_part + kept

    if discarded and discarded[0] >= "5":
        digits = list(magnitude)
        carry = 1
        for i in range(len(digits) - 1, -1, -1):
            if digits[i] == ".":
                continue
            if digits[i] == "9":
                digits[i] = "0"
            else:
                digits[i] = chr(ord(digits[i]) + 1)
                carry = 0
                break
        if carry:
            digits.insert(0, "1")
        magnitude = "".join(digits)

    if ndigits:
        magnitude = magnitude[:-ndigits] + "." + magnitude[-ndigits:]

    if negative and any(char in "123456789" for char in magnitude):
        return "-" + magnitude
    return magnitude
