import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """Order items so that every item comes after all of its dependencies.

    Deterministic: built step by step, and whenever more than one item has
    all of its dependencies already placed, the lexicographically smallest
    one (plain string comparison) is placed first.

    Every item mentioned anywhere (as a key or inside a dependency list)
    appears exactly once.  Duplicate entries in dependency lists are ignored.
    Raises ValueError on a self-dependency or any cycle.  The input dict and
    its lists are never modified.
    """
    # Collect every item mentioned anywhere; items that never appear as a
    # key simply have no dependencies of their own.
    nodes = set(deps)
    for requirements in deps.values():
        nodes.update(requirements)

    # pending[item]: number of distinct unplaced dependencies of item.
    # dependents[dep]: items that are waiting on dep.
    pending = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}
    for item, requirements in deps.items():
        seen = set()
        for dep in requirements:
            if dep not in seen:
                seen.add(dep)
                pending[item] += 1
                dependents[dep].append(item)

    ready = [node for node in nodes if pending[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")
    return order
