def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    stack = []
    for part in p.split("/"):
        # Ignore empty components (from repeated or leading/trailing slashes) and "."
        if part == "" or part == ".":
            continue
        if part == "..":
            if absolute:
                # ".." at the root of an absolute path is ignored
                if stack:
                    stack.pop()
            else:
                # Relative: pop a resolvable previous component; otherwise the
                # ".." cannot be resolved and is kept as a leading component.
                # (A kept ".." can never be removed by another "..".)
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    stack.append("..")
        else:
            # Any other name, including "...", is an ordinary component
            stack.append(part)
    if absolute:
        # Prepending "/" handles both the root ("/") and non-root results
        # ("/a/b") with no trailing slash.
        return "/" + "/".join(stack)
    # Empty relative result (including empty input) is "."
    return "/".join(stack) if stack else "."
