_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def _increment(digits: str) -> str:
    """Add 1 to a non-empty string of ASCII digits (preserving width, adding a carry digit if needed)."""
    buf = list(digits)
    i = len(buf) - 1
    while i >= 0 and buf[i] == "9":
        buf[i] = "0"
        i -= 1
    if i < 0:
        buf.insert(0, "1")
    else:
        buf[i] = chr(ord(buf[i]) + 1)
    return "".join(buf)


def round_half_up(x: str, ndigits: int) -> str:
    """Round the decimal string `x` to `ndigits` places, ties away from zero.

    Exact decimal arithmetic (pure string manipulation, no float involvement).
    """
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError(
            "x must be a decimal string matching -?[0-9]+(\\.[0-9]+)?, got %r" % (x,)
        )
    if isinstance(ndigits, bool) or not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer, got %r" % (ndigits,))

    negative = x[0] == "-"
    body = x[1:] if negative else x

    if "." in body:
        int_part, frac_part = body.split(".")
    else:
        int_part, frac_part = body, ""

    if ndigits >= len(frac_part):
        # Nothing to drop: pad with zeros, no rounding needed.
        digits = int_part + frac_part + "0" * (ndigits - len(frac_part))
    else:
        digits = int_part + frac_part[:ndigits]
        # Round half away from zero: only the first dropped digit matters,
        # since it being >= 5 means the remainder is >= exactly one half.
        if frac_part[ndigits] >= "5":
            digits = _increment(digits)

    if ndigits:
        out_int, out_frac = digits[:-ndigits], digits[-ndigits:]
    else:
        out_int, out_frac = digits, ""

    if not out_int:
        out_int = "0"

    # Never emit a negative zero.
    if not out_int.strip("0") and not out_frac.strip("0"):
        negative = False

    sign = "-" if negative else ""
    return sign + out_int + ("." + out_frac if ndigits else "")
