import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire name matches the path-like glob pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(r"[\s\S]*")
                i += 2
            else:
                regex.append(r"[^/]*")
                i += 1
        elif char == "?":
            regex.append(r"[^/]")
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            # A closing bracket is literal when it is the first set member.
            members = []
            if i < len(pattern) and pattern[i] == "]":
                members.append(("]", True))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in character set")
                    members.append((pattern[i], True))
                    i += 1
                else:
                    members.append((pattern[i], False))
                    i += 1

            if i == len(pattern):
                raise ValueError("unclosed character set")
            if not members:
                raise ValueError("empty character set")

            parts = []
            j = 0
            while j < len(members):
                if (
                    j + 2 < len(members)
                    and members[j + 1] == ("-", False)
                ):
                    start, end = members[j][0], members[j + 2][0]
                    if ord(start) > ord(end):
                        raise ValueError("reversed character range")
                    parts.append(re.escape(start) + "-" + re.escape(end))
                    j += 3
                else:
                    parts.append(re.escape(members[j][0]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    return re.fullmatch(r"\A" + "".join(regex) + r"\Z", name) is not None
