def flatten(nested, depth=None):
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative")

    result = []
    stack = [(iter(reversed(nested)), depth)]

    while stack:
        items, remaining = stack[-1]
        try:
            item = next(items)
        except StopIteration:
            stack.pop()
            continue

        if type(item) is list and (remaining is None or remaining > 0):
            stack.append(
                (iter(reversed(item)), None if remaining is None else remaining - 1)
            )
        else:
            result.append(item)

