    if len(frac_part) <= ndigits:
        digits = int_part + frac_part + '0' * (ndigits - len(frac_part))
    else:
        digits = int_part + frac_part[:ndigits]
        if frac_part[ndigits] >= '5':          # first dropped digit -> half-away-from-zero
            digits = _increment(digits)

    if ndigits:
        result = digits[:-ndigits] + '.' + digits[-ndigits:]
    else:
        result = digits

    if negative and result.replace('.', '').strip('0'):
        result = '-' + result
