def rle_decode(s: str) -> str:
    if not isinstance(s, str):
        raise TypeError("s must be a string")

    parts = []
    total_length = 0
    i = 0
    n = len(s)

    while i < n:
        count_start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if i == count_start or i == n:
            raise ValueError("invalid encoding")

        count_text = s[count_start:i]
        if count_text[0] == "0":
            raise ValueError("count must be positive with no leading zeros")

        count = int(count_text)
        total_length += count
        if total_length > 10000:
            raise ValueError("decoded output exceeds 10000 characters")

        char = s[i]
        if "0" <= char <= "9":
            raise ValueError("invalid encoding")

        parts.append(char * count)
        i += 1

    return "".join(parts)
