def parse_csv_line(line: str) -> list:
    """Split a single CSV line (no newline chars) into a list of strings.

    Raises ValueError for a quote inside an unquoted field, an unterminated
    quoted field, or any non-comma character following a closing quote.
    """
    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # Quoted field: opening quote must be the first char of the field.
            i += 1
            buf = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')  # escaped quote
                        i += 2
                    else:
                        i += 1  # closing quote
                        closed = True
                        break
                else:
                    buf.append(c)
                    i += 1
            if not closed:
                raise ValueError("unterminated quoted field")
            if i < n:
                if line[i] != ',':
                    raise ValueError(
                        "unexpected character after closing quote"
                    )
                i += 1  # consume separator, parse next field
                fields.append(''.join(buf))
                continue
            fields.append(''.join(buf))
            return fields
        else:
            # Unquoted field: literal, may be empty, no quotes allowed.
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("double quote in unquoted field")
                i += 1
            fields.append(line[start:i])
            if i >= n:
                return fields
            i += 1  # consume separator, parse next field
