import re

# A number token: ASCII digits, optionally followed by a dot and more ASCII digits.
# Punctuation tokens are the five operators and the two parentheses.
_TOKEN_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?|[-+*/^()]")
_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")


def _tokenize(text):
    """Split the source into a list of token strings, skipping whitespace."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        m = _TOKEN_RE.match(text, i)
        if m is None:
            raise ValueError("invalid character %r at position %d" % (ch, i))
        tokens.append(m.group(0))
        i = m.end()
    return tokens


class _Parser(object):
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def advance(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        self.pos += 1
        return tok

    def parse(self):
        value = self.parse_expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos],))
        return value

    # expr := term (('+' | '-') term)*
    def parse_expr(self):
        value = self.parse_term()
        while True:
            tok = self.peek()
            if tok == "+":
                self.advance()
                value = value + self.parse_term()
            elif tok == "-":
                self.advance()
                value = value - self.parse_term()
            else:
                return value

    # term := unary (('*' | '/') unary)*
    def parse_term(self):
        value = self.parse_unary()
        while True:
            tok = self.peek()
            if tok == "*":
                self.advance()
                value = value * self.parse_unary()
            elif tok == "/":
                self.advance()
                divisor = self.parse_unary()
                if divisor == 0:
                    raise ValueError("division by zero")
                value = value / divisor
            else:
                return value

    # unary := '-' unary | power      (binds less tightly than '^')
    def parse_unary(self):
        if self.peek() == "-":
            self.advance()
            return -self.parse_unary()
        return self.parse_power()

    # power := atom ('^' unary)?       (right-associative; exponent may be unary)
    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == "^":
            self.advance()
            exponent = self.parse_unary()
            return base ** exponent
        return base

    def parse_atom(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("unexpected end of input")
        if tok == "(":
            self.advance()
            value = self.parse_expr()
            if self.peek() != ")":
                raise ValueError("expected ')'")
            self.advance()
            return value
        if _NUMBER_RE.fullmatch(tok):
            self.advance()
            if "." in tok:
                return float(tok)
            return int(tok)
        raise ValueError("unexpected token %r" % (tok,))


def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return an int or float."""
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()
