from datetime import date


def _parse(s: str) -> date:
    """Return the date for an exact 'YYYY-MM-DD' ASCII string, else ValueError."""
    if len(s) != 10:
        raise ValueError(f"not a YYYY-MM-DD string: {s!r}")
    if s[4] != "-" or s[7] != "-":
        raise ValueError(f"not a YYYY-MM-DD string: {s!r}")
    digits = s[0:4] + s[5:7] + s[8:10]
    if not all("0" <= ch <= "9" for ch in digits):
        raise ValueError(f"not a YYYY-MM-DD string: {s!r}")
    year, month, day = int(s[0:4]), int(s[5:7]), int(s[8:10])
    # date() itself rejects impossible combinations (month 0/13, Feb 30,
    # year 0, ...) with ValueError.
    return date(year, month, day)


def days_between(a: str, b: str) -> int:
    return abs((_parse(a) - _parse(b)).days)
