_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+.\-]*)://")
# 1-5 ASCII digits (explicit [0-9] so non-ASCII digits never match)
_PORT_RE = re.compile(r"[0-9]{1,5}")

_AUTHORITY_TERMINATORS = "/?#"
# characters that may not appear in a plain (non-bracketed) host
_HOST_TERMINATORS = frozenset(" /?#@:[]")


