def _int_to_roman(n: int) -> str:
    """Canonical Roman numeral for 1 <= n <= 3999."""
    table = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )
    out = []
    for value, symbol in table:
        count, n = divmod(n, value)
        if count:
            out.append(symbol * count)
    return "".join(out)


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1..3999) to an int.

    Raises ValueError for the empty string, non-strings, lowercase or other
    unknown characters, out-of-range values, and non-canonical forms such as
    "IIII", "IC", "VX", "IIV", "XXXX" or "MMMM".
    """
    if not isinstance(s, str) or not s:
        raise ValueError("input must be a non-empty string")

    values = {
        "I": 1, "V": 5, "X": 10, "L": 50,
        "C": 100, "D": 500, "M": 1000,
    }

    total = 0
    n = len(s)
    for i, ch in enumerate(s):
        if ch not in values:
            raise ValueError("invalid character in Roman numeral: %r" % (ch,))
        v = values[ch]
        if i + 1 < n and values[s[i + 1]] > v:
            total -= v
        else:
            total += v

    if not 1 <= total <= 3999:
        raise ValueError("value out of range: %d" % (total,))

    # The canonical spelling for a value is unique, so re-encoding the parsed
    # value and comparing rejects every non-canonical arrangement.
    if _int_to_roman(total) != s:
        raise ValueError("non-canonical Roman numeral: %r" % (s,))

    return total
