def normalize_path(p: str) -> str:
    """Normalize a Unix-style path (lexically, no filesystem access)."""
    is_absolute = p.startswith("/")
    stack: list = []

    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not is_absolute:
                stack.append("..")
            # absolute and nothing to pop: ignore (at root)
        else:
            stack.append(part)

    if is_absolute:
        return "/" + "/".join(stack)

    return "/".join(stack) or "."
