def flatten(nested, depth=None):
    """Flatten nested lists up to `depth` levels.

    depth=None flattens fully; depth=0 returns a shallow copy of `nested`.
    Only objects of exact type `list` are flattened. The input is never
    modified and a new list is always returned.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative or None")

    def _flatten(seq, remaining):
        # remaining is None (unlimited) or an int >= 0
        out = []
        for item in seq:
            if type(item) is list and (remaining is None or remaining > 0):
                nxt = None if remaining is None else remaining - 1
                out.extend(_flatten(item, nxt))
            else:
                out.append(item)
        return out

    if depth == 0:
        return list(nested)
    return _flatten(nested, depth)
