def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0
    while i < len(expr):
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            start = i
            while i < len(expr) and "0" <= expr[i] <= "9":
                i += 1
            if i < len(expr) and expr[i] == ".":
                i += 1
                fraction_start = i
                while i < len(expr) and "0" <= expr[i] <= "9":
                    i += 1
                if i == fraction_start:
                    raise ValueError("malformed decimal literal")
                tokens.append(float(expr[start:i]))
            else:
                tokens.append(int(expr[start:i]))
        elif ch in "+-*/^()":
            tokens.append(ch)
            i += 1
        else:
            raise ValueError("invalid character")

    if not tokens:
        raise ValueError("empty expression")

    position = 0

    def parse_expression():
        nonlocal position
        value = parse_term()
        while position < len(tokens) and tokens[position] in ("+", "-"):
            op = tokens[position]
            position += 1
            right = parse_term()
            value = value + right if op == "+" else value - right
        return value

    def parse_term():
        nonlocal position
        value = parse_unary()
        while position < len(tokens) and tokens[position] in ("*", "/"):
            op = tokens[position]
            position += 1
            right = parse_unary()
            if op == "*":
                value *= right
            else:
                try:
                    value /= right
                except ZeroDivisionError as exc:
                    raise ValueError("division by zero") from exc
        return value

    def parse_unary():
        nonlocal position
        if position < len(tokens) and tokens[position] == "-":
            position += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal position
        value = parse_atom()
        if position < len(tokens) and tokens[position] == "^":
            position += 1
            right = parse_unary()
            try:
                value = value ** right
            except ZeroDivisionError as exc:
                raise ValueError("division by zero") from exc
        return value

    def parse_atom():
        nonlocal position
        if position >= len(tokens):
            raise ValueError("missing operand")

        token = tokens[position]
        if isinstance(token, (int, float)):
            position += 1
            return token
        if token == "(":
            position += 1
            value = parse_expression()
            if position >= len(tokens) or tokens[position] != ")":
                raise ValueError("unbalanced parentheses")
            position += 1
            return value
        raise ValueError("expected a number or parenthesized expression")

    result = parse_expression()
    if position != len(tokens):
        raise ValueError("unexpected token")
    return result
