def first_bracket_error(s: str) -> int:
    """Index of the first bracket error in `s`, or -1 if the brackets balance.

    Non-bracket characters are ignored, but returned indices are offsets into
    the original string. A closing bracket that is unmatched or that does not
    match the most recent unclosed opening bracket is the first kind of error;
    if no such closing bracket exists, the leftmost opening bracket still
    unclosed at the end is reported instead.
    """
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []  # (opening bracket, its index), innermost last

    for i, ch in enumerate(s):
        if ch in "([{":
            stack.append((ch, i))
        elif ch in ")]}":
            if not stack or stack[-1][0] != pairs[ch]:
                return i
            stack.pop()

    if stack:
        return stack[0][1]
    return -1
