import re

_PATTERN = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def round_half_up(x: str, ndigits: int) -> str:
    """Round the decimal string `x` to `ndigits` places, half away from zero.

    Uses pure integer arithmetic so the result is exact decimal rounding.
    """
    if not isinstance(ndigits, int) or isinstance(ndigits, bool) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")
    if not isinstance(x, str) or _PATTERN.fullmatch(x) is None:
        raise ValueError("x must match: optional '-', digits, optional '.' + digits")

    negative = x.startswith("-")
    body = x[1:] if negative else x
    if "." in body:
        int_part, frac_part = body.split(".")
    else:
        int_part, frac_part = body, ""

    combined = int(int_part + frac_part) if frac_part else int(int_part)
    scale = len(frac_part)

    if scale <= ndigits:
        scaled = combined * 10 ** (ndigits - scale)
    else:
        divisor = 10 ** (scale - ndigits)
        scaled, remainder = divmod(combined, divisor)
        if remainder * 2 >= divisor:
            scaled += 1

    digits = str(scaled).rjust(ndigits + 1, "0")
    if ndigits:
        result = digits[:-ndigits] + "." + digits[-ndigits:]
    else:
        result = digits

    if negative and scaled != 0:
        result = "-" + result
    return result
