from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest t with start <= t, t + duration <= end and
    [t, t + duration) disjoint from every busy interval.

    Busy intervals are half-open (begin, finish): the minute `finish` is free.
    They may be unsorted, overlapping or merely touching. The input is never
    mutated.

    Raises ValueError if `duration` is not a positive integer, or if any busy
    interval has begin >= finish.
    """
    # --- validation -------------------------------------------------------
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    usable: List[Tuple[int, int]] = []  # clipped, overlap-free, sorted work list
    for interval in busy:
        try:
            begin, finish = interval
        except (TypeError, ValueError):
            raise ValueError("each busy interval must be a (begin, finish) pair")
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        # Keep only the part that can affect the window [start, end).
        if finish > start and begin < end:
            usable.append((begin, finish))

    # --- sweep ------------------------------------------------------------
    usable.sort()
    candidate = start
    for begin, finish in usable:
        if begin - candidate >= duration:
            return candidate
        if finish > candidate:
            candidate = finish
    if end - candidate >= duration:
        return candidate
    return None
