def format_bytes(n: int) -> str:
    """Format a byte count using binary units (B, KiB, MiB, GiB, TiB).

    Rounding is exact round-half-up on the true rational value; all math is
    done with Python integers so no floating-point error can creep in.
    """
    if n < 0:
        raise ValueError("byte count must be non-negative: {0!r}".format(n))

    if n < 1024:
        return "{0} B".format(n)

    UNITS = ("KiB", "MiB", "GiB", "TiB")

    def tenths(value: int, unit_index: int) -> int:
        # Exact round-half-up of value * 10 / 1024**(unit_index + 1),
        # returned as a whole number of tenths.
        den = 1024 ** (unit_index + 1)
        return (value * 20 + den) // (2 * den)

    # Largest unit index i with n / 1024**(i+1) >= 1, capped at TiB.
    i = 0
    while i < len(UNITS) - 1 and n >= 1024 ** (i + 2):
        i += 1

    t = tenths(n, i)

    # A value just below the next unit can round up to 1024.0; step up.
    # TiB is the largest unit, so anything >= 1024 TiB stays in TiB.
    if t >= 10240 and i < len(UNITS) - 1:
        i += 1
        t = tenths(n, i)

    return "{0}.{1} {2}".format(t // 10, t % 10, UNITS[i])
