import re


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0

    while i < len(expr):
        if expr[i].isspace():
            i += 1
            continue

        match = re.match(r"[0-9]+\.[0-9]+|[0-9]+", expr[i:])
        if match:
            text = match.group(0)
            tokens.append(float(text) if "." in text else int(text))
            i += len(text)
            continue

        if expr[i] in "+-*/^()":
            tokens.append(expr[i])
            i += 1
            continue

        raise ValueError("invalid character")

    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def parse_primary():
        nonlocal pos

        if pos >= len(tokens):
            raise ValueError("missing operand")

        token = tokens[pos]
        if isinstance(token, (int, float)):
            pos += 1
            return token

        if token == "(":
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value

        raise ValueError("expected a number or parenthesis")

    def parse_power():
        nonlocal pos

        value = parse_primary()
        if pos < len(tokens) and tokens[pos] == "^":
            pos += 1
            value = value ** parse_unary()
        return value

    def parse_unary():
        nonlocal pos

        if pos < len(tokens) and tokens[pos] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_product():
        nonlocal pos

        value = parse_unary()
        while pos < len(tokens) and tokens[pos] in ("*", "/"):
            operator = tokens[pos]
            pos += 1
            right = parse_unary()
            if operator == "*":
                value *= right
            else:
                try:
                    value /= right
                except ZeroDivisionError as exc:
                    raise ValueError("division by zero") from exc
        return value

    def parse_expression():
        nonlocal pos

        value = parse_product()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            operator = tokens[pos]
            pos += 1
            right = parse_product()
            if operator == "+":
                value += right
            else:
                value -= right
        return value

    result = parse_expression()
    if pos != len(tokens):
        raise ValueError("unexpected token")
    return result
