import re


_SEMVER_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_COMPARATOR_RE = re.compile(r"(>=|<=|=|>|<|\^|~)?(.+)")


def _parse_semver(text):
    """Return (core, ordering_key, has_prerelease), validating all syntax."""
    if not isinstance(text, str):
        raise ValueError("A version must be a string")

    match = _SEMVER_RE.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    core = tuple(int(match.group(i)) for i in (1, 2, 3))
    prerelease = match.group(4)

    if prerelease is None:
        return core, core + (1, ()), False

    identifiers = []
    for identifier in prerelease.split("."):
        # The regular expression already guarantees ASCII characters.
        if all("0" <= character <= "9" for character in identifier):
            if len(identifier) > 1 and identifier[0] == "0":
                raise ValueError(
                    "Numeric prerelease identifiers cannot have leading zeros"
                )
            identifiers.append((0, int(identifier)))
        else:
            identifiers.append((1, identifier))

    # Tagged identifiers make tuple ordering follow SemVer ordering:
    # numeric identifiers precede nonnumeric ones, and a shorter equal
    # prefix precedes a longer one. Releases sort after prereleases.
    return core, core + (0, tuple(identifiers)), True


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check the specified SemVer constraint language.

    Every comparator is validated, including comparators in OR groups
    that are unnecessary to determine the result. Invalid input raises
    ValueError.
    """
    version_core, version_key, version_has_prerelease = _parse_semver(version)

    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("The constraint must be a nonempty string")

    groups = []

    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups cannot be empty")

        comparisons = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_RE.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            target_core, target_key, target_has_prerelease = _parse_semver(
                match.group(2)
            )

            if target_has_prerelease:
                prerelease_cores.add(target_core)

            if operator in ("^", "~"):
                major, minor, patch = target_core

                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                comparisons.append((">=", target_key))
                comparisons.append(("<", upper_core + (1, ())))
            else:
                comparisons.append((operator, target_key))

        groups.append((comparisons, prerelease_cores))

    for comparisons, prerelease_cores in groups:
        if version_has_prerelease and version_core not in prerelease_cores:
            continue

        for operator, target_key in comparisons:
            if operator == "=":
                satisfied = version_key == target_key
            elif operator == ">":
                satisfied = version_key > target_key
            elif operator == ">=":
                satisfied = version_key >= target_key
            elif operator == "<":
                satisfied = version_key < target_key
            else:  # All operators have already been validated; this is "<=".
                satisfied = version_key <= target_key

            if not satisfied:
                break
        else:
            return True

    return False
