def leftmost_index(a, x):
    """Return the smallest index i with a[i] == x, or -1 if absent.

    `a` is sorted in non-decreasing order. Binary search over the half-open
    range [lo, hi) that is still known to contain the answer: the lower-bound
    search narrows to the first position where a[position] >= x.
    """
    lo, hi = 0, len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1   # everything up to mid is strictly below x
        else:
            hi = mid       # a[mid] >= x, so the leftmost hit is at or before mid
    if lo < len(a) and a[lo] == x:
        return lo
    return -1
