_DIGITS = frozenset("0123456789")


def _is_ascii_digits(s: str) -> bool:
    return len(s) > 0 and all(c in _DIGITS for c in s)


def round_half_up(x: str, ndigits: int) -> str:
    """Round a decimal string to ndigits places, half away from zero, exactly."""
    if not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")
    if not isinstance(x, str):
        raise ValueError("x must be a string")

    neg = x.startswith("-")
    body = x[1:] if neg else x

    if "." in body:
        if body.count(".") != 1:
            raise ValueError("invalid number format: %r" % (x,))
        int_part, frac_part = body.split(".")
        if not _is_ascii_digits(int_part) or not _is_ascii_digits(frac_part):
            raise ValueError("invalid number format: %r" % (x,))
    else:
        int_part, frac_part = body, ""
        if not _is_ascii_digits(int_part):
            raise ValueError("invalid number format: %r" % (x,))

    digits = int_part + frac_part  # all significant digits, no point

    if len(frac_part) <= ndigits:
        # Exact padding, no rounding needed.
        scaled = int(digits) * 10 ** (ndigits - len(frac_part))
    else:
        shift = len(frac_part) - ndigits
        q, r = divmod(int(digits), 10 ** shift)
        # r/10^shift >= 1/2  <=>  2*r >= 10^shift ; ties round away from zero
        if 2 * r >= 10 ** shift:
            q += 1
        scaled = q

    s = str(scaled)
    if len(s) <= ndigits:
        s = "0" * (ndigits + 1 - len(s)) + s

    if ndigits:
        out = s[:-ndigits] + "." + s[-ndigits:]
    else:
        out = s

    if neg and scaled != 0:
        out = "-" + out
    return out
