from typing import Iterable, List, Sequence


def merge_intervals(intervals: Iterable[Sequence[int]]) -> List[List[int]]:
    """Merge overlapping or endpoint-sharing closed intervals.

    Args:
        intervals: A list of [start, end] pairs of integers. May be
            unsorted or empty.

    Returns:
        A new list of [start, end] lists sorted by start, with all
        overlapping or endpoint-sharing intervals merged. Intervals made
        of adjacent integers (e.g. [1, 2] and [3, 4]) stay separate.

    Raises:
        ValueError: If any interval has start > end.
    """
    # Validate every interval up front, so an invalid pair is reported
    # no matter where it appears in the input.
    normalized = []
    for interval in intervals:
        start, end = interval
        if start > end:
            raise ValueError(
                "invalid interval [%r, %r]: start is greater than end"
                % (start, end)
            )
        normalized.append((start, end))

    normalized.sort()

    merged: List[List[int]] = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            # Overlaps or shares an endpoint with the last merged interval.
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged


