def first_bracket_error(s: str) -> int:
    match = {')': '(', ']': '[', '}': '{'}
    openers = {'(', '[', '{'}
    stack = []  # holds (index, char) of currently unclosed opening brackets

    for i, ch in enumerate(s):
        if ch in openers:
            stack.append((i, ch))
        elif ch in match:
            if not stack or stack[-1][1] != match[ch]:
                return i
            stack.pop()

    if stack:
        # Indices were pushed in increasing order, so the bottom of the
        # stack is the leftmost still-unclosed opening bracket.
        return stack[0][0]

    return -1
