_TOKEN_RE = re.compile(r"\d+(?:\.\d+)?|[()+\-*/^]")


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    pos = 0
    while pos < len(expr):
        if expr[pos].isspace():
            pos += 1
            continue
        match = _TOKEN_RE.match(expr, pos)
        if match is None:
            raise ValueError("invalid character or number")
        tokens.append(match.group())
        pos = match.end()

    if not tokens:
        raise ValueError("empty expression")

    index = 0

    def parse_additive():
        nonlocal index
        value = parse_multiplicative()
        while index < len(tokens) and tokens[index] in ("+", "-"):
            operator = tokens[index]
            index += 1
            right = parse_multiplicative()
            value = value + right if operator == "+" else value - right
        return value

    def parse_multiplicative():
        nonlocal index
        value = parse_unary()
        while index < len(tokens) and tokens[index] in ("*", "/"):
            operator = tokens[index]
            index += 1
            right = parse_unary()
            if operator == "*":
                value *= right
            else:
                try:
                    value /= right
                except ZeroDivisionError as exc:
                    raise ValueError("division by zero") from exc
        return value

    def parse_unary():
        nonlocal index
        if index < len(tokens) and tokens[index] == "-":
            index += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        nonlocal index
        value = parse_primary()
        if index < len(tokens) and tokens[index] == "^":
            index += 1
            value = value ** parse_unary()
        return value

    def parse_primary():
        nonlocal index
        if index >= len(tokens):
            raise ValueError("missing operand")

        token = tokens[index]
        if token == "(":
            index += 1
            value = parse_additive()
            if index >= len(tokens) or tokens[index] != ")":
                raise ValueError("unbalanced parentheses")
            index += 1
            return value

        if token == ")" or token in ("+", "-", "*", "/", "^"):
            raise ValueError("expected a number or parenthesized expression")

        index += 1
        return float(token) if "." in token else int(token)

    result = parse_additive()
    if index != len(tokens):
        raise ValueError("unexpected token")
    return result
