import re
from typing import Optional, Tuple


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?",
    re.ASCII,
)


def _parse_version(version: str) -> Tuple[Tuple[int, int, int], Optional[Tuple[str, ...]]]:
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid semantic version")

    major, minor, patch = (int(match.group(i)) for i in range(1, 4))
    prerelease_text = match.group(4)
    prerelease = None if prerelease_text is None else tuple(prerelease_text.split("."))

    if prerelease is not None:
        for identifier in prerelease:
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return (major, minor, patch), prerelease


def _compare_prerelease(
    left: Optional[Tuple[str, ...]],
    right: Optional[Tuple[str, ...]],
) -> int:
    if left is None:
        return 0 if right is None else 1
    if right is None:
        return -1

    for a, b in zip(left, right):
        a_numeric = a.isdigit()
        b_numeric = b.isdigit()

        if a_numeric and b_numeric:
            a_value, b_value = int(a), int(b)
            if a_value != b_value:
                return -1 if a_value < b_value else 1
        elif a_numeric != b_numeric:
            return -1 if a_numeric else 1
        elif a != b:
            return -1 if a < b else 1

    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left, right) -> int:
    if left[0] != right[0]:
        return -1 if left[0] < right[0] else 1
    prerelease_order = _compare_prerelease(left[1], right[1])
    if prerelease_order:
        return prerelease_order
    return 0


def semver_satisfies(version: str, constraint: str) -> bool:
    """Return whether a valid semantic version satisfies an npm-style constraint."""
    version_core, version_prerelease = _parse_version(version)
    parsed_version = (version_core, version_prerelease)

    if not constraint.strip():
        raise ValueError("constraint must not be empty")

    groups = constraint.split("||")
    if any(not group.strip() for group in groups):
        raise ValueError("constraint contains an empty group")

    parsed_groups = []
    for group in groups:
        comparators = []
        for token in group.split():
            if token == "*":
                comparators.append(("*", None, None))
                continue

            operator = "="
            operand = token
            for candidate in (">=", "<=", ">", "<", "^", "~", "="):
                if token.startswith(candidate):
                    operator = candidate
                    operand = token[len(candidate):]
                    break

            if not operand:
                raise ValueError("comparator must include a version")

            core, prerelease = _parse_version(operand)
            parsed_operand = (core, prerelease)

            if operator == "^":
                major, minor, patch = core
                if major > 0:
                    upper = ((major + 1, 0, 0), None)
                elif minor > 0:
                    upper = ((0, minor + 1, 0), None)
                else:
                    upper = ((0, 0, patch + 1), None)
            elif operator == "~":
                upper = ((core[0], core[1] + 1, 0), None)
            else:
                upper = None

            comparators.append((operator, parsed_operand, upper))

        if not comparators:
            raise ValueError("constraint group must contain a comparator")
        parsed_groups.append(comparators)

    for comparators in parsed_groups:
        if version_prerelease is not None and not any(
            operand is not None
            and operand[0] == version_core
            and operand[1] is not None
            for _, operand, _ in comparators
        ):
            continue

        satisfied = True
        for operator, operand, upper in comparators:
            if operator == "*":
                continue

            comparison = _compare_versions(parsed_version, operand)

            if operator == "=":
                holds = comparison == 0
            elif operator == ">":
                holds = comparison > 0
            elif operator == ">=":
                holds = comparison >= 0
            elif operator == "<":
                holds = comparison < 0
            elif operator == "<=":
                holds = comparison <= 0
            elif operator in ("^", "~"):
                holds = comparison >= 0 and _compare_versions(parsed_version, upper) < 0
            else:
                raise ValueError("invalid comparator")

            if not holds:
                satisfied = False
                break

        if satisfied:
            return True

    return False
