def is_valid_ipv4(s: str) -> bool:
    """Return True if *s* is a valid dotted-quad IPv4 address in strict form.

    Rules: exactly four dot-separated parts; each part 1-3 ASCII digits
    ('0'-'9' only) with value 0-255; no leading zeros unless the part is
    exactly "0"; no other characters anywhere.
    """
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not 1 <= len(part) <= 3:
            return False
        # Explicit ASCII range check: str.isdigit() accepts Unicode digits
        # (e.g. "١٢٣") and int() happily parses some of them, so neither
        # can be used as the digit test here.
        for ch in part:
            if ch < "0" or ch > "9":
                return False
        if len(part) > 1 and part[0] == "0":
            return False
        if int(part) > 255:
            return False

    return True
