def _parse_pattern(pattern):
    """Compile a glob pattern into a list of tokens, raising ValueError on errors."""
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a trailing backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            if j - i >= 2:
                tokens.append(('deep',))
            else:
                tokens.append(('star',))
            i = j
        elif c == '?':
            tokens.append(('one',))
            i += 1
        elif c == '[':
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            singles = set()
            ranges = []
            first = True
            closed = False
            while j < n:
                ch = pattern[j]
                if ch == ']' and not first:
                    closed = True
                    j += 1
                    break
                first = False
                if j + 2 < n and pattern[j + 1] == '-' and pattern[j + 2] != ']':
                    ranges.append((ch, pattern[j + 2]))
                    j += 3
                else:
                    singles.add(ch)
                    j += 1
            if not closed:
                raise ValueError("unterminated character class in pattern")
            tokens.append(('cls', negated, frozenset(singles), tuple(ranges)))
            i = j
        else:
            tokens.append(('lit', c))
            i += 1
    return tokens


def _class_matches(token, ch):
    _, negated, singles, ranges = token
    hit = ch in singles
    if not hit:
        for lo, hi in ranges:
            if lo <= ch <= hi:
                hit = True
                break
    return (not hit) if negated else hit


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches the glob `pattern`."""
    tokens = _parse_pattern(pattern)
    m = len(name)

    # next_slash[p] = index of the first '/' at or after p, else m
    next_slash = [m] * (m + 1)
    for p in range(m - 1, -1, -1):
        next_slash[p] = p if name[p] == '/' else next_slash[p + 1]

    cur = {0}
    for token in tokens:
        kind = token[0]
        new = set()
        if kind == 'lit':
            ch = token[1]
            for p in cur:
                if p < m and name[p] == ch:
                    new.add(p + 1)
        elif kind == 'one':
            for p in cur:
                if p < m and name[p] != '/':
                    new.add(p + 1)
        elif kind == 'star':
            for p in cur:
                new.update(range(p, next_slash[p] + 1))
        elif kind == 'deep':
            for p in cur:
                new.update(range(p, m + 1))
        else:  # 'cls'
            for p in cur:
                if p < m and _class_matches(token, name[p]):
                    new.add(p + 1)
        if not new:
            return False
        cur = new

    return m in cur
