def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    stack = []
    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                # Unresolvable ".." in a relative path: keep it.
                stack.append("..")
            # Absolute path: ".." at or above root is ignored.
        else:
            stack.append(part)

    if absolute:
        return "/" + "/".join(stack)
    if not stack:
        return "."
    return "/".join(stack)
