_SCHEME_RE = re.compile(r"([A-Za-z][A-Za-z0-9+.\-]*)://")
_HOST_RE = re.compile(r"[^\s/?#@:\[\]]+")
_PORT_RE = re.compile(r"[0-9]{1,5}")


def _split_host(hostport: str):
    """Split the host part (userinfo already removed) into (host, remainder)."""
    if hostport.startswith("["):
        end = hostport.find("]")
        if end == -1:
            raise ValueError("unterminated IPv6 literal in authority")
        literal = hostport[1:end]
        if literal == "":
            raise ValueError("empty IPv6 literal in authority")
        return literal.lower(), hostport[end + 1:]

    match = _HOST_RE.match(hostport)
    if match is None:
        raise ValueError("missing or invalid host in authority")
    host = match.group(0)
    remainder = hostport[match.end():]
    if remainder and not remainder.startswith(":"):
        raise ValueError("invalid character in authority")
    return host.lower(), remainder


def _split_port(remainder: str):
    """Return the port as an int, or None when there is no port."""
    if remainder == "":
        return None
    if not remainder.startswith(":"):
        raise ValueError("unexpected characters after host")
    digits = remainder[1:]
    if not _PORT_RE.fullmatch(digits):
        raise ValueError("invalid port")
    port = int(digits)
    if not 1 <= port <= 65535:
        raise ValueError("port out of range")
    return port


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("url must start with a scheme followed by '://'")
    scheme = match.group(1).lower()

    rest = url[match.end():]

    # Authority runs up to the first '/', '?' or '#' (or the end).
    cut = len(rest)
    for index, char in enumerate(rest):
        if char in "/?#":
            cut = index
            break
    authority, tail = rest[:cut], rest[cut:]

    if authority == "":
        raise ValueError("empty authority")

    at = authority.rfind("@")
    if at == -1:
        userinfo, hostport = "", authority
    else:
        userinfo, hostport = authority[:at], authority[at + 1:]

    host, remainder = _split_host(hostport)
    port = _split_port(remainder)

    hash_pos = tail.find("#")
    if hash_pos == -1:
        before_fragment, fragment = tail, ""
    else:
        before_fragment, fragment = tail[:hash_pos], tail[hash_pos + 1:]

    query_pos = before_fragment.find("?")
    if query_pos == -1:
        path, query = before_fragment, ""
    else:
        path, query = before_fragment[:query_pos], before_fragment[query_pos + 1:]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
