            dom_matches = current_day.day in month_days
            # datetime uses Monday=0; cron uses Sunday=0.
            dow_matches = (current_day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = 0
                if current_day == start.date():
                    index = bisect_right(
                        firing_minutes, start.hour * 60 + start.minute
                    )

                if index < len(firing_minutes):
                    hour, minute = divmod(firing_minutes[index], 60)
                    candidate = datetime(
                        current_day.year,
                        current_day.month,
                        current_day.day,
