from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]], duration: int, start: int, end: int
) -> Optional[int]:
    if not isinstance(duration, int) or isinstance(duration, bool) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    intervals = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")
        if finish > start and begin < end:
            intervals.append((max(begin, start), min(finish, end)))

    intervals.sort()
    candidate = start

    for begin, finish in intervals:
        if candidate + duration <= begin:
            return candidate
        if candidate < finish:
            candidate = finish

    return candidate if candidate + duration <= end else None
