"""Arithmetic expression evaluator.

Grammar (whitespace ignored between tokens):

    expr  := term (('+' | '-') term)*
    term  := unary (('*' | '/') unary)*
    unary := '-' unary | power
    power := atom ('^' unary)?          # '^' is right-associative
    atom  := INT | DECIMAL | '(' expr ')'

The exponent is parsed as a `unary`, which is what makes `2 ^ -1` legal and
`2 ^ 3 ^ 2` right-associative.  `unary` is reached from `power`, so unary
minus binds less tightly than `^` (`-2 ^ 2 == -4`).

Python 3.9, standard library only.
"""

_DIGITS = "0123456789"
_WHITESPACE = " \t\n\r\f\v"
_OPERATORS = "+-*/^"


def _tokenize(text):
    """Return a list of (kind, text) tokens: num / op / paren."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        if ch in _WHITESPACE:
            i += 1

        elif ch in _DIGITS:
            # Integer part: one or more digits.
            j = i
            while j < n and text[j] in _DIGITS:
                j += 1
            if j < n and text[j] == ".":
                # Decimal part: a dot followed by at least one digit.
                k = j + 1
                if k >= n or text[k] not in _DIGITS:
                    raise ValueError(
                        "malformed number literal: %r" % text[i:k + 1]
                    )
                while k < n and text[k] in _DIGITS:
                    k += 1
                tokens.append(("num", text[i:k]))
                i = k
            else:
                tokens.append(("num", text[i:j]))
                i = j

        elif ch in _OPERATORS:
            if ch == "*" and i + 1 < n and text[i + 1] == "*":
                raise ValueError(
                    "'**' is not a valid operator; use '^' for exponentiation"
                )
            tokens.append(("op", ch))
            i += 1

        elif ch == "(" or ch == ")":
            tokens.append(("paren", ch))
            i += 1

        else:
            raise ValueError("unexpected character %r" % (ch,))

    return tokens


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def parse(self):
        value = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError(
                "unexpected token %r" % (self._tokens[self._pos][1],)
            )
        return value

    def _expr(self):
        value = self._term()
        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in "+-":
                return value
            self._pos += 1
            rhs = self._term()
            value = value + rhs if tok[1] == "+" else value - rhs

    def _term(self):
        value = self._unary()
        while True:
            tok = self._peek()
            if tok is None or tok[0] != "op" or tok[1] not in "*/":
                return value
            self._pos += 1
            rhs = self._unary()
            if tok[1] == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs

    def _unary(self):
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "-":
            self._pos += 1
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._atom()
        tok = self._peek()
        if tok is not None and tok[0] == "op" and tok[1] == "^":
            self._pos += 1
            exponent = self._unary()          # right-associative, may be negated
            return base ** exponent
        return base

    def _atom(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        kind, text = tok

        if kind == "num":
            self._pos += 1
            return float(text) if "." in text else int(text)

        if kind == "paren" and text == "(":
            self._pos += 1
            value = self._expr()
            closing = self._peek()
            if closing is None or closing != ("paren", ")"):
                raise ValueError("unbalanced parentheses: missing ')'")
            self._pos += 1
            return value

        raise ValueError("unexpected token %r" % (text,))


def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return an int or float.

    Raises ValueError for any malformed input and for division by zero.
    """
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    try:
        return _Parser(tokens).parse()
    except ZeroDivisionError:
        # e.g. `0 ^ -1`, which Python reports as a ZeroDivisionError.
        raise ValueError("division by zero")
