"""parse_duration: convert a duration string such as "1h 30m" into seconds."""

import re

__all__ = ["parse_duration"]

_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}

# Whole-string shape: optional U+0020 padding, then one or more parts of the
# form "<digits><unit>", each part optionally followed by U+0020 spaces. The
# part is atomic, so a space between a number and its unit cannot match.
_SHAPE_RE = re.compile(r" *(?:[0-9]+[dhms] *)+")
_PART_RE = re.compile(r"([0-9]+)([dhms])")


def parse_duration(s: str) -> int:
    """Return the number of seconds described by `s`, or raise ValueError."""
    if not isinstance(s, str):
        raise TypeError("duration must be a string, got %s" % type(s).__name__)

    if _SHAPE_RE.fullmatch(s) is None:
        raise ValueError("invalid duration string: %r" % (s,))

    total = 0
    seen = set()
    for number, unit in _PART_RE.findall(s):
        if unit in seen:
            raise ValueError("repeated unit %r in %r" % (unit, s))
        seen.add(unit)
        total += int(number) * _UNIT_SECONDS[unit]
    return total
