"""Arithmetic expression evaluator.

Grammar (whitespace is allowed between any two tokens and ignored):

    expr    := term (('+' | '-') term)*
    term    := factor (('*' | '/') factor)*
    factor  := '-' factor | power
    power   := atom ('^' factor)?          # right-associative
    atom    := NUMBER | '(' expr ')'

`factor` sits *between* the additive/multiplicative levels and `power`, which
is what makes the unary minus bind less tightly than `^` (`-2 ^ 2 == -4`)
while still allowing a unary minus to open the exponent (`2 ^ -1 == 0.5`).
Making the right-hand side of `^` a `factor` (not another `power`) gives both
right-associativity and the "exponent may start with '-'" rule at once.
"""

_WHITESPACE = " \t\n\r\v\f"
_PUNCTUATION = "+-*/^()"


def _tokenize(text):
    """Split `text` into a list of operator strings and int/float values."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        if ch in _WHITESPACE:
            i += 1
            continue

        if ch in _PUNCTUATION:
            tokens.append(ch)
            i += 1
            continue

        if "0" <= ch <= "9":
            j = i
            while j < n and "0" <= text[j] <= "9":
                j += 1
            is_float = False
            if j < n and text[j] == ".":
                k = j + 1  # a decimal literal needs digits after the dot
                if k >= n or not ("0" <= text[k] <= "9"):
                    raise ValueError(
                        "malformed decimal literal in %r" % (text,)
                    )
                while k < n and "0" <= text[k] <= "9":
                    k += 1
                j = k
                is_float = True
            literal = text[i:j]
            tokens.append(float(literal) if is_float else int(literal))
            i = j
            continue

        raise ValueError("unexpected character %r in %r" % (ch, text))

    return tokens


class _Parser:
    __slots__ = ("tokens", "pos")

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    # -- helpers ---------------------------------------------------------
    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _advance(self):
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        self.pos += 1
        return token

    # -- entry point -----------------------------------------------------
    def parse(self):
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError(
                "unexpected token %r" % (self.tokens[self.pos],)
            )
        return value

    # -- rules -----------------------------------------------------------
    def _expr(self):
        value = self._term()
        while True:
            token = self._peek()
            if token == "+":
                self._advance()
                value = value + self._term()
            elif token == "-":
                self._advance()
                value = value - self._term()
            else:
                return value

    def _term(self):
        value = self._factor()
        while True:
            token = self._peek()
            if token == "*":
                self._advance()
                value = value * self._factor()
            elif token == "/":
                self._advance()
                divisor = self._factor()
                try:
                    value = value / divisor
                except ZeroDivisionError:
                    raise ValueError("division by zero") from None
            else:
                return value

    def _factor(self):
        if self._peek() == "-":
            self._advance()
            return -self._factor()
        return self._power()

    def _power(self):
        base = self._atom()
        if self._peek() == "^":
            self._advance()
            exponent = self._factor()
            try:
                return base ** exponent
            except ZeroDivisionError:  # e.g. 0 ^ -1
                raise ValueError("division by zero") from None
        return base

    def _atom(self):
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        if isinstance(token, str):
            if token == "(":
                self._advance()
                value = self._expr()
                if self._peek() != ")":
                    raise ValueError("unbalanced parentheses")
                self._advance()
                return value
            raise ValueError("unexpected token %r" % (token,))
        self._advance()
        return token


def evaluate(expr: str):
    """Evaluate an arithmetic expression string, returning an int or float.

    Raises ValueError for malformed input and for division by zero.
    """
    return _Parser(_tokenize(expr)).parse()
