    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
]

_SINGLE = {sym: val for val, sym in _VALUES if len(sym) == 1}
_PAIR = {sym: val for val, sym in _VALUES if len(sym) == 2}
_ALL_CHARS = frozenset(_SINGLE)


def _to_roman(n: int) -> str:
    """Canonical Roman numeral for 1 <= n <= 3999."""
    if not 1 <= n <= 3999:
        raise ValueError("out of range")
    out = []
    for value, sym in _VALUES:
        while n >= value:
            out.append(sym)
            n -= value
    return "".join(out)


def roman_to_int(s: str) -> int:
    if not s or not set(s) <= _ALL_CHARS:
        raise ValueError("not a canonical uppercase Roman numeral")

    total = 0
    i = 0
    while i < len(s):
        if s[i:i + 2] in _PAIR:
            total += _PAIR[s[i:i + 2]]
            i += 2
        else:
            total += _SINGLE[s[i]]
            i += 1

    if not 1 <= total <= 3999 or _to_roman(total) != s:
        raise ValueError("not a canonical uppercase Roman numeral")
    return total
