import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    dependency_sets: dict[str, set[str]] = {}

    for item, dependencies in deps.items():
        unique_dependencies = set(dependencies)
        dependency_sets[item] = unique_dependencies
        nodes.update(unique_dependencies)

    dependents: dict[str, set[str]] = {node: set() for node in nodes}
    remaining: dict[str, int] = {node: 0 for node in nodes}

    for item, dependencies in dependency_sets.items():
        remaining[item] = len(dependencies)
        for dependency in dependencies:
            dependents[dependency].add(item)

    ready = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(ready)

    result: list[str] = []

    while ready:
        node = heapq.heappop(ready)
        result.append(node)

        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(nodes):
        raise ValueError("dependencies contain a cycle")

    return result
