def parse_duration(s: str) -> int:
    units = {"d": 86400, "h": 3600, "m": 60, "s": 1}
    total = 0
    seen = set()
    i = 0
    n = len(s)

    while i < n and s[i] == " ":
        i += 1

    if i == n:
        raise ValueError("invalid duration")

    while i < n:
        if not ("0" <= s[i] <= "9"):
            raise ValueError("invalid duration")

        start = i
        while i < n and "0" <= s[i] <= "9":
            i += 1

        if i == n or s[i] not in units:
            raise ValueError("invalid duration")

        unit = s[i]
        if unit in seen:
            raise ValueError("invalid duration")

        seen.add(unit)
        total += int(s[start:i]) * units[unit]
        i += 1

        while i < n and s[i] == " ":
            i += 1

        if i < n and not ("0" <= s[i] <= "9"):
            raise ValueError("invalid duration")

    return total
