import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned and each item's unique dependencies.
    unique_deps: dict[str, set] = {}
    for item in deps:
        unique_deps.setdefault(item, set())
    for item, dep_list in deps.items():
        for dep in dep_list:
            unique_deps.setdefault(dep, set())
            unique_deps[item].add(dep)

    # Number of dependencies still unplaced for each item.
    remaining = {item: len(d) for item, d in unique_deps.items()}

    # Reverse edges: dependency -> items that depend on it.
    dependents: dict[str, list] = {item: [] for item in unique_deps}
    for item, d in unique_deps.items():
        for dep in d:
            dependents[dep].append(item)

    # Available items (no unmet dependencies), smallest first.
    ready = [item for item, count in remaining.items() if count == 0]
    heapq.heapify(ready)

    result: list[str] = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents[item]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(unique_deps):
        raise ValueError("cyclic dependency detected")

    return result
