def wrap_text(text: str, width: int):
    if width < 1:
        raise ValueError("width must be >= 1")

    words = [w for w in text.split(" ") if w != ""]
    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            i = 0
            n = len(word)
            while n - i > width:
                lines.append(word[i:i + width])
                i += width
            current = word[i:]
        else:
            if not current:
                current = word
            elif len(current) + 1 + len(word) <= width:
                current = current + " " + word
            else:
                lines.append(current)
                current = word

    if current:
        lines.append(current)

