def flatten(nested, depth=None):
    """Flatten nested lists up to `depth` levels.

    depth=None flattens completely, depth=0 returns a shallow copy of the
    top level. Only objects whose type is exactly `list` are flattened.
    The input is never modified.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative or None")

    def walk(seq, remaining):
        for item in seq:
            if type(item) is list and (remaining is None or remaining > 0):
                next_remaining = None if remaining is None else remaining - 1
                yield from walk(item, next_remaining)
            else:
                yield item

    return list(walk(nested, depth))
