def shell_split(s: str) -> list[str]:
    words = []
    current = None  # None: no word started yet; str: word being built
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ' or c == '\t':
            # Separator outside quotes: finish the current word, if any.
            if current is not None:
                words.append(current)
                current = None
            i += 1
        elif c == '\\':
            # Outside quotes: backslash escapes the next character literally.
            if i + 1 >= n:
                raise ValueError("backslash at end of input")
            if current is None:
                current = ""
            current += s[i + 1]
            i += 2
        elif c == "'":
            # Single quotes: everything up to the next single quote is literal.
            if current is None:
                current = ""
            i += 1
            end = s.find("'", i)
            if end == -1:
                raise ValueError("unterminated single quote")
            current += s[i:end]
            i = end + 1
        elif c == '"':
            # Double quotes: only \" and \\ are escapes; all else literal.
            if current is None:
                current = ""
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                c2 = s[i]
                if c2 == '"':
                    i += 1
                    break
                if c2 == '\\' and i + 1 < n and s[i + 1] in ('"', '\\'):
                    current += s[i + 1]
                    i += 2
                else:
                    current += c2
                    i += 1
        else:
            # Ordinary character outside quotes.
            if current is None:
                current = ""
            current += c
            i += 1
    if current is not None:
        words.append(current)
    return words
