def shell_split(s: str) -> list:
    words = []
    buf = None  # None means "no word started yet"; str may be '' for an empty word
    n = len(s)
    i = 0

    while i < n:
        c = s[i]

        if c == " " or c == "\t":
            if buf is not None:
                words.append(buf)
                buf = None
            i += 1

        elif c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            if buf is None:
                buf = ""
            buf += s[i + 1]
            i += 2

        elif c == "'":
            j = s.find("'", i + 1)
            if j == -1:
                raise ValueError("unterminated single quote")
            if buf is None:
                buf = ""
            buf += s[i + 1:j]
            i = j + 1

        elif c == '"':
            if buf is None:
                buf = ""
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                d = s[i]
                if d == '"':
                    i += 1
                    break
                if d == "\\":
                    if i + 1 < n and (s[i + 1] == '"' or s[i + 1] == "\\"):
                        buf += s[i + 1]
                        i += 2
                    else:
                        buf += "\\"
                        i += 1
                else:
                    buf += d
                    i += 1

        else:
            if buf is None:
                buf = ""
            buf += c
            i += 1

    if buf is not None:
