    if not isinstance(url, str):
        raise ValueError("url must be a string")

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("url must start with a valid scheme followed by '://'")
    scheme = match.group(1).lower()
    rest = url[match.end():]

    # Authority: up to the first '/', '?' or '#', or the end of the string.
    cut = len(rest)
    for idx, ch in enumerate(rest):
        if ch in "/?#":
            cut = idx
            break
    authority, remainder = rest[:cut], rest[cut:]

    if not authority:
        raise ValueError("empty authority")

    # userinfo is everything before the LAST '@', verbatim.
    at = authority.rfind("@")
    if at == -1:
        userinfo, hostport = "", authority
    else:
        userinfo, hostport = authority[:at], authority[at + 1:]

    if not hostport:
        raise ValueError("empty host")

    if hostport[0] == "[":
        close = hostport.find("]")
        if close == -1:
            raise ValueError("unterminated IPv6 literal")
        host = hostport[1:close]
        if not host or "[" in host:
            raise ValueError("invalid IPv6 literal")
        tail = hostport[close + 1:]
    else:
        i = 0
        while i < len(hostport) and hostport[i] not in _HOST_STOP:
            i += 1
        host = hostport[:i]
        if not host:
            raise ValueError("empty host")
        tail = hostport[i:]

    # Optional ':port' — the only thing allowed after the host.
    if tail == "":
        port = None
    elif tail[0] == ":":
        digits = tail[1:]
        if _PORT_RE.match(digits) is None:
            raise ValueError("invalid port")
        port = int(digits)
        if not 1 <= port <= 65535:
            raise ValueError("port out of range")
    else:
        raise ValueError("unexpected characters after host")

    # First '#' starts the fragment; in what precedes it, the first '?' starts
    # the query; the remainder is the path. Nothing is decoded or normalised.
    hash_at = remainder.find("#")
    if hash_at == -1:
        fragment, before_hash = "", remainder
    else:
        fragment, before_hash = remainder[hash_at + 1:], remainder[:hash_at]

    query_at = before_hash.find("?")
    if query_at == -1:
        query, path = "", before_hash
    else:
        query, path = before_hash[query_at + 1:], before_hash[:query_at]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host.lower(),
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
