def rle_decode(s: str) -> str:
    """Decode a run-length encoded string.

    Each group is a positive decimal count with no leading zeros, written in
    ASCII digits, followed by exactly one non-ASCII-digit character.

    Raises ValueError if a count is missing, zero, or zero-padded; if the
    string ends with digits; or if the decoded length would exceed 10000.
    """
    MAX_DECODED_LENGTH = 10000

    def is_digit(ch: str) -> bool:
        return "0" <= ch <= "9"

    pieces = []
    total = 0
    i = 0
    n = len(s)

    while i < n:
        if not is_digit(s[i]):
            raise ValueError(
                "missing count before character {!r} at index {}".format(s[i], i)
            )

        j = i
        while j < n and is_digit(s[j]):
            j += 1

        if j == n:
            raise ValueError("string ends with digit(s): {!r}".format(s[i:]))

        count_text = s[i:j]
        if count_text[0] == "0":
            raise ValueError("count is zero or has a leading zero: {!r}".format(count_text))

        count = int(count_text)
        char = s[j]

        # Accumulate before materializing, so an oversized request never
        # allocates a giant intermediate string.
        total += count
        if total > MAX_DECODED_LENGTH:
            raise ValueError(
                "decoded length {} exceeds maximum of {}".format(total, MAX_DECODED_LENGTH)
            )

        pieces.append(char * count)
        i = j + 1

    return "".join(pieces)
```

Key design points: the scan always consumes digits-then-one-char, so a bare character or a trailing run of digits is caught structurally; `count_text[0] == "0"` rejects both `"0"` and any leading-zero form in one check; and the running total is checked *before* building each run so a long count like `"999999999a"` fails fast instead of allocating.

