def dedupe_keep_order(items):
    """Return a new list with duplicates removed (first occurrence kept, order preserved).

    Duplicates are determined by == only, so 1, 1.0 and True collapse to the
    first one seen, and unhashable items (lists, dicts, ...) are supported.
    The input list is never touched.
    """
    result = []            # every kept item, in original order
    buckets = {}           # hash(item) -> kept items sharing that hash
    unhashable = []        # kept items whose hash() raises TypeError

    for item in items:
        try:
            h = hash(item)
        except TypeError:
            h = None       # unhashable: must compare against everything

        found = False
        if h is None:
            for seen in result:
                if seen == item:
                    found = True
                    break
        else:
            for seen in buckets.get(h, ()):
                if seen == item:
                    found = True
                    break
            if not found:
                for seen in unhashable:
                    if seen == item:
                        found = True
                        break

        if not found:
            result.append(item)
            if h is None:
                unhashable.append(item)
            else:
                buckets.setdefault(h, []).append(item)

    return result
