"""Semantic version constraint matching following SemVer 2.0 ordering and
npm-style range rules.  Standard library only, Python 3.9 compatible."""

import re

__all__ = ["semver_satisfies"]

# ---------------------------------------------------------------------------
# version grammar
# ---------------------------------------------------------------------------

_CORE = r"(?:0|[1-9][0-9]*)"
_IDENT = r"[0-9A-Za-z-]+"

_VERSION_RE = re.compile(
    r"^(" + _CORE + r")\.(" + _CORE + r")\.(" + _CORE + r")"
    r"(?:-(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
    r"(?:\+(" + _IDENT + r"(?:\." + _IDENT + r")*))?$"
)

_NUMERIC_IDENT_RE = re.compile(r"[0-9]+\Z")

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


class _Version(object):
    """A parsed semantic version (build metadata discarded)."""

    __slots__ = ("major", "minor", "patch", "prerelease")

    def __init__(self, major, minor, patch, prerelease):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # list of identifier strings

    def core(self):
        return (self.major, self.minor, self.patch)


def _parse_version(text):
    """Parse a version string; raise ValueError if it is not valid."""
    if not isinstance(text, str):
        raise ValueError(
            "version must be a string, got %s" % type(text).__name__
        )
    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))

    prerelease = []
    raw_pre = match.group(4)
    if raw_pre is not None:
        prerelease = raw_pre.split(".")
        for ident in prerelease:
            if (
                _NUMERIC_IDENT_RE.match(ident)
                and len(ident) > 1
                and ident[0] == "0"
            ):
                raise ValueError(
                    "invalid version %r: numeric pre-release identifier %r "
                    "has a leading zero" % (text, ident)
                )

    return _Version(
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        prerelease,
    )


# ---------------------------------------------------------------------------
# ordering
# ---------------------------------------------------------------------------


def _cmp_ident(a, b):
    """Compare two pre-release identifiers per SemVer 2.0."""
    a_numeric = _NUMERIC_IDENT_RE.match(a) is not None
    b_numeric = _NUMERIC_IDENT_RE.match(b) is not None
    if a_numeric and b_numeric:
        ai = int(a)
        bi = int(b)
        return (ai > bi) - (ai < bi)
    if a_numeric:
        return -1
    if b_numeric:
        return 1
    return (a > b) - (a < b)


def _cmp_version(a, b):
    """Total order over versions: -1, 0 or 1."""
    for x, y in (
        (a.major, b.major),
        (a.minor, b.minor),
        (a.patch, b.patch),
    ):
        if x != y:
            return -1 if x < y else 1

    apre, bpre = a.prerelease, b.prerelease
    if not apre and not bpre:
        return 0
    if not apre:
        return 1  # release > pre-release
    if not bpre:
        return -1

    for x, y in zip(apre, bpre):
        result = _cmp_ident(x, y)
        if result:
            return result
    return (len(apre) > len(bpre)) - (len(apre) < len(bpre))


# ---------------------------------------------------------------------------
# comparators
# ---------------------------------------------------------------------------


def _parse_comparator(token):
    """Return (operator, version-or-None); '*' yields ('*', None)."""
    if token == "*":
        return ("*", None)

    operator = "="
    rest = token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            operator = candidate
            rest = token[len(candidate):]
            break

    if rest == "":
        raise ValueError("invalid comparator: %r" % (token,))

    return (operator, _parse_version(rest))


def _caret_upper(version):
    """Exclusive upper bound for a caret range."""
    if version.major > 0:
        return _Version(version.major + 1, 0, 0, [])
    if version.minor > 0:
        return _Version(0, version.minor + 1, 0, [])
    return _Version(0, 0, version.patch + 1, [])


def _tilde_upper(version):
    """Exclusive upper bound for a tilde range."""
    return _Version(version.major, version.minor + 1, 0, [])


def _comparator_ok(operator, bound, version):
    if operator == "*":
        return True
    if operator == "=":
        return _cmp_version(version, bound) == 0
    if operator == ">":
        return _cmp_version(version, bound) > 0
    if operator == ">=":
        return _cmp_version(version, bound) >= 0
    if operator == "<":
        return _cmp_version(version, bound) < 0
    if operator == "<=":
        return _cmp_version(version, bound) <= 0
    if operator == "^":
        return (
            _cmp_version(version, bound) >= 0
            and _cmp_version(version, _caret_upper(bound)) < 0
        )
    if operator == "~":
        return (
            _cmp_version(version, bound) >= 0
            and _cmp_version(version, _tilde_upper(bound)) < 0
        )
    raise ValueError("invalid comparator operator: %r" % (operator,))


def _group_ok(version, comparators):
    for operator, bound in comparators:
        if not _comparator_ok(operator, bound, version):
            return False

    if version.prerelease:
        for operator, bound in comparators:
            if (
                bound is not None
                and bound.prerelease
                and bound.core() == version.core()
            ):
                return True
        return False

    return True


# ---------------------------------------------------------------------------
# public API
# ---------------------------------------------------------------------------


def semver_satisfies(version, constraint):
    """Check *version* against an npm-style *constraint*.

    Raises ValueError for an invalid version, an invalid comparator or an
    empty constraint.
    """
    if not isinstance(constraint, str):
        raise ValueError(
            "constraint must be a string, got %s" % type(constraint).__name__
        )

    parsed_version = _parse_version(version)

    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty constraint: %r" % (constraint,))
        groups.append([_parse_comparator(token) for token in tokens])

    for comparators in groups:
        if _group_ok(parsed_version, comparators):
            return True
    return False
