import re
from datetime import date, datetime, timedelta


def next_cron(expr: str, after: str) -> str:
    def parse_field(text: str, minimum: int, maximum: int) -> set[int]:
        values = set()

        for item in text.split(","):
            if not item:
                raise ValueError("empty cron item")

            parts = item.split("/")
            if len(parts) > 2:
                raise ValueError("malformed cron item")

            base = parts[0]
            if len(parts) == 2:
                if not re.fullmatch(r"[0-9]+", parts[1]):
                    raise ValueError("invalid step")
                step = int(parts[1])
                if step < 1:
                    raise ValueError("step must be at least 1")
            else:
                step = 1

            if base == "*":
                start, end = minimum, maximum
            elif re.fullmatch(r"[0-9]+", base):
                start = int(base)
                end = maximum if len(parts) == 2 else start
            else:
                match = re.fullmatch(r"([0-9]+)-([0-9]+)", base)
                if not match:
                    raise ValueError("malformed cron item")
                start, end = map(int, match.groups())

            if not (minimum <= start <= maximum and minimum <= end <= maximum):
                raise ValueError("cron value out of range")
            if start > end:
                raise ValueError("invalid range")

            values.update(range(start, end + 1, step))

        if not values:
            raise ValueError("empty cron field")
        return values

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly five fields")

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    days = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    weekdays = parse_field(fields[4], 0, 6)

    try:
        if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}", after):
            raise ValueError("invalid datetime format")
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
        if start.strftime("%Y-%m-%d %H:%M") != after:
            raise ValueError("invalid datetime format")
    except (TypeError, ValueError) as exc:
        raise ValueError("after must be a valid YYYY-MM-DD HH:MM datetime") from exc

    try:
        cutoff_year = start.year + 5
        cutoff_day = min(
            start.day,
            (date(cutoff_year, start.month + 1, 1) - timedelta(days=1)).day
            if start.month < 12
            else 31,
        )
        cutoff = datetime(
            cutoff_year, start.month, cutoff_day, start.hour, start.minute
        )
    except ValueError:
        # February 29 becomes February 28 when the target year is not a leap year.
        cutoff = datetime(start.year + 5, 2, 28, start.hour, start.minute)

    current_day = start.date()
    while current_day <= cutoff.date():
        if current_day.month in months:
            dom_match = current_day.day in days
            dow_match = (current_day.weekday() + 1) % 7 in weekdays
            dom_restricted = fields[2] != "*"
            dow_restricted = fields[4] != "*"

            if dom_restricted and dow_restricted:
                day_matches = dom_match or dow_match
            elif dom_restricted:
                day_matches = dom_match
            elif dow_restricted:
                day_matches = dow_match
            else:
                day_matches = True

            if day_matches:
                for hour in sorted(hours):
                    for minute in sorted(minutes):
                        candidate = datetime(
                            current_day.year,
                            current_day.month,
                            current_day.day,
                            hour,
                            minute,
                        )
                        if start < candidate <= cutoff:
                            return candidate.strftime("%Y-%m-%d %H:%M")

        current_day += timedelta(days=1)

    raise ValueError("no matching time within five years")
