"""Arithmetic expression evaluator — Python 3.9, standard library only.

Grammar (recursive descent, one function per precedence level):

    expr    := term (('+' | '-') term)*          # left-assoc, lowest
    term    := unary (('*' | '/') unary)*        # left-assoc
    unary   := '-' unary | power                 # unary minus, weaker than '^'
    power   := atom ('^' unary)?                 # right-assoc, exponent may be unary
    atom    := NUMBER | '(' expr ')'

Requirements covered: int/float literal typing, true division for '/',
division by zero -> ValueError, '^' -> '**', and ValueError for every
malformed input (empty, bad chars, two numbers in a row, missing operand,
unbalanced parens, '**', implicit multiplication).
"""

import re
from typing import List, Tuple, Union

Number = Union[int, float]

# digits [ . digits ]  -- a decimal literal requires digits on BOTH sides of the dot
_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_OPERATORS = frozenset("+-*/^()")


def _tokenize(expr: str) -> List[Tuple[str, object]]:
    tokens: List[Tuple[str, object]] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        match = _NUMBER_RE.match(expr, i)
        if match is not None:
            text = match.group()
            value: Number = float(text) if "." in text else int(text)
            tokens.append(("num", value))
            i = match.end()
            continue
        if ch in _OPERATORS:
            tokens.append(("op", ch))
            i += 1
            continue
        raise ValueError("invalid character %r at position %d" % (ch, i))
    return tokens


class _Parser:
    def __init__(self, tokens: List[Tuple[str, object]]) -> None:
        self._tokens = tokens
        self._pos = 0

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _next(self):
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _peek_op(self, chars: str):
        token = self._peek()
        if token is not None and token[0] == "op" and token[1] in chars:
            return token[1]
        return None

    def at_end(self) -> bool:
        return self._pos >= len(self._tokens)

    def parse_expr(self) -> Number:
        value = self.parse_term()
        while True:
            op = self._peek_op("+-")
            if op is None:
                return value
            self._next()
            rhs = self.parse_term()
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs

    def parse_term(self) -> Number:
        value = self.parse_unary()
        while True:
            op = self._peek_op("*/")
            if op is None:
                return value
            self._next()
            rhs = self.parse_unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs

    def parse_unary(self) -> Number:
        if self._peek_op("-") is not None:
            self._next()
            return -self.parse_unary()
        return self.parse_power()

    def parse_power(self) -> Number:
        base = self.parse_atom()
        if self._peek_op("^") is not None:
            self._next()
            exponent = self.parse_unary()
            try:
                return base ** exponent
            except ZeroDivisionError:  # e.g. 0 ^ -1
                raise ValueError("division by zero") from None
        return base

    def parse_atom(self) -> Number:
        token = self._peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        kind, value = token
        if kind == "num":
            self._next()
            return value  # type: ignore[return-value]
        if kind == "op" and value == "(":
            self._next()
            inner = self.parse_expr()
            closing = self._peek()
            if closing is None or closing[0] != "op" or closing[1] != ")":
                raise ValueError("unbalanced parentheses")
            self._next()
            return inner
        raise ValueError("unexpected token %r" % (value,))


def evaluate(expr: str) -> Number:
    """Evaluate an infix arithmetic expression and return its numeric value.

    Raises ValueError for any malformed input or division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    result = parser.parse_expr()
    if not parser.at_end():
        raise ValueError("unexpected trailing input")
    return result
