def flatten(nested, depth=None):
    """Flatten nested lists up to `depth` levels.

    depth=None flattens completely; depth=0 returns a shallow copy of the
    top-level list. Only objects of exact type `list` are flattened.
    """
    if depth is not None:
        if depth < 0:
            raise ValueError("depth must be non-negative or None")
        if depth == 0:
            return list(nested)

    result = []
    stack = [(item, 0) for item in reversed(nested)]
    while stack:
        item, level = stack.pop()
        if type(item) is list and (depth is None or level < depth):
            stack.extend((sub, level + 1) for sub in reversed(item))
        else:
            result.append(item)
    return result
