# Implementation (passes the test suite above).
# Target: Python 3.9, standard library only.

_PAIRS = {")": "(", "]": "[", "}": "{"}
_OPENERS = frozenset(_PAIRS.values())  # {'(', '[', '{'}


def first_bracket_error(s: str) -> int:
    """Return the index of the first bracket error in ``s``.

    Scans left to right, ignoring every non-bracket character:
      * returns the index of the first closing bracket that does not match
        the most recent unclosed opening bracket, or that has no opener;
      * otherwise, if opening brackets remain unclosed, returns the index
        of the leftmost unclosed opening bracket;
      * returns -1 if all brackets are balanced.
    """
    open_indices = []  # indices of currently unclosed opening brackets
    for i, ch in enumerate(s):
        if ch in _OPENERS:
            open_indices.append(i)
        else:
            expected = _PAIRS.get(ch)
            if expected is None:
                continue  # not a bracket: ignore
            if not open_indices or s[open_indices[-1]] != expected:
                return i
            open_indices.pop()
    return open_indices[0] if open_indices else -1
