def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0

    while i < len(expr):
        char = expr[i]

        if char.isspace():
            i += 1
        elif char.isascii() and char.isdigit():
            start = i
            while i < len(expr) and expr[i].isascii() and expr[i].isdigit():
                i += 1

            is_decimal = False
            if i < len(expr) and expr[i] == ".":
                is_decimal = True
                i += 1
                fraction_start = i
                while i < len(expr) and expr[i].isascii() and expr[i].isdigit():
                    i += 1
                if i == fraction_start:
                    raise ValueError("invalid decimal literal")

            text = expr[start:i]
            tokens.append(("number", float(text) if is_decimal else int(text)))
        elif char in "+-*/^()":
            tokens.append((char, char))
            i += 1
        else:
            raise ValueError("invalid character")

    tokens.append(("end", None))
    position = 0

    def peek():
        return tokens[position][0]

    def consume(kind):
        nonlocal position
        if peek() != kind:
            raise ValueError("malformed expression")
        value = tokens[position][1]
        position += 1
        return value

    def primary():
        if peek() == "number":
            return consume("number")
        if peek() == "(":
            consume("(")
            value = additive()
            consume(")")
            return value
        raise ValueError("missing operand")

    def power():
        value = primary()
        if peek() == "^":
            consume("^")
            exponent = unary()
            value = value ** exponent
        return value

    def unary():
        if peek() == "-":
            consume("-")
            return -unary()
        return power()

    def multiplicative():
        value = unary()
        while peek() in ("*", "/"):
            operator = tokens[position][0]
            consume(operator)
            right = unary()
            try:
                value = value * right if operator == "*" else value / right
            except ZeroDivisionError as exc:
                raise ValueError("division by zero") from exc
        return value

    def additive():
        value = multiplicative()
        while peek() in ("+", "-"):
            operator = tokens[position][0]
            consume(operator)
            right = multiplicative()
            value = value + right if operator == "+" else value - right
        return value

    if peek() == "end":
        raise ValueError("empty expression")

    result = additive()
    if peek() != "end":
        raise ValueError("malformed expression")
    return result
