import re


def roman_to_int(s: str) -> int:
    if not isinstance(s, str) or not s or re.fullmatch(
        r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})",
        s,
    ) is None:
        raise ValueError("Not a canonical Roman numeral from 1 to 3999")

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    for i, symbol in enumerate(s):
        value = values[symbol]
        if i + 1 < len(s) and value < values[s[i + 1]]:
            total -= value
        else:
            total += value
    return total
