# Implementation (TDD step 2) — the complete solution
from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    """Wrap text into lines of at most `width` characters, greedily.

    Words are runs of characters separated by one or more U+0020 spaces.
    A word longer than `width` starts a new line and is split into pieces
    of exactly `width` characters; its final (possibly shorter) piece may
    be continued by following words that fit.

    Raises ValueError if width < 1. Empty or space-only text yields [].
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: List[str] = []
    current: List[str] = []  # words in the line being built
    current_len = 0          # length of the line being built

    for word in text.split(" "):
        if not word:
            continue  # collapse multiple spaces / ignore leading/trailing ones

        if len(word) > width:
            # A too-long word always starts on a fresh line: flush current.
            if current:
                lines.append(" ".join(current))
                current = []
                current_len = 0
            full, rest = divmod(len(word), width)
            for i in range(full):
                lines.append(word[i * width:(i + 1) * width])
            if rest:
                # Shorter last piece starts a line that may continue.
                current = [word[full * width:]]
                current_len = rest
            # If rest == 0, the word ended exactly on a full line.

        else:
            extra = len(word) + 1 if current else len(word)
            if current_len + extra <= width:
                current.append(word)
                current_len += extra
            else:
                if current:
                    lines.append(" ".join(current))
                current = [word]
                current_len = len(word)

    if current:
        lines.append(" ".join(current))
    return lines
