        first, last, step_text = match.group(1), match.group(2), match.group(3)
        step = int(step_text) if step_text is not None else 1
        if step < 1:
            raise ValueError("cron step must be >= 1: %r" % (item,))

        if first is None:                       # '*'
            start, end = low, high
        else:
            start = int(first)
            if last is not None:                # 'a-b'
                end = int(last)
                if start > end:
                    raise ValueError("descending cron range: %r" % (item,))
            elif step_text is not None:         # 'a/n' -> a .. field maximum
                end = high
            else:                               # bare 'a'
                end = start

        if not (low <= start <= high) or not (low <= end <= high):
            raise ValueError("cron value out of range: %r" % (item,))

        values.update(range(start, end + 1, step))
    return values


def _add_years(moment, years):
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:                          # 29 February
        return moment.replace(year=moment.year + years, day=28)


def next_cron(expr, after):
    """Return the earliest time matching `expr` strictly after `after`."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 cron fields, got %d" % len(fields))

    minutes, hours, days_of_month, months, days_of_week = [
        _parse_field(field, low, high)
        for field, (low, high) in zip(fields, _BOUNDS)
    ]

    # A field is "restricted" unless it is literally '*'.
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    cutoff = _add_years(after_dt, 5)
    start = after_dt + timedelta(minutes=1)

    hour_list = sorted(hours)
    minute_list = sorted(minutes)

    def matches_day(day):
        dom_ok = day.day in days_of_month
        dow_ok = ((day.weekday() + 1) % 7) in days_of_week   # cron: Sunday == 0
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        if dom_restricted:
            return dom_ok
        if dow_restricted:
            return dow_ok
        return True

    first_day = start.date()
    last_day = cutoff.date()

    day = first_day
    while day <= last_day:
        if day.month in months and matches_day(day):
            same_day = day == first_day
            for hour in hour_list:
                if same_day and hour < start.hour:
                    continue
                for minute in minute_list:
                    if same_day and hour == start.hour and minute < start.minute:
                        continue
                    candidate = datetime(day.year, day.month, day.day, hour, minute)
                    if candidate > cutoff:
                        raise ValueError("no matching time within 5 years of %s" % (after,))
                    return "%04d-%02d-%02d %02d:%02d" % (
                        candidate.year, candidate.month, candidate.day,
                        candidate.hour, candidate.minute,
                    )
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years of %s" % (after,))
