"""Next firing time of a standard 5-field cron expression.

Python 3.9+, standard library only.
"""

from datetime import datetime, timedelta

# (field name, minimum, maximum), in cron field order.
_FIELDS = (
    ("minute", 0, 59),
    ("hour", 0, 23),
    ("day of month", 1, 31),
    ("month", 1, 12),
    ("day of week", 0, 6),
)

_DIGITS = frozenset("0123456789")
_TIME_FORMAT = "%Y-%m-%d %H:%M"


def _to_int(text, what):
    """Strictly parse a non-negative decimal integer (no sign, no whitespace)."""
    if not text or any(ch not in _DIGITS for ch in text):
        raise ValueError("invalid %s: %r" % (what, text))
    return int(text)


def _parse_field(text, name, lo, hi):
    """Expand one cron field into the set of values it matches."""
    values = set()
    for item in text.split(","):
        if not item:
            raise ValueError("empty item in %s field: %r" % (name, text))

        has_step = "/" in item
        if has_step:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("malformed item in %s field: %r" % (name, item))
            base, step_text = parts
            step = _to_int(step_text, "%s step" % name)
            if step < 1:
                raise ValueError("step must be >= 1 in %s field: %r" % (name, item))
        else:
            base, step = item, 1

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            bounds = base.split("-")
            if len(bounds) != 2:
                raise ValueError("malformed range in %s field: %r" % (name, item))
            start = _to_int(bounds[0], "%s value" % name)
            end = _to_int(bounds[1], "%s value" % name)
            if start > end:
                raise ValueError("reversed range in %s field: %r" % (name, item))
        else:
            start = _to_int(base, "%s value" % name)
            # "a/n" runs from a up to the field maximum; a bare "a" is just a.
            end = hi if has_step else start

        if start < lo or end > hi:
            raise ValueError(
                "%s field value out of range %d-%d: %r" % (name, lo, hi, item)
            )
        values.update(range(start, end + 1, step))
    return values


def _parse_after(after):
    try:
        return datetime.strptime(after.strip(), _TIME_FORMAT)
    except (AttributeError, ValueError):
        raise ValueError("invalid 'after' time: %r" % (after,))


def next_cron(expr: str, after: str) -> str:
    """Return the first moment strictly after ``after`` at which ``expr`` fires.

    ``expr`` is a 5-field cron expression (minute hour day-of-month month
    day-of-week).  ``after`` is a naive local time "YYYY-MM-DD HH:MM".
    Raises ValueError for a malformed expression, a malformed ``after``,
    or when nothing fires within five years.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(
            "cron expression must have exactly 5 fields, got %d" % len(fields)
        )

    parsed = [
        _parse_field(text, name, lo, hi)
        for text, (name, lo, hi) in zip(fields, _FIELDS)
    ]
    minutes, hours, days, months, weekdays = parsed

    after_dt = _parse_after(after)

    # Standard cron semantics: a field written exactly "*" is unrestricted.
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    def day_matches(day):
        dom_hit = day.day in days
        dow_hit = (day.weekday() + 1) % 7 in weekdays  # Monday=1 .. Sunday=0
        if dom_restricted and dow_restricted:
            return dom_hit or dow_hit
        if dom_restricted:
            return dom_hit
        if dow_restricted:
            return dow_hit
        return True

    # Ascending by (hour, minute): the first hit on a day is the earliest one.
    times = [(hour, minute) for hour in sorted(hours) for minute in sorted(minutes)]

    try:
        limit = after_dt.replace(year=after_dt.year + 5)
    except ValueError:  # 29 February and the target year is not a leap year
        limit = after_dt.replace(year=after_dt.year + 5, day=28)

    day = after_dt.date()
    last_day = limit.date()
    one_day = timedelta(days=1)
    while day <= last_day:
        if day.month in months and day_matches(day):
            for hour, minute in times:
                candidate = datetime(day.year, day.month, day.day, hour, minute)
                if candidate > after_dt and candidate <= limit:
                    return candidate.strftime(_TIME_FORMAT)
        day += one_day

    raise ValueError("no firing time within 5 years for %r" % (expr,))
