"""Glob-style pattern matching for path-like strings."""


def _parse_class(pattern: str, i: int):
    """Parse a bracket expression starting at pattern[i] == '['.

    Returns (chars, negated, next_index), where next_index points just past
    the closing ']'.
    """
    n = len(pattern)
    i += 1  # skip '['

    negated = False
    if i < n and pattern[i] == '!':
        negated = True
        i += 1

    chars = set()
    first = True
    while True:
        if i >= n:
            raise ValueError("unterminated '[' in pattern")
        if pattern[i] == ']' and not first:
            i += 1
            break

        # A ']' in first position is a literal member of the set.
        if pattern[i] == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a backslash")
            lo = pattern[i + 1]
            i += 2
        else:
            lo = pattern[i]
            i += 1
        first = False

        # Possible range: X-Y (a trailing '-' before ']' stays literal).
        if i < n and pattern[i] == '-' and i + 1 < n and pattern[i + 1] != ']':
            if pattern[i + 1] == '\\':
                if i + 2 >= n:
                    raise ValueError("pattern ends with a backslash")
                hi = pattern[i + 2]
                i += 3
            else:
                hi = pattern[i + 1]
                i += 2
            if ord(hi) < ord(lo):
                raise ValueError("invalid range in pattern")
            for code in range(ord(lo), ord(hi) + 1):
                chars.add(chr(code))
        else:
            chars.add(lo)

    return chars, negated, i


def _tokenize(pattern: str):
    """Split a pattern into matching tokens, raising on malformed input."""
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a backslash")
            tokens.append(('LIT', pattern[i + 1]))
            i += 2
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            tokens.append(('DSTAR',) if j - i >= 2 else ('STAR',))
            i = j
        elif c == '?':
            tokens.append(('QMARK',))
            i += 1
        elif c == '[':
            chars, negated, i = _parse_class(pattern, i)
            tokens.append(('CLASS', frozenset(chars), negated))
        else:
            tokens.append(('LIT', c))
            i += 1
    return tokens


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches `pattern` (case-sensitive)."""
    tokens = _tokenize(pattern)
    m = len(name)

    # reachable[j] is True if the tokens consumed so far can match name[:j].
    reachable = [False] * (m + 1)
    reachable[0] = True

    for tok in tokens:
        kind = tok[0]
        nxt = [False] * (m + 1)

        if kind == 'LIT':
            ch = tok[1]
            for si in range(m):
                if reachable[si] and name[si] == ch:
                    nxt[si + 1] = True

        elif kind == 'QMARK':
            for si in range(m):
                if reachable[si] and name[si] != '/':
                    nxt[si + 1] = True

        elif kind == 'CLASS':
            chars, negated = tok[1], tok[2]
            for si in range(m):
                if reachable[si] and ((name[si] in chars) != negated):
                    nxt[si + 1] = True

        elif kind == 'STAR':
            # '*' spans any run of non-'/' characters, including nothing.
            for j in range(m + 1):
                if reachable[j]:
                    nxt[j] = True
                elif j and nxt[j - 1] and name[j - 1] != '/':
                    nxt[j] = True

        else:  # 'DSTAR'
            # '**' spans anything, so once a position is reachable, so is
            # every later position.
            for j in range(m + 1):
                if reachable[j]:
                    for k in range(j, m + 1):
                        nxt[k] = True
                    break

        reachable = nxt

    return reachable[m]
