import re


def glob_match(pattern: str, name: str) -> bool:
    parts = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("Trailing backslash in pattern")
            parts.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                parts.append(".*")
                i += 2
            else:
                parts.append("[^/]*")
                i += 1
        elif char == "?":
            parts.append("[^/]")
            i += 1
        elif char == "[":
            start = i
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            atoms = []
            if i < len(pattern) and pattern[i] == "]":
                atoms.append(("]", True))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("Trailing backslash in character set")
                    atoms.append((pattern[i], True))
                else:
                    atoms.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError(f"Unclosed character set at index {start}")
            if not atoms:
                raise ValueError(f"Empty character set at index {start}")

            content = []
            j = 0
            while j < len(atoms):
                if (
                    j + 2 < len(atoms)
                    and atoms[j + 1] == ("-", False)
                    and atoms[j][0] != "-"
                    and atoms[j + 2][0] != "-"
                ):
                    content.append(re.escape(atoms[j][0]))
                    content.append("-")
                    content.append(re.escape(atoms[j + 2][0]))
                    j += 3
                else:
                    content.append(re.escape(atoms[j][0]))
                    j += 1

            parts.append("[" + ("^" if negate else "") + "".join(content) + "]")
            i += 1
        else:
            parts.append(re.escape(char))
            i += 1

    try:
        regex = re.compile("".join(parts), re.DOTALL)
    except re.error as exc:
        raise ValueError("Invalid pattern") from exc
    return regex.fullmatch(name) is not None
