# ---------------------------------------------------------------------------
# Implementation
# ---------------------------------------------------------------------------

_NUMBER_RE = re.compile(r"[0-9]+(?:\.[0-9]+)?")
_DIGITS = "0123456789"
_WHITESPACE = " \t\n\r\v\f"
_OPERATOR_CHARS = "+-*/^"

__all__ = ["evaluate"]


def _tokenize(text):
    """Split *text* into ``(kind, value)`` pairs.

    Kinds: ``number`` (int or float), ``op`` (one of ``+-*/^``), ``lparen``,
    ``rparen``.  Whitespace is skipped.  Anything else is a ``ValueError``.
    """
    tokens = []
    index = 0
    length = len(text)
    while index < length:
        char = text[index]
        if char in _WHITESPACE:
            index += 1
        elif char in _DIGITS:
            match = _NUMBER_RE.match(text, index)
            raw = match.group()
            value = float(raw) if "." in raw else int(raw)
            tokens.append(("number", value))
            index = match.end()
        elif char in _OPERATOR_CHARS:
            tokens.append(("op", char))
            index += 1
        elif char == "(":
            tokens.append(("lparen", char))
            index += 1
        elif char == ")":
            tokens.append(("rparen", char))
            index += 1
        else:
            raise ValueError(
                "unexpected character {!r} at index {}".format(char, index)
            )
    return tokens


def _safe_divide(left, right):
    if right == 0:
        raise ValueError("division by zero")
    return left / right


def _safe_power(base, exponent):
    try:
        return base ** exponent
    except ZeroDivisionError:
        # e.g. 0 ** -1 -- a division by zero in disguise.
        raise ValueError("division by zero") from None


class _Parser(object):
    """Recursive-descent parser/evaluator over a token list."""

    def __init__(self, tokens):
        self._tokens = tokens
        self._index = 0

    # -- token helpers ----------------------------------------------------

    def _peek(self):
        if self._index < len(self._tokens):
            return self._tokens[self._index]
        return ("eof", None)

    def _advance(self):
        token = self._peek()
        self._index += 1
        return token

    # -- entry point ------------------------------------------------------

    def parse(self):
        value = self._parse_expression()
        kind, token_value = self._peek()
        if kind != "eof":
            raise ValueError("unexpected {!r} after expression".format(token_value))
        return value

    # -- grammar ----------------------------------------------------------

    def _parse_expression(self):
        value = self._parse_term()
        while True:
            kind, op = self._peek()
            if kind != "op" or op not in "+-":
                return value
            self._advance()
            right = self._parse_term()
            value = value + right if op == "+" else value - right

    def _parse_term(self):
        value = self._parse_unary()
        while True:
            kind, op = self._peek()
            if kind != "op" or op not in "*/":
                return value
            self._advance()
            right = self._parse_unary()
            value = value * right if op == "*" else _safe_divide(value, right)

    def _parse_unary(self):
        kind, op = self._peek()
        if kind == "op" and op == "-":
            self._advance()
            return -self._parse_unary()
        return self._parse_power()

    def _parse_power(self):
        base = self._parse_atom()
        kind, op = self._peek()
        if kind == "op" and op == "^":
            self._advance()
            # Right operand parsed as unary: right-associative and signed.
            return _safe_power(base, self._parse_unary())
        return base

    def _parse_atom(self):
        kind, value = self._advance()
        if kind == "number":
            return value
        if kind == "lparen":
            inner = self._parse_expression()
            kind, token_value = self._advance()
            if kind != "rparen":
                raise ValueError("expected ')' but found {!r}".format(token_value))
            return inner
        raise ValueError("expected a number or '(' but found {!r}".format(value))


def evaluate(expr):
    """Evaluate the arithmetic expression *expr* and return ``int`` or ``float``.

    Raises ``ValueError`` for malformed input and for division by zero.
    """
    return _Parser(_tokenize(expr)).parse()


if __name__ == "__main__":
    unittest.main(verbosity=2)
