import string

_DIGITS = frozenset(string.digits)
_TAG_CHARS = frozenset(string.ascii_letters + string.digits)


def compare_versions(a: str, b: str) -> int:
    def parse(version):
        if not isinstance(version, str) or not version:
            raise ValueError(f"invalid version: {version!r}")

        numeric, sep, tag = version.partition("-")

        parts = numeric.split(".")
        if not parts:
            raise ValueError(f"invalid version: {version!r}")
        for part in parts:
            if not part or any(ch not in _DIGITS for ch in part):
                raise ValueError(f"invalid version: {version!r}")
        numbers = [int(part) for part in parts]

        if sep:
            if not tag or any(ch not in _TAG_CHARS for ch in tag):
                raise ValueError(f"invalid version: {version!r}")
            return numbers, tag
        return numbers, None

    na, ta = parse(a)
    nb, tb = parse(b)

    width = max(len(na), len(nb))
    na = na + [0] * (width - len(na))
    nb = nb + [0] * (width - len(nb))

    if na != nb:
        return -1 if na < nb else 1

    if ta is None and tb is None:
        return 0
    if ta is None:
        return 1
    if tb is None:
        return -1
    if ta == tb:
        return 0
    return -1 if ta < tb else 1
