import re

_SCHEME_RE = re.compile(r"\A([A-Za-z][A-Za-z0-9+.\-]*)://")

_BAD_HOST_CHARS = frozenset(" /?#@:[]")


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("URL must be a string")

    m = _SCHEME_RE.match(url)
    if m is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = m.group(1).lower()

    tail = url[m.end():]

    # Authority: up to the first '/', '?' or '#' (or the end of the string).
    stop = len(tail)
    for i, ch in enumerate(tail):
        if ch == "/" or ch == "?" or ch == "#":
            stop = i
            break
    authority = tail[:stop]
    if authority == "":
        raise ValueError("empty authority")
    rest = tail[stop:]

    # userinfo: everything before the LAST '@', else "".
    at = authority.rfind("@")
    if at != -1:
        userinfo = authority[:at]
        hostport = authority[at + 1:]
    else:
        userinfo = ""
        hostport = authority

    # host and optional port
    if hostport.startswith("["):
        close = hostport.find("]")
        if close == -1:
            raise ValueError("unterminated IPv6 literal")
        inner = hostport[1:close]
        if inner == "":
            raise ValueError("empty IPv6 literal")
        for ch in inner:
            if ch.isspace() or ch in "[]":
                raise ValueError("invalid character in IPv6 literal")
        host = inner.lower()
        remainder = hostport[close + 1:]
        if remainder != "" and not remainder.startswith(":"):
            raise ValueError("unexpected characters after host")
    else:
        colon = hostport.find(":")
        if colon == -1:
            host = hostport
            remainder = ""
        else:
            host = hostport[:colon]
            remainder = hostport[colon:]
        if host == "":
            raise ValueError("empty host")
        for ch in host:
            if ch in _BAD_HOST_CHARS or ch.isspace():
                raise ValueError("invalid character in host")
        host = host.lower()

    # port
    if remainder == "":
        port = None
    else:
        digits = remainder[1:]
        if not (1 <= len(digits) <= 5):
            raise ValueError("invalid port")
        for ch in digits:
            if not ("0" <= ch <= "9"):
                raise ValueError("invalid port")
        port = int(digits)
        if not (1 <= port <= 65535):
            raise ValueError("port out of range")

    # path / query / fragment
    hash_pos = rest.find("#")
    if hash_pos == -1:
        fragment = ""
        before_hash = rest
    else:
        fragment = rest[hash_pos + 1:]
        before_hash = rest[:hash_pos]

    q_pos = before_hash.find("?")
    if q_pos == -1:
        query = ""
        path = before_hash
    else:
        query = before_hash[q_pos + 1:]
        path = before_hash[:q_pos]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
