import re


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)


def _parse_version(text):
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError("invalid semantic version")

    major, minor, patch = (int(match.group(i)) for i in range(1, 4))
    prerelease_text = match.group(4)
    prerelease = None

    if prerelease_text is not None:
        prerelease = tuple(prerelease_text.split("."))
        if any(
            identifier.isdigit()
            and len(identifier) > 1
            and identifier.startswith("0")
            for identifier in prerelease
        ):
            raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return (major, minor, patch), prerelease


def _compare_prerelease(left, right):
    if left is None:
        return 0 if right is None else 1
    if right is None:
        return -1

    for a, b in zip(left, right):
        a_numeric = a.isdigit()
        b_numeric = b.isdigit()

        if a_numeric and b_numeric:
            a_value, b_value = int(a), int(b)
            if a_value != b_value:
                return -1 if a_value < b_value else 1
        elif a_numeric != b_numeric:
            return -1 if a_numeric else 1
        elif a != b:
            return -1 if a < b else 1

    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left, right):
    if left[0] != right[0]:
        return -1 if left[0] < right[0] else 1
    return _compare_prerelease(left[1], right[1])


def semver_satisfies(version: str, constraint: str) -> bool:
    version_core, version_prerelease = _parse_version(version)

    if not constraint or not constraint.strip():
        raise ValueError("constraint cannot be empty")

    groups = constraint.split("||")
    parsed_groups = []

    for group in groups:
        tokens = group.split()
        if not tokens:
            raise ValueError("constraint contains an empty group")

        comparators = []
        for token in tokens:
            if token == "*":
                comparators.append(("*", None, None))
                continue

            operator = "="
            value = token
            for candidate in (">=", "<=", ">", "<", "^", "~", "="):
                if token.startswith(candidate):
                    operator = candidate
                    value = token[len(candidate):]
                    break

            if not value:
                raise ValueError("invalid comparator")

            comparator_core, comparator_prerelease = _parse_version(value)
            comparators.append((operator, comparator_core, comparator_prerelease))

        parsed_groups.append(comparators)

    for comparators in parsed_groups:
        matches = True
        allows_prerelease = False

        for operator, comparator_core, comparator_prerelease in comparators:
            if operator == "*":
                continue

            if comparator_prerelease is not None and comparator_core == version_core:
                allows_prerelease = True

            comparison = _compare_versions(
                (version_core, version_prerelease),
                (comparator_core, comparator_prerelease),
            )

            if operator == "=":
                satisfied = comparison == 0
            elif operator == ">":
                satisfied = comparison > 0
            elif operator == ">=":
                satisfied = comparison >= 0
            elif operator == "<":
                satisfied = comparison < 0
            elif operator == "<=":
                satisfied = comparison <= 0
            elif operator == "^":
                satisfied = comparison >= 0
                major, minor, patch = comparator_core
                if major > 0:
                    upper = ((major + 1, 0, 0), None)
                elif minor > 0:
                    upper = ((0, minor + 1, 0), None)
                else:
                    upper = ((0, 0, patch + 1), None)
                satisfied = satisfied and _compare_versions(
                    (version_core, version_prerelease), upper
                ) < 0
            else:  # "~"
                satisfied = comparison >= 0
                upper = ((comparator_core[0], comparator_core[1] + 1, 0), None)
                satisfied = satisfied and _compare_versions(
                    (version_core, version_prerelease), upper
                ) < 0

            if not satisfied:
                matches = False
                break

        if matches and (version_prerelease is None or allows_prerelease):
            return True

    return False
