def evaluate(expr: str):
    def is_digit(ch):
        return '0' <= ch <= '9'

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if is_digit(c):
            j = i
            while j < n and is_digit(expr[j]):
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                if j >= n or not is_digit(expr[j]):
                    raise ValueError("malformed number")
                while j < n and is_digit(expr[j]):
                    j += 1
                tokens.append(('num', float(expr[i:j])))
            else:
                tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append((c,))
            i += 1
            continue
        raise ValueError("unknown character")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def parse_expr():
        v = parse_term()
        while True:
            t = peek()
            if t is not None and t[0] in '+-':
                advance()
                r = parse_term()
                v = v + r if t[0] == '+' else v - r
            else:
                return v

    def parse_term():
        v = parse_unary()
        while True:
            t = peek()
            if t is not None and t[0] in '*/':
                op = t[0]
                advance()
                r = parse_unary()
                try:
                    v = v * r if op == '*' else v / r
                except ZeroDivisionError:
                    raise ValueError("division by zero")
            else:
                return v

    def parse_unary():
        t = peek()
        if t is not None and t[0] == '-':
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        t = peek()
        if t is not None and t[0] == '^':
            advance()
            exp = parse_unary()
            try:
                return base ** exp
            except ZeroDivisionError:
                raise ValueError("division by zero")
        return base

    def parse_atom():
        t = peek()
        if t is None:
            raise ValueError("unexpected end of input")
        if t[0] == 'num':
            advance()
            return t[1]
        if t[0] == '(':
            advance()
            v = parse_expr()
            t2 = peek()
            if t2 is None or t2[0] != ')':
                raise ValueError("unbalanced parentheses")
            advance()
            return v
        raise ValueError("unexpected token")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token")
    return result
