import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Gather every node mentioned, as a key or inside a dependency list.
    nodes = set(deps)
    for dep_list in deps.values():
        nodes.update(dep_list)

    # Distinct dependencies per item (duplicates ignored).
    dep_set = {item: set(dep_list) for item, dep_list in deps.items()}

    indeg = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    for item, dset in dep_set.items():
        for dep in dset:
            # edge dep -> item: dep must be placed before item
            indeg[item] += 1
            dependents[dep].append(item)

    # Nodes with no outstanding dependencies, always take the smallest first.
    ready = [node for node in nodes if indeg[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for nxt in dependents[node]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(ready, nxt)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")

    return order
