import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether name matches the path-like glob pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(r"[\s\S]*")
                i += 2
            else:
                regex.append(r"[^/]*")
                i += 1
        elif char == "?":
            regex.append(r"[^/]")
            i += 1
        elif char == "[":
            i += 1
            negated = i < len(pattern) and pattern[i] == "!"
            if negated:
                i += 1

            members = []
            if i < len(pattern) and pattern[i] == "]":
                members.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in pattern")
                    members.append((pattern[i], True))
                    i += 1
                else:
                    members.append((pattern[i], False))
                    i += 1

            if i == len(pattern):
                raise ValueError("unclosed character class")

            if not members:
                raise ValueError("empty character class")

            class_parts = ["^"] if negated else []
            for index, (member, escaped) in enumerate(members):
                if member == "-" and not escaped and 0 < index < len(members) - 1:
                    class_parts.append("-")
                else:
                    class_parts.append(re.escape(member))

            regex.append("[" + "".join(class_parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    return re.fullmatch("".join(regex), name, flags=re.DOTALL) is not None
