import unittest


def wrap_text(text: str, width: int):
    """Greedily wrap `text` into lines of at most `width` characters.

    Words are runs of characters separated by one or more U+0020 spaces.
    A word longer than `width` starts on a fresh line and is chopped into
    consecutive pieces of exactly `width` characters; its (possibly shorter)
    final piece starts a line that later words may join if they fit.
    """
    if width < 1:
        raise ValueError("width must be >= 1")

    words = [w for w in text.split(" ") if w]
    lines = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                lines.append(current)
                current = ""
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current = pieces[-1]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)
    return lines


if __name__ == "__main__":
    class TestWrapText(unittest.TestCase):
        def test_empty_and_space_only(self):
            self.assertEqual(wrap_text("", 5), [])
            self.assertEqual(wrap_text("   ", 5), [])
            self.assertEqual(wrap_text("      ", 1), [])

        def test_width_less_than_one_raises(self):
            for bad in (0, -1, -100):
                with self.assertRaises(ValueError):
                    wrap_text("anything", bad)

        def test_single_word_fits(self):
            self.assertEqual(wrap_text("hello", 5), ["hello"])
            self.assertEqual(wrap_text("hello", 100), ["hello"])

        def test_greedy_packing(self):
            self.assertEqual(
                wrap_text("the quick brown fox", 10),
                ["the quick", "brown fox"],
            )
            self.assertEqual(wrap_text("a b c", 3), ["a b", "c"])

        def test_no_leading_or_trailing_spaces(self):
            for line in wrap_text("  hello   world  ", 5):
                self.assertEqual(line, line.strip(" "))
            self.assertEqual(wrap_text("  hello   world  ", 5), ["hello", "world"])

        def test_multiple_spaces_collapse_to_one(self):
            self.assertEqual(wrap_text("a    b     c", 3), ["a b", "c"])

        def test_only_u0020_is_a_separator(self):
            self.assertEqual(wrap_text("a\tb c", 10), ["a\tb c"])
            self.assertEqual(wrap_text("ab\ncd", 10), ["ab\ncd"])

        def test_long_word_is_split_into_exact_width_pieces(self):
            self.assertEqual(
                wrap_text("supercalifragilistic", 5),
                ["super", "calif", "ragil", "istic"],
            )

        def test_long_word_pieces_are_exactly_width(self):
            lines = wrap_text("a" * 10, 3)
            self.assertEqual(lines, ["aaa", "aaa", "aaa", "a"])
            for line in lines[:-1]:
                self.assertEqual(len(line), 3)

        def test_long_word_length_multiple_of_width(self):
            self.assertEqual(wrap_text("abcdef", 3), ["abc", "def"])

        def test_long_word_starts_on_new_line(self):
            self.assertEqual(
                wrap_text("ab cdefghij", 4),
                ["ab", "cdef", "ghij"],
            )

        def test_last_piece_of_long_word_accepts_following_words(self):
            self.assertEqual(
                wrap_text("abcdefgh i j", 3),
                ["abc", "def", "gh i j"],
            )
            self.assertEqual(
