        elif c == "[":
            i += 1
            negate = False
            if i < n and pattern[i] == "!":
                negate = True
                i += 1
            chars = set()
            first = True
            while True:
                if i >= n:
                    raise ValueError("unterminated character class")
                ch = pattern[i]
                if ch == "]" and not first:
                    i += 1
