                        chars.add(chr(code))
                else:
                    chars.add(lo)
                first = False
            tokens.append(("class", negate, frozenset(chars)))
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches the glob `pattern`.

    `*` matches any run of characters without `/`; `**` matches any run of
    characters including `/`; `?` matches one non-`/` character; `[...]`
    matches one character from a (possibly negated, possibly ranged) set;
    a backslash escapes the following pattern character.  Matching is
    case-sensitive and anchored at both ends.
    """
    tokens = _tokenize(pattern)
    t_count = len(tokens)
