        kind = tok[0]
        cur = [False] * (m + 1)
        if kind == "lit":
            ch = tok[1]
            for j in range(m - 1, -1, -1):
                cur[j] = name[j] == ch and nxt[j + 1]
        elif kind == "q":
            for j in range(m - 1, -1, -1):
                cur[j] = name[j] != "/" and nxt[j + 1]
        elif kind == "star":
            cur[m] = nxt[m]
            for j in range(m - 1, -1, -1):
                cur[j] = nxt[j] or (name[j] != "/" and cur[j + 1])
        elif kind == "dstar":
            cur[m] = nxt[m]
            for j in range(m - 1, -1, -1):
                cur[j] = nxt[j] or cur[j + 1]
        else:  # ("class", negate, chars)
            negate, chars = tok[1], tok[2]
            for j in range(m - 1, -1, -1):
                hit = name[j] in chars
                if negate:
                    hit = not hit
                cur[j] = hit and nxt[j + 1]
