import heapq

def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    items = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    remaining = {item: set(deps.get(item, ())) for item in items}

    for item, rem in remaining.items():
        if item in rem:
            raise ValueError(f"self-dependency: {item!r}")

    dependents = {item: [] for item in items}
    for item, rem in remaining.items():
        for dep in rem:
            dependents[dep].append(item)

    heap = [item for item in items if not remaining[item]]
    heapq.heapify(heap)

    result = []
    while heap:
        item = heapq.heappop(heap)
        result.append(item)
        for dependent in dependents[item]:
            remaining[dependent].discard(item)
            if not remaining[dependent]:
