def glob_match(pattern: str, name: str) -> bool:
    """Return whether the entire path-like name matches the glob pattern."""
    tokens: List[Token] = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("pattern ends with an escape")
            tokens.append(("literal", pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                tokens.append(("globstar",))
                i += 2
            else:
                tokens.append(("star",))
                i += 1
        elif char == "?":
            tokens.append(("question",))
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            elements = []
            if i < len(pattern) and pattern[i] == "]":
                elements.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("pattern ends with an escape")
                    elements.append((pattern[i], True))
                    i += 1
                else:
                    elements.append((pattern[i], False))
                    i += 1

            if i == len(pattern):
                raise ValueError("unterminated character class")
            i += 1

            singles = []
            ranges = []
            j = 0
            while j < len(elements):
                if (
                    j + 2 < len(elements)
                    and elements[j + 1] == ("-", False)
                ):
                    start = elements[j][0]
                    end = elements[j + 2][0]
                    if ord(start) > ord(end):
                        raise ValueError("reversed character range")
                    ranges.append((start, end))
                    j += 3
                else:
                    singles.append(elements[j][0])
                    j += 1

            tokens.append(("class", negate, tuple(singles), tuple(ranges)))
        else:
            tokens.append(("literal", char))
            i += 1

    @lru_cache(maxsize=None)
    def matches(token_index: int, name_index: int) -> bool:
        if token_index == len(tokens):
            return name_index == len(name)

        token = tokens[token_index]
        kind = token[0]

        if kind == "literal":
            return (
                name_index < len(name)
                and name[name_index] == token[1]
                and matches(token_index + 1, name_index + 1)
            )

        if kind == "question":
            return (
                name_index < len(name)
                and name[name_index] != "/"
                and matches(token_index + 1, name_index + 1)
            )

        if kind in ("star", "globstar"):
            if matches(token_index + 1, name_index):
                return True
            return (
                name_index < len(name)
                and (kind == "globstar" or name[name_index] != "/")
                and matches(token_index, name_index + 1)
            )

        _, negate, singles, ranges = token
        if name_index == len(name):
            return False
        char = name[name_index]
        in_set = char in singles or any(
            start <= char <= end for start, end in ranges
        )
        return (
            (not in_set if negate else in_set)
            and matches(token_index + 1, name_index + 1)
        )

    return matches(0, 0)
