def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    pos = 0
    length = len(expr)

    def skip_whitespace():
        nonlocal pos
        while pos < length and expr[pos].isspace():
            pos += 1

    def peek():
        skip_whitespace()
        return expr[pos] if pos < length else ""

    def parse_number():
        nonlocal pos
        skip_whitespace()
        start = pos

        while pos < length and "0" <= expr[pos] <= "9":
            pos += 1

        is_decimal = False
        if pos < length and expr[pos] == ".":
            is_decimal = True
            pos += 1
            fraction_start = pos
            while pos < length and "0" <= expr[pos] <= "9":
                pos += 1
            if pos == fraction_start:
                raise ValueError("invalid decimal literal")

        if pos == start:
            raise ValueError("expected a number")

        text = expr[start:pos]
        return float(text) if is_decimal else int(text)

    def parse_primary():
        nonlocal pos
        token = peek()
        if token == "(":
            pos += 1
            value = parse_sum()
            if peek() != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        if "0" <= token <= "9":
            return parse_number()
        raise ValueError("expected a number or parenthesized expression")

    def parse_power():
        nonlocal pos
        value = parse_primary()
        if peek() == "^":
            pos += 1
            value = value ** parse_unary()
        return value

    def parse_unary():
        nonlocal pos
        if peek() == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_product():
        nonlocal pos
        value = parse_unary()
        while peek() in ("*", "/"):
            operator = peek()
            pos += 1
            right = parse_unary()
            if operator == "*":
                value *= right
            else:
                try:
                    value /= right
                except ZeroDivisionError as exc:
                    raise ValueError("division by zero") from exc
        return value

    def parse_sum():
        nonlocal pos
        value = parse_product()
        while peek() in ("+", "-"):
            operator = peek()
            pos += 1
            right = parse_product()
            value = value + right if operator == "+" else value - right
        return value

    skip_whitespace()
    if pos == length:
        raise ValueError("empty expression")

    result = parse_sum()
    if peek():
        raise ValueError("unexpected token")
    return result
