                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(r"[\s\S]*")
                i += 2
            else:
                regex.append(r"[^/]*")
                i += 1
        elif char == "?":
            regex.append(r"[^/]")
            i += 1
        elif char == "[":
            start = i
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            atoms = []
            if i < len(pattern) and pattern[i] == "]":
                atoms.append(("]", False))
                i += 1

            while i < len(pattern):
                if pattern[i] == "]":
                    break
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in pattern")
                    atoms.append((pattern[i], True))
                else:
                    atoms.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError(f"unterminated character set at index {start}")
            if not atoms:
                raise ValueError(f"empty character set at index {start}")

            parts = []
            j = 0
            while j < len(atoms):
                if (
                    j + 2 < len(atoms)
                    and atoms[j + 1] == ("-", False)
                    and atoms[j][0] != "-"
                    and atoms[j + 2][0] != "-"
                ):
                    first = re.escape(atoms[j][0])
                    last = re.escape(atoms[j + 2][0])
                    if ord(atoms[j][0]) > ord(atoms[j + 2][0]):
                        raise ValueError(f"invalid character range at index {start}")
                    parts.append(first + "-" + last)
                    j += 3
                else:
                    parts.append(re.escape(atoms[j][0]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    return re.fullmatch("".join(regex), name) is not None
