import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    dep_counts: dict[str, int] = {}
    dependents: dict[str, list[str]] = {node: [] for node in nodes}

    for node in nodes:
        unique_deps = set(deps.get(node, ()))
        dep_counts[node] = len(unique_deps)
        for d in unique_deps:
            dependents[d].append(node)

    heap = [node for node, count in dep_counts.items() if count == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for succ in dependents[node]:
            dep_counts[succ] -= 1
            if dep_counts[succ] == 0:
                heapq.heappush(heap, succ)

    if len(result) != len(nodes):
        raise ValueError("cycle detected in dependencies")

    return result
