def evaluate(expr: str):
    # ---------- Tokenizer ----------
    digits = "0123456789"
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in digits:
            start = i
            while i < n and expr[i] in digits:
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                if i >= n or expr[i] not in digits:
                    raise ValueError("malformed decimal literal")
                while i < n and expr[i] in digits:
                    i += 1
                tokens.append(("num", float(expr[start:i])))
            else:
                tokens.append(("num", int(expr[start:i])))
            continue
        if ch in "+-*/^":
            tokens.append(("op", ch))
            i += 1
            continue
        if ch == "(":
            tokens.append(("lp", ch))
            i += 1
            continue
        if ch == ")":
            tokens.append(("rp", ch))
            i += 1
            continue
        raise ValueError("unknown character: %r" % (ch,))

    # ---------- Recursive-descent parser ----------
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else ("eof", "")

    def advance():
        nonlocal pos
        tok = peek()
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while True:
            tok = peek()
            if tok[0] == "op" and (tok[1] == "+" or tok[1] == "-"):
                advance()
                rhs = parse_term()
                value = value + rhs if tok[1] == "+" else value - rhs
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            tok = peek()
            if tok[0] == "op" and (tok[1] == "*" or tok[1] == "/"):
                advance()
                rhs = parse_unary()
                if tok[1] == "*":
                    value = value * rhs
                else:
                    try:
                        value = value / rhs
                    except ZeroDivisionError:
                        raise ValueError("division by zero") from None
            else:
                return value

    def parse_unary():
        negate = False
        while True:
            tok = peek()
            if tok[0] == "op" and tok[1] == "-":
                advance()
                negate = not negate
            else:
                break
        value = parse_power()
        return -value if negate else value

    def parse_power():
        base = parse_atom()
        tok = peek()
        if tok[0] == "op" and tok[1] == "^":
            advance()
            exponent = parse_unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero") from None
        return base

    def parse_atom():
        tok = peek()
        if tok[0] == "num":
            advance()
            return tok[1]
        if tok[0] == "lp":
            advance()
            value = parse_expr()
            if peek()[0] != "rp":
                raise ValueError("unbalanced parentheses")
            advance()
            return value
        raise ValueError("expected a number or '('")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token")
    return result
