"""Semantic Versioning 2.0 ordering plus npm-style constraint matching.

Public API:
    semver_satisfies(version: str, constraint: str) -> bool

Standard library only, Python 3.9 compatible.
"""

import re

__all__ = ["semver_satisfies"]

# --------------------------------------------------------------------------
# Version parsing
# --------------------------------------------------------------------------

# A numeric component of MAJOR.MINOR.PATCH: no leading zeros, no sign.
_NUM = r"(?:0|[1-9][0-9]*)"

_VERSION_RE = re.compile(
    r"(?P<major>" + _NUM + r")\."
    r"(?P<minor>" + _NUM + r")\."
    r"(?P<patch>" + _NUM + r")"
    r"(?:-(?P<pre>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+(?P<build>[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)", re.DOTALL)

_DIGITS = frozenset("0123456789")


def _is_numeric_identifier(text):
    """True when every character of a (non-empty) prerelease identifier is a digit."""
    for ch in text:
        if ch not in _DIGITS:
            return False
    return True


def _parse_version(text):
    """Parse a version string into (major, minor, patch, prerelease_ids).

    ``prerelease_ids`` is ``None`` for a normal release, or a list of identifier
    strings. Build metadata is validated but discarded.

    Raises ValueError on anything that is not a strict SemVer 2.0 version.
    """
    if not isinstance(text, str):
        raise ValueError("version must be a string: %r" % (text,))

    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))

    pre_text = match.group("pre")
    if pre_text is None:
        pre_ids = None
    else:
        pre_ids = pre_text.split(".")
        for identifier in pre_ids:
            # Numeric identifiers must not carry leading zeros ("0" is fine).
            if (
                len(identifier) > 1
                and identifier[0] == "0"
                and _is_numeric_identifier(identifier)
            ):
                raise ValueError("invalid version: %r" % (text,))

    return (
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        pre_ids,
    )


# --------------------------------------------------------------------------
# Ordering (SemVer 2.0 precedence rules)
# --------------------------------------------------------------------------


def _compare_prerelease(left, right):
    """Compare two prerelease identifier lists; returns -1, 0 or 1."""
    for left_id, right_id in zip(left, right):
        if left_id == right_id:
            continue

        left_numeric = _is_numeric_identifier(left_id)
        right_numeric = _is_numeric_identifier(right_id)

        if left_numeric and right_numeric:
            left_value = int(left_id)
            right_value = int(right_id)
            if left_value != right_value:
                return -1 if left_value < right_value else 1
            continue

        if left_numeric:
            # numeric identifiers always rank below alphanumeric ones
            return -1
        if right_numeric:
            return 1

        return -1 if left_id < right_id else 1  # ASCII comparison

    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left, right):
    """Total ordering over parsed versions; returns -1, 0 or 1."""
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1

    left_pre = left[3]
    right_pre = right[3]

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1  # release > prerelease
    if right_pre is None:
        return -1
    return _compare_prerelease(left_pre, right_pre)


# --------------------------------------------------------------------------
# Comparator handling
# --------------------------------------------------------------------------


def _caret_upper_bound(version):
    """Upper bound (exclusive) for the '^' operator."""
    major, minor, patch = version[0], version[1], version[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper_bound(version):
    """Upper bound (exclusive) for the '~' operator."""
    return (version[0], version[1] + 1, 0, None)


def _parse_comparator(token):
    """Return (operator, parsed_version_or_None); '*' yields ('*', None)."""
    if token == "*":
        return ("*", None)

    match = _COMPARATOR_RE.fullmatch(token)
    if match is None:
        raise ValueError("invalid comparator: %r" % (token,))

    operator = match.group(1) or "="
    version_text = match.group(2)
    if version_text == "":
        raise ValueError("invalid comparator: %r" % (token,))

    return (operator, _parse_version(version_text))


def _parse_constraint(constraint):
    """Return a list of groups, each a list of (operator, version) pairs."""
    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string: %r" % (constraint,))

    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty comparator group in constraint: %r" % (constraint,))
        groups.append([_parse_comparator(token) for token in tokens])
    return groups


def _satisfies_comparator(operator, bound, version):
    """Ordering check for a single comparator (ignoring the prerelease rule)."""
    order = _compare_versions(version, bound)

    if operator == "=":
        return order == 0
    if operator == ">":
        return order > 0
    if operator == ">=":
        return order >= 0
    if operator == "<":
        return order < 0
    if operator == "<=":
        return order <= 0
    if operator == "^":
        if order < 0:
            return False
        return _compare_versions(version, _caret_upper_bound(bound)) < 0
    if operator == "~":
        if order < 0:
            return False
        return _compare_versions(version, _tilde_upper_bound(bound)) < 0

    raise ValueError("invalid comparator operator: %r" % (operator,))


def _group_matches(group, version):
    """True when every comparator holds and the prerelease rule is honoured."""
    for operator, bound in group:
        if operator == "*":
            continue
        if not _satisfies_comparator(operator, bound, version):
            return False

    # A prerelease version can only match a group that explicitly opts in by
    # writing a prerelease on the very same MAJOR.MINOR.PATCH somewhere.
    if version[3] is not None:
        for operator, bound in group:
            if (
                bound is not None
                and bound[3] is not None
                and bound[0] == version[0]
                and bound[1] == version[1]
                and bound[2] == version[2]
            ):
                return True
        return False

    return True


# --------------------------------------------------------------------------
# Public API
# --------------------------------------------------------------------------


def semver_satisfies(version, constraint):
    """Check a semantic version against an npm-style constraint.

    >>> semver_satisfies("1.2.3", "^1.0.0")
    True
    >>> semver_satisfies("1.0.0-alpha", "<1.0.0")
    False

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty / malformed constraint.
    """
    parsed_version = _parse_version(version)
    groups = _parse_constraint(constraint)

    for group in groups:
        if _group_matches(group, parsed_version):
            return True
    return False
