def first_bracket_error(s: str) -> int:
    matching = {')': '(', ']': '[', '}': '{'}
    openers = {'(', '[', '{'}
    stack = []  # (index, char) of currently unclosed opening brackets
    for i, ch in enumerate(s):
        if ch in openers:
            stack.append((i, ch))
        elif ch in matching:
            if not stack or stack[-1][1] != matching[ch]:
                return i
            stack.pop()
    if stack:
        # Leftmost still-unclosed opener is at the bottom of the stack.
        return stack[0][0]
    return -1
