            dependents[d].append(n)

    # A self-dependency leaves pending[n] >= 1 forever, so it surfaces as a
    # cycle below; this also catches longer cycles and nodes downstream of them.
    ready = [n for n in nodes if pending[n] == 0]
    heapq.heapify(ready)

    order: list[str] = []
    while ready:
        n = heapq.heappop(ready)  # smallest available, lexicographically
        order.append(n)
        for m in dependents[n]:
            pending[m] -= 1
            if pending[m] == 0:
                heapq.heappush(ready, m)

    if len(order) != len(nodes):
        raise ValueError("dependency cycle detected")
    return order
