"""Strict canonical Roman numeral conversion (values 1..3999)."""

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}

# Greedy table for the unique canonical form of every value in 1..3999.
_TABLE = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def _to_canonical(n: int) -> str:
    """Return the canonical Roman numeral for 1 <= n <= 3999."""
    if not 1 <= n <= 3999:
        raise ValueError("out of canonical range: %r" % (n,))
    parts = []
    for value, symbol in _TABLE:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def roman_to_int(s: str) -> int:
    """Convert a canonical uppercase Roman numeral (1..3999) to an int.

    Raises ValueError for the empty string, non-string input, lowercase or
    otherwise invalid characters, and any non-canonical spelling such as
    "IIII", "IC", "VX", "IIV", "XXXX" or "MMMM".
    """
    if not isinstance(s, str):
        raise ValueError("Roman numeral must be a str, got %r" % (s,))
    if not s:
        raise ValueError("empty string is not a Roman numeral")

    total = 0
    previous = 0
    for char in s:
        value = _VALUES.get(char)
        if value is None:
            raise ValueError("invalid character %r in %r" % (char, s))
        total += value
        if value > previous:      # subtractive pair: undo the earlier addition twice
            total -= 2 * previous
        previous = value

    # The canonical spelling of any value is unique, so round-tripping is an
    # exact test for canonical form (and rejects everything below 1 or above
    # 3999, since no canonical numeral exists there).
    try:
        canonical = _to_canonical(total)
    except ValueError:
        raise ValueError("%r is not a canonical Roman numeral" % (s,)) from None
    if canonical != s:
        raise ValueError(
            "%r is not the canonical form of %d (expected %r)" % (s, total, canonical)
        )
    return total
