import bisect
import calendar
import re
from datetime import datetime, timedelta


_ITEM_RE = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_AFTER_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")


def _parse_field(field: str, minimum: int, maximum: int):
    values = set()

    def parse_value(text: str) -> int:
        # Avoid converting arbitrarily long integers.
        significant = text.lstrip("0") or "0"
        if len(significant) > len(str(maximum)):
            raise ValueError("Field value out of range")
        value = int(significant)
        if not minimum <= value <= maximum:
            raise ValueError("Field value out of range")
        return value

    for item in field.split(","):
        match = _ITEM_RE.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item")

        base, step_text = match.groups()

        if step_text is None:
            step = 1
        else:
            significant = step_text.lstrip("0")
            if not significant:
                raise ValueError("Step must be positive")

            # Any step larger than the field's width selects only its start.
            width = maximum - minimum + 1
            if len(significant) > len(str(width)):
                step = width
            else:
                step = min(int(significant), width)

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start_text, end_text = base.split("-")
            start = parse_value(start_text)
            end = parse_value(end_text)
            if start > end:
                raise ValueError("Reversed cron range")
        else:
            start = parse_value(base)
            end = maximum if step_text is not None else start

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Expected exactly five cron fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(fields, bounds)
    ]

    if _AFTER_RE.fullmatch(after) is None:
        raise ValueError("Expected YYYY-MM-DD HH:MM")
    start = datetime.strptime(after, "%Y-%m-%d %H:%M")

    # Use the fifth calendar anniversary as the inclusive search limit.
    # A February 29 anniversary falls on February 28 in a non-leap year.
    if start.year + 5 <= 9999:
        limit_year = start.year + 5
        limit_day = min(
            start.day, calendar.monthrange(limit_year, start.month)[1]
        )
        limit = start.replace(year=limit_year, day=limit_day)
    else:
        limit = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    day = start.date()
    last_day = limit.date()
    start_minute = start.hour * 60 + start.minute
    limit_minute = limit.hour * 60 + limit.minute

    while day <= last_day:
        if day.month in months:
            dom_matches = day.day in month_days
            dow_matches = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect.bisect_right(times, start_minute)
                    if day == start.date()
                    else 0
                )
                if index < len(times):
                    minute_of_day = times[index]
                    if day < last_day or minute_of_day <= limit_minute:
                        hour, minute = divmod(minute_of_day, 60)
                        return (
                            f"{day.year:04d}-{day.month:02d}-{day.day:02d} "
                            f"{hour:02d}:{minute:02d}"
                        )

        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("No matching time within five years")
