import re

_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+\-.]*)://")
_HOST_FORBIDDEN = frozenset(" /?#@:[]")
_DIGITS = frozenset("0123456789")


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    m = _SCHEME_RE.match(url)
    if m is None:
        raise ValueError("URL must start with a scheme followed by '://'")

    scheme = m.group(1).lower()
    rest = url[m.end():]

    # Authority: everything up to the first '/', '?' or '#' (or the end).
    cut = len(rest)
    for i, ch in enumerate(rest):
        if ch == "/" or ch == "?" or ch == "#":
            cut = i
            break
    authority = rest[:cut]
    rest = rest[cut:]

    if authority == "":
        raise ValueError("authority must be non-empty")

    # userinfo: everything before the LAST '@', returned as is.
    at = authority.rfind("@")
    if at == -1:
        userinfo = ""
        hostport = authority
    else:
        userinfo = authority[:at]
        hostport = authority[at + 1:]

    if hostport.startswith("["):
        end = hostport.find("]")
        if end == -1:
            raise ValueError("unterminated IPv6 literal")
        host = hostport[1:end]
        if host == "":
            raise ValueError("empty host")
        host = host.lower()
        remainder = hostport[end + 1:]
    else:
        i = 0
        n = len(hostport)
        while i < n and hostport[i] != ":":
            i += 1
        host = hostport[:i]
        if host == "":
            raise ValueError("empty host")
        for ch in host:
            if ch in _HOST_FORBIDDEN:
                raise ValueError("invalid character in host")
        host = host.lower()
        remainder = hostport[i:]

    if remainder == "":
        port = None
    else:
        if not remainder.startswith(":"):
            raise ValueError("invalid trailing characters after host")
        digits = remainder[1:]
        if not (1 <= len(digits) <= 5):
            raise ValueError("invalid port")
        for ch in digits:
            if ch not in _DIGITS:
                raise ValueError("invalid port")
        port = int(digits)
        if not (1 <= port <= 65535):
            raise ValueError("port out of range")

    # Fragment: everything after the first '#'.
    hash_i = rest.find("#")
    if hash_i == -1:
        before_hash = rest
        fragment = ""
    else:
        before_hash = rest[:hash_i]
        fragment = rest[hash_i + 1:]

    # Query: everything after the first '?' that precedes the fragment.
    q_i = before_hash.find("?")
    if q_i == -1:
        path = before_hash
        query = ""
    else:
        path = before_hash[:q_i]
        query = before_hash[q_i + 1:]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
