from typing import List, Optional, Tuple


def earliest_slot(
    busy: List[Tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest free start time within [start, end], if any."""
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, even when the window cannot fit the meeting.
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")

    candidate = start
    if candidate + duration > end:
        return None

    # sorted() creates a new list, preserving the caller's input.
    for begin, finish in sorted(busy):
        if finish <= candidate:
            continue

        if candidate + duration <= begin:
            return candidate

        # This interval overlaps the proposed meeting. No earlier start
        # at or after candidate can fit before this interval finishes.
        candidate = finish
        if candidate + duration > end:
            return None

    return candidate
