def is_valid_ipv4(s: str) -> bool:
    """Return True iff s is a valid dotted-quad IPv4 address in strict ASCII form."""
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        # Length must be 1..3 characters (also rejects the empty part).
        if not (1 <= len(part) <= 3):
            return False

        # Explicit ASCII 0-9 check: str.isdigit() would wrongly accept
        # Unicode digits such as '١' (Arabic-Indic) or '²' (superscript).
        for ch in part:
            if not ("0" <= ch <= "9"):
                return False

        # No leading zeros unless the part is exactly "0".
        if len(part) > 1 and part[0] == "0":
            return False

        # Value range check (safe: part is 1-3 ASCII digits).
        if int(part) > 255:
            return False

    return True
