from typing import List


def parse_csv_line(line: str) -> List[str]:
    """Split a single CSV line (no newlines) into a list of field strings.

    Quoted fields may contain commas and use "" to escape a double quote.
    Raises ValueError on a double quote inside an unquoted field, an
    unterminated quoted field, or text following a closing quote.
    """
    fields: List[str] = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # ----- quoted field -----
            i += 1
            chars: List[str] = []
            while True:
                if i >= n:
                    raise ValueError(
                        "unterminated quoted field in %r" % (line,)
                    )
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')   # "" -> literal quote
                        i += 2
                        continue
                    i += 1                  # consume the closing quote
                    break
                chars.append(ch)
                i += 1

            fields.append(''.join(chars))

            if i >= n:
                break
            if line[i] != ',':
                raise ValueError(
                    "unexpected character %r after closing quote in %r"
                    % (line[i], line)
                )
            i += 1                          # consume the field separator
            continue

        # ----- unquoted field -----
        start = i
        while i < n and line[i] != ',':
            if line[i] == '"':
                raise ValueError(
                    "double quote inside unquoted field in %r" % (line,)
                )
            i += 1
        fields.append(line[start:i])

        if i >= n:
            break
        i += 1                              # consume the field separator

    return fields
