"""Version comparison helper (Python 3.9, standard library only)."""

from typing import List, Optional, Tuple

_DIGITS = "0123456789"


def compare_versions(a: str, b: str) -> int:
    """Compare two version strings; return -1, 0 or 1, or raise ValueError."""

    def _parse(value: str) -> Tuple[List[str], Optional[str]]:
        if not isinstance(value, str):
            raise ValueError("version must be a string: {0!r}".format(value))

        if "-" in value:
            numeric, _, tag = value.partition("-")
            if not tag:
                raise ValueError("empty tag in {0!r}".format(value))
            for ch in tag:
                if not (ch in _DIGITS
                        or ("a" <= ch <= "z")
                        or ("A" <= ch <= "Z")):
                    raise ValueError("invalid tag character {0!r} in {1!r}".format(ch, value))
        else:
            numeric, tag = value, None

        if not numeric:
            raise ValueError("empty version: {0!r}".format(value))

        parts = numeric.split(".")
        numbers = []
        for part in parts:
            if not part:
                raise ValueError("empty part in {0!r}".format(value))
            for ch in part:
                if ch not in _DIGITS:
                    raise ValueError("non-digit part {0!r} in {1!r}".format(part, value))
            stripped = part.lstrip("0")
            numbers.append(stripped if stripped else "0")
        return numbers, tag

    def _cmp_digits(x: str, y: str) -> int:
        # x and y are non-empty digit strings without leading zeros
        if len(x) != len(y):
            return -1 if len(x) < len(y) else 1
        if x == y:
            return 0
        return -1 if x < y else 1

    nums_a, tag_a = _parse(a)
    nums_b, tag_b = _parse(b)

    length = max(len(nums_a), len(nums_b))
    for i in range(length):
        x = nums_a[i] if i < len(nums_a) else "0"
        y = nums_b[i] if i < len(nums_b) else "0"
        result = _cmp_digits(x, y)
        if result:
            return result

    if tag_a is None and tag_b is None:
        return 0
    if tag_a is None:
        return 1          # a has no tag, b does -> b is lower
    if tag_b is None:
        return -1         # a has a tag, b does not -> a is lower
    if tag_a == tag_b:
        return 0
    return -1 if tag_a < tag_b else 1
