import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned anywhere (keys and dependency values).
    nodes = set(deps)
    for dep_list in deps.values():
        nodes.update(dep_list)

    indegree = {node: 0 for node in nodes}
    dependents = {node: [] for node in nodes}

    # Edge dep -> item, counting each distinct dependency once (duplicates ignored).
    for item, dep_list in deps.items():
        for dep in set(dep_list):
            dependents[dep].append(item)
            indegree[item] += 1

    # Everything with no outstanding dependencies is ready; a min-heap keeps
    # the ready set ordered so the lexicographically smallest is taken first.
    ready = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(nodes):
        # Some item never became ready: self-dependency or a longer cycle.
        raise ValueError("dependency graph contains a cycle")

    return order
