"""Semantic-version constraint matching.

Implements SemVer 2.0 precedence rules together with npm-style range
constraints (``||``, whitespace-AND, ``=`` ``>`` ``>=`` ``<`` ``<=`` ``^``
``~``, bare version, bare ``*``), including the npm pre-release gate.
"""

import re

__all__ = ["semver_satisfies"]

# A non-negative integer without leading zeros.
_NUM = r"(?:0|[1-9][0-9]*)"
# A pre-release / build identifier: non-empty, [0-9A-Za-z-] only.
_IDENT = r"[0-9A-Za-z-]+"

_VERSION_RE = re.compile(
    r"(" + _NUM + r")\.(" + _NUM + r")\.(" + _NUM + r")"
    r"(?:-(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
    r"(?:\+(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
)

_TWO_CHAR_OPS = (">=", "<=")
_ONE_CHAR_OPS = "=<>^~"


class _Version(object):
    """A parsed version: numeric core plus an optional pre-release tuple."""

    __slots__ = ("major", "minor", "patch", "pre")

    def __init__(self, major, minor, patch, pre):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.pre = pre  # tuple[str, ...] or None; build metadata is dropped


def _parse_version(text):
    """Parse ``MAJOR.MINOR.PATCH[-pre][+build]`` or raise ``ValueError``."""
    if not isinstance(text, str):
        raise ValueError("version must be a string, got %r" % (text,))
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))
    major, minor, patch, pre, _build = match.groups()
    pre_ids = None
    if pre is not None:
        ids = pre.split(".")
        for ident in ids:
            # Numeric identifiers must not have leading zeros.
            if len(ident) > 1 and ident[0] == "0" and ident.isdigit():
                raise ValueError(
                    "invalid numeric pre-release identifier: %r" % (ident,)
                )
        pre_ids = tuple(ids)
    return _Version(int(major), int(minor), int(patch), pre_ids)


def _compare_pre(left, right):
    """Compare two pre-release identifier tuples (SemVer 2.0 rule 11)."""
    for a, b in zip(left, right):
        a_is_num = a.isdigit()
        b_is_num = b.isdigit()
        if a_is_num and b_is_num:
            ia, ib = int(a), int(b)
            if ia != ib:
                return -1 if ia < ib else 1
        elif a_is_num != b_is_num:
            # Numeric identifiers always have lower precedence.
            return -1 if a_is_num else 1
        elif a != b:
            return -1 if a < b else 1  # ASCII string comparison
    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare(a, b):
    """Return -1, 0 or 1 for the SemVer precedence of ``a`` vs ``b``."""
    for attr in ("major", "minor", "patch"):
        x = getattr(a, attr)
        y = getattr(b, attr)
        if x != y:
            return -1 if x < y else 1
    if a.pre is None and b.pre is None:
        return 0
    if a.pre is None:
        return 1  # a release outranks the same version with a pre-release
    if b.pre is None:
        return -1
    return _compare_pre(a.pre, b.pre)


class _Comparator(object):
    __slots__ = ("op", "version")

    def __init__(self, op, version):
        self.op = op
        self.version = version  # None only for the bare "*" wildcard


def _parse_comparator(token):
    """Parse a single comparator token or raise ``ValueError``."""
    if token == "*":
        return _Comparator("*", None)
    if token[:2] in _TWO_CHAR_OPS:
        op, rest = token[:2], token[2:]
    elif token[:1] in _ONE_CHAR_OPS and token[:1]:
        op, rest = token[:1], token[1:]
    else:
        op, rest = "=", token
    return _Comparator(op, _parse_version(rest))


def _upper_bound(version, op):
    """Exclusive upper bound for ``^`` / ``~`` comparators."""
    if op == "^":
        if version.major > 0:
            return _Version(version.major + 1, 0, 0, None)
        if version.minor > 0:
            return _Version(0, version.minor + 1, 0, None)
        return _Version(0, 0, version.patch + 1, None)
    # "~X.Y.Z" -> < X.(Y+1).0
    return _Version(version.major, version.minor + 1, 0, None)


def _satisfies_comparator(comparator, target):
    if comparator.op == "*":
        return True
    version = comparator.version
    order = _compare(target, version)
    op = comparator.op
    if op == "=":
        return order == 0
    if op == ">":
        return order > 0
    if op == ">=":
        return order >= 0
    if op == "<":
        return order < 0
    if op == "<=":
        return order <= 0
    # "^" or "~": lower bound plus an exclusive upper bound.
    if order < 0:
        return False
    return _compare(target, _upper_bound(version, op)) < 0


def _satisfies_group(comparators, target):
    for comparator in comparators:
        if not _satisfies_comparator(comparator, target):
            return False
    if target.pre is not None:
        # Pre-release gate: some comparator must name a pre-release on the
        # very same MAJOR.MINOR.PATCH as the candidate.
        for comparator in comparators:
            version = comparator.version
            if version is None or version.pre is None:
                continue
            if (version.major, version.minor, version.patch) == (
                target.major,
                target.minor,
                target.patch,
            ):
                return True
        return False
    return True


def semver_satisfies(version, constraint):
    """Return ``True`` if ``version`` satisfies ``constraint``.

    ``version`` is a full SemVer 2.0 string; ``constraint`` is one or more
    whitespace-separated comparators joined by ``||``.  Any invalid version,
    invalid comparator or empty constraint raises ``ValueError``.
    """
    target = _parse_version(version)

    if not isinstance(constraint, str):
        raise ValueError("constraint must be a string, got %r" % (constraint,))
    text = constraint.strip()
    if not text:
        raise ValueError("empty constraint")

    groups = []
    for raw_group in text.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("empty group in constraint: %r" % (constraint,))
        groups.append([_parse_comparator(token) for token in tokens])

    for comparators in groups:
        if _satisfies_group(comparators, target):
            return True
    return False
