def earliest_slot(busy, duration, start, end):
    """Earliest t with start <= t, t + duration <= end and [t, t + duration) free.

    Busy intervals are half-open: the minute `finish` is already free.
    Returns None when no such slot exists.
    Raises ValueError for a non-positive/non-integer duration or a
    degenerate busy interval (begin >= finish).
    """
    # bool is an int subclass, so True/False are accepted as 1/0 here;
    # False is rejected below because it is not positive.
    if not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate every interval, but keep only the part inside [start, end):
    # busy time outside the window cannot influence the result.
    clipped = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")
        if finish <= start or begin >= end:
            continue
        clipped.append((begin if begin > start else start,
                        finish if finish < end else end))

    if duration > end - start:
        return None

    clipped.sort()

    earliest = start
    for begin, finish in clipped:
        # The whole meeting fits before this block, and every later block
        # starts no earlier, so `earliest` is the answer.
        if earliest + duration <= begin:
            return earliest
        if finish > earliest:
            earliest = finish
        if earliest + duration > end:
            return None

    return earliest if earliest + duration <= end else None


