_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_DIGITS = frozenset("0123456789")


def parse_duration(s: str) -> int:
    """Convert a duration string like '1d 2h 30m' to total seconds."""
    i, n = 0, len(s)

    # Optional leading spaces.
    while i < n and s[i] == " ":
        i += 1
    if i == n:
        raise ValueError("duration string contains no parts")

    total = 0
    seen = set()

    while i < n:
        start = i
        while i < n and s[i] in _DIGITS:
            i += 1
        if i == start:
            raise ValueError("expected a number, found %r" % (s[i],))
        if i == n:
            raise ValueError("number without a unit")

        unit = s[i]
        if unit not in _UNIT_SECONDS:
            raise ValueError("unknown unit %r" % (unit,))
        if unit in seen:
            raise ValueError("repeated unit %r" % (unit,))
        seen.add(unit)

        total += int(s[start:i]) * _UNIT_SECONDS[unit]
        i += 1

        # Optional separating spaces (may also be the trailing spaces).
        while i < n and s[i] == " ":
            i += 1

    return total
