"""Arithmetic expression evaluator (Python 3.9, stdlib only).

Grammar (precedence low -> high, matching the spec):

    expr    := term (('+' | '-') term)*
    term    := unary (('*' | '/') unary)*
    unary   := '-' unary | power          # unary minus binds looser than '^'
    power   := atom ('^' unary)?          # '^' is right-associative
    atom    := NUMBER | '(' expr ')'

The exponent side of '^' is parsed with `unary`, which makes `2 ^ -1` and
right-associativity (`2 ^ 3 ^ 2 == 512`) fall out naturally, while
`-2 ^ 2 == -(2 ^ 2) == -4`.
"""


class _Parser:
    """Recursive-descent parser over a pre-tokenized expression."""

    def __init__(self, text):
        self.tokens = self._tokenize(text)
        self.pos = 0

    # ---------------------------------------------------------------- lexer
    @staticmethod
    def _tokenize(text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            c = text[i]

            if c.isspace():
                i += 1
                continue

            if c in "+-*/^()":
                tokens.append((c, c))
                i += 1
                continue

            if "0" <= c <= "9":
                j = i
                while j < n and "0" <= text[j] <= "9":
                    j += 1
                # A '.' may only appear as part of "digits.digits".
                if j < n and text[j] == ".":
                    k = j + 1
                    while k < n and "0" <= text[k] <= "9":
                        k += 1
                    if k == j + 1:  # nothing after the dot
                        raise ValueError(
                            "malformed decimal literal at position %d" % i
                        )
                    tokens.append(("num", text[i:k]))
                    i = k
                else:
                    tokens.append(("num", text[i:j]))
                    i = j
                continue

            raise ValueError("unexpected character %r at position %d" % (c, i))

        return tokens

    # --------------------------------------------------------------- cursor
    def _peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    # ------------------------------------------------------------ entry pt
    def parse(self):
        value = self._expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token %r" % (self.tokens[self.pos][1],))
        return value

    # ------------------------------------------------------------- grammar
    def _expr(self):
        value = self._term()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] in ("+", "-"):
                self.pos += 1
                rhs = self._term()
                value = value + rhs if tok[0] == "+" else value - rhs
            else:
                return value

    def _term(self):
        value = self._unary()
        while True:
            tok = self._peek()
            if tok is not None and tok[0] in ("*", "/"):
                self.pos += 1
                rhs = self._unary()
                if tok[0] == "*":
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ValueError("division by zero")
                    value = value / rhs
            else:
                return value

    def _unary(self):
        tok = self._peek()
        if tok is not None and tok[0] == "-":
            self.pos += 1
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._atom()
        tok = self._peek()
        if tok is not None and tok[0] == "^":
            self.pos += 1
            exponent = self._unary()
            return base ** exponent
        return base

    def _atom(self):
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")

        kind, text = tok

        if kind == "num":
            self.pos += 1
            if "." in text:
                return float(text)
            return int(text)

        if kind == "(":
            self.pos += 1
            value = self._expr()
            closing = self._peek()
            if closing is None or closing[0] != ")":
                raise ValueError("missing closing parenthesis")
            self.pos += 1
            return value

        raise ValueError("unexpected token %r" % (text,))


def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return int or float.

    Raises ValueError for any malformed input or for division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    return _Parser(expr).parse()
