"""flatten(nested, depth=None) — flatten nested lists up to `depth` levels."""


def flatten(nested, depth=None):
    """Return a new list with nested lists flattened up to `depth` levels.

    Args:
        nested: a list, possibly containing (exactly) `list` objects.
        depth: maximum number of levels to descend. ``None`` (default)
            flattens completely; ``0`` returns a shallow copy of `nested`;
            ``1`` flattens one level, and so on.

    Returns:
        A new list. Non-`list` items (tuples, strings, dicts, subclasses of
        list, etc.) are kept as single items. `nested` is never modified.

    Raises:
        ValueError: if `depth` is negative.
    """
    if depth is not None and depth < 0:
        raise ValueError("depth must be non-negative or None, got %r" % (depth,))

    result = []
    # Iterative DFS: each stack entry is (iterator over a list, remaining depth).
    # remaining is None for "unlimited", or the number of further levels allowed.
    stack = [(iter(nested), depth)]

    while stack:
        iterator, remaining = stack[-1]
        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            continue

        if type(item) is list and (remaining is None or remaining > 0):
            stack.append((iter(item), None if remaining is None else remaining - 1))
        else:
            result.append(item)

    return result
