```python
def mask_email(s: str) -> str:
    """Mask the local part of an email address, leaving the domain unchanged.

    Keeps the first and last characters of the local part and replaces every
    character between them with '*'. A one-character local part becomes '*';
    a two-character local part keeps its first character and masks the second.

    Raises:
        ValueError: if s does not contain exactly one '@' with a non-empty
            local part before it and a non-empty domain after it.
    """
    if s.count("@") != 1:
        raise ValueError("email must contain exactly one '@'")

    local, domain = s.split("@")
    if not local:
        raise ValueError("local part must be non-empty")
    if not domain:
        raise ValueError("domain must be non-empty")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
