def wrap_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: List[str] = []
    current = ""

    for word in text.split(" "):
        if not word:
            continue

        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            # Leave the final piece available for following words.
            pieces_before_last = (len(word) - 1) // width
            for i in range(pieces_before_last):
                start = i * width
                lines.append(word[start:start + width])
            current = word[pieces_before_last * width:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

