import re


def round_half_up(x: str, ndigits: int) -> str:
    if ndigits < 0:
        raise ValueError("ndigits must be nonnegative")
    if not isinstance(x, str) or re.fullmatch(
        r"-?[0-9]+(?:\.[0-9]+)?", x
    ) is None:
        raise ValueError("Invalid decimal format")

    negative = x.startswith("-")
    magnitude = x[1:] if negative else x
    whole, _, fraction = magnitude.partition(".")

    digits = list(
        (whole.lstrip("0") or "0")
        + fraction[:ndigits].ljust(ndigits, "0")
    )

    if len(fraction) > ndigits and fraction[ndigits] >= "5":
        i = len(digits) - 1
        while i >= 0 and digits[i] == "9":
            digits[i] = "0"
            i -= 1
        if i >= 0:
            digits[i] = chr(ord(digits[i]) + 1)
        else:
            digits.insert(0, "1")

    rounded = "".join(digits).lstrip("0") or "0"
    sign = "-" if negative and rounded != "0" else ""

    if ndigits == 0:
        return sign + rounded

    rounded = rounded.zfill(ndigits + 1)
    return sign + rounded[:-ndigits] + "." + rounded[-ndigits:]
