import math  # noqa: F401  (stdlib only; not strictly needed but harmless)


def evaluate(expr: str):
    """Evaluate an arithmetic expression string and return an int or float.

    Grammar (recursive descent):
        expr    := term (('+' | '-') term)*
        term    := unary (('*' | '/') unary)*
        unary   := '-' unary | power
        power   := primary ('^' unary)?          # right-associative
        primary := NUMBER | '(' expr ')'

    Raises ValueError on malformed input or division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    NUM, OP, LPAREN, RPAREN, EOF = "NUM", "OP", "LPAREN", "RPAREN", "EOF"

    # ---------- tokenizer ----------
    tokens = []
    i, n = 0, len(expr)
    while i < n:
        c = expr[i]

        if c.isspace():
            i += 1
            continue

        if "0" <= c <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            if j < n and expr[j] == ".":
                k = j + 1
                if k >= n or not ("0" <= expr[k] <= "9"):
                    raise ValueError("malformed decimal literal at index %d" % i)
                while k < n and "0" <= expr[k] <= "9":
                    k += 1
                tokens.append((NUM, float(expr[i:k])))
                i = k
            else:
                tokens.append((NUM, int(expr[i:j])))
                i = j
            continue

        if c in "+-*/^":
            tokens.append((OP, c))
            i += 1
            continue

        if c == "(":
            tokens.append((LPAREN, c))
            i += 1
            continue

        if c == ")":
            tokens.append((RPAREN, c))
            i += 1
            continue

        raise ValueError("unknown character %r at index %d" % (c, i))

    # ---------- parser ----------
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else (EOF, None)

    def advance():
        nonlocal pos
        tok = peek()
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while True:
            kind, op = peek()
            if kind == OP and op in "+-":
                advance()
                rhs = parse_term()
                value = value + rhs if op == "+" else value - rhs
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            kind, op = peek()
            if kind == OP and op in "*/":
                advance()
                rhs = parse_unary()
                if op == "*":
                    value = value * rhs
                else:
                    if rhs == 0:
                        raise ValueError("division by zero")
                    value = value / rhs
            else:
                return value

    def parse_unary():
        kind, op = peek()
        if kind == OP and op == "-":
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_primary()
        kind, op = peek()
        if kind == OP and op == "^":
            advance()
            exponent = parse_unary()   # allows unary minus, keeps '^' right-assoc
            return base ** exponent
        return base

    def parse_primary():
        kind, value = peek()
        if kind == NUM:
            advance()
            return value
        if kind == LPAREN:
            advance()
            inner = parse_expr()
            closing, _ = peek()
            if closing != RPAREN:
                raise ValueError("missing closing parenthesis")
            advance()
            return inner
        raise ValueError("expected a number or '(' but found %r" % (value,))

    try:
        result = parse_expr()
    except ZeroDivisionError:
        raise ValueError("division by zero")

    if pos != len(tokens):
        raise ValueError("unexpected trailing input near index %d" % pos)

    return result
