            scale = 1024**exponent
            with self.subTest(unit=unit):
                self.assertEqual(format_bytes(scale), f"1.0 {unit}")
                self.assertEqual(format_bytes(scale + 1), f"1.0 {unit}")
                self.assertEqual(format_bytes(3 * scale // 2), f"1.5 {unit}")

    def test_exact_half_up_rounding(self):
        for exponent, unit in enumerate(("KiB", "MiB", "GiB", "TiB"), 1):
            scale = 1024**exponent
            for whole in (1, 2):
                midpoint = whole * scale + scale // 4
                with self.subTest(unit=unit, whole=whole):
                    self.assertEqual(
                        format_bytes(midpoint - 1), f"{whole}.2 {unit}"
                    )
                    self.assertEqual(
                        format_bytes(midpoint), f"{whole}.3 {unit}"
                    )
                    self.assertEqual(
                        format_bytes(midpoint + 1), f"{whole}.3 {unit}"
                    )

