        units = ("KiB", "MiB", "GiB", "TiB")
        for exponent in range(1, 4):
            scale = 1024**exponent
            boundary = 1024 * scale
            # ceil(1023.95 * scale), using integer arithmetic.
            first_promoted = (20479 * scale + 19) // 20
            with self.subTest(exponent=exponent):
                self.assertEqual(
                    format_bytes(first_promoted - 1),
                    f"1023.9 {units[exponent - 1]}",
                )
                self.assertEqual(
                    format_bytes(first_promoted), f"1.0 {units[exponent]}"
                )
                self.assertEqual(
                    format_bytes(boundary - 1), f"1.0 {units[exponent]}"
                )

    def test_explicit_promotion_example(self):
        self.assertEqual(format_bytes(1048575), "1.0 MiB")

    def test_tib_is_largest_unit(self):
        scale = 1024**4
        self.assertEqual(format_bytes(1024 * scale - 1), "1024.0 TiB")
        self.assertEqual(format_bytes(1024 * scale), "1024.0 TiB")
        self.assertEqual(format_bytes(2048 * scale), "2048.0 TiB")

    def test_large_integers_preserve_exact_rounding(self):
        scale = 1024**4
        whole = 10**100
        midpoint = whole * scale + scale // 4
        self.assertEqual(format_bytes(midpoint - 1), f"{whole}.2 TiB")
        self.assertEqual(format_bytes(midpoint), f"{whole}.3 TiB")


def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be nonnegative")
    if n < 1024:
        return f"{n} B"

    units = ("KiB", "MiB", "GiB", "TiB")
    unit_index = 0
    scale = 1024

    while unit_index < len(units) - 1 and n >= scale * 1024:
        scale *= 1024
        unit_index += 1

    # Round the exact value in tenths, with ties rounded upward.
    tenths = (n * 10 + scale // 2) // scale

    if tenths == 10240 and unit_index < len(units) - 1:
        unit_index += 1
        tenths = 10

    whole, decimal = divmod(tenths, 10)
    return f"{whole}.{decimal} {units[unit_index]}"


