import re
from typing import Optional, Tuple

_Version = Tuple[int, int, int, Tuple[str, ...]]

_VERSION_PATTERN = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
)
_COMPARATOR_PATTERN = re.compile(r"(>=|<=|[=><^~])?(.+)")


def _parse_semver(text: str) -> _Version:
    match = _VERSION_PATTERN.fullmatch(text)
    if match is None:
        raise ValueError("Invalid semantic version: {!r}".format(text))

    major, minor, patch, prerelease, _build = match.groups()
    identifiers = tuple(prerelease.split(".")) if prerelease else ()

    for identifier in identifiers:
        if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError("Invalid numeric prerelease identifier")

    return (
        _decimal_integer(major),
        _decimal_integer(minor),
        _decimal_integer(patch),
        identifiers,
    )


def _decimal_integer(digits: str) -> int:
    # Chunking also supports arbitrarily long components on Python versions
    # that limit the number of digits accepted by a single int() conversion.
    value = 0
    for offset in range(0, len(digits), 9):
        chunk = digits[offset:offset + 9]
        value = value * (10 ** len(chunk)) + int(chunk)
    return value


def _compare_semver(left: _Version, right: _Version) -> int:
    if left[:3] != right[:3]:
        return 1 if left[:3] > right[:3] else -1

    left_pre, right_pre = left[3], right[3]
    if not left_pre or not right_pre:
        return (bool(right_pre) > bool(left_pre)) - (
            bool(right_pre) < bool(left_pre)
        )

    for left_id, right_id in zip(left_pre, right_pre):
        if left_id == right_id:
            continue

        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()

        if left_numeric and right_numeric:
            left_key = (len(left_id), left_id)
            right_key = (len(right_id), right_id)
            return 1 if left_key > right_key else -1
        if left_numeric != right_numeric:
            return -1 if left_numeric else 1
        return 1 if left_id > right_id else -1

    return (len(left_pre) > len(right_pre)) - (
        len(left_pre) < len(right_pre)
    )


def _comparator_holds(
    version: _Version, operator: str, target: _Version
) -> bool:
    comparison = _compare_semver(version, target)

    if operator == "=":
        return comparison == 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0

    major, minor, patch, _prerelease = target
    if operator == "~":
        upper = (major, minor + 1, 0, ())
    elif major > 0:
        upper = (major + 1, 0, 0, ())
    elif minor > 0:
        upper = (0, minor + 1, 0, ())
    else:
        upper = (0, 0, patch + 1, ())

    return comparison >= 0 and _compare_semver(version, upper) < 0


def semver_satisfies(version: str, constraint: str) -> bool:
    parsed_version = _parse_semver(version)
    if not constraint.strip():
        raise ValueError("Constraint must not be empty")

    any_group_matches = False

    # Every comparator is validated, including those in nonmatching groups
    # and groups appearing after an already matching group.
    for group in constraint.split("||"):
        tokens = group.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        group_matches = True
        prerelease_allowed = not parsed_version[3]

        for token in tokens:
            if token == "*":
                continue

            match = _COMPARATOR_PATTERN.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            target = _parse_semver(match.group(2))

            if target[3] and target[:3] == parsed_version[:3]:
                prerelease_allowed = True

            holds = _comparator_holds(parsed_version, operator, target)
            group_matches = group_matches and holds

        if group_matches and prerelease_allowed:
            any_group_matches = True

    return any_group_matches
