def shell_split(s: str) -> list[str]:
    words = []
    current = []
    i = 0
    in_word = False

    while i < len(s):
        char = s[i]

        if char in " \t":
            if in_word:
                words.append("".join(current))
                current = []
                in_word = False
            i += 1
            continue

        in_word = True

        if char == "\\":
            if i + 1 >= len(s):
                raise ValueError("trailing backslash")
            current.append(s[i + 1])
            i += 2
        elif char == "'":
            end = s.find("'", i + 1)
            if end == -1:
                raise ValueError("unterminated single quote")
            current.append(s[i + 1:end])
            i = end + 1
        elif char == '"':
            i += 1
            while i < len(s):
                char = s[i]
                if char == '"':
                    i += 1
                    break
                if char == "\\" and i + 1 < len(s) and s[i + 1] in '\\"':
                    current.append(s[i + 1])
                    i += 2
                else:
                    current.append(char)
                    i += 1
            else:
                raise ValueError("unterminated double quote")
        else:
            current.append(char)
            i += 1

    if in_word:
        words.append("".join(current))

    return words
