        raise ValueError("empty duration string")
    if _VALID.fullmatch(stripped) is None:
        raise ValueError("invalid duration string: {!r}".format(s))
    total = 0
    seen = set()
    for num, unit in _PART.findall(stripped):
        if unit in seen:
            raise ValueError("repeated unit: {!r}".format(unit))
        seen.add(unit)
