"""Compare version strings (Python 3.9, standard library only)."""

_DIGITS = frozenset("0123456789")
_ALNUM = frozenset(
    "0123456789"
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "abcdefghijklmnopqrstuvwxyz"
)


def _parse_version(version):
    """Split a version into (numeric parts as ints, tag or None).

    Raises ValueError if ``version`` is not a valid version string.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("invalid version: {!r}".format(version))

    numeric, sep, tag = version.partition("-")

    if sep:
        if not tag:
            raise ValueError("empty tag in version: {!r}".format(version))
        for ch in tag:
            if ch not in _ALNUM:
                raise ValueError("invalid tag in version: {!r}".format(version))

    parts = []
    for part in numeric.split("."):
        if not part:
            raise ValueError("empty part in version: {!r}".format(version))
        for ch in part:
            if ch not in _DIGITS:
                raise ValueError(
                    "non-digit part in version: {!r}".format(version)
                )
        parts.append(int(part))

    return parts, (tag if sep else None)


def compare_versions(a: str, b: str) -> int:
    """Return -1, 0 or 1 comparing version ``a`` against version ``b``."""
    nums_a, tag_a = _parse_version(a)
    nums_b, tag_b = _parse_version(b)

    # Missing numeric parts count as zero.
    width = max(len(nums_a), len(nums_b))
    nums_a.extend([0] * (width - len(nums_a)))
    nums_b.extend([0] * (width - len(nums_b)))

    for left, right in zip(nums_a, nums_b):
        if left < right:
            return -1
        if left > right:
            return 1

    # Numeric parts are equal: a tagged version sorts below an untagged one.
    if (tag_a is None) != (tag_b is None):
        return 1 if tag_a is None else -1

    if tag_a is None:
        return 0

    if tag_a < tag_b:
        return -1
    if tag_a > tag_b:
        return 1
    return 0
