    _DIGITS = "0123456789"

    # ---------- Tokenizer ----------
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in _DIGITS:
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                if j >= n or expr[j] not in _DIGITS:
                    raise ValueError("malformed number literal")
                while j < n and expr[j] in _DIGITS:
                    j += 1
                tokens.append(float(expr[i:j]))
            else:
                tokens.append(int(expr[i:j]))
            i = j
            continue
        if c in "+-*/^()":
            tokens.append(c)
            i += 1
            continue
        raise ValueError("unknown character: %r" % (c,))

    # ---------- Recursive-descent parser ----------
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_unary()
            value = value * rhs if op == '*' else value / rhs
        return value

    def parse_unary():
        if peek() == '-':
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            advance()
            exponent = parse_unary()
            return base ** exponent
        return base

    def parse_atom():
        tok = peek()
        if isinstance(tok, (int, float)):
            advance()
            return tok
        if tok == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses: expected ')'")
            advance()
            return value
        if tok is None:
            raise ValueError("unexpected end of input")
        raise ValueError("unexpected token: %r" % (tok,))

    try:
        result = parse_expr()
    except ZeroDivisionError:
        raise ValueError("division by zero")
    if pos != len(tokens):
        raise ValueError("unexpected token: %r" % (tokens[pos],))
    return result
