import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    for dlist in deps.values():
        nodes.update(dlist)

    dependents: dict[str, set[str]] = {n: set() for n in nodes}
    indegree: dict[str, int] = {n: 0 for n in nodes}

    for item, dlist in deps.items():
        for dep in dlist:
            if dep == item:
                raise ValueError(f"cycle detected: {item!r} depends on itself")
            if item not in dependents[dep]:
                dependents[dep].add(item)
                indegree[item] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("cycle detected in dependencies")

    return result
