_ITEM_RE = re.compile(r"(?:\*|\d+|\d+-\d+)(?:/(\d+))?\Z")


def _parse_field(text, lo, hi, name):
    """Expand a cron field into a sorted list of ints; ValueError if malformed."""
    if not text:
        raise ValueError("empty %s field" % name)
    values = set()
    for item in text.split(","):
        match = _ITEM_RE.match(item)
        if match is None:
            raise ValueError("malformed item %r in %s field" % (item, name))
        step_text = match.group(1)
        step = int(step_text) if step_text is not None else 1
        if step < 1:
            raise ValueError("bad step in %s field: %r" % (name, item))
        body = item.split("/", 1)[0]
        if body == "*":
            start, end = lo, hi
        elif "-" in body:
            left, right = body.split("-")
            start, end = int(left), int(right)
        else:
            start = int(body)
            # "a/n" runs from a up to the field maximum; bare "a" is just a.
            end = hi if step_text is not None else start
        if start < lo or end > hi or start > end:
            raise ValueError("value out of range in %s field: %r" % (name, item))
        values.update(range(start, end + 1, step))
    return sorted(values)


def _add_years(moment, years):
    """Same month/day/time `years` later, clamping Feb 29 to Feb 28."""
    try:
        return moment.replace(year=moment.year + years)
    except ValueError:
        return moment.replace(year=moment.year + years, day=28)


def next_cron(expr, after):
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("expected 5 fields, got %d" % len(fields))

    minutes = _parse_field(fields[0], 0, 59, "minute")
    hours = _parse_field(fields[1], 0, 23, "hour")
    days_of_month = _parse_field(fields[2], 1, 31, "day of month")
    months = _parse_field(fields[3], 1, 12, "month")
    days_of_week = _parse_field(fields[4], 0, 6, "day of week")

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    limit = _add_years(after_dt, 5)
    first = after_dt + timedelta(minutes=1)  # earliest allowed candidate

    message = "no matching time within 5 years after %s" % after
    if first > limit:
        raise ValueError(message)

    first_date = first.date()
    last_date = limit.date()
    day = first_date
    while day <= last_date:
        if day.month in months:
            dom_hit = day.day in days_of_month
            dow_hit = ((day.weekday() + 1) % 7) in days_of_week  # cron: 0 = Sunday
            if dom_restricted and dow_restricted:
                day_hit = dom_hit or dow_hit
            elif dom_restricted:
                day_hit = dom_hit
            elif dow_restricted:
                day_hit = dow_hit
            else:
                day_hit = True

            if day_hit:
                if day == first_date:
                    low_hour, low_minute = first.hour, first.minute
                else:
                    low_hour, low_minute = 0, 0
                for hour in hours:
                    if hour < low_hour:
                        continue
                    if hour == low_hour:
                        minute = next((m for m in minutes if m >= low_minute), None)
                        if minute is None:
                            continue
                    else:
                        minute = minutes[0]
                    stamp = datetime(day.year, day.month, day.day, hour, minute)
                    if stamp > limit:
                        raise ValueError(message)
                    return stamp.strftime("%Y-%m-%d %H:%M")
