        kind = token[0]
        row = [False] * (width + 1)

        if kind == 'lit':
            literal = token[1]
            for j in range(width - 1, -1, -1):
                row[j] = nxt[j + 1] and name[j] == literal
        elif kind == 'any':
            for j in range(width - 1, -1, -1):
                row[j] = nxt[j + 1] and name[j] != '/'
        elif kind == 'set':
            negate, items = token[1], token[2]
            for j in range(width - 1, -1, -1):
                row[j] = nxt[j + 1] and _in_set(name[j], negate, items)
        elif kind == 'star':
            row[width] = nxt[width]
            for j in range(width - 1, -1, -1):
                row[j] = nxt[j] or (name[j] != '/' and row[j + 1])
        else:  # 'dstar'
            row[width] = nxt[width]
            for j in range(width - 1, -1, -1):
                row[j] = nxt[j] or row[j + 1]

        nxt = row

