        parts = tuple(
            part.lstrip("0") or "0"
            for part in match.group(1).split(".")
        )
        return parts, match.group(2)

    parts_a, tag_a = parse(a)
    parts_b, tag_b = parse(b)

    for part_a, part_b in zip_longest(parts_a, parts_b, fillvalue="0"):
        if len(part_a) != len(part_b):
            return 1 if len(part_a) > len(part_b) else -1
        if part_a != part_b:
            return 1 if part_a > part_b else -1

    if tag_a is None:
        return 0 if tag_b is None else 1
    if tag_b is None:
        return -1

    return (tag_a > tag_b) - (tag_a < tag_b)
