    """Return (list_of_int_parts, tag_or_None); raise ValueError if invalid."""
    match = _VERSION_RE.fullmatch(version)
    if match is None:
        raise ValueError("invalid version: %r" % (version,))
    numbers = [int(part) for part in match.group(1).split(".")]
    return numbers, match.group(2)


def compare_versions(a: str, b: str) -> int:
    numbers_a, tag_a = _parse(a)
    numbers_b, tag_b = _parse(b)

    # Compare numeric parts; missing parts count as zero.
    length = max(len(numbers_a), len(numbers_b))
    numbers_a += [0] * (length - len(numbers_a))
    numbers_b += [0] * (length - len(numbers_b))

    if numbers_a < numbers_b:
        return -1
    if numbers_a > numbers_b:
        return 1

    # Numeric parts are equal: a tag makes a version lower than no tag;
    # two tags are compared as plain (case-sensitive) strings.
    if tag_a is None and tag_b is None:
        return 0
    if tag_a is None:
        return 1
    if tag_b is None:
        return -1
    if tag_a < tag_b:
        return -1
    if tag_a > tag_b:
        return 1
    return 0
