import re

_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def _increment(digits: str) -> str:
    """Add 1 to a non-empty string of ASCII digits (exact, arbitrary length)."""
    out = list(digits)
    i = len(out) - 1
    while i >= 0:
        if out[i] == "9":
            out[i] = "0"
            i -= 1
        else:
            out[i] = chr(ord(out[i]) + 1)
            return "".join(out)
    return "1" + "".join(out)  # carry out of the most significant digit


def round_half_up(x: str, ndigits: int) -> str:
    # ---- validation -------------------------------------------------------
    if isinstance(ndigits, bool) or not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer, got %r" % (ndigits,))
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError("not a valid decimal literal: %r" % (x,))

    # ---- split into sign / integer digits / fraction digits ---------------
    negative = x.startswith("-")
    body = x[1:] if negative else x
    if "." in body:
        int_part, frac_part = body.split(".")
    else:
        int_part, frac_part = body, ""

    # ---- round exactly, on the digit string -------------------------------
    if ndigits >= len(frac_part):
        # nothing is dropped, just pad with zeros
        frac_part = frac_part + "0" * (ndigits - len(frac_part))
    else:
        kept = int_part + frac_part[:ndigits]
        if frac_part[ndigits] >= "5":      # half-up = away from zero for both signs
            kept = _increment(kept)
        if ndigits:
            int_part, frac_part = kept[:-ndigits], kept[-ndigits:]
        else:
            int_part, frac_part = kept, ""

    int_part = int_part.lstrip("0") or "0"

    # ---- never return a negative zero -------------------------------------
    if int_part == "0" and not frac_part.strip("0"):
        negative = False

    sign = "-" if negative else ""
    if ndigits == 0:
        return sign + int_part
    return sign + int_part + "." + frac_part
