"""semver_satisfies(version, constraint) -> bool

Requirements
------------
* version := MAJOR.MINOR.PATCH ("0" | [1-9][0-9]*, no leading zeros)
             [ "-" prerelease ]        dotted ids [0-9A-Za-z-]+, non-empty,
                                       all-digit ids have no leading zeros
             [ "+" build ]             [0-9A-Za-z-]+ dots, ignored entirely
* ordering: numbers first; prerelease < release; ids left to right,
  numeric < alphanumeric, numeric vs numeric by value, strings by ASCII,
  exhausted (shorter) side is lower.
* constraint := group ("||" group)*; group := comparator (ws comparator)*
  comparator := op version, op in = > >= < <= ^ ~, bare version == "=",
  bare "*" == any version.
* ^X.Y.Z -> >=X.Y.Z <X+1.0.0   (X>0)
            >=0.Y.Z <0.Y+1.0   (X==0, Y>0)
            >=0.0.Z <0.0.Z+1   (X==0, Y==0)
  ~X.Y.Z -> >=X.Y.Z <X.Y+1.0
* prerelease gating: a prerelease version can satisfy a group only if some
  comparator in that group carries a prerelease on the *same* MAJOR.MINOR.PATCH.
* ValueError on: bad version, bad comparator, empty constraint/group.

Edge cases handled: "v1.2.3", "1.2", "1.02.3", "1.2.3-", "1.2.3+", "1.0.0-01",
"1.0.0-0", "*" (no prereleases), "1.0.0||", "=", " =>1.0.0", hyphen ranges
(unsupported -> ValueError), build metadata in both inputs, eager validation of
every group even when an earlier group already matches.
"""

import re

__all__ = ["semver_satisfies"]

_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


def _parse_version(text):
    """-> (major, minor, patch, prerelease ids list or None). Raises ValueError."""
    if not isinstance(text, str):
        raise ValueError("invalid version: {!r}".format(text))
    m = _VERSION_RE.match(text)
    if m is None:
        raise ValueError("invalid version: {!r}".format(text))
    major, minor, patch, pre = m.group(1), m.group(2), m.group(3), m.group(4)
    if pre is None:
        pre_ids = None
    else:
        pre_ids = pre.split(".")
        for ident in pre_ids:
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError("invalid version: {!r}".format(text))
    return (int(major), int(minor), int(patch), pre_ids)


def _compare(a, b):
    """SemVer 2.0 precedence: -1, 0 or 1."""
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1
    pre_a, pre_b = a[3], b[3]
    if pre_a is None or pre_b is None:
        if pre_a is None and pre_b is None:
            return 0
        return 1 if pre_a is None else -1
    for x, y in zip(pre_a, pre_b):
        if x == y:
            continue
        x_num, y_num = x.isdigit(), y.isdigit()
        if x_num and y_num:
            return -1 if int(x) < int(y) else 1
        if x_num != y_num:
            return -1 if x_num else 1
        return -1 if x < y else 1
    if len(pre_a) != len(pre_b):
        return -1 if len(pre_a) < len(pre_b) else 1
    return 0


def _parse_comparator(token):
    """-> (op, version tuple) with op '*' meaning 'any'."""
    if token == "*":
        return ("*", None)
    op, rest = "=", token
    for candidate in _OPERATORS:
        if token.startswith(candidate):
            op = candidate
            rest = token[len(candidate):]
            break
    if rest == "":
        raise ValueError("invalid comparator: {!r}".format(token))
    return (op, _parse_version(rest))


def _upper_bound(op, base):
    major, minor, patch = base[0], base[1], base[2]
    if op == "~":
        return (major, minor + 1, 0, None)
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _comparator_ok(version, comparator):
    op, base = comparator
    if op == "*":
        return True
    c = _compare(version, base)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    # "^" and "~" are a lower bound plus a derived upper bound
    if c < 0:
        return False
    return _compare(version, _upper_bound(op, base)) < 0


def _group_ok(version, comparators):
    for comparator in comparators:
        if not _comparator_ok(version, comparator):
            return False
    if version[3] is not None:
        for _op, base in comparators:
            if base is not None and base[3] is not None and base[:3] == version[:3]:
                break
        else:
            return False  # prerelease without a matching prerelease comparator
    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    parsed_version = _parse_version(version)
    if not isinstance(constraint, str):
        raise ValueError("invalid constraint: {!r}".format(constraint))
    groups = []
    for raw_group in constraint.split("||"):
        tokens = raw_group.split()
        if not tokens:
            raise ValueError("invalid constraint: {!r}".format(constraint))
        groups.append([_parse_comparator(token) for token in tokens])
    return any(_group_ok(parsed_version, group) for group in groups)
