from typing import Set


_ITEM = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_TIMESTAMP = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")


def _parse_field(text: str, minimum: int, maximum: int) -> Set[int]:
    values: Set[int] = set()

    for item in text.split(","):
        match = _ITEM.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item: {!r}".format(item))

        base, step_text = match.groups()
        step = int(step_text) if step_text is not None else 1
        if step < 1:
            raise ValueError("Cron steps must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            start_text, end_text = base.split("-")
            start, end = int(start_text), int(end_text)
        else:
            start = int(base)
            end = maximum if step_text is not None else start

        if not (minimum <= start <= end <= maximum):
            raise ValueError("Cron value or range is out of bounds")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    """Return the first firing strictly after `after`, within five calendar years."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("A cron expression must contain exactly five fields")

    minutes, hours, month_days, months, week_days = [
        _parse_field(field, minimum, maximum)
        for field, (minimum, maximum) in zip(
            fields, ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
        )
    ]

    if _TIMESTAMP.fullmatch(after) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")

    try:
        start = datetime(
            int(after[0:4]),
            int(after[5:7]),
            int(after[8:10]),
            int(after[11:13]),
            int(after[14:16]),
        )
    except ValueError as exc:
        raise ValueError("Invalid after timestamp") from exc

    if start.year <= 9994:
        deadline_year = start.year + 5
        deadline_day = min(
            start.day, calendar.monthrange(deadline_year, start.month)[1]
        )
        deadline = start.replace(year=deadline_year, day=deadline_day)
    else:
        # No timestamp in the required format can represent a later year.
        deadline = datetime(9999, 12, 31, 23, 59)

    # Whether a day field is restricted depends on its literal spelling.
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    daily_minutes = sorted(hour * 60 + minute for hour in hours for minute in minutes)
    first_date = start.date()
    last_date = deadline.date()
    day = first_date

    while day <= last_date:
        if day.month in months:
            dom_matches = day.day in month_days
            dow_matches = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect_right(daily_minutes, start.hour * 60 + start.minute)
                    if day == first_date
                    else 0
                )
                if index < len(daily_minutes):
                    hour, minute = divmod(daily_minutes[index], 60)
                    candidate = datetime(day.year, day.month, day.day, hour, minute)
                    if candidate <= deadline:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {candidate.hour:02d}:"
                            f"{candidate.minute:02d}"
                        )

        if day == last_date:
            break
        day += timedelta(days=1)

