import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether name matches the path-like glob pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(".*")
                i += 2
            else:
                regex.append("[^/]*")
                i += 1
        elif char == "?":
            regex.append("[^/]")
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            items = []
            if i < len(pattern) and pattern[i] == "]":
                items.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in character set")
                    items.append((pattern[i], True))
                else:
                    items.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError("unclosed character set")
            if not items:
                raise ValueError("empty character set")

            parts = []
            j = 0
            while j < len(items):
                if (
                    j + 2 < len(items)
                    and items[j + 1] == ("-", False)
                    and not items[j][1]
                    and not items[j + 2][1]
                ):
                    parts.append(
                        re.escape(items[j][0]) + "-" + re.escape(items[j + 2][0])
                    )
                    j += 3
                else:
                    parts.append(re.escape(items[j][0]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    try:
        return re.fullmatch("".join(regex), name) is not None
    except re.error as exc:
        raise ValueError("invalid pattern") from exc
