def is_valid_ipv4(s: str) -> bool:
    if not isinstance(s, str):
        return False

    parts = s.split(".")
    if len(parts) != 4:
        return False

    for part in parts:
        if not (1 <= len(part) <= 3):
            return False
        # Explicit ASCII range check: rejects Unicode digits, signs, whitespace.
        for ch in part:
            if ch < "0" or ch > "9":
                return False
        # No leading zeros unless the part is exactly "0".
        if part[0] == "0" and len(part) > 1:
            return False
        if int(part) > 255:
            return False

