from typing import List, Sequence


def merge_intervals(intervals: Sequence[Sequence[int]]) -> List[List[int]]:
    """Merge overlapping or touching closed integer intervals.

    Two intervals are merged when they overlap or share an endpoint
    (``start <= previous_end``). Intervals whose integer ranges are merely
    adjacent (``[1, 2]`` and ``[3, 4]``) are left separate, since no integer
    lies in both.

    The input is never modified, and the returned lists are freshly created.
    Raises ValueError if any interval has start > end.
    """
    if not intervals:
        return []

    # Copy into fresh lists while validating, so the caller's data is untouched.
    prepared: List[List[int]] = []
    for index, interval in enumerate(intervals):
        try:
            start, end = interval
        except (TypeError, ValueError):
            raise ValueError(
                "interval at index %d is not a [start, end] pair: %r"
                % (index, interval)
            )
        if start > end:
            raise ValueError(
                "interval at index %d has start > end: [%r, %r]"
                % (index, start, end)
            )
        prepared.append([start, end])

    prepared.sort(key=lambda pair: pair[0])

    merged: List[List[int]] = [prepared[0]]
    for start, end in prepared[1:]:
        last = merged[-1]
        if start <= last[1]:
            # Overlapping or sharing an endpoint: extend if it reaches further.
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged
