def _to_roman(n: int) -> str:
    out = []
    for sym, val in _SYMBOLS:
        while n >= val:
            out.append(sym)
            n -= val
    return "".join(out)


def roman_to_int(s: str) -> int:
    if not isinstance(s, str) or not s:
        raise ValueError("empty or non-string input")
    if s != s.upper():
        raise ValueError("lowercase or non-uppercase characters are not allowed")

    i = 0
    total = 0
    for sym, val in _SYMBOLS:
        while s.startswith(sym, i):
            total += val
            i += len(sym)

    if i != len(s):
        raise ValueError("not a valid Roman numeral: %r" % (s,))
    if not 1 <= total <= 3999:
        raise ValueError("out of range 1..3999: %r" % (s,))
    if _to_roman(total) != s:
        raise ValueError("non-canonical Roman numeral: %r" % (s,))
    return total
