import re

_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+((?:[0-9A-Za-z-]+)(?:\.[0-9A-Za-z-]+)*))?$"
)

_COMPARATOR_RE = re.compile(r"^(>=|<=|>|<|=|\^|~)?(.*)$")


def _parse_version(text):
    """Return (major, minor, patch, pre_tuple_or_None). Raise ValueError if invalid."""
    if not isinstance(text, str):
        raise ValueError("invalid version: {!r}".format(text))
    m = _VERSION_RE.match(text)
    if m is None:
        raise ValueError("invalid version: {!r}".format(text))
    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))
    raw_pre = m.group(4)
    if raw_pre is None:
        pre = None
    else:
        parts = raw_pre.split(".")
        for ident in parts:
            if not ident:
                raise ValueError("invalid version: {!r}".format(text))
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError("invalid version: {!r}".format(text))
        pre = tuple(parts)
    # build metadata (m.group(5)) is validated by the regex and otherwise ignored
    return (major, minor, patch, pre)


def _compare_pre(a, b):
    """Compare two pre-release tuples (or None). Return -1, 0 or 1."""
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    for x, y in zip(a, b):
        if x == y:
            continue
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num:
            return -1
        elif y_num:
            return 1
        else:
            return -1 if x < y else 1
    if len(a) == len(b):
        return 0
    return -1 if len(a) < len(b) else 1


def _compare_versions(a, b):
    """Compare two parsed versions. Return -1, 0 or 1."""
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1
    return _compare_pre(a[3], b[3])


def _parse_comparator(part):
    """Return (operator, parsed_version_or_None). Raise ValueError if invalid."""
    if part == "*":
        return ("*", None)
    m = _COMPARATOR_RE.match(part)
    op = m.group(1) or "="
    version = _parse_version(m.group(2))
    return (op, version)


def _eval_comparator(comp, ver):
    op, cver = comp
    if op == "*":
        return True
    c = _compare_versions(ver, cver)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    if op == "^":
        cm, cmi, cp, _ = cver
        if cm > 0:
            upper = (cm + 1, 0, 0, None)
        elif cmi > 0:
            upper = (0, cmi + 1, 0, None)
        else:
            upper = (0, 0, cp + 1, None)
        return c >= 0 and _compare_versions(ver, upper) < 0
    if op == "~":
        cm, cmi, _, _ = cver
        upper = (cm, cmi + 1, 0, None)
        return c >= 0 and _compare_versions(ver, upper) < 0
    raise ValueError("invalid operator: {!r}".format(op))


def _satisfies_group(comparators, ver):
    if not comparators:
        return False
    for comp in comparators:
        if not _eval_comparator(comp, ver):
            return False
    if ver[3] is not None:
        for _, cver in comparators:
            if (
                cver is not None
                and cver[3] is not None
                and (cver[0], cver[1], cver[2]) == (ver[0], ver[1], ver[2])
            ):
                break
        else:
            return False
    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a semver version against an npm-style constraint."""
    if not isinstance(constraint, str):
        raise ValueError("invalid constraint: {!r}".format(constraint))

    ver = _parse_version(version)

    text = constraint.strip()
    if not text:
        raise ValueError("empty constraint")

    groups = []
    for raw_group in text.split("||"):
        raw_group = raw_group.strip()
        if not raw_group:
            raise ValueError("empty group in constraint: {!r}".format(constraint))
        parts = raw_group.split()
        comparators = [_parse_comparator(p) for p in parts]
        groups.append(comparators)

    return any(_satisfies_group(g, ver) for g in groups)
