from typing import List


def normalize_path(p: str) -> str:
    """Normalize a Unix-style path.

    Collapses empty and "." components, resolves ".." against preceding
    components (kept verbatim for unresolvable leading ".." in relative
    paths), and never emits a trailing slash except for the root "/".
    """
    if not isinstance(p, str):
        raise TypeError("normalize_path() expects a str, got %r" % type(p).__name__)

    absolute = p.startswith("/")
    stack: List[str] = []

    for component in p.split("/"):
        if component == "" or component == ".":
            continue
        if component == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                # Leading, unresolvable ".." in a relative path is preserved.
                stack.append("..")
            # Absolute path: ".." at the root is ignored.
        else:
            # Anything else, including "...", is an ordinary name.
            stack.append(component)

    if absolute:
        return "/" + "/".join(stack) if stack else "/"
    return "/".join(stack) if stack else "."
