"""Split a URL into its components.

Python 3.9, standard library only.
"""

import re

__all__ = ["parse_url"]

# scheme: letter followed by letters/digits/"+"/"-"/".", then "://"
_SCHEME_RE = re.compile(r"([A-Za-z][A-Za-z0-9+.\-]*)://")

# characters that may never appear in a plain (non-bracketed) host
_HOST_FORBIDDEN = frozenset(" /?#@:[]")

_ASCII_DIGITS = frozenset("0123456789")
_IPV6_ADDR_CHARS = frozenset("0123456789abcdefABCDEF:.")
_IPV6_ZONE_CHARS = frozenset(
    "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-._~%"
)


def _parse_port(text):
    """1..5 ASCII digits, value 1..65535 -> int. Anything else is an error."""
    if not text or len(text) > 5:
        raise ValueError("invalid port: %r" % (text,))
    for ch in text:
        if ch not in _ASCII_DIGITS:
            raise ValueError("invalid port: %r" % (text,))
    value = int(text)
    if not 1 <= value <= 65535:
        raise ValueError("port out of range: %r" % (text,))
    return value


def _split_ipv6_literal(hostport):
    """hostport starts with '['. Return (host_without_brackets, tail)."""
    end = hostport.find("]")
    if end == -1:
        raise ValueError("unterminated IPv6 literal: %r" % (hostport,))
    literal = hostport[1:end]
    if not literal:
        raise ValueError("empty IPv6 literal")
    address, sep, zone = literal.partition("%")
    if not address or any(ch not in _IPV6_ADDR_CHARS for ch in address):
        raise ValueError("invalid IPv6 literal: %r" % (literal,))
    if sep and (not zone or any(ch not in _IPV6_ZONE_CHARS for ch in zone)):
        raise ValueError("invalid IPv6 zone id: %r" % (literal,))
    return literal.lower(), hostport[end + 1:]


def _split_host_port(hostport):
    """Return (host, port) from the part of the authority after userinfo."""
    if hostport.startswith("["):
        host, tail = _split_ipv6_literal(hostport)
        if tail == "":
            return host, None
        if not tail.startswith(":"):
            raise ValueError("invalid character after IPv6 literal: %r" % (tail,))
        return host, _parse_port(tail[1:])

    if ":" in hostport:
        host_part, _, port_part = hostport.partition(":")
    else:
        host_part, port_part = hostport, None

    if host_part == "":
        raise ValueError("empty host")
    for ch in host_part:
        if ch in _HOST_FORBIDDEN:
            raise ValueError("invalid character in host: %r" % (ch,))

    port = None if port_part is None else _parse_port(port_part)
    return host_part.lower(), port


def parse_url(url):
    """Split *url* into scheme/userinfo/host/port/path/query/fragment.

    Raises ValueError on anything that does not match the rules.
    """
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = match.group(1).lower()
    rest = url[match.end():]

    # authority ends at the first '/', '?' or '#'
    cut = len(rest)
    for i, ch in enumerate(rest):
        if ch in "/?#":
            cut = i
            break
    authority = rest[:cut]
    remainder = rest[cut:]

    if authority == "":
        raise ValueError("empty authority")

    if "@" in authority:
        userinfo, _, hostport = authority.rpartition("@")
    else:
        userinfo, hostport = "", authority

    host, port = _split_host_port(hostport)

    # first '#' starts the fragment; before it, the first '?' starts the query
    hash_pos = remainder.find("#")
    if hash_pos == -1:
        before_hash, fragment = remainder, ""
    else:
        before_hash, fragment = remainder[:hash_pos], remainder[hash_pos + 1:]

    query_pos = before_hash.find("?")
    if query_pos == -1:
        path, query = before_hash, ""
    else:
        path, query = before_hash[:query_pos], before_hash[query_pos + 1:]

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
