"""Exact, integer-only byte formatter (Python 3.9, stdlib only)."""

_UNITS = ("KiB", "MiB", "GiB", "TiB")  # exponents 1..4 relative to 1024
_MAX_EXP = len(_UNITS)  # TiB is terminal


def format_bytes(n: int) -> str:
    """Format a byte count as e.g. "1023 B", "1.5 KiB", "1024.0 TiB".

    Values below 1024 are printed as plain bytes. Otherwise the largest
    power-of-1024 unit whose value is >= 1 is used, printed with exactly one
    decimal place, rounded half-up on the true mathematical value. If that
    rounding reaches 1024.0, the next unit is used instead. TiB is the
    largest unit, so 1024 TiB and beyond stay in TiB.

    Raises ValueError for negative input.
    """
    if n < 0:
        raise ValueError("byte count must be non-negative, got %r" % (n,))

    if n < 1024:
        return "%d B" % n

    # Largest exponent exp in 1..4 such that n / 1024**exp >= 1.
    exp = 1
    while exp < _MAX_EXP and n >= 1024 ** (exp + 1):
        exp += 1

    while True:
        denom = 1024 ** exp
        # round(n * 10 / denom) with half-up, done in exact integer arithmetic:
        #   floor(n*10/denom + 1/2) == (20*n + denom) // (2*denom)
        tenths = (20 * n + denom) // (2 * denom)
        if tenths >= 10240 and exp < _MAX_EXP:
            exp += 1  # rounding overflowed to 1024.0 -> use the next unit
            continue
        return "%d.%d %s" % (tenths // 10, tenths % 10, _UNITS[exp - 1])
