def next_weekday(date_str: str, weekday: int) -> str:
    if not 0 <= weekday <= 6:
        raise ValueError("weekday must be in the range 0 to 6")

    date = datetime.strptime(date_str, "%Y-%m-%d").date()
    days_ahead = (weekday - date.weekday()) % 7
    if days_ahead == 0:
        days_ahead = 7

