import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    # Collect every item mentioned anywhere (as a key or inside a list).
    items = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    # Normalize dependencies: distinct deps only (duplicates ignored);
    # items without a key of their own have no dependencies.
    dep_map = {item: set(deps.get(item, ())) for item in items}

    # A self-dependency is a cycle.
    for item, ds in dep_map.items():
        if item in ds:
            raise ValueError(f"cycle detected: {item!r} depends on itself")

    # Build reverse edges and in-degree counts (over distinct dependencies).
    dependents: dict[str, list[str]] = {item: [] for item in items}
    in_degree: dict[str, int] = {item: len(ds) for item, ds in dep_map.items()}
    for item, ds in dep_map.items():
        for d in ds:
            dependents[d].append(item)

    # Kahn's algorithm with a min-heap: among all items whose dependencies
    # are already placed, always take the lexicographically smallest.
    heap = [item for item, deg in in_degree.items() if deg == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        item = heapq.heappop(heap)
        result.append(item)
        for dependent in dependents[item]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    # If not all items were placed, a cycle exists.
    if len(result) != len(items):
        raise ValueError("dependency cycle detected")

    return result
