    regex = []
    i = 0

    def class_char(char: str) -> str:
        if char in r"\]-^":
            return "\\" + char
        return char

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(".*")
                i += 2
            else:
                regex.append("[^/]*")
                i += 1
        elif char == "?":
            regex.append("[^/]")
            i += 1
        elif char == "[":
            i += 1
            if i == len(pattern):
                raise ValueError("unclosed character set")

            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            chars = []
            if i < len(pattern) and pattern[i] == "]":
                chars.append(("]", True))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash in pattern")
                    chars.append((pattern[i], True))
                else:
                    chars.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError("unclosed character set")
            if not chars:
                raise ValueError("empty character set")

            pieces = []
            j = 0
            while j < len(chars):
                if (
                    j + 2 < len(chars)
                    and chars[j + 1] == ("-", False)
                    and chars[j][0] != "-"
                    and chars[j + 2][0] != "-"
                ):
                    start = chars[j][0]
                    end = chars[j + 2][0]
                    if ord(start) > ord(end):
                        raise ValueError("descending character range")
                    pieces.append(class_char(start) + "-" + class_char(end))
                    j += 3
