from datetime import datetime, timedelta

_FIELD_RANGES = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
_NUM_RE = re.compile(r"\d+")


def _to_int(text):
    if not _NUM_RE.fullmatch(text):
        raise ValueError("invalid number: %r" % (text,))
    return int(text)


def _parse_item(item, lo, hi):
    if "/" in item:
        parts = item.split("/")
        if len(parts) != 2:
            raise ValueError("malformed item: %r" % (item,))
        base, step_text = parts
        step = _to_int(step_text)
        if step < 1:
            raise ValueError("step must be >= 1: %r" % (item,))
    else:
        base = item
        step = None

    if base == "*":
        start, end = lo, hi
    elif "-" in base:
        parts = base.split("-")
        if len(parts) != 2:
            raise ValueError("malformed item: %r" % (item,))
        start = _to_int(parts[0])
        end = _to_int(parts[1])
        if start > end:
            raise ValueError("invalid range: %r" % (item,))
        if start < lo or end > hi:
            raise ValueError("value out of range: %r" % (item,))
    else:
        start = _to_int(base)
        if start < lo or start > hi:
            raise ValueError("value out of range: %r" % (item,))
        if step is None:
            return [start]
        end = hi

    return list(range(start, end + 1, step if step is not None else 1))


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(","):
        values.update(_parse_item(item, lo, hi))
    if not values:
        raise ValueError("empty field")
    return sorted(values)


def _day_matches(day, dom_restricted, dom_set, dow_restricted, dow_set):
    dom_hit = day.day in dom_set
    dow_hit = (day.isoweekday() % 7) in dow_set
    if dom_restricted and dow_restricted:
        return dom_hit or dow_hit
    if dom_restricted:
        return dom_hit
    if dow_restricted:
        return dow_hit
    return True


def _add_years(value, years):
    try:
        return value.replace(year=value.year + years)
    except ValueError:
        return value.replace(year=value.year + years, day=28)


def next_cron(expr: str, after: str) -> str:
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minutes = _parse_field(fields[0], *_FIELD_RANGES[0])
    hours = _parse_field(fields[1], *_FIELD_RANGES[1])
    doms = _parse_field(fields[2], *_FIELD_RANGES[2])
    months = _parse_field(fields[3], *_FIELD_RANGES[3])
    dows = _parse_field(fields[4], *_FIELD_RANGES[4])

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    dom_set = set(doms)
    dow_set = set(dows)
    month_set = set(months)

    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except Exception:
        raise ValueError("invalid 'after' value: %r" % (after,))

    limit = _add_years(start, 5)
    last_day = limit.date()

    day = start.date()
    while day <= last_day:
        if day.month in month_set and _day_matches(
            day, dom_restricted, dom_set, dow_restricted, dow_set
        ):
            for h in hours:
                for m in minutes:
                    candidate = datetime(day.year, day.month, day.day, h, m)
                    if candidate > start:
                        if candidate > limit:
                            raise ValueError("no matching time within 5 years")
                        return candidate.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)

    raise ValueError("no matching time within 5 years")
