import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """Deterministic topological sort: among all items whose dependencies are
    already placed, always place the lexicographically smallest one first.

    Raises ValueError on a cycle (a self-dependency counts as a cycle).
    The input mapping is only read, never mutated.
    """
    # Every item mentioned anywhere is a node once.
    nodes: set[str] = set(deps)
    for required in deps.values():
        nodes.update(required)

    # Duplicate dependency entries collapse into a set.
    needs: dict[str, set[str]] = {node: set(deps.get(node, ())) for node in nodes}

    # Reverse edges: which nodes become unblocked once `node` is placed.
    dependents: dict[str, set[str]] = {node: set() for node in nodes}
    for node, required in needs.items():
        for dep in required:
            dependents[dep].add(node)

    remaining: dict[str, int] = {node: len(req) for node, req in needs.items()}

    ready = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(ready)  # min-string order, "plain string comparison"

    order: list[str] = []
    while ready:
        node = heapq.heappop(ready)
        order.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    # A self-dependency keeps its own counter above zero, so it lands here too.
    if len(order) != len(nodes):
        raise ValueError("cyclic dependency graph")

    return order
