def wrap_text(text: str, width: int) -> list[str]:
    """Wrap `text` into lines of at most `width` characters.

    Words are runs of characters separated by one or more U+0020 spaces.
    Filling is greedy. A word longer than `width` always starts on a new
    line and is split into consecutive pieces of exactly `width` characters;
    its final (possibly shorter) piece starts a line that may continue with
    following words if they fit.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current: list[str] = []  # words/pieces composing the current line
    current_len = 0          # length of ' '.join(current)

    for word in text.split(' '):
        if not word:
            # Collapses runs of spaces, plus leading/trailing spaces.
            continue

        if len(word) > width:
            # A too-long word always begins on a fresh line.
            if current:
                lines.append(' '.join(current))
                current, current_len = [], 0
            pieces = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(pieces[:-1])
            current, current_len = [pieces[-1]], len(pieces[-1])
        else:
            if current and current_len + 1 + len(word) > width:
                lines.append(' '.join(current))
                current, current_len = [], 0
            if current:
                current_len += 1 + len(word)
            else:
                current_len = len(word)
            current.append(word)

    if current:
        lines.append(' '.join(current))
    return lines
