import re


def glob_match(pattern: str, name: str) -> bool:
    parts = ["\\A"]
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("trailing backslash")
            parts.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                parts.append(".*")
                i += 2
            else:
                parts.append("[^/]*")
                i += 1
        elif char == "?":
            parts.append("[^/]")
            i += 1
        elif char == "[":
            i += 1
            negated = i < len(pattern) and pattern[i] == "!"
            if negated:
                i += 1

            tokens = []
            if i < len(pattern) and pattern[i] == "]":
                tokens.append(("]", False))
                i += 1

            closed = False
            while i < len(pattern):
                char = pattern[i]
                if char == "]":
                    closed = True
                    i += 1
                    break
                if char == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("trailing backslash")
                    tokens.append((pattern[i], True))
                    i += 1
                else:
                    tokens.append((char, False))
                    i += 1

            if not closed:
                raise ValueError("unclosed character class")
            if not tokens:
                raise ValueError("empty character class")

            class_parts = []
            j = 0
            while j < len(tokens):
                if (
                    j + 2 < len(tokens)
                    and tokens[j + 1] == ("-", False)
                    and tokens[j][0] != "-"
                    and tokens[j + 2][0] != "-"
                ):
                    start, end = tokens[j][0], tokens[j + 2][0]
                    if ord(start) > ord(end):
                        raise ValueError("descending character range")
                    class_parts.append(re.escape(start) + "-" + re.escape(end))
                    j += 3
                else:
                    class_parts.append(re.escape(tokens[j][0]))
                    j += 1

            prefix = "^" if negated else ""
            parts.append("[" + prefix + "".join(class_parts) + "]")
        else:
            parts.append(re.escape(char))
            i += 1

    parts.append("\\Z")
    try:
        return re.match("".join(parts), name) is not None
    except re.error as exc:
        raise ValueError("invalid pattern") from exc
