from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: List[str] = []
    current = ""

    for word in text.split(" "):
        if not word:
            continue

        if len(word) > width:
            if current:
                lines.append(current)
                current = ""

            start = 0
            while start + width < len(word):
                lines.append(word[start:start + width])
                start += width
            current = word[start:]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word

    if current:
        lines.append(current)

    return lines
