def mask_email(s: str) -> str:
    """Mask the local part of an email address, leaving the domain intact.

    The local part keeps its first and last character; everything between them
    becomes "*".  A one-character local part becomes "*", and a two-character
    local part keeps its first character and masks the second.

    Raises ValueError unless ``s`` holds exactly one "@", with a non-empty
    local part before it and a non-empty domain after it.
    """
    if not isinstance(s, str):
        raise ValueError("email address must be a string")
    if s.count("@") != 1:
        raise ValueError("email address must contain exactly one '@'")

    local, domain = s.split("@")
    if not local:
        raise ValueError("email address must have a non-empty local part")
    if not domain:
        raise ValueError("email address must have a non-empty domain")

    if len(local) == 1:
        masked = "*"
    elif len(local) == 2:
        masked = local[0] + "*"
    else:
        masked = local[0] + "*" * (len(local) - 2) + local[-1]

    return masked + "@" + domain
