import re
from functools import cmp_to_key


_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)\."
    r"(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_NUMERIC_IDENTIFIER_RE = re.compile(r"0|[1-9][0-9]*")
_TOKEN_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.+)")


def _parse_version(text):
    match = _VERSION_RE.fullmatch(text)
    if not match:
        raise ValueError("invalid semantic version")

    major, minor, patch = map(int, match.group(1, 2, 3))
    prerelease_text = match.group(4)
    prerelease = None

    if prerelease_text is not None:
        prerelease = prerelease_text.split(".")
        if any(
            identifier.isdigit()
            and not _NUMERIC_IDENTIFIER_RE.fullmatch(identifier)
            for identifier in prerelease
        ):
            raise ValueError("numeric pre-release identifiers cannot have leading zeros")

    return (major, minor, patch, prerelease)


def _compare_versions(left, right):
    left_core = left[:3]
    right_core = right[:3]
    if left_core != right_core:
        return (left_core > right_core) - (left_core < right_core)

    left_pre = left[3]
    right_pre = right[3]

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        left_numeric = _NUMERIC_IDENTIFIER_RE.fullmatch(left_id) is not None
        right_numeric = _NUMERIC_IDENTIFIER_RE.fullmatch(right_id) is not None

        if left_numeric and right_numeric:
            left_value, right_value = int(left_id), int(right_id)
            if left_value != right_value:
                return (left_value > right_value) - (left_value < right_value)
        elif left_numeric != right_numeric:
            return -1 if left_numeric else 1
        elif left_id != right_id:
            return (left_id > right_id) - (left_id < right_id)

    return (len(left_pre) > len(right_pre)) - (len(left_pre) < len(right_pre))


def semver_satisfies(version: str, constraint: str) -> bool:
    """Check a SemVer version against npm-style comparator groups.

    Reject malformed versions, comparators, empty groups, and empty constraints.
    Build metadata is validated but ignored. Pre-release versions additionally
    require a comparator in the matching group with a pre-release on the same core.
    """
    candidate = _parse_version(version)

    if not constraint or not constraint.strip():
        raise ValueError("constraint must not be empty")

    groups = constraint.split("||")
    if any(not group.strip() for group in groups):
        raise ValueError("constraint contains an empty group")

    for group in groups:
        tokens = group.split()
        if not tokens:
            raise ValueError("constraint contains an empty group")

        comparators = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                comparators.append(("*", None, None))
                continue

            match = _TOKEN_RE.fullmatch(token)
            if not match:
                raise ValueError("invalid comparator")

            operator = match.group(1) or "="
            version_text = match.group(2)
            if version_text == "*" or not version_text:
                raise ValueError("invalid comparator")

            bound = _parse_version(version_text)
            if bound[3] is not None:
                prerelease_cores.add(bound[:3])

            if operator == "^":
                major, minor, patch = bound[:3]
                if major > 0:
                    upper = (major + 1, 0, 0, None)
                elif minor > 0:
                    upper = (0, minor + 1, 0, None)
                else:
                    upper = (0, 0, patch + 1, None)
                comparators.append((">=", bound, None))
                comparators.append(("<", upper, None))
            elif operator == "~":
                major, minor, _ = bound[:3]
                upper = (major, minor + 1, 0, None)
                comparators.append((">=", bound, None))
                comparators.append(("<", upper, None))
            else:
                comparators.append((operator, bound, None))

        if candidate[3] is not None and candidate[:3] not in prerelease_cores:
            continue

        satisfied = True
        for operator, bound, _ in comparators:
            if operator == "*":
                continue

            comparison = _compare_versions(candidate, bound)
            if (
                (operator == "=" and comparison != 0)
                or (operator == ">" and comparison <= 0)
                or (operator == ">=" and comparison < 0)
                or (operator == "<" and comparison >= 0)
                or (operator == "<=" and comparison > 0)
            ):
                satisfied = False
                break

        if satisfied:
            return True

    return False
