import bisect
import calendar
import re
from datetime import datetime, timedelta


_ITEM_RE = re.compile(r"(\*|[0-9]+(?:-[0-9]+)?)(?:/([0-9]+))?")
_TIME_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")


def _bounded_integer(text: str, limit: int) -> int:
    """Return the integer, or limit + 1 if it exceeds limit."""
    text = text.lstrip("0") or "0"
    bound = str(limit)
    if len(text) > len(bound) or (
        len(text) == len(bound) and text > bound
    ):
        return limit + 1
    return int(text)


def _parse_field(field: str, minimum: int, maximum: int):
    values = set()

    for item in field.split(","):
        match = _ITEM_RE.fullmatch(item)
        if match is None:
            raise ValueError("Malformed cron item")

        base, step_text = match.groups()
        step = (
            1
            if step_text is None
            else _bounded_integer(step_text, maximum - minimum + 1)
        )
        if step < 1:
            raise ValueError("Cron steps must be positive")

        if base == "*":
            start, end = minimum, maximum
        elif "-" in base:
            left, right = base.split("-")
            start = _bounded_integer(left, maximum)
            end = _bounded_integer(right, maximum)
        else:
            start = _bounded_integer(base, maximum)
            end = start if step_text is None else maximum

        if not minimum <= start <= end <= maximum:
            raise ValueError("Cron value or range is out of bounds")

        values.update(range(start, end + 1, step))

    return values


def next_cron(expr: str, after: str) -> str:
    if not isinstance(expr, str) or not isinstance(after, str):
        raise ValueError("expr and after must be strings")

    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("A cron expression must contain five fields")

    bounds = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))
    minutes, hours, month_days, months, week_days = [
        _parse_field(field, low, high)
        for field, (low, high) in zip(fields, bounds)
    ]

    if _TIME_RE.fullmatch(after) is None:
        raise ValueError("after must have format YYYY-MM-DD HH:MM")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as exc:
        raise ValueError("Invalid date or time") from exc

    if start.year + 5 <= 9999:
        end_year = start.year + 5
        end_day = min(
            start.day,
            calendar.monthrange(end_year, start.month)[1],
        )
        deadline = start.replace(year=end_year, day=end_day)
    else:
        deadline = datetime(9999, 12, 31, 23, 59)

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"
    times = sorted(hour * 60 + minute for hour in hours for minute in minutes)

    day = start.date()
    last_day = deadline.date()

    while day <= last_day:
        if day.month in months:
            dom_matches = day.day in month_days
            dow_matches = (day.weekday() + 1) % 7 in week_days

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            elif dom_restricted:
                day_matches = dom_matches
            elif dow_restricted:
                day_matches = dow_matches
            else:
                day_matches = True

            if day_matches:
                index = (
                    bisect.bisect_right(times, start.hour * 60 + start.minute)
                    if day == start.date()
                    else 0
                )
                if index < len(times):
                    hour, minute = divmod(times[index], 60)
                    candidate = datetime(
                        day.year, day.month, day.day, hour, minute
                    )
                    if candidate <= deadline:
                        return (
                            f"{candidate.year:04d}-{candidate.month:02d}-"
                            f"{candidate.day:02d} {candidate.hour:02d}:"
                            f"{candidate.minute:02d}"
                        )

        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("No matching time exists within five years")
