def first_bracket_error(s: str) -> int:
    matching = {')': '(', ']': '[', '}': '{'}
    stack = []  # (opening_bracket_char, index)

    for i, ch in enumerate(s):
        if ch in '([{':
            stack.append((ch, i))
        elif ch in matching:
            if not stack or stack[-1][0] != matching[ch]:
                return i
            stack.pop()

    # Any opening brackets left unclosed: leftmost is at the bottom of the stack.
    if stack:
        return stack[0][1]
    return -1
