import re


def glob_match(pattern: str, name: str) -> bool:
    # Requirements and edge cases:
    # - Match the entire name, case-sensitively.
    # - * and ? do not match /; runs of two or more * match anything.
    # - Character classes support negation, ranges, and a leading literal ].
    # - Backslash quotes the next character, including inside a character class.
    # - Reject an unmatched [, a trailing backslash, and invalid ranges.
    regex = ["^"]
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("Trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            end = i + 1
            while end < len(pattern) and pattern[end] == "*":
                end += 1
            regex.append(r"[\s\S]*" if end - i >= 2 else r"[^/]*")
            i = end
        elif char == "?":
            regex.append(r"[^/]")
            i += 1
        elif char == "[":
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            members = []
            if i < len(pattern) and pattern[i] == "]":
                members.append(("]", False))
                i += 1

            while i < len(pattern) and pattern[i] != "]":
                if pattern[i] == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("Trailing backslash in character class")
                    members.append((pattern[i], True))
                else:
                    members.append((pattern[i], False))
                i += 1

            if i == len(pattern):
                raise ValueError("Unclosed character class")
            if not members:
                raise ValueError("Empty character class")

            class_parts = []
            j = 0
            while j < len(members):
                if (
                    j + 2 < len(members)
                    and members[j + 1] == ("-", False)
                    and not members[j][1]
                    and not members[j + 2][1]
                ):
                    start, finish = members[j][0], members[j + 2][0]
                    if ord(start) > ord(finish):
                        raise ValueError("Invalid character range")
                    class_parts.append(re.escape(start) + "-" + re.escape(finish))
                    j += 3
                else:
                    class_parts.append(re.escape(members[j][0]))
                    j += 1

            regex.append("[" + ("^" if negate else "") + "".join(class_parts) + "]")
            i += 1
        else:
            regex.append(re.escape(char))
            i += 1

    regex.append("$")
    try:
        return re.fullmatch("".join(regex), name) is not None
    except re.error as exc:
        raise ValueError("Invalid glob pattern") from exc
