import re


def semver_satisfies(version: str, constraint: str) -> bool:
    version_pattern = re.compile(
        r"(0|[1-9][0-9]*)\."
        r"(0|[1-9][0-9]*)\."
        r"(0|[1-9][0-9]*)"
        r"(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
        r"(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?"
    )
    comparator_pattern = re.compile(r"(>=|<=|[=><^~])?(.+)")

    def parse_version(text):
        if not isinstance(text, str):
            raise ValueError("Version must be a string")

        match = version_pattern.fullmatch(text)
        if match is None:
            raise ValueError("Invalid semantic version: {!r}".format(text))

        core = tuple(int(match.group(i)) for i in (1, 2, 3))
        prerelease = match.group(4)

        if prerelease is None:
            return core + ((1,),)

        identifiers = []
        for identifier in prerelease.split("."):
            if all("0" <= char <= "9" for char in identifier):
                if len(identifier) > 1 and identifier[0] == "0":
                    raise ValueError(
                        "Numeric prerelease identifiers cannot have leading zeros"
                    )
                identifiers.append((0, int(identifier)))
            else:
                identifiers.append((1, identifier))

        return core + ((0, tuple(identifiers)),)

    candidate = parse_version(version)

    if not isinstance(constraint, str) or not constraint.strip():
        raise ValueError("Constraint must be a nonempty string")

    groups = []
    for group_text in constraint.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("Constraint groups must not be empty")

        comparisons = []
        prerelease_cores = set()

        for token in tokens:
            if token == "*":
                continue

            match = comparator_pattern.fullmatch(token)
            if match is None:
                raise ValueError("Invalid comparator: {!r}".format(token))

            operator = match.group(1) or "="
            bound = parse_version(match.group(2))
            core = bound[:3]

            if bound[3][0] == 0:
                prerelease_cores.add(core)

            if operator in ("^", "~"):
                major, minor, patch = core
                if operator == "~":
                    upper_core = (major, minor + 1, 0)
                elif major > 0:
                    upper_core = (major + 1, 0, 0)
                elif minor > 0:
                    upper_core = (0, minor + 1, 0)
                else:
                    upper_core = (0, 0, patch + 1)

                comparisons.append((">=", bound))
                comparisons.append(("<", upper_core + ((1,),)))
            else:
                comparisons.append((operator, bound))

        groups.append((comparisons, prerelease_cores))

    def matches(operator, bound):
        if operator == "=":
            return candidate == bound
        if operator == ">":
            return candidate > bound
        if operator == ">=":
            return candidate >= bound
        if operator == "<":
            return candidate < bound
        return candidate <= bound

    for comparisons, prerelease_cores in groups:
        if candidate[3][0] == 0 and candidate[:3] not in prerelease_cores:
            continue
        if all(matches(operator, bound) for operator, bound in comparisons):
            return True

    return False
