def round_half_up(x: str, ndigits: int) -> str:
    if not isinstance(x, str):
        raise ValueError("x must be a decimal string")
    if not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")

    negative = x.startswith("-")
    body = x[1:] if negative else x

    if not body:
        raise ValueError("invalid decimal number")
    if body.count(".") > 1:
        raise ValueError("invalid decimal number")

    if "." in body:
        integer_part, fractional_part = body.split(".")
        if not integer_part or not fractional_part:
            raise ValueError("invalid decimal number")
    else:
        integer_part = body
        fractional_part = ""

    if not all("0" <= char <= "9" for char in integer_part):
        raise ValueError("invalid decimal number")
    if not all("0" <= char <= "9" for char in fractional_part):
        raise ValueError("invalid decimal number")

    if len(fractional_part) <= ndigits:
        rounded_fraction = fractional_part.ljust(ndigits, "0")
        rounded_integer = integer_part
    else:
        kept_fraction = fractional_part[:ndigits]
        discarded_fraction = fractional_part[ndigits:]
        kept = integer_part + kept_fraction

        if discarded_fraction[0] >= "5":
            digits = list(kept)
            index = len(digits) - 1

            while index >= 0 and digits[index] == "9":
                digits[index] = "0"
                index -= 1

            if index < 0:
                digits.insert(0, "1")
            else:
                digits[index] = chr(ord(digits[index]) + 1)

            kept = "".join(digits)

        if ndigits:
            rounded_integer = kept[:-ndigits]
            rounded_fraction = kept[-ndigits:]
        else:
            rounded_integer = kept
            rounded_fraction = ""

    rounded_integer = rounded_integer.lstrip("0") or "0"
    is_zero = rounded_integer == "0" and (
        not rounded_fraction or set(rounded_fraction) == {"0"}
    )

    sign = "-" if negative and not is_zero else ""
    if ndigits == 0:
        return sign + rounded_integer
    return sign + rounded_integer + "." + rounded_fraction
