    dependents = {item: [] for item in prerequisites}
    remaining = {}

    for item, required_items in prerequisites.items():
        remaining[item] = len(required_items)
        for required in required_items:
            dependents[required].append(item)

    ready = [item for item, count in remaining.items() if count == 0]
    heapq.heapify(ready)

    result = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)

        for dependent in dependents[item]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(prerequisites):
