def add_months(date_str: str, n: int) -> str:
    """Add `n` calendar months to a YYYY-MM-DD date string.

    If the target month has fewer days than the original day of month,
    the day is clamped to the last day of the target month.
    """
    year, month, day = map(int, date_str.split("-"))

    # Convert to a 0-based month counter so that multi-year and negative
    # shifts are handled correctly by floor division (Python's divmod
    # floors toward negative infinity, which is what we want here).
    total = year * 12 + (month - 1) + n
    new_year, month_index = divmod(total, 12)
    new_month = month_index + 1

    if new_month == 2:
        is_leap = new_year % 4 == 0 and (new_year % 100 != 0 or new_year % 400 == 0)
        last_day = 29 if is_leap else 28
    elif new_month in (4, 6, 9, 11):
        last_day = 30
    else:
        last_day = 31

    new_day = min(day, last_day)
    return f"{new_year:04d}-{new_month:02d}-{new_day:02d}"
