import heapq


def topo_sort(deps: dict) -> list:
    # Collect every item mentioned anywhere; dedupe dependency edges.
    nodes = set(deps)
    edges_out = {}  # dependency -> set of items that need it

    pending = {}  # item -> set of its (distinct) dependencies
    for item, dep_list in deps.items():
        pending.setdefault(item, set())
        for d in dep_list:
            nodes.add(d)
            pending.setdefault(d, set())
            pending[item].add(d)

    for n in nodes:
        pending.setdefault(n, set())
        edges_out.setdefault(n, set())

    indegree = {n: len(pending[n]) for n in nodes}
    for item, ds in pending.items():
        for d in ds:
            edges_out[d].add(item)

    available = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(available)

    ordered = []
    while available:
        n = heapq.heappop(available)
        ordered.append(n)
        for m in edges_out[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(available, m)

    if len(ordered) != len(nodes):
        raise ValueError("dependency graph contains a cycle")

    return ordered
