def normalize_path(p: str) -> str:
    """Normalize a Unix-style path.

    - Empty path components and "." are ignored.
    - ".." removes the previous component; at the root of an absolute path
      it is ignored, while in a relative path unresolvable ".." are kept.
    - The result has no trailing slash, except for the root "/".
    - An empty relative result is ".".
    """
    absolute = p.startswith("/")
    stack = []

    for comp in p.split("/"):
        if comp == "" or comp == ".":
            continue
        if comp == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif absolute:
                # ".." at the root of an absolute path is ignored.
                continue
            else:
                # Relative path: unresolvable ".." is kept.
                stack.append("..")
        else:
            # Anything else (including "..." or ".hidden") is a normal name.
            stack.append(comp)

    if absolute:
        return "/" + "/".join(stack)
    return "/".join(stack) if stack else "."
