from typing import Optional


def earliest_slot(
    busy: list[tuple[int, int]], duration: int, start: int, end: int
) -> Optional[int]:
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")
    for interval in busy:
        b, f = interval
        if b >= f:
            raise ValueError("busy interval must have begin < finish")
    if end - start < duration:
        return None
    clipped = []
    for b, f in busy:
        lo = b if b > start else start
        hi = f if f < end else end
        if lo < hi:
            clipped.append((lo, hi))
    clipped.sort()
    t = start
    for b, f in clipped:
        if b - t >= duration:
            return t
        if f > t:
            t = f
    return t if end - t >= duration else None
