def format_bytes(n: int) -> str:
    if n < 0:
        raise ValueError("n must be nonnegative")
    if n < 1024:
        return f"{n} B"

    units = ("KiB", "MiB", "GiB", "TiB")
    index = 0
    scale = 1024

    while index < len(units) - 1 and n >= scale * 1024:
        scale *= 1024
        index += 1

    # Round the exact value to tenths, with ties rounded upward.
    tenths = (10 * n + scale // 2) // scale

    if tenths == 10240 and index < len(units) - 1:
        index += 1
        tenths = 10

    whole, decimal = divmod(tenths, 10)
    return f"{whole}.{decimal} {units[index]}"


