from typing import List


def parse_csv_line(line: str) -> List[str]:
    """Parse one CSV line, raising ValueError for invalid quoting."""
    fields: List[str] = []
    length = len(line)
    index = 0

    while True:
        if index < length and line[index] == '"':
            index += 1
            characters: List[str] = []

            while index < length:
                if line[index] != '"':
                    characters.append(line[index])
                    index += 1
                elif index + 1 < length and line[index + 1] == '"':
                    characters.append('"')
                    index += 2
                else:
                    index += 1
                    break
            else:
                raise ValueError("Unterminated quoted field")

            if index < length and line[index] != ",":
                raise ValueError("Unexpected character after closing quote")

            fields.append("".join(characters))
        else:
            start = index
            while index < length and line[index] != ",":
                if line[index] == '"':
                    raise ValueError("Double quote inside unquoted field")
                index += 1
            fields.append(line[start:index])

        if index == length:
            return fields

        index += 1
