def dedupe_keep_order(items):
    """Return a new list with duplicates removed, keeping first occurrences in order.

    Uses == for equality (so 1, 1.0 and True collapse), so unhashable items
    such as lists and dicts are supported. The input is never modified.
    """
    result = []
    for item in items:
        if not any(item == seen for seen in result):
            result.append(item)
    return result
