import re

_TOKEN_RE = re.compile(r"\s+|[0-9]+(?:\.[0-9]+)?|[+\-*/^()]", re.ASCII)


def _tokenize(source: str):
    """Split source into ('num', value) and (op, None) tokens."""
    tokens = []
    pos = 0
    length = len(source)
    while pos < length:
        match = _TOKEN_RE.match(source, pos)
        if match is None:
            raise ValueError("invalid character at position %d" % pos)
        text = match.group(0)
        pos = match.end()
        if text.isspace():
            continue
        if text in "+-*/^()":
            tokens.append((text, None))
        elif "." in text:
            tokens.append(("num", float(text)))
        else:
            tokens.append(("num", int(text)))
    return tokens


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def parse_expr():
        # expr := term (('+' | '-') term)*     (left-associative)
        nonlocal pos
        value = parse_term()
        while peek() in ("+", "-"):
            op = peek()
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        # term := unary (('*' | '/') unary)*   (left-associative)
        nonlocal pos
        value = parse_unary()
        while peek() in ("*", "/"):
            op = peek()
            pos += 1
            rhs = parse_unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    def parse_unary():
        # unary := '-' unary | power          (binds looser than '^')
        nonlocal pos
        if peek() == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    def parse_power():
        # power := atom ('^' unary)?          (right-associative)
        nonlocal pos
        base = parse_atom()
        if peek() == "^":
            pos += 1
            exponent = parse_unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero")
        return base

    def parse_atom():
        nonlocal pos
        token = peek()
        if token is None:
            raise ValueError("unexpected end of expression")
        if token == "(":
            pos += 1
            value = parse_expr()
            if peek() != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        if token == "num":
            value = tokens[pos][1]
            pos += 1
            return value
        raise ValueError("unexpected token %r" % (token,))

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token %r" % (tokens[pos][0],))
    return result
