"""Semantic version constraint matching.

Implements SemVer 2.0 version ordering together with npm-style constraint
ranges: ``||`` separated groups of whitespace separated comparators.
"""

import re

__all__ = ["semver_satisfies"]

# ---------------------------------------------------------------------------
# Version parsing
# ---------------------------------------------------------------------------

_NUMERIC = r"(?:0|[1-9][0-9]*)"
_IDENTIFIER = r"(?:" + _NUMERIC + r"|[0-9]*[a-zA-Z-][0-9a-zA-Z-]*)"

_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?"
)

_COMPARATOR_RE = re.compile(r"(>=|<=|>|<|=|\^|~)?(.*)")


def _parse_version(text):
    """Return ``(major, minor, patch, prerelease_or_None)`` for *text*.

    Build metadata is validated and then discarded.  Raises ``ValueError`` for
    anything that is not a valid SemVer 2.0 version string.
    """
    try:
        match = _VERSION_RE.fullmatch(text)
    except TypeError:
        match = None
    if match is None:
        raise ValueError("invalid semantic version: {!r}".format(text))
    prerelease = match.group(4)
    return (
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        None if prerelease is None else prerelease.split("."),
    )


# ---------------------------------------------------------------------------
# Ordering
# ---------------------------------------------------------------------------

def _compare_prerelease(left, right):
    """Compare two lists of pre-release identifiers: -1, 0 or 1."""
    for left_id, right_id in zip(left, right):
        if left_id == right_id:
            continue
        left_numeric = left_id.isdigit()
        right_numeric = right_id.isdigit()
        if left_numeric and right_numeric:
            left_value = int(left_id)
            right_value = int(right_id)
            return -1 if left_value < right_value else 1
        if left_numeric:
            return -1
        if right_numeric:
            return 1
        return -1 if left_id < right_id else 1
    if len(left) == len(right):
        return 0
    return -1 if len(left) < len(right) else 1


def _compare_versions(left, right):
    """Compare two parsed versions: -1, 0 or 1 (build metadata ignored)."""
    for index in range(3):
        if left[index] != right[index]:
            return -1 if left[index] < right[index] else 1
    left_pre = left[3]
    right_pre = right[3]
    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1
    return _compare_prerelease(left_pre, right_pre)


# ---------------------------------------------------------------------------
# Constraint parsing
# ---------------------------------------------------------------------------

def _parse_comparator(token):
    """Turn a comparator token into ``(operator, parsed_version_or_None)``."""
    if token == "*":
        return ("*", None)
    match = _COMPARATOR_RE.fullmatch(token)
    if match is None:
        raise ValueError("invalid comparator: {!r}".format(token))
    operator = match.group(1) or "="
    version_text = match.group(2)
    if not version_text:
        raise ValueError("invalid comparator: {!r}".format(token))
    return (operator, _parse_version(version_text))


def _parse_constraint(constraint):
    """Turn a constraint into a list of groups of comparators."""
    try:
        text = constraint.strip()
    except AttributeError:
        raise ValueError("invalid constraint: {!r}".format(constraint))
    if not text:
        raise ValueError("empty constraint")
    groups = []
    for raw_group in text.split("||"):
        comparators = [_parse_comparator(token) for token in raw_group.split()]
        if not comparators:
            raise ValueError("empty comparator group in constraint: {!r}".format(constraint))
        groups.append(comparators)
    return groups


# ---------------------------------------------------------------------------
# Comparator evaluation
# ---------------------------------------------------------------------------

def _caret_upper_bound(target):
    major, minor, patch = target[0], target[1], target[2]
    if major > 0:
        return (major + 1, 0, 0, None)
    if minor > 0:
        return (0, minor + 1, 0, None)
    return (0, 0, patch + 1, None)


def _tilde_upper_bound(target):
    return (target[0], target[1] + 1, 0, None)


def _comparator_holds(operator, target, version):
    comparison = _compare_versions(version, target)
    if operator == "=":
        return comparison == 0
    if operator == ">":
        return comparison > 0
    if operator == ">=":
        return comparison >= 0
    if operator == "<":
        return comparison < 0
    if operator == "<=":
        return comparison <= 0
    if operator == "^":
        return comparison >= 0 and _compare_versions(version, _caret_upper_bound(target)) < 0
    if operator == "~":
        return comparison >= 0 and _compare_versions(version, _tilde_upper_bound(target)) < 0
    raise ValueError("invalid comparator operator: {!r}".format(operator))


def _group_holds(comparators, version):
    for operator, target in comparators:
        if operator == "*":
            continue
        if not _comparator_holds(operator, target, version):
            return False
    if version[3] is not None:
        for operator, target in comparators:
            if (
                operator != "*"
                and target is not None
                and target[3] is not None
                and target[:3] == version[:3]
            ):
                break
        else:
            return False
    return True


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

def semver_satisfies(version, constraint):
    """Return ``True`` if *version* satisfies *constraint*.

    Raises ``ValueError`` for an invalid version, an invalid comparator or an
    empty constraint.
    """
    parsed_version = _parse_version(version)
    groups = _parse_constraint(constraint)
    for comparators in groups:
        if _group_holds(comparators, parsed_version):
            return True
    return False
