        raise ValueError("depth must be non-negative")

    result = []
    stack = [(iter(nested), 0)]

    while stack:
        items, level = stack[-1]
        try:
            item = next(items)
        except StopIteration:
            stack.pop()
            continue

        if type(item) is list and (depth is None or level < depth):
            stack.append((iter(item), level + 1))
        else:
            result.append(item)

