import re


def glob_match(pattern: str, name: str) -> bool:
    """Return whether name fully matches the case-sensitive glob pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == "\\":
            i += 1
            if i == len(pattern):
                raise ValueError("Trailing backslash in pattern")
            regex.append(re.escape(pattern[i]))
            i += 1
        elif char == "*":
            if i + 1 < len(pattern) and pattern[i + 1] == "*":
                regex.append(".*")
                i += 2
            else:
                regex.append("[^/]*")
                i += 1
        elif char == "?":
            regex.append("[^/]")
            i += 1
        elif char == "[":
            start = i
            i += 1
            negate = i < len(pattern) and pattern[i] == "!"
            if negate:
                i += 1

            members = []
            if i < len(pattern) and pattern[i] == "]":
                members.append("]")
                i += 1

            closed = False
            while i < len(pattern):
                char = pattern[i]
                if char == "]":
                    closed = True
                    i += 1
                    break
                if char == "\\":
                    i += 1
                    if i == len(pattern):
                        raise ValueError("Trailing backslash in character set")
                    char = pattern[i]
                    members.append(re.escape(char))
                elif char == "-":
                    members.append("-")
                else:
                    members.append(re.escape(char))
                i += 1

            if not closed:
                raise ValueError(f"Unclosed character set at position {start}")
            if not members:
                raise ValueError(f"Empty character set at position {start}")

            regex.append("[" + ("^" if negate else "") + "".join(members) + "]")
        else:
            regex.append(re.escape(char))
            i += 1

    try:
        compiled = re.compile("".join(regex))
    except re.error as exc:
        raise ValueError(f"Invalid glob pattern: {exc}") from exc

    return compiled.fullmatch(name) is not None
