    while i < n:
        ch = expr[i]

        if ch.isspace():
            i += 1
            continue

        if "0" <= ch <= "9":
            if not expect_operand:
                raise ValueError("Missing operator")

            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1

            is_decimal = i < n and expr[i] == "."
            if is_decimal:
                i += 1
                fractional_start = i
                while i < n and "0" <= expr[i] <= "9":
                    i += 1
                if i == fractional_start:
                    raise ValueError("Invalid decimal literal")

            literal = expr[start:i]
            output.append(float(literal) if is_decimal else int(literal))
            expect_operand = False
            continue

        if ch == "(":
            if not expect_operand:
                raise ValueError("Missing operator before parenthesis")
            operators.append(ch)
            i += 1
            continue

        if ch == ")":
            if expect_operand:
                raise ValueError("Missing operand")

            while operators and operators[-1] != "(":
                output.append(operators.pop())

            if not operators:
                raise ValueError("Unbalanced parentheses")

            operators.pop()
            expect_operand = False
            i += 1
            continue

        if ch in "+-*/^":
            if expect_operand:
                if ch != "-":
                    raise ValueError("Missing operand")
                # Prefix minus must not reduce a pending exponentiation.
                operators.append("neg")
            else:
                while operators and operators[-1] != "(":
                    top = operators[-1]
                    if precedence[top] < precedence[ch]:
                        break
                    if ch == "^" and precedence[top] == precedence[ch]:
                        break
                    output.append(operators.pop())

                operators.append(ch)
                expect_operand = True

            i += 1
            continue

        raise ValueError("Unknown character")

    if expect_operand:
        raise ValueError("Empty expression or missing operand")

    while operators:
        operator = operators.pop()
        if operator == "(":
            raise ValueError("Unbalanced parentheses")
        output.append(operator)

    values = []
    for token in output:
        if not isinstance(token, str):
            values.append(token)
            continue

        if token == "neg":
            values[-1] = -values[-1]
            continue

        right = values.pop()
        left = values.pop()

        try:
            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                result = left / right
            else:
                result = left ** right
        except ZeroDivisionError as exc:
            raise ValueError("Division by zero") from exc

        values.append(result)

