def _tokenize(text):
    """Split the input into literal / operator tokens.

    Integer literals become int, decimal literals (digits '.' digits) become float.
    Raises ValueError on any character that is not part of a valid token.
    """
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        if ch.isspace():
            i += 1
            continue

        if ch in _DIGITS:
            j = i
            while j < n and text[j] in _DIGITS:
                j += 1
            if j < n and text[j] == ".":
                k = j + 1
                if k >= n or text[k] not in _DIGITS:
                    raise ValueError("malformed decimal literal")
                while k < n and text[k] in _DIGITS:
                    k += 1
                tokens.append(float(text[i:k]))
                i = k
            else:
                tokens.append(int(text[i:j]))
                i = j
            continue

        if ch == ".":
            raise ValueError("malformed decimal literal")

        if ch in _OPERATORS:
            tokens.append(ch)
            i += 1
            continue

        raise ValueError("unexpected character: %r" % (ch,))

    return tokens


def evaluate(expr: str):
    """Evaluate an arithmetic expression and return an int or float."""
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    # expression := term (('+' | '-') term)*
    def parse_expression():
        nonlocal pos
        value = parse_term()
        while pos < len(tokens) and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/') unary)*
    def parse_term():
        nonlocal pos
        value = parse_unary()
        while pos < len(tokens) and tokens[pos] in ("*", "/"):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == "*":
                value = value * rhs
            else:
                try:
                    value = value / rhs
                except ZeroDivisionError:
                    raise ValueError("division by zero")
        return value

    # unary := '-' unary | power      (binds less tightly than '^')
    def parse_unary():
        nonlocal pos
        if pos < len(tokens) and tokens[pos] == "-":
            pos += 1
            return -parse_unary()
        return parse_power()

    # power := primary ('^' unary)?    (right associative, exponent may be signed)
    def parse_power():
        nonlocal pos
        base = parse_primary()
        if pos < len(tokens) and tokens[pos] == "^":
            pos += 1
            exponent = parse_unary()
            try:
                return base ** exponent
            except ZeroDivisionError:
                raise ValueError("division by zero")
        return base

    def parse_primary():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("unexpected end of expression")
        token = tokens[pos]
        if token == "(":
            pos += 1
            value = parse_expression()
            if pos >= len(tokens) or tokens[pos] != ")":
                raise ValueError("unbalanced parentheses")
            pos += 1
            return value
        if isinstance(token, (int, float)):
            pos += 1
            return token
        raise ValueError("unexpected token: %r" % (token,))

    value = parse_expression()
    if pos != len(tokens):
        raise ValueError("unexpected trailing input")
    return value
