# Canonical Roman numerals 1..3999, digit by digit:
#   thousands: M{0,3}
#   hundreds:  CM | CD | D?C{0,3}
#   tens:      XC | XL | L?X{0,3}
#   units:     IX | IV | V?I{0,3}
# This regex accepts exactly the canonical forms (plus the empty string,
# which is rejected separately), and nothing else.
_CANONICAL = re.compile(
    r"M{0,3}(?:CM|CD|D?C{0,3})(?:XC|XL|L?X{0,3})(?:IX|IV|V?I{0,3})"
)

