    """Convert a canonical uppercase Roman numeral (1..3999) to an integer.

    Raises ValueError for anything else: non-strings, the empty string,
    lowercase letters, whitespace, and any non-canonical form such as
    "IIII", "IC", "VX", "IIV", "XXXX", "MMMM", "IL", "XM", "DD", "VV".
    """
    if not isinstance(s, str) or not s or _CANONICAL.fullmatch(s) is None:
        raise ValueError(f"invalid Roman numeral: {s!r}")

    total = 0
    prev = 0
    for ch in reversed(s):
        value = _VALUES[ch]
        if value < prev:
