def earliest_slot(busy, duration, start, end):
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    for interval in busy:
        if len(interval) != 2:
            raise ValueError("each busy interval must be a (begin, finish) pair")
        begin, finish = interval
        if begin >= finish:
            raise ValueError("busy interval must satisfy begin < finish")

    # Clip to the window: only the part that overlaps [start, end) matters.
    clipped = []
    for begin, finish in busy:
        lo = max(begin, start)
        hi = min(finish, end)
        if lo < hi:
            clipped.append((lo, hi))

    clipped.sort()

    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1][1] = hi
        else:
            merged.append([lo, hi])

    t = start
    for lo, hi in merged:
        if lo - t >= duration:
            return t
        if hi > t:
            t = hi

    if end - t >= duration:
        return t
    return None
