from typing import List, Tuple


def _parse_class(pattern: str, i: int):
    """Parse a character class; `i` is the index just after '['.

    Returns ((kind, negated, members), next_index) where members is a tuple of
    inclusive (low, high) character ranges.
    """
    n = len(pattern)
    negated = False
    if i < n and pattern[i] == '!':
        negated = True
        i += 1

    members: List[Tuple[str, str]] = []
    first = True
    closed = False

    while i < n:
        c = pattern[i]
        if c == ']' and not first:
            closed = True
            i += 1
            break
        first = False

        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a trailing backslash")
            c = pattern[i + 1]
            i += 2
            escaped = True
        else:
            i += 1
            escaped = False

        # A '-' that is neither first nor last in the set, and is not escaped,
        # forms a range with the following character.
        if not escaped and i + 1 < n and pattern[i] == '-' and pattern[i + 1] != ']':
            hi = pattern[i + 1]
            if hi == '\\':
                if i + 2 >= n:
                    raise ValueError("pattern ends with a trailing backslash")
                hi = pattern[i + 2]
                i += 3
            else:
                i += 2
            members.append((c, hi))
        else:
            members.append((c, c))

    if not closed:
        raise ValueError("unterminated character set in pattern")

    return ('class', negated, tuple(members)), i


def _parse(pattern: str):
    tokens = []
    i = 0
    n = len(pattern)

    while i < n:
        c = pattern[i]

        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a trailing backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            tokens.append(('dstar',) if j - i >= 2 else ('star',))
            i = j
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '[':
            token, i = _parse_class(pattern, i + 1)
            tokens.append(token)
        else:
            tokens.append(('lit', c))
            i += 1

    return tokens


def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of `name` matches `pattern` (anchored)."""
    tokens = _parse(pattern)

    t_count = len(tokens)
    n_len = len(name)

    # dp[ni] == True iff tokens[ti:] matches name[ni:], evaluated for
    # ti = t_count down to 0, keeping only the next row at a time.
    nxt = [False] * (n_len + 1)
    nxt[n_len] = True

    for ti in range(t_count - 1, -1, -1):
        tok = tokens[ti]
        kind = tok[0]
        cur = [False] * (n_len + 1)

        if kind == 'lit':
            lit = tok[1]
            for ni in range(n_len - 1, -1, -1):
                cur[ni] = name[ni] == lit and nxt[ni + 1]
        elif kind == 'any':
            for ni in range(n_len - 1, -1, -1):
                cur[ni] = name[ni] != '/' and nxt[ni + 1]
        elif kind == 'class':
            negated = tok[1]
            members = tok[2]
            for ni in range(n_len - 1, -1, -1):
                ch = name[ni]
                hit = any(lo <= ch <= hi for lo, hi in members)
                if negated:
                    hit = not hit
                cur[ni] = hit and nxt[ni + 1]
        elif kind == 'star':
            cur[n_len] = nxt[n_len]
            for ni in range(n_len - 1, -1, -1):
                if nxt[ni]:
                    cur[ni] = True
                elif name[ni] != '/' and cur[ni + 1]:
                    cur[ni] = True
        else:  # 'dstar'
            cur[n_len] = nxt[n_len]
            for ni in range(n_len - 1, -1, -1):
                cur[ni] = nxt[ni] or cur[ni + 1]

        nxt = cur

    return nxt[0]
