            if not part or not all('0' <= c <= '9' for c in part):
                raise ValueError("invalid numeric part: %r" % (v,))
            nums.append(int(part))
        return nums, tag

    na, ta = parse(a)
    nb, tb = parse(b)

    for i in range(max(len(na), len(nb))):
        x = na[i] if i < len(na) else 0
        y = nb[i] if i < len(nb) else 0
        if x != y:
            return -1 if x < y else 1

    if ta is None and tb is None:
        return 0
    if ta is None:
        return 1
    if tb is None:
        return -1
    if ta == tb:
        return 0
    return -1 if ta < tb else 1
