import re

_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?\Z")


def _increment(digits: str) -> str:
    """Add one to a non-empty string of ASCII digits (string arithmetic)."""
    out = list(digits)
    i = len(out) - 1
    while i >= 0 and out[i] == "9":
        out[i] = "0"
        i -= 1
    if i < 0:
        return "1" + "".join(out)
    out[i] = chr(ord(out[i]) + 1)
    return "".join(out)


def round_half_up(x: str, ndigits: int) -> str:
    """Round a decimal string to `ndigits` places, ties away from zero.

    All arithmetic is done on digit strings, so the result is exact.
    """
    if not isinstance(ndigits, int):
        raise ValueError("ndigits must be a non-negative integer")
    if ndigits < 0:
        raise ValueError("ndigits must be non-negative")
    if not isinstance(x, str) or not _DECIMAL_RE.fullmatch(x):
        raise ValueError("invalid decimal string: {!r}".format(x))

    negative = x.startswith("-")
    body = x[1:] if negative else x
    if "." in body:
        int_part, frac_part = body.split(".", 1)
    else:
        int_part, frac_part = body, ""

    if len(frac_part) <= ndigits:
        digits = int_part + frac_part.ljust(ndigits, "0")
    else:
        digits = int_part + frac_part[:ndigits]
        # The first dropped digit being >= 5 means the remainder is at least
        # half a unit, so round up -- this covers exact ties too.
        if frac_part[ndigits] >= "5":
            digits = _increment(digits)

    # Ensure there are enough digits to split into integer/fraction parts.
    if len(digits) <= ndigits:
        digits = digits.rjust(ndigits + 1, "0")

    if ndigits:
        int_out, frac_out = digits[:-ndigits], digits[-ndigits:]
    else:
        int_out, frac_out = digits, ""

    int_out = int_out.lstrip("0") or "0"

    # Never emit a negative zero.
    if negative and (int_out != "0" or frac_out.strip("0")):
        return "-" + int_out + ("." + frac_out if ndigits else "")
    return int_out + ("." + frac_out if ndigits else "")
