def _parse_comparator(token):
    """Parse one comparator into (operator, parsed version or None)."""
    if token == "*":
        return ("*", None)

    for operator in _OPERATORS:
        if token.startswith(operator):
            target = token[len(operator):]
            if not target:
                raise ValueError("invalid comparator: %r" % (token,))
            return (operator, _parse_version(target))

    # A bare version means "=".
    return ("=", _parse_version(token))


def _parse_constraint(text):
    """Parse a constraint into a list of groups of comparators."""
    if not isinstance(text, str):
        raise ValueError("constraint must be a string, got %s" % type(text).__name__)

    body = text.strip()
    if not body:
        raise ValueError("empty constraint")

    groups = []
    for group_text in body.split("||"):
        tokens = group_text.split()
        if not tokens:
            raise ValueError("empty comparator group in constraint: %r" % (text,))
        groups.append([_parse_comparator(token) for token in tokens])
    return groups


def _satisfies_comparator(version, operator, target):
    if operator == "*":
        return True

    order = _compare_versions(version, target)

    if operator == "=":
        return order == 0
    if operator == ">":
        return order > 0
    if operator == ">=":
        return order >= 0
    if operator == "<":
        return order < 0
    if operator == "<=":
        return order <= 0

    if order < 0:
        return False

    if operator == "^":
        major, minor, patch, _pre = target
        if major > 0:
            upper = (major + 1, 0, 0, None)
        elif minor > 0:
            upper = (0, minor + 1, 0, None)
        else:
            upper = (0, 0, patch + 1, None)
        return _compare_versions(version, upper) < 0

    # operator == "~"
    major, minor, _patch, _pre = target
    upper = (major, minor + 1, 0, None)
    return _compare_versions(version, upper) < 0


def _satisfies_group(version, comparators):
    for operator, target in comparators:
        if not _satisfies_comparator(version, operator, target):
            return False

    # Pre-release rule: a pre-release version only matches a group when some
    # comparator in that group carries a pre-release on the same
    # MAJOR.MINOR.PATCH.
    if version[3] is not None:
        for _operator, target in comparators:
            if (
                target is not None
                and target[3] is not None
                and target[:3] == version[:3]
            ):
                return True
        return False

    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    """Return True if ``version`` satisfies ``constraint``.

    Raises ValueError for an invalid version, an invalid comparator, or an
    empty constraint.
    """
    parsed_version = _parse_version(version)
    groups = _parse_constraint(constraint)
    return any(_satisfies_group(parsed_version, group) for group in groups)
