def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current_section = ""

    def valid_suffix(suffix: str) -> bool:
        suffix = suffix.lstrip()
        return not suffix or suffix.startswith((";", "#"))

    for line_number, raw_line in enumerate(text.split("\n"), start=1):
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]

        line = raw_line.strip()
        if not line or line.startswith((";", "#")):
            continue

        def error(message: str) -> ValueError:
            return ValueError(f"Line {line_number}: {message}")

        if line.startswith("["):
            closing = line.find("]")
            if closing == -1:
                raise error("missing closing ']' in section header")

            name = line[1:closing].strip()
            if not name:
                raise error("section name must not be empty")
            if not valid_suffix(line[closing + 1:]):
                raise error("unexpected text after section header")

            current_section = name
            sections.setdefault(name, {})
            continue

        if "=" not in line:
            raise error("expected a key/value pair")

        raw_key, raw_value = line.split("=", 1)
        key = raw_key.strip()
        if not key:
            raise error("key must not be empty")

        value = raw_value.strip()
        if value.startswith('"'):
            closing = value.find('"', 1)
            if closing == -1:
                raise error("missing closing quote")
            if not valid_suffix(value[closing + 1:]):
                raise error("unexpected text after quoted value")
            value = value[1:closing]
        else:
            for index, character in enumerate(raw_value):
                if (
                    character in ";#"
                    and index > 0
                    and raw_value[index - 1] in " \t"
                ):
                    raw_value = raw_value[:index]
                    break
            value = raw_value.strip()

        sections.setdefault(current_section, {})[key] = value

    return sections
