import re

_DECIMAL_RE = re.compile(r'-?[0-9]+(?:\.[0-9]+)?')


def _add_one(digits: str) -> str:
    """Increment a non-negative integer written as a decimal digit string by one."""
    chars = list(digits)
    i = len(chars) - 1
    while i >= 0 and chars[i] == '9':
        chars[i] = '0'
        i -= 1
    if i < 0:
        return '1' + ''.join(chars)
    chars[i] = chr(ord(chars[i]) + 1)
    return ''.join(chars)


def round_half_up(x: str, ndigits: int) -> str:
    """Round the exact decimal string ``x`` to ``ndigits`` fractional digits.

    Ties are rounded away from zero. All arithmetic is performed on the
    decimal digit string itself, so the result is exact (no binary
    floating point is involved).
    """
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError(
            "x must be a decimal string of the form '-?digits[.digits]'"
        )
    if not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")

    negative = x.startswith('-')
    body = x[1:] if negative else x
    if '.' in body:
        int_part, frac_part = body.split('.', 1)
    else:
        int_part, frac_part = body, ''

    if len(frac_part) <= ndigits:
        # Value is exactly representable with ndigits fractional digits:
        # just pad with trailing zeros, no rounding needed.
        digits = int_part + frac_part + '0' * (ndigits - len(frac_part))
    else:
        digits = int_part + frac_part[:ndigits]
        # Round up iff the first discarded digit is >= '5'.  A '5' followed
        # by anything (including nothing) is a tie or more; ties round away
        # from zero, which is "up" on the absolute value handled here.
        if frac_part[ndigits] >= '5':
            digits = _add_one(digits)

    # Suppress the sign for a result of zero (never return "-0.00").
    sign = '-' if negative and digits.strip('0') else ''

    if ndigits == 0:
        integer, fraction = digits, ''
    else:
        # len(digits) is always >= ndigits + 1 here, so both slices are safe.
        integer, fraction = digits[:-ndigits], digits[-ndigits:]
    integer = integer.lstrip('0') or '0'

    return sign + integer + ('.' + fraction if ndigits else '')
