"""A minimal INI parser (Python 3.9, standard library only)."""

from typing import Optional

__all__ = ["parse_ini"]


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parse a simple INI document into ``{section: {key: value}}``.

    Keys appearing before the first ``[header]`` land in the ``""`` section,
    which only shows up in the result if such a key actually exists.
    Malformed input raises ``ValueError``.
    """
    result: dict[str, dict[str, str]] = {}
    current: Optional[str] = None  # None => implicit "" section, not yet created

    def section(name: str) -> dict[str, str]:
        if name not in result:
            result[name] = {}
        return result[name]

    def check_trailing(rest: str, line: str) -> None:
        """Whatever follows the payload must be whitespace or a comment."""
        rest = rest.strip()
        if rest and rest[0] not in ";#":
            raise ValueError("unexpected text after value: {!r}".format(line))

    for raw in text.split("\n"):
        line = raw[:-1] if raw.endswith("\r") else raw
        stripped = line.strip()

        # Blank lines and full-line comments.
        if not stripped or stripped[0] in ";#":
            continue

        # [section]  with optional surrounding whitespace.
        if stripped[0] == "[":
            close = stripped.find("]")
            if close == -1:
                raise ValueError("unterminated section header: {!r}".format(line))
            name = stripped[1:close].strip()
            if not name:
                raise ValueError("empty section name: {!r}".format(line))
            check_trailing(stripped[close + 1:], line)
            current = name
            section(name)
            continue

        # key = value  (split on the first '=')
        eq = stripped.find("=")
        if eq == -1:
            raise ValueError("expected 'key = value': {!r}".format(line))
        key = stripped[:eq].strip()
        if not key:
            raise ValueError("empty key: {!r}".format(line))

        value = stripped[eq + 1:].strip()

        if value.startswith('"'):
            # Quoted: take everything up to the next '"' literally.
            close = value.find('"', 1)
            if close == -1:
                raise ValueError("unterminated quoted value: {!r}".format(line))
            parsed = value[1:close]
            check_trailing(value[close + 1:], line)
        else:
            # Inline comment: ';' or '#' preceded by a space or tab.
            cut = len(value)
            for i in range(1, len(value)):
                if value[i] in ";#" and value[i - 1] in " \t":
                    cut = i
                    break
            parsed = value[:cut].strip()

        target = "" if current is None else current
        section(target)[key] = parsed

    return result
```

