    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= expr[j] <= '9':
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                frac_start = j
                while j < n and '0' <= expr[j] <= '9':
                    j += 1
                if j == frac_start:
                    raise ValueError(f"malformed number at position {i}")
                tokens.append(('num', float(expr[i:j])))
            else:
                tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"unexpected character {c!r} at position {i}")
    return tokens


class _Parser:
    """Recursive-descent parser implementing Python-like precedence:

    expr  := term (('+' | '-') term)*
    term  := unary (('*' | '/') unary)*
    unary := '-' unary | power
    power := atom ('^' unary)?          # right-associative
    atom  := number | '(' expr ')'
    """

    def __init__(self, tokens: List[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError(f"unexpected token {self._tokens[self._pos][0]!r}")
        return value

    def _peek(self) -> Optional[Token]:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self) -> Token:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        self._pos += 1
        return tok

    def _expr(self) -> Number:
        value = self._term()
        while True:
            tok = self._peek()
            if tok is None or tok[0] not in ('+', '-'):
                return value
            self._pos += 1
            rhs = self._term()
            value = value + rhs if tok[0] == '+' else value - rhs

    def _term(self) -> Number:
        value = self._unary()
        while True:
            tok = self._peek()
            if tok is None or tok[0] not in ('*', '/'):
                return value
            self._pos += 1
            rhs = self._unary()
            if tok[0] == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs

    def _unary(self) -> Number:
        tok = self._peek()
        if tok is not None and tok[0] == '-':
            self._pos += 1
            return -self._unary()
        return self._power()

    def _power(self) -> Number:
        base = self._atom()
        tok = self._peek()
        if tok is not None and tok[0] == '^':
            self._pos += 1
            exponent = self._unary()
            return base ** exponent
        return base

    def _atom(self) -> Number:
        tok = self._advance()
        kind = tok[0]
        if kind == 'num':
            return tok[1]
        if kind == '(':
            value = self._expr()
            closing = self._advance()
            if closing[0] != ')':
                raise ValueError(f"expected ')' but got {closing[0]!r}")
            return value
        raise ValueError(f"unexpected token {kind!r}")


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression string and return an int or float.

    Grammar/semantics:
      - integer literals are int, decimals are float
      - '+' and '-' lowest precedence; '*' and '/' higher; '^' highest
      - '+' '-' '*' '/' are left-associative; '^' is right-associative
      - unary minus binds less tightly than '^' but tighter than '*' '/'
      - '/' is always true division; division by zero raises ValueError
      - any malformed input raises ValueError
