from typing import List, Tuple, Union

Num = Union[int, float]
Token = Tuple[str, object]


def _tokenize(expr: str) -> List[Token]:
    """Split the input into ('NUM', number) and ('OP', char) tokens.

    Integer literals are runs of ASCII digits; decimal literals are
    digits, a dot, digits (digits required on both sides of the dot).
    Whitespace between tokens is skipped; any other character is an error.
    """
    tokens: List[Token] = []
    i = 0
    n = len(expr)
    digits = '0123456789'
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in digits:
            j = i
            while j < n and expr[j] in digits:
                j += 1
            if j + 1 < n and expr[j] == '.' and expr[j + 1] in digits:
                j += 1
                while j < n and expr[j] in digits:
                    j += 1
                tokens.append(('NUM', float(expr[i:j])))
            else:
                tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/^()':
            tokens.append(('OP', c))
            i += 1
            continue
        raise ValueError('unknown character %r at position %d' % (c, i))
    return tokens


def evaluate(expr: str) -> Num:
    """Evaluate an arithmetic expression with + - * / ^ and parentheses.

    Grammar (highest to lowest precedence):
        atom  := NUMBER | '(' expr ')'
        power := atom ['^' unary]          (right-associative)
        unary := '-' unary | power         (unary minus, binds looser than '^')
        term  := unary [('*' | '/') unary]*   (left-associative)
        expr  := term [('+' | '-') term]*     (left-associative)
    """
    tokens = _tokenize(expr)
    ntok = len(tokens)
    pos = 0

    def peek():
        return tokens[pos] if pos < ntok else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr() -> Num:
        value = parse_term()
        while True:
            tok = peek()
            if tok == ('OP', '+'):
                advance()
                value = value + parse_term()
            elif tok == ('OP', '-'):
                advance()
                value = value - parse_term()
            else:
                return value

    def parse_term() -> Num:
        value = parse_unary()
        while True:
            tok = peek()
            if tok == ('OP', '*'):
                advance()
                value = value * parse_unary()
            elif tok == ('OP', '/'):
                advance()
                value = value / parse_unary()
            else:
                return value

    def parse_unary() -> Num:
        if peek() == ('OP', '-'):
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power() -> Num:
        base = parse_atom()
        if peek() == ('OP', '^'):
            advance()
            return base ** parse_unary()
        return base

    def parse_atom() -> Num:
        tok = peek()
        if tok is None:
            raise ValueError('unexpected end of expression')
        if tok[0] == 'NUM':
            advance()
            return tok[1]
        if tok == ('OP', '('):
            advance()
            value = parse_expr()
            if peek() != ('OP', ')'):
                raise ValueError('missing closing parenthesis')
            advance()
            return value
        raise ValueError('unexpected token %r' % (tok[1],))

    try:
        result = parse_expr()
    except ZeroDivisionError:
        raise ValueError('division by zero') from None
    if pos != ntok:
        raise ValueError('unexpected token %r' % (tokens[pos][1],))
    return result
