    current = None  # name of the active section, None until one is seen

    for raw_line in text.split("\n"):
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]
        line = raw_line.strip()

        # Blank lines and whole-line comments are skipped.
        if not line or line[0] in _COMMENT:
            continue

        header = _HEADER_RE.match(line)
        if header is not None:
            name = header.group(1).strip()
            if not name:
                raise ValueError("empty section name: {!r}".format(raw_line))
            sections.setdefault(name, {})
            current = name
            continue

        eq = line.find("=")
        if eq < 0:
            raise ValueError(
                "not a section header or key/value line: {!r}".format(raw_line)
            )

        key = line[:eq].strip()
        if not key:
            raise ValueError("empty key: {!r}".format(raw_line))

        raw_value = line[eq + 1:]
        trimmed = raw_value.strip()

        if trimmed.startswith('"'):
            end = trimmed.find('"', 1)
            if end < 0:
                raise ValueError("unterminated quoted value: {!r}".format(raw_line))
            value = trimmed[1:end]
            if not _only_ws_or_comment(trimmed[end + 1:]):
