import re

_SCHEME_RE = re.compile(r'([A-Za-z][A-Za-z0-9+\-.]*)://')
_AUTHORITY_END_RE = re.compile(r'[/?#]')


def _parse_port(text: str) -> int:
    """Validate ``text`` as a port: 1-5 ASCII digits with value 1..65535."""
    if not (1 <= len(text) <= 5) or not all('0' <= ch <= '9' for ch in text):
        raise ValueError(f"invalid port: {text!r}")
    value = int(text)
    if not 1 <= value <= 65535:
        raise ValueError(f"port out of range: {value}")
    return value


def parse_url(url: str) -> dict:
    """Split *url* into scheme, userinfo, host, port, path, query, fragment.

    Raises ValueError for anything that violates the parsing rules.
    """
    scheme_match = _SCHEME_RE.match(url)
    if scheme_match is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = scheme_match.group(1).lower()
    rest = url[scheme_match.end():]

    # Authority: everything up to the first '/', '?' or '#' (or the end).
    end_match = _AUTHORITY_END_RE.search(rest)
    if end_match is None:
        authority, remainder = rest, ''
    else:
        authority, remainder = rest[:end_match.start()], rest[end_match.start():]
    if not authority:
        raise ValueError("URL has an empty authority")

    # Userinfo: everything before the LAST '@' of the authority, if any.
    at_index = authority.rfind('@')
    if at_index == -1:
        userinfo, hostport = '', authority
    else:
        userinfo, hostport = authority[:at_index], authority[at_index + 1:]

    # Host and optional port.
    if hostport.startswith('['):
        close_index = hostport.find(']')
        if close_index == -1:
            raise ValueError("host has an unterminated '['")
        host = hostport[1:close_index]
        if not host:
            raise ValueError("host has an empty IPv6 literal")
        tail = hostport[close_index + 1:]
        if not tail:
            port = None
        elif tail.startswith(':'):
            port = _parse_port(tail[1:])
        else:
            raise ValueError("unexpected characters after ']' in host")
    else:
        colon_index = hostport.find(':')
        if colon_index == -1:
            host, port = hostport, None
        else:
            host = hostport[:colon_index]
            port = _parse_port(hostport[colon_index + 1:])
        if not host:
            raise ValueError("URL has an empty host")
        if any(ch in ' /?#:@[]' for ch in host):
            raise ValueError(f"invalid character in host: {host!r}")
    host = host.lower()

    # First '#' starts the fragment (it may contain '?'); before that, the
    # first '?' starts the query; whatever remains is the path.
    hash_index = remainder.find('#')
    if hash_index == -1:
        before_fragment, fragment = remainder, ''
    else:
        before_fragment, fragment = remainder[:hash_index], remainder[hash_index + 1:]
    query_index = before_fragment.find('?')
    if query_index == -1:
        path, query = before_fragment, ''
    else:
        path, query = before_fragment[:query_index], before_fragment[query_index + 1:]

    return {
        'scheme': scheme,
        'userinfo': userinfo,
        'host': host,
        'port': port,
        'path': path,
        'query': query,
        'fragment': fragment,
    }
