from datetime import datetime, timedelta

# minute, hour, day-of-month, month, day-of-week allowed ranges
_FIELD_RANGES = ((0, 59), (0, 23), (1, 31), (1, 12), (0, 6))


def _parse_item(item: str, lo: int, hi: int) -> set:
    """Parse a single cron field item and return the set of values it selects."""
    if not item:
        raise ValueError("empty item in cron field")
    base, slash, step_text = item.partition("/")
    if slash:
        if not step_text.isdigit():
            raise ValueError("malformed step in cron item: %r" % (item,))
        step = int(step_text)
        if step < 1:
            raise ValueError("step must be >= 1 in cron item: %r" % (item,))
    else:
        step = 1

    if base == "*":
        start, end = lo, hi
    else:
        first, dash, second = base.partition("-")
        if dash:
            if not first.isdigit() or not second.isdigit():
                raise ValueError("malformed cron item: %r" % (item,))
            start, end = int(first), int(second)
            if start > end:
                raise ValueError("range start greater than end in cron item: %r" % (item,))
        else:
            if not base.isdigit():
                raise ValueError("malformed cron item: %r" % (item,))
            start = int(base)
            end = hi  # a/n goes up to the field's maximum
        if not (lo <= start <= hi and lo <= end <= hi):
            raise ValueError("value out of field range in cron item: %r" % (item,))

    return set(range(start, end + 1, step))


def _parse_field(field: str, lo: int, hi: int) -> set:
    values = set()
    for item in field.split(","):
        values |= _parse_item(item, lo, hi)
    return values


def _day_matches(day, doms, months, dows, dom_restricted: bool, dow_restricted: bool) -> bool:
    """Standard cron day matching (OR rule only when both dom and dow are restricted)."""
    if day.month not in months:
        return False
    dom_ok = day.day in doms
    dow_ok = (day.isoweekday() % 7) in dows  # cron: 0=Sunday .. 6=Saturday
    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    if dom_restricted:
        return dom_ok
    if dow_restricted:
        return dow_ok
    return True


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_set, hour_set, dom_set, month_set, dow_set = (
        _parse_field(field, lo, hi) for field, (lo, hi) in zip(fields, _FIELD_RANGES)
    )

    # "Restricted" means the raw field text is not exactly "*".
    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    start_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    first = start_dt + timedelta(minutes=1)  # strictly later than "after"
    limit_date = (start_dt + timedelta(days=5 * 366)).date()  # ~5 year horizon

    minutes = sorted(minute_set)
    hours = sorted(hour_set)

    cur = first.date()
    min_time = first.hour * 60 + first.minute  # earliest minute-of-day on the first day

    while cur <= limit_date:
        if _day_matches(cur, dom_set, month_set, dow_set, dom_restricted, dow_restricted):
            h0, m0 = divmod(min_time, 60)
            for h in hours:
                if h < h0:
                    continue
                if h == h0:
                    for m in minutes:
                        if m >= m0:
                            return "%04d-%02d-%02d %02d:%02d" % (cur.year, cur.month, cur.day, h, m)
                else:
                    return "%04d-%02d-%02d %02d:%02d" % (cur.year, cur.month, cur.day, h, minutes[0])
        cur += timedelta(days=1)
        min_time = 0

    raise ValueError("no matching time within 5 years after the given time")
