import re

_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+\-.]*)://")
_AUTHORITY_END = frozenset("/?#")
_HOST_STOP = frozenset(" /?#@:[]")
_PORT_DIGITS = frozenset("0123456789")


def _parse_port(text: str) -> int:
    """Parse a port: 1 to 5 ASCII digits with a value from 1 to 65535."""
    if not 1 <= len(text) <= 5 or any(ch not in _PORT_DIGITS for ch in text):
        raise ValueError("invalid port: %r" % (text,))
    value = int(text)
    if not 1 <= value <= 65535:
        raise ValueError("port out of range: %d" % value)
    return value


def parse_url(url: str) -> dict:
    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = match.group(1).lower()

    rest = url[match.end():]

    # Authority ends at the first '/', '?' or '#' (or at the end of the URL).
    cut = len(rest)
    for i, ch in enumerate(rest):
        if ch in _AUTHORITY_END:
            cut = i
            break
    authority, tail = rest[:cut], rest[cut:]

    if not authority:
        raise ValueError("empty authority")

    # Userinfo is everything before the LAST '@' (returned as is).
    if "@" in authority:
        userinfo, hostpart = authority.rsplit("@", 1)
    else:
        userinfo, hostpart = "", authority

    port = None

    if hostpart.startswith("["):
        closing = hostpart.find("]")
        if closing == -1:
            raise ValueError("unterminated IPv6 literal: missing ']'")
        literal = hostpart[1:closing]
        try:
            ipaddress.IPv6Address(literal)
        except ValueError:
            raise ValueError("invalid IPv6 literal: %r" % (literal,)) from None
        host = literal
        after = hostpart[closing + 1:]
        if after:
            if after[0] != ":":
                raise ValueError("unexpected characters after ']' in authority")
            port = _parse_port(after[1:])
    else:
        i = 0
        n = len(hostpart)
        while i < n and hostpart[i] not in _HOST_STOP:
            i += 1
        host = hostpart[:i]
        if not host:
            raise ValueError("empty host")
        after = hostpart[i:]
        if after:
            if after[0] != ":":
                raise ValueError("unexpected characters after host: %r" % (after,))
            port = _parse_port(after[1:])

    host = host.lower()

    # The first '#' starts the fragment (its content may contain '?');
    # before that, the first '?' starts the query; the rest is the path.
    before_fragment, _, fragment = tail.partition("#")
    path, _, query = before_fragment.partition("?")

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
