from typing import List, Optional, Tuple, Union

Number = Union[int, float]
Token = Tuple[str, object]

_ASCII_DIGITS = frozenset("0123456789")
_OPERATOR_CHARS = frozenset("+-*/^()")


def _tokenize(expr: str) -> List[Token]:
    """Convert the input string into (kind, value) tokens.

    kind is "num" (value: int or float) or "op" (value: one of +-*/^()).
    Raises ValueError on unknown characters or malformed numeric literals.
    """
    tokens: List[Token] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _ASCII_DIGITS:
            start = i
            while i < n and expr[i] in _ASCII_DIGITS:
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                if i >= n or expr[i] not in _ASCII_DIGITS:
                    raise ValueError("malformed number: '.' must be surrounded by digits")
                while i < n and expr[i] in _ASCII_DIGITS:
                    i += 1
                tokens.append(("num", float(expr[start:i])))
            else:
                tokens.append(("num", int(expr[start:i])))
            continue
        if ch in _OPERATOR_CHARS:
            tokens.append(("op", ch))
            i += 1
            continue
        raise ValueError("unknown character: {!r}".format(ch))
    return tokens


class _Parser:
    """Recursive-descent parser/evaluator.

    expression := term (('+' | '-') term)*          left-associative
    term       := factor (('*' | '/') factor)*      left-associative
    factor     := '-' factor | power                unary minus
    power      := atom ('^' factor)?                right-associative
    atom       := NUMBER | '(' expression ')'
    """

    def __init__(self, tokens: List[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        result = self._expression()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected token: {!r}".format(self._tokens[self._pos][1]))
        return result

    def _peek(self) -> Optional[Token]:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _expression(self) -> Number:
        value = self._term()
        while True:
            tok = self._peek()
            if tok == ("op", "+"):
                self._pos += 1
                value = value + self._term()
            elif tok == ("op", "-"):
                self._pos += 1
                value = value - self._term()
            else:
                return value

    def _term(self) -> Number:
        value = self._factor()
        while True:
            tok = self._peek()
            if tok == ("op", "*"):
                self._pos += 1
                value = value * self._factor()
            elif tok == ("op", "/"):
                self._pos += 1
                value = value / self._factor()
            else:
                return value

    def _factor(self) -> Number:
        if self._peek() == ("op", "-"):
            self._pos += 1
            return -self._factor()
        return self._power()

    def _power(self) -> Number:
        base = self._atom()
        if self._peek() == ("op", "^"):
            self._pos += 1
            return base ** self._factor()
        return base

    def _atom(self) -> Number:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        kind, value = tok
        if kind == "num":
            self._pos += 1
            return value  # int or float
        if kind == "op" and value == "(":
            self._pos += 1
            result = self._expression()
            if self._peek() != ("op", ")"):
                raise ValueError("missing closing parenthesis")
            self._pos += 1
            return result
        raise ValueError("unexpected token: {!r}".format(value))


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression string and return the result.

    Supports int/float literals, the binary operators + - * / ^, unary minus,
    and parentheses. '^' is right-associative exponentiation; '/' is always
    true division. Raises ValueError on malformed input or division by zero.
    """
    parser = _Parser(_tokenize(expr))
    try:
        return parser.parse()
    except ZeroDivisionError:
        raise ValueError("division by zero") from None
