from typing import Optional


def earliest_slot(
    busy: list[tuple[int, int]], duration: int, start: int, end: int
) -> Optional[int]:
    """Find the earliest free meeting slot.

    Searches for the smallest integer t with start <= t and
    t + duration <= end such that the half-open interval [t, t + duration)
    does not overlap any busy interval in ``busy`` (busy intervals are
    half-open [begin, finish) and may be unsorted, overlapping, or touching).

    Busy time outside the window [start, end] is irrelevant except where it
    overlaps the window. The input list is not modified.

    Args:
        busy: List of (begin, finish) busy intervals, minutes since midnight.
        duration: Meeting length in minutes; must be a positive integer.
        start: Earliest allowed start of the meeting (minutes).
        end: Latest allowed end of the meeting (minutes).

    Returns:
        The earliest valid start time t, or None if no slot fits.

    Raises:
        ValueError: If ``duration`` is not a positive integer, or if any
            busy interval has begin >= finish.
    """
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    intervals = []
    for interval in busy:
        begin, finish = interval
        if begin >= finish:
            raise ValueError(
                f"invalid busy interval {interval!r}: begin must be < finish"
            )
        intervals.append((begin, finish))

    intervals.sort()

    t = start
    i = 0
    n = len(intervals)
    while i < n:
        # Merge the run of overlapping/touching intervals starting at i.
        run_begin, run_finish = intervals[i]
        i += 1
        while i < n and intervals[i][0] <= run_finish:
            if intervals[i][1] > run_finish:
                run_finish = intervals[i][1]
            i += 1

        # t never decreases, so once the meeting cannot end by ``end``,
        # no later start works either.
        if t + duration > end:
            return None
        if t + duration <= run_begin:
            return t  # [t, t + duration) fits in the gap before this run.
        if run_finish > t:
            t = run_finish

    if t + duration <= end:
        return t
    return None
