from datetime import datetime, timedelta


def _is_number(s):
    """True if s is a non-empty string of ASCII digits 0-9."""
    return bool(s) and all('0' <= c <= '9' for c in s)


def _parse_field(field, lo, hi):
    """Parse one cron field into the set of integer values it matches."""
    values = set()
    for item in field.split(','):
        base, step, has_step = item, 1, False
        if '/' in item:
            base, step_str = item.split('/', 1)
            if not _is_number(step_str):
                raise ValueError("malformed step in cron field item: %r" % item)
            step = int(step_str)
            if step < 1:
                raise ValueError("step must be >= 1 in cron field item: %r" % item)
            has_step = True
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-', 1)
            if not (_is_number(a) and _is_number(b)):
                raise ValueError("malformed cron field item: %r" % item)
            start, end = int(a), int(b)
            if start > end:
                raise ValueError("range start exceeds end in cron field item: %r" % item)
        else:
            if not _is_number(base):
                raise ValueError("malformed cron field item: %r" % item)
            start = int(base)
            # 'a/n' means every n-th value from a up to the field's maximum
            end = hi if has_step else start
        if not (lo <= start <= hi and lo <= end <= hi):
            raise ValueError("value out of range in cron field item: %r" % item)
        values.update(range(start, end + 1, step))
    if not values:
        raise ValueError("cron field matches no values")
    return values


def _plus_years(dt, years):
    try:
        return dt.replace(year=dt.year + years)
    except ValueError:  # Feb 29 in a non-leap target year
        return dt.replace(year=dt.year + years, day=28)


def _format(dt):
    return "%04d-%02d-%02d %02d:%02d" % (
        dt.year, dt.month, dt.day, dt.hour, dt.minute)


def next_cron(expr: str, after: str) -> str:
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minute_vals = _parse_field(fields[0], 0, 59)
    hour_vals = _parse_field(fields[1], 0, 23)
    dom_vals = _parse_field(fields[2], 1, 31)
    month_vals = _parse_field(fields[3], 1, 12)
    dow_vals = _parse_field(fields[4], 0, 6)

    # "Restricted" means the raw field is not literally '*'.
    dom_restricted = fields[2] != '*'
    dow_restricted = fields[4] != '*'

    after_dt = datetime.strptime(after, "%Y-%m-%d %H:%M")
    limit = _plus_years(after_dt, 5)

    def day_matches(day):
        if day.month not in month_vals:
            return False
        dom_ok = day.day in dom_vals
        dow_ok = (day.weekday() + 1) % 7 in dow_vals  # cron: 0 = Sunday
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        if dom_restricted:
            return dom_ok
        if dow_restricted:
            return dow_ok
        return True

    hours_sorted = sorted(hour_vals)
    minutes_sorted = sorted(minute_vals)

    day = after_dt.date()
    last_day = limit.date()
    step_day = timedelta(days=1)
    while day <= last_day:
        if day_matches(day):
            for h in hours_sorted:
                for m in minutes_sorted:
                    cand = datetime(day.year, day.month, day.day, h, m)
                    if cand > after_dt:
                        if cand <= limit:
                            return _format(cand)
                        raise ValueError("no matching time within 5 years")
        day += step_day
    raise ValueError("no matching time within 5 years")
