"""Minimal, strict INI parser (Python 3.9, standard library only)."""

__all__ = ["parse_ini"]


def _error(line_no: int, line: str) -> ValueError:
    return ValueError(f"invalid INI syntax on line {line_no}: {line!r}")


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parse a simple INI document into ``{section: {key: value}}``.

    Keys before any header live in the ``""`` section, which only exists if
    such a key was actually seen.  Any malformed line raises ``ValueError``.
    """
    result: dict[str, dict[str, str]] = {}
    current = ""

    for line_no, raw_line in enumerate(text.split("\n"), start=1):
        # A trailing "\r" (CRLF files) is ignored.
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]
        line = raw_line.strip()

        # Blank lines and comment lines are skipped.
        if not line or line[0] in ";#":
            continue

        # Section header.
        if line[0] == "[":
            close = line.find("]")
            if close == -1:
                raise _error(line_no, raw_line)
            name = line[1:close].strip()
            if not name:
                raise _error(line_no, raw_line)
            tail = line[close + 1:].strip()
            if tail and tail[0] not in ";#":
                raise _error(line_no, raw_line)
            current = name
            result.setdefault(name, {})
            continue

        # key = value (split on the FIRST "=").
        eq = line.find("=")
        if eq == -1:
            raise _error(line_no, raw_line)
        key = line[:eq].strip()
        if not key:
            raise _error(line_no, raw_line)
        value = line[eq + 1:].strip()

        if value.startswith('"'):
            # Quoted value: literal up to the next double quote.
            close = value.find('"', 1)
            if close == -1:
                raise _error(line_no, raw_line)
            parsed = value[1:close]
            tail = value[close + 1:].strip()
            if tail and tail[0] not in ";#":
                raise _error(line_no, raw_line)
        else:
            # Inline comment: a ";" or "#" preceded by a space or tab.
            cut = -1
            for i in range(1, len(value)):
                if value[i] in ";#" and value[i - 1] in " \t":
                    cut = i
                    break
            if cut != -1:
                value = value[:cut]
            parsed = value.strip()

        result.setdefault(current, {})[key] = parsed

    return result
