from typing import List, Optional, Tuple, Union

Number = Union[int, float, complex]
_Token = Tuple[str, object]


def _tokenize(expr: str) -> List[_Token]:
    """Convert input into ('num', value) and ('op', char) tokens."""
    tokens: List[_Token] = []
    digits = "0123456789"
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c in "+-*/^()":
            tokens.append(("op", c))
            i += 1
            continue
        if c in digits:
            j = i
            while j < n and expr[j] in digits:
                j += 1
            if j < n and expr[j] == ".":
                k = j + 1
                if k < n and expr[k] in digits:
                    while k < n and expr[k] in digits:
                        k += 1
                    tokens.append(("num", float(expr[i:k])))
                    i = k
                else:
                    raise ValueError(
                        "malformed number: expected digit after decimal point"
                    )
            else:
                tokens.append(("num", int(expr[i:j])))
                i = j
            continue
        raise ValueError("unexpected character {!r}".format(c))
    return tokens


class _Parser:
    """Recursive-descent parser.

    expression := term  (('+' | '-') term)*
    term       := unary (('*' | '/') unary)*
    unary      := '-' unary | power
    power      := primary ('^' unary)?
    primary    := NUMBER | '(' expression ')'
    """

    def __init__(self, tokens: List[_Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expression()
        if self._pos < len(self._tokens):
            raise ValueError(
                "unexpected token {!r}".format(self._tokens[self._pos][1])
            )
        return value

    def _peek(self) -> Optional[_Token]:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _at_op(self, *ops: str) -> bool:
        tok = self._peek()
        return tok is not None and tok[0] == "op" and tok[1] in ops

    def _expression(self) -> Number:
        value = self._term()
        while self._at_op("+", "-"):
            op = self._tokens[self._pos][1]
            self._pos += 1
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self) -> Number:
        value = self._unary()
        while self._at_op("*", "/"):
            op = self._tokens[self._pos][1]
            self._pos += 1
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    def _unary(self) -> Number:
        if self._at_op("-"):
            self._pos += 1
            return -self._unary()
        return self._power()

    def _power(self) -> Number:
        base = self._primary()
        if self._at_op("^"):
            self._pos += 1
            exponent = self._unary()
            return base ** exponent
        return base

    def _primary(self) -> Number:
        tok = self._peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        kind, value = tok
        if kind == "num":
            self._pos += 1
            return value
        if value == "(":
            self._pos += 1
            result = self._expression()
            if not self._at_op(")"):
                raise ValueError("missing closing parenthesis")
            self._pos += 1
            return result
        raise ValueError("unexpected token {!r}".format(value))


def evaluate(expr: str) -> Number:
    tokens = _tokenize(expr)
    parser = _Parser(tokens)
    try:
