def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current_section = ""

    for raw_line in text.split("\n"):
        line = raw_line[:-1] if raw_line.endswith("\r") else raw_line
        stripped = line.strip()

        if not stripped or stripped[0] in ";#":
            continue

        if stripped[0] == "[":
            bracket_end = stripped.find("]")
            if bracket_end == -1:
                raise ValueError(f"malformed section header: {line!r}")
            name = stripped[1:bracket_end].strip()
            if not name:
                raise ValueError(f"empty section name: {line!r}")
            tail = stripped[bracket_end + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected text after section header: {line!r}")
            current_section = name
            sections.setdefault(name, {})
            continue

        eq_index = stripped.find("=")
        if eq_index == -1:
            raise ValueError(f"invalid line (expected key = value): {line!r}")
        key = stripped[:eq_index].strip()
        if not key:
            raise ValueError(f"empty key: {line!r}")
        value = stripped[eq_index + 1:].strip()

        if value.startswith('"'):
            close_index = value.find('"', 1)
            if close_index == -1:
                raise ValueError(f"missing closing quote: {line!r}")
            parsed_value = value[1:close_index]
            tail = value[close_index + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected text after quoted value: {line!r}")
        else:
            parsed_value = value
            for i in range(1, len(parsed_value)):
                if parsed_value[i] in ";#" and parsed_value[i - 1] in " \t":
                    parsed_value = parsed_value[:i].strip()
                    break

        sections.setdefault(current_section, {})[key] = parsed_value

    return sections
