```python
def shell_split(s: str) -> list[str]:
    """Split a command line into words using a small subset of POSIX
    shell quoting rules.

    - Outside quotes, spaces and tabs separate words.
    - Outside quotes, a backslash makes the next character literal.
    - Single quotes: contents are fully literal until the next single quote.
    - Double quotes: \" -> ", \\ -> \, any other backslash stays as is.
    - Touching quoted/unquoted pieces form one word; empty quotes are a word.

    Raises ValueError on a trailing backslash outside quotes or an
    unterminated quote.
    """
    words: list[str] = []
    current: list[str] = []
    has_word = False
    i = 0
    n = len(s)

    while i < n:
        ch = s[i]

        if ch in " \t":  # separators outside quotes
            if has_word:
                words.append("".join(current))
                current = []
                has_word = False
            i += 1

        elif ch == "\\":  # escape: the next character is literal
            if i + 1 >= n:
                raise ValueError("shell_split: trailing backslash")
            current.append(s[i + 1])
            has_word = True
            i += 2

        elif ch == "'":  # single-quoted: literal until the next '
            end = s.find("'", i + 1)
            if end == -1:
                raise ValueError("shell_split: unterminated single quote")
            current.append(s[i + 1 : end])
            has_word = True
            i = end + 1

        elif ch == '"':  # double-quoted until the next unescaped "
            i += 1
            while True:
                if i >= n:
                    raise ValueError("shell_split: unterminated double quote")
                ch = s[i]
                if ch == '"':
                    i += 1
                    break
                if ch == "\\":
                    if i + 1 >= n:
                        raise ValueError("shell_split: unterminated double quote")
                    nxt = s[i + 1]
                    if nxt == '"' or nxt == "\\":
                        current.append(nxt)
                    else:  # any other backslash is kept as is
                        current.append("\\")
                        current.append(nxt)
                    i += 2
                else:
                    current.append(ch)
                    i += 1
            has_word = True  # an empty quoted string is still a word

        else:  # ordinary character
            current.append(ch)
            has_word = True
            i += 1

    if has_word:
        words.append("".join(current))
    return words
