import ipaddress
import re

_SCHEME_RE = re.compile(r"([A-Za-z][A-Za-z0-9+\-.]*)://")
_AUTHORITY_END_RE = re.compile(r"[/?#]")
_PORT_RE = re.compile(r"[0-9]{1,5}")
_BAD_HOST_CHARS = frozenset(" /?#:[]@")


def _parse_port(text: str) -> int:
    """Validate a port string (1-5 ASCII digits, value 1-65535) and return it as an int."""
    if _PORT_RE.fullmatch(text) is None:
        raise ValueError(f"invalid port after ':': {text!r}")
    value = int(text)
    if not 1 <= value <= 65535:
        raise ValueError(f"port value {value} is outside the range 1..65535")
    return value


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError("url must be a string")

    # --- scheme ---
    scheme_match = _SCHEME_RE.match(url)
    if scheme_match is None:
        raise ValueError(f"URL must start with a scheme followed by '://': {url!r}")
    scheme = scheme_match.group(1).lower()
    rest = url[scheme_match.end():]

    # --- authority: up to the first '/', '?' or '#' (or the end) ---
    end_match = _AUTHORITY_END_RE.search(rest)
    if end_match is None:
        authority, remainder = rest, ""
    else:
        authority, remainder = rest[:end_match.start()], rest[end_match.start():]
    if not authority:
        raise ValueError("authority must be non-empty")

    # --- userinfo: everything before the LAST '@' in the authority ---
    at_index = authority.rfind("@")
    if at_index >= 0:
        userinfo, hostport = authority[:at_index], authority[at_index + 1:]
    else:
        userinfo, hostport = "", authority

    # --- host and optional port ---
    if hostport.startswith("["):
        close_index = hostport.find("]")
        if close_index < 0:
            raise ValueError(f"IPv6 literal is missing its closing ']': {hostport!r}")
        host_raw = hostport[1:close_index]
        try:
            ipaddress.IPv6Address(host_raw)
        except ValueError:
            raise ValueError(f"invalid IPv6 literal: {host_raw!r}") from None
        host = host_raw.lower()
        after = hostport[close_index + 1:]
        if not after:
            port = None
        elif after.startswith(":"):
            port = _parse_port(after[1:])
        else:
            raise ValueError(f"unexpected characters after IPv6 literal: {after!r}")
    else:
        colon_index = hostport.find(":")
        if colon_index >= 0:
            host_raw = hostport[:colon_index]
            port = _parse_port(hostport[colon_index + 1:])
        else:
            host_raw, port = hostport, None
        if not host_raw:
            raise ValueError("host must be non-empty")
        for character in host_raw:
            if character in _BAD_HOST_CHARS:
                raise ValueError(f"invalid character {character!r} in host: {host_raw!r}")
        host = host_raw.lower()

    # --- path, query, fragment: the first '#' wins, then the first '?' before it ---
    hash_index = remainder.find("#")
    if hash_index >= 0:
        fragment, remainder = remainder[hash_index + 1:], remainder[:hash_index]
    else:
        fragment = ""
    query_index = remainder.find("?")
    if query_index >= 0:
        query, path = remainder[query_index + 1:], remainder[:query_index]
    else:
        query, path = "", remainder

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }
