import re

_SCHEME_RE = re.compile(r'^([A-Za-z][A-Za-z0-9+\-.]*)://')
_HOST_FORBIDDEN = set(' /?#@:[]')


def _parse_port(text: str) -> int:
    if text == '' or len(text) > 5:
        raise ValueError('invalid port')
    for ch in text:
        if not ('0' <= ch <= '9'):
            raise ValueError('invalid port')
    value = int(text)
    if value < 1 or value > 65535:
        raise ValueError('port out of range')
    return value


def parse_url(url: str) -> dict:
    if not isinstance(url, str):
        raise ValueError('url must be a string')

    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = match.group(1).lower()

    rest = url[match.end():]

    delim = re.search(r'[/?#]', rest)
    if delim is not None:
        authority = rest[:delim.start()]
        remainder = rest[delim.start():]
    else:
        authority = rest
        remainder = ''

    if authority == '':
        raise ValueError('authority must be non-empty')

    if '@' in authority:
        userinfo, hostport = authority.rsplit('@', 1)
    else:
        userinfo, hostport = '', authority

    if hostport.startswith('['):
        close = hostport.find(']')
        if close == -1:
            raise ValueError("IPv6 literal is missing ']'")
        host = hostport[1:close]
        if host == '':
            raise ValueError('empty IPv6 literal')
        after = hostport[close + 1:]
        if after == '':
            port = None
        elif after.startswith(':'):
            port = _parse_port(after[1:])
        else:
            raise ValueError('invalid characters after IPv6 literal')
    else:
        colon = hostport.find(':')
        if colon == -1:
            host = hostport
            port = None
        else:
            host = hostport[:colon]
            port = _parse_port(hostport[colon + 1:])
        if host == '':
            raise ValueError('host must be non-empty')
        for ch in host:
            if ch in _HOST_FORBIDDEN:
                raise ValueError('invalid character in host')

    hash_pos = remainder.find('#')
    if hash_pos != -1:
        before_fragment = remainder[:hash_pos]
        fragment = remainder[hash_pos + 1:]
    else:
        before_fragment = remainder
        fragment = ''

    query_pos = before_fragment.find('?')
    if query_pos != -1:
        path = before_fragment[:query_pos]
        query = before_fragment[query_pos + 1:]
    else:
        path = before_fragment
        query = ''

    return {
        'scheme': scheme,
        'userinfo': userinfo,
        'host': host.lower(),
        'port': port,
        'path': path,
        'query': query,
        'fragment': fragment,
    }
