import heapq


def topo_sort(deps: dict[str, list[str]]) -> list[str]:
    """Return items ordered so every item comes after all of its dependencies.

    - Every item mentioned as a key or inside a dependency list appears
      exactly once in the result.
    - Duplicate entries in dependency lists are ignored.
    - Deterministic: whenever several items are "ready" (all of their
      dependencies already placed), the lexicographically smallest one is
      emitted first (plain string comparison).
    - Raises ValueError on a self-dependency or any cycle.
    - The input dict and its lists are not modified.
    """
    # Collect every item mentioned anywhere.
    items = set(deps)
    for dep_list in deps.values():
        items.update(dep_list)

    # Build reverse edges and in-degrees, deduplicating dependency lists
    # without mutating them.
    dependents: dict[str, list[str]] = {item: [] for item in items}
    unmet: dict[str, int] = {item: 0 for item in items}

    for item, dep_list in deps.items():
        for dep in dict.fromkeys(dep_list):  # dedupe, keep order, no mutation
            dependents[dep].append(item)
            unmet[item] += 1

    # Kahn's algorithm with a min-heap for deterministic tie-breaking.
    ready = [item for item, count in unmet.items() if count == 0]
    heapq.heapify(ready)

    result: list[str] = []
    while ready:
        item = heapq.heappop(ready)
        result.append(item)
        for dependent in dependents[item]:
            unmet[dependent] -= 1
            if unmet[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(items):
        raise ValueError("dependency cycle detected (possibly a self-dependency)")
    return result
