def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parse a simple INI document.

    Returns a mapping of section name -> mapping of key -> value.
    Keys appearing before any section header belong to the section "".
    Raises ValueError on malformed input.
    """
    sections: dict[str, dict[str, str]] = {}
    current = ""

    for raw in text.split("\n"):
        # Ignore a single trailing '\r' (CRLF line endings).
        if raw.endswith("\r"):
            raw = raw[:-1]

        stripped = raw.strip()

        # Blank lines and whole-line comments are skipped.
        if not stripped or stripped[0] in ";#":
            continue

        # Section header: [name] with optional whitespace; after ']' only
        # whitespace or a comment may follow.
        if stripped[0] == "[":
            end = stripped.find("]")
            if end == -1:
                raise ValueError(f"unterminated section header: {raw!r}")
            name = stripped[1:end].strip()
            if not name:
                raise ValueError(f"empty section name: {raw!r}")
            tail = stripped[end + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected text after section header: {raw!r}")
            current = name
            if name not in sections:
                sections[name] = {}
            continue

        # Key/value line: split on the FIRST '='.
        eq = raw.find("=")
        if eq == -1:
            raise ValueError(f"invalid line (expected 'key = value'): {raw!r}")
        key = raw[:eq].strip()
        if not key:
            raise ValueError(f"missing key: {raw!r}")

        rest = raw[eq + 1:]
        trimmed = rest.strip()

        if trimmed.startswith('"'):
            # Quoted value: literal up to the next '"', no escapes.
            close = trimmed.find('"', 1)
            if close == -1:
                raise ValueError(f"unterminated quoted value: {raw!r}")
            value = trimmed[1:close]
            tail = trimmed[close + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected text after quoted value: {raw!r}")
        else:
            # Inline comment starts at ';' or '#' preceded by a space or tab.
            # The character before rest[0] is '=', so index 0 never starts one.
            cut = -1
            for i in range(1, len(rest)):
                if rest[i] in ";#" and rest[i - 1] in " \t":
                    cut = i
                    break
            value = rest.strip() if cut == -1 else rest[:cut].strip()

        # Last duplicate key wins; the "" section is created only when used.
        sections.setdefault(current, {})[key] = value

    return sections
