    """Return True if `name` fully matches the glob `pattern` (case-sensitive)."""
    tokens = _parse_pattern(pattern)
    n_tokens = len(tokens)

    def epsilon_close(states):
        stack = list(states)
        while stack:
            i = stack.pop()
            if i < n_tokens and tokens[i][0] in ('STAR', 'DSTAR'):
                j = i + 1
                if j not in states:
                    states.add(j)
                    stack.append(j)
        return states

    current = epsilon_close({0})
    for ch in name:
        nxt = set()
        for i in current:
            if i >= n_tokens:
                continue
            tok = tokens[i]
            kind = tok[0]
            if kind == 'LIT':
                if tok[1] == ch:
                    nxt.add(i + 1)
            elif kind == 'ANY':
