                    nxt.add(i + 1)
            elif kind == 'STAR':
                if ch != '/':
                    nxt.add(i)
            else:  # 'DSTAR'
                nxt.add(i)
        if not nxt:
            return False
        current = epsilon_close(nxt)
    return n_tokens in current


def _parse_pattern(pattern):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('DSTAR',))
                i += 2
            else:
                tokens.append(('STAR',))
                i += 1
        elif c == '?':
            tokens.append(('ANY',))
            i += 1
        elif c == '[':
            negated, items, i = _parse_class(pattern, i)
            tokens.append(('CLASS', negated, tuple(items)))
        elif c == '\\':
            if i + 1 >= n:
                raise ValueError('pattern error: backslash at end of pattern')
            tokens.append(('LIT', pattern[i + 1]))
            i += 2
        else:
            tokens.append(('LIT', c))
            i += 1
    return tokens


def _parse_class(pattern, i):
    # pattern[i] == '['; returns (negated, items, next_index)
    n = len(pattern)
    i += 1
    negated = False
    if i < n and pattern[i] == '!':
        negated = True
        i += 1
    items = []  # list of inclusive (lo, hi) ranges
    first = True
    while True:
        if i >= n:
            raise ValueError('pattern error: unterminated [set]')
        c = pattern[i]
        if c == ']' and not first:
            return negated, items, i + 1
        if c == '\\':
            if i + 1 >= n:
                raise ValueError('pattern error: backslash at end of pattern')
            c = pattern[i + 1]
            i += 2
        else:
            i += 1
        if i + 1 < n and pattern[i] == '-' and pattern[i + 1] != ']':
            i += 1
            hi = pattern[i]
            if hi == '\\':
                if i + 1 >= n:
                    raise ValueError('pattern error: backslash at end of pattern')
                hi = pattern[i + 1]
                i += 2
            else:
                i += 1
            if ord(hi) < ord(c):
                raise ValueError('pattern error: invalid character range')
            items.append((c, hi))
        else:
