    current = None  # name of the current section, None until the first key

    for raw_line in text.split("\n"):
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]

        line = raw_line.strip()
        if not line or line[0] in ";#":
            continue

        # Section header: [name] with optional trailing whitespace/comment.
        if line[0] == "[":
            end = line.find("]")
            if end < 0:
                raise ValueError("malformed section header: %r" % (raw_line,))
            name = line[1:end].strip()
            if not name:
                raise ValueError("empty section name: %r" % (raw_line,))
            trailing = line[end + 1:].strip()
            if trailing and trailing[0] not in ";#":
                raise ValueError(
                    "unexpected text after section header: %r" % (raw_line,)
                )
            if name not in result:
                result[name] = {}
            current = name
            continue

        # Key/value line: split on the first '='.
        eq = line.find("=")
        if eq < 0:
            raise ValueError("expected 'key = value': %r" % (raw_line,))
        key = line[:eq].strip()
        if not key:
            raise ValueError("empty key: %r" % (raw_line,))
        value = line[eq + 1:].strip()

        if value.startswith('"'):
            # Quoted value: literal contents up to the next double quote.
            close = value.find('"', 1)
            if close < 0:
                raise ValueError("unterminated quoted value: %r" % (raw_line,))
            trailing = value[close + 1:].strip()
            if trailing and trailing[0] not in ";#":
                raise ValueError(
                    "unexpected text after quoted value: %r" % (raw_line,)
                )
            value = value[1:close]
        else:
            # Inline comment: ';' or '#' preceded by a space or tab.
            for i in range(1, len(value)):
                if value[i] in ";#" and value[i - 1] in " \t":
                    value = value[:i]
                    break
            value = value.strip()

        if current is None:
            current = ""
            result.setdefault("", {})
        result[current][key] = value

