from typing import List, Optional, Tuple, Union

Number = Union[int, float]

# A token is a (kind, value, position) triple.  For numbers the kind is
# 'num' and value holds the int/float literal; for operators and
# parentheses the kind is the character itself and value is None.
Token = Tuple[str, Optional[Number], int]


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression and return the result.

    Grammar (recursive descent, one token of lookahead):

        expr   := term (('+' | '-') term)*        # lowest precedence
        term   := unary (('*' | '/') unary)*
        unary  := '-' unary | power
        power  := atom ('^' unary)?               # highest precedence
        atom   := NUMBER | '(' expr ')'

    '^' is right-associative and binds tighter than unary minus, so
    2 ^ 3 ^ 2 == 512, -2 ^ 2 == -4 and 2 ^ -1 == 0.5.  Integer literals
    evaluate to int, decimal literals to float, and '/' is always true
    division.  Any malformed input (including division by zero) raises
    ValueError.
    """
    try:
        return _Parser(_tokenize(expr)).parse()
    except ZeroDivisionError:
        # Python raises ZeroDivisionError for e.g. 0 ^ -1; the spec
        # requires ValueError for any division by zero.
        raise ValueError("division by zero") from None


class _Parser:
    """Consumes the token list produced by _tokenize."""

    __slots__ = ("_tokens", "_pos")

    def __init__(self, tokens: List[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def parse(self) -> Number:
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expr()
        if self._pos < len(self._tokens):
            kind, _, pos = self._tokens[self._pos]
            raise ValueError(f"unexpected token {kind!r} at position {pos}")
        return value

    # ------------------------------------------------------------------
    # Token helpers

    def _peek(self) -> Optional[str]:
        if self._pos < len(self._tokens):
            return self._tokens[self._pos][0]
        return None

    def _advance(self) -> Token:
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    # ------------------------------------------------------------------
    # Grammar rules, in order of increasing precedence

    def _expr(self) -> Number:
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._advance()[0]
            right = self._term()
            value = value + right if op == "+" else value - right
        return value

    def _term(self) -> Number:
        value = self._unary()
        while self._peek() in ("*", "/"):
            op = self._advance()[0]
            right = self._unary()
            if op == "*":
                value = value * right
            else:
                if right == 0:
                    raise ValueError("division by zero")
                value = value / right
        return value

    def _unary(self) -> Number:
        if self._peek() == "-":
            self._advance()
            return -self._unary()
        return self._power()

    def _power(self) -> Number:
        base = self._atom()
        if self._peek() == "^":
            self._advance()
            # The right-hand side re-enters at 'unary': this makes '^'
            # right-associative and permits a leading minus (2 ^ -1),
            # while the base itself is a bare atom, so -2 ^ 2 == -4.
            return base ** self._unary()
        return base

    def _atom(self) -> Number:
        kind = self._peek()
        if kind == "num":
            return self._advance()[1]  # tokenizer guarantees int/float
        if kind == "(":
            self._advance()
            value = self._expr()
            if self._peek() != ")":
                raise ValueError("missing closing parenthesis")
            self._advance()
            return value
        if kind is None:
            raise ValueError("unexpected end of expression; operand expected")
        raise ValueError(f"unexpected token {kind!r}; operand expected")


def _tokenize(expr: str) -> List[Token]:
    """Split *expr* into tokens; raise ValueError on anything invalid."""
    tokens: List[Token] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        start = i
        if "0" <= ch <= "9":  # ASCII digits only, per spec
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            if i < n and expr[i] == ".":
                i += 1
                if i >= n or not "0" <= expr[i] <= "9":
                    raise ValueError(
                        f"malformed number at position {start}: "
                        "a decimal point must be followed by a digit"
                    )
                while i < n and "0" <= expr[i] <= "9":
                    i += 1
                tokens.append(("num", float(expr[start:i]), start))
            else:
                tokens.append(("num", int(expr[start:i]), start))
        elif ch in "+-*/^()":
            tokens.append((ch, None, start))
            i += 1
        else:
            raise ValueError(f"unknown character {ch!r} at position {i}")
    return tokens
