def earliest_slot(
    busy: list[tuple[int, int]],
    duration: int,
    start: int,
    end: int,
) -> Optional[int]:
    """Return the earliest minute ``t`` with ``start <= t`` and
    ``t + duration <= end`` such that ``[t, t + duration)`` does not overlap
    any busy interval; ``None`` if no such minute exists.

    Busy intervals are half-open ``[begin, finish)`` pairs and may be given
    unsorted and overlapping; time outside ``[start, end]`` is ignored.  The
    input list is not modified.  Raises ``ValueError`` if ``duration`` is not
    a positive integer or if any busy interval has ``begin >= finish``.
    """
    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError("duration must be a positive integer")

    # Validate the original intervals, then clip them to the window.
    clipped = []
    for begin, finish in busy:
        if begin >= finish:
            raise ValueError("busy intervals must have begin < finish")
        lo = begin if begin > start else start
        hi = finish if finish < end else end
        if lo < hi:  # interval actually intersects [start, end]
            clipped.append((lo, hi))

    clipped.sort()

    # Merge overlapping or touching intervals into a disjoint, sorted list.
    merged = []
    for lo, hi in clipped:
        if merged and lo <= merged[-1][1]:
            if hi > merged[-1][1]:
                merged[-1] = (merged[-1][0], hi)
        else:
            merged.append((lo, hi))

    # Sweep: try the window start, then the end of each busy block; a fit
    # before any block is necessarily the earliest one.
    t = start
    for lo, hi in merged:
        if t + duration <= lo:
            return t
        t = hi
    return t if t + duration <= end else None


