"""wrap_text — greedy text wrapping (TDD step 2).

Only the space character (U+0020) separates words. Each line holds as many
words as fit, joined by single spaces, without exceeding ``width``. A word
longer than ``width`` always starts a new line and is cut into chunks of
exactly ``width`` characters; its final, possibly shorter, chunk opens a
line that later words may still join. Empty or space-only input yields an
empty list. Raises ValueError when ``width < 1``.

Targets Python 3.9, standard library only (no imports required).
"""


def wrap_text(text: str, width: int) -> list[str]:
    """Greedily wrap ``text`` into lines of at most ``width`` characters.

    Returns a list of lines without leading or trailing spaces. Raises
    ValueError if ``width < 1``.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: list[str] = []
    current: list[str] = []   # words placed on the line being built
    length = 0                # length of that line once joined with spaces

    for word in text.split(" "):
        if not word:                     # collapse space runs / edges
            continue
        word_len = len(word)

        if word_len > width:
            # An over-long word always starts on a fresh line.
            if current:
                lines.append(" ".join(current))
                current, length = [], 0
            full_chunks, remainder = divmod(word_len, width)
            for i in range(full_chunks):
                lines.append(word[i * width:(i + 1) * width])
            if remainder:
                # Short tail opens a line that following words may join.
                current = [word[full_chunks * width:]]
                length = remainder
            # remainder == 0: last chunk is a full-width line; the next
            # word necessarily starts yet another line (current stays empty).
        else:
            extra = word_len if not current else length + 1 + word_len
            if extra <= width:
                current.append(word)
                length = extra
            else:
                lines.append(" ".join(current))
                current, length = [word], word_len

    if current:
        lines.append(" ".join(current))
    return lines
