_DIGITS = "0123456789"
_PUNCT = "+-*/^()"


def _tokenize(text):
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _DIGITS:
            j = i
            while j < n and text[j] in _DIGITS:
                j += 1
            if j < n and text[j] == ".":
                j += 1
                if j >= n or text[j] not in _DIGITS:
                    raise ValueError("malformed number literal")
                while j < n and text[j] in _DIGITS:
                    j += 1
                tokens.append(float(text[i:j]))
            else:
                tokens.append(int(text[i:j]))
            i = j
            continue
        if ch in _PUNCT:
            tokens.append(ch)
            i += 1
            continue
        raise ValueError("unexpected character: %r" % ch)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._pos = 0

    def parse(self):
        if not self._tokens:
            raise ValueError("empty expression")
        value = self._expr()
        if self._pos != len(self._tokens):
            raise ValueError("unexpected token")
        return value

    def _peek(self):
        if self._pos < len(self._tokens):
            return self._tokens[self._pos]
        return None

    def _advance(self):
        token = self._peek()
        self._pos += 1
        return token

    def _expr(self):
        value = self._term()
        while self._peek() in ("+", "-"):
            op = self._advance()
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self):
        value = self._unary()
        while self._peek() in ("*", "/"):
            op = self._advance()
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ValueError("division by zero")
                value = value / rhs
        return value

    def _unary(self):
        if self._peek() == "-":
            self._advance()
            return -self._unary()
        return self._power()

    def _power(self):
        base = self._atom()
        if self._peek() == "^":
            self._advance()
            exponent = self._unary()
            return base ** exponent
        return base

    def _atom(self):
        token = self._advance()
        if isinstance(token, (int, float)):
            return token
        if token == "(":
            value = self._expr()
            if self._advance() != ")":
                raise ValueError("unbalanced parentheses")
            return value
        raise ValueError("expected a number or '('")


def evaluate(expr: str):
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    parser = _Parser(_tokenize(expr))
    try:
        return parser.parse()
    except ZeroDivisionError:
        raise ValueError("division by zero") from None
