import re

_SCHEME_RE = re.compile(r'[A-Za-z][A-Za-z0-9+\-.]*://')
_AUTH_END_RE = re.compile(r'[/?#]')
_ASCII_DIGITS = frozenset('0123456789')
_BAD_HOST_CHARS = frozenset(' /?#:@[]')


def parse_url(url: str) -> dict:
    """Split *url* into scheme, userinfo, host, port, path, query, fragment."""
    match = _SCHEME_RE.match(url)
    if match is None:
        raise ValueError('URL must start with a scheme followed by "://"')
    scheme = match.group(0)[:-3].lower()

    rest = url[match.end():]
    auth_end = _AUTH_END_RE.search(rest)
    if auth_end is not None:
        authority = rest[:auth_end.start()]
        tail = rest[auth_end.start():]
    else:
        authority = rest
        tail = ''
    if not authority:
        raise ValueError('empty authority')

    at = authority.rfind('@')
    if at == -1:
        userinfo, hostport = '', authority
    else:
        userinfo, hostport = authority[:at], authority[at + 1:]

    host, port = _parse_hostport(hostport)

    hash_pos = tail.find('#')
    if hash_pos != -1:
        fragment = tail[hash_pos + 1:]
        tail = tail[:hash_pos]
    else:
        fragment = ''
    query_pos = tail.find('?')
    if query_pos != -1:
        query, path = tail[query_pos + 1:], tail[:query_pos]
    else:
        query, path = '', tail

    return {
        'scheme': scheme,
        'userinfo': userinfo,
        'host': host,
        'port': port,
        'path': path,
        'query': query,
        'fragment': fragment,
    }


def _parse_hostport(hostport: str):
    if hostport.startswith('['):
        close = hostport.find(']')
        if close == -1:
            raise ValueError('IPv6 literal missing closing bracket')
        host = hostport[1:close]
        if not host or any(c in '[] ' for c in host):
            raise ValueError('invalid IPv6 literal')
        remainder = hostport[close + 1:]
        if not remainder:
            return host.lower(), None
        if remainder[0] != ':':
            raise ValueError('unexpected characters after IPv6 literal')
        return host.lower(), _parse_port(remainder[1:])

    colon = hostport.find(':')
    if colon == -1:
        host, port_str = hostport, None
    else:
        host, port_str = hostport[:colon], hostport[colon + 1:]
    if not host or any(c in _BAD_HOST_CHARS for c in host):
        raise ValueError('invalid host')
    host = host.lower()
    if port_str is None:
        return host, None
    return host, _parse_port(port_str)


def _parse_port(port_str: str) -> int:
    if not 1 <= len(port_str) <= 5 or any(c not in _ASCII_DIGITS for c in port_str):
        raise ValueError('invalid port')
    port = int(port_str)
    if not 1 <= port <= 65535:
        raise ValueError('port out of range')
    return port
