        if not sep:
            raise ValueError('invalid line (expected key = value): %r' % raw_line)
        key = key.strip()
        if not key:
            raise ValueError('empty key: %r' % raw_line)
        value = raw_value.strip()

        if value.startswith('"'):
            # Quoted value: literal up to the next '"'; no escapes, no trimming.
            end = value.find('"', 1)
            if end == -1:
                raise ValueError('missing closing quote: %r' % raw_line)
            parsed = value[1:end]
            trailing = value[end + 1:].strip()
            if trailing and trailing[0] not in ';#':
                raise ValueError('unexpected text after quoted value: %r' % raw_line)
        else:
            # Inline comment starts at ';'/'#' preceded by a space or tab.
            # (Value is trimmed, so a marker at index 0 has no preceding
            # whitespace and is part of the value.)
