"""A small INI parser (Python 3.9, standard library only)."""


def _cut_inline_comment(value: str) -> str:
    """Drop an inline comment from `value` and return the trimmed result.

    An inline comment begins at the first ';' or '#' that is preceded by a
    space or a tab.  A ';' or '#' that is not preceded by whitespace is a
    literal part of the value (e.g. ``http://x/#frag``).
    """
    for i, ch in enumerate(value):
        if ch in ";#" and i > 0 and value[i - 1] in " \t":
            return value[:i].strip()
    return value.strip()


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """Parse a simple INI document into {section: {key: value}}.

    Keys appearing before any section header live in the section "" which is
    created only if such a key actually occurs.  Named sections are created
    as soon as their header is seen, even if they end up keyless.  Duplicate
    keys keep the last value; a repeated section header merges the sections.

    Raises ValueError on any malformed line.
    """
    result: dict[str, dict[str, str]] = {}
    section = ""

    for lineno, raw in enumerate(text.split("\n"), 1):
        if raw.endswith("\r"):
            raw = raw[:-1]

        line = raw.strip()

        # Blank lines and whole-line comments are skipped.
        if not line or line[0] in ";#":
            continue

        # Section header.
        if line[0] == "[":
            end = line.find("]")
            if end == -1:
                raise ValueError(
                    "line %d: unterminated section header: %r" % (lineno, raw)
                )
            name = line[1:end].strip()
            if not name:
                raise ValueError(
                    "line %d: empty section name: %r" % (lineno, raw)
                )
            tail = line[end + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(
                    "line %d: text after ']' in section header: %r" % (lineno, raw)
                )
            section = name
            result.setdefault(name, {})
            continue

        # Key/value line: split on the FIRST '='.
        if "=" not in line:
            raise ValueError(
                "line %d: not a section header or a key/value line: %r" % (lineno, raw)
            )
        key_part, _, value_part = line.partition("=")

        key = key_part.strip()
        if not key:
            raise ValueError("line %d: empty key: %r" % (lineno, raw))

        trimmed = value_part.strip()
        if trimmed.startswith('"'):
            # Quoted value: literal text up to the next '"'.
            end = trimmed.find('"', 1)
            if end == -1:
                raise ValueError(
                    "line %d: missing closing quote: %r" % (lineno, raw)
                )
            value = trimmed[1:end]
            tail = trimmed[end + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(
                    "line %d: text after closing quote: %r" % (lineno, raw)
                )
        else:
            # Unquoted: cut at an inline comment, then trim.
            value = _cut_inline_comment(value_part)

        result.setdefault(section, {})[key] = value

    return result
