from typing import List


def wrap_text(text: str, width: int) -> List[str]:
    """Greedily wrap `text` into lines of at most `width` characters.

    Words are maximal runs of characters containing no U+0020; one or more
    U+0020 characters separate them. A word longer than `width` always
    starts a new line and is split into consecutive pieces of exactly
    `width` characters; its final (possibly shorter) piece starts a line
    that may take following words if they fit. Lines never have leading
    or trailing spaces. Empty or space-only text yields [].

    Raises:
        ValueError: if width < 1.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines: List[str] = []
    current = ""
    for word in text.split(" "):
        if not word:
            continue  # collapses runs of spaces and leading/trailing spaces
        if len(word) > width:
            # Long word: always flush the current line first, then emit
            # fixed-size chunks; the final chunk seeds the next line.
            if current:
                lines.append(current)
                current = ""
            chunks = [word[i:i + width] for i in range(0, len(word), width)]
            lines.extend(chunks[:-1])
            current = chunks[-1]
        elif not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines
