def glob_match(pattern: str, name: str) -> bool:
    """Return True if the whole of ``name`` matches the glob ``pattern``.

    Semantics (anchored at both ends, case-sensitive):
      *     any run of characters containing no '/'
      **    any run of characters, possibly empty, may contain '/'
      ?     exactly one character other than '/'
      [..]  one character from the set; 'a-z' style ranges allowed; a
            leading '!' negates; a ']' immediately after '[' or '[!' is a
            literal member; a backslash makes the next pattern character
            literal.

    Raises ValueError for malformed patterns: an unterminated '[', a
    trailing backslash, or a reversed range such as '[z-a]'.
    """
    _LIT, _STAR, _GSTAR, _QMARK, _CLASS = 0, 1, 2, 3, 4

    def read_char(pat, j):
        # Consume one (possibly backslash-escaped) character at pat[j];
        # return (character, index just past it).
        if pat[j] == '\\':
            if j + 1 >= len(pat):
                raise ValueError("pattern ends with a bare backslash")
            return pat[j + 1], j + 2
        return pat[j], j + 1

    def parse_class(pat, i):
        # Parse the character class starting at pat[i] == '[';
        # return ((token kind, payload), index just past the closing ']').
        n = len(pat)
        j = i + 1
        negate = False
        if j < n and pat[j] == '!':
            negate = True
            j += 1
        items = []            # single characters or (low, high) ranges
        first = True
        closed = False
        while j < n:
            if pat[j] == ']' and not first:
                j += 1
                closed = True
                break
            lo, j = read_char(pat, j)
            first = False
            if j < n and pat[j] == '-' and j + 1 < n and pat[j + 1] != ']':
                hi, j = read_char(pat, j + 1)
                if lo > hi:
                    raise ValueError("reversed character range in '[...]'")
                items.append((lo, hi))
            else:
                items.append(lo)
        if not closed:
            raise ValueError("unterminated '[' in pattern")
        return (_CLASS, (negate, items)), j

    # ---- Pass 1: tokenize (and thereby validate) the pattern ----
    tokens = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a bare backslash")
            tokens.append((_LIT, pattern[i + 1]))
            i += 2
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append((_GSTAR, None))
                i += 2
            else:
                tokens.append((_STAR, None))
                i += 1
        elif c == '?':
            tokens.append((_QMARK, None))
            i += 1
        elif c == '[':
            tok, i = parse_class(pattern, i)
            tokens.append(tok)
        else:
            tokens.append((_LIT, c))
            i += 1

    # ---- Pass 2: dynamic programming over (token index, name index) ----
    # dp[t][j] is True iff tokens[t:] matches name[j:] exactly.
    T, N = len(tokens), len(name)
    dp = [[False] * (N + 1) for _ in range(T + 1)]
    dp[T][N] = True
    for t in range(T - 1, -1, -1):
        kind, val = tokens[t]
        row, nxt = dp[t], dp[t + 1]
        if kind == _LIT:
            for j in range(N, -1, -1):
                row[j] = j < N and name[j] == val and nxt[j + 1]
        elif kind == _QMARK:
            for j in range(N, -1, -1):
                row[j] = j < N and name[j] != '/' and nxt[j + 1]
        elif kind == _CLASS:
            negate, items = val
            for j in range(N, -1, -1):
                if j < N:
                    ch = name[j]
                    inside = False
                    for item in items:
                        if isinstance(item, tuple):
                            if item[0] <= ch <= item[1]:
                                inside = True
                                break
                        elif item == ch:
                            inside = True
                            break
                    row[j] = (inside != negate) and nxt[j + 1]
                else:
                    row[j] = False
        elif kind == _STAR:
            for j in range(N, -1, -1):
                row[j] = nxt[j] or (j < N and name[j] != '/' and row[j + 1])
        else:  # _GSTAR
            for j in range(N, -1, -1):
                row[j] = nxt[j] or (j < N and row[j + 1])
    return dp[0][0]
