import re

_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def _increment(digits: str) -> str:
    """Add one to a non-empty string of ASCII digits (unsigned)."""
    chars = list(digits)
    i = len(chars) - 1
    while i >= 0 and chars[i] == "9":
        chars[i] = "0"
        i -= 1
    if i < 0:
        return "1" + "".join(chars)
    chars[i] = chr(ord(chars[i]) + 1)
    return "".join(chars)


def round_half_up(x: str, ndigits: int) -> str:
    # Validate x: optional '-', one or more ASCII digits, optional '.' + digits.
    if not isinstance(x, str) or _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError("x must be of the form -?digits(.digits)? with ASCII digits")
    if not isinstance(ndigits, int) or ndigits < 0:
        raise ValueError("ndigits must be a non-negative integer")

    negative = x.startswith("-")
    body = x[1:] if negative else x
    if "." in body:
        int_part, frac_part = body.split(".", 1)
    else:
        int_part, frac_part = body, ""

    if len(frac_part) <= ndigits:
        # No fractional digits are discarded; just pad with trailing zeros.
        magnitude = int_part + frac_part + "0" * (ndigits - len(frac_part))
    else:
        # Keep ndigits fractional digits; round away from zero on a tie.
        magnitude = int_part + frac_part[:ndigits]
        if frac_part[ndigits] >= "5":
            magnitude = _increment(magnitude)

    # Normalize: strip leading zeros (keep at least one digit).
    magnitude = magnitude.lstrip("0") or "0"
    is_zero = magnitude == "0"

    if ndigits == 0:
        result = magnitude
    else:
        magnitude = magnitude.zfill(ndigits + 1)
        result = magnitude[:-ndigits] + "." + magnitude[-ndigits:]

    if negative and not is_zero:
        result = "-" + result
    return result
