def evaluate(expr: str):
    """Evaluate an arithmetic expression and return an int or float.

    Grammar (recursive descent):
        expr    := term (('+' | '-') term)*
        term    := unary (('*' | '/') unary)*
        unary   := '-' unary | power
        power   := primary ('^' unary)?        # right-associative
        primary := NUMBER | '(' expr ')'
    """
    tokens = _tokenize(expr)
    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ('*', '/'):
            op = advance()[0]
            rhs = parse_unary()
            value = value * rhs if op == '*' else value / rhs
        return value

    def parse_unary():
        if peek() == '-':
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_primary()
        if peek() == '^':
            advance()
            return base ** parse_unary()
        return base

    def parse_primary():
        kind = peek()
        if kind == 'num':
            return advance()[1]
        if kind == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses: expected ')'")
            advance()
            return value
        if kind is None:
            raise ValueError("unexpected end of expression: missing operand")
        raise ValueError(f"unexpected token {kind!r}")

    try:
        result = parse_expr()
    except ZeroDivisionError as exc:
        raise ValueError("division by zero") from exc

    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos][0]!r} after end of expression")
    return result


def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    digits = '0123456789'
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c in digits:
            j = i
            while j < n and expr[j] in digits:
                j += 1
            if j < n and expr[j] == '.':
                j += 1
                if j >= n or expr[j] not in digits:
                    raise ValueError("malformed number: expected digits after '.'")
                while j < n and expr[j] in digits:
                    j += 1
                tokens.append(('num', float(expr[i:j])))
            else:
                tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, None))
            i += 1
        else:
            raise ValueError(f"unknown character {c!r}")
    return tokens
