"""A minimal, dependency-free INI parser (Python 3.9+, standard library only)."""

from typing import Dict, Tuple

_COMMENT_CHARS = ";#"
_SPACE_CHARS = " \t"


def _parse_section_header(stripped: str, lineno: int) -> str:
    """Parse `[name]` (possibly followed by a comment) and return `name`."""
    end = stripped.find("]", 1)
    if end < 0:
        raise ValueError("line %d: unterminated section header: %r" % (lineno, stripped))
    name = stripped[1:end].strip()
    if not name:
        raise ValueError("line %d: empty section name" % lineno)
    tail = stripped[end + 1:].strip()
    if tail and tail[0] not in _COMMENT_CHARS:
        raise ValueError(
            "line %d: unexpected text after section header: %r" % (lineno, tail)
        )
    return name


def _parse_key_value(line: str, lineno: int) -> Tuple[str, str]:
    """Parse `key = value` (splitting on the first '=') and return (key, value)."""
    eq = line.find("=")
    if eq < 0:
        raise ValueError(
            "line %d: expected 'key = value' or '[section]': %r" % (lineno, line)
        )
    key = line[:eq].strip()
    if not key:
        raise ValueError("line %d: empty key" % lineno)

    value = line[eq + 1:].strip()

    # Quoted value: everything up to the next '"' is literal.
    if value.startswith('"'):
        end = value.find('"', 1)
        if end < 0:
            raise ValueError("line %d: unterminated quoted value: %r" % (lineno, value))
        result = value[1:end]
        tail = value[end + 1:].strip()
        if tail and tail[0] not in _COMMENT_CHARS:
            raise ValueError(
                "line %d: unexpected text after quoted value: %r" % (lineno, tail)
            )
        return key, result

    # Unquoted value: an inline comment starts at a ';' or '#'
    # that is preceded by a space or tab.
    for i in range(1, len(value)):
        if value[i] in _COMMENT_CHARS and value[i - 1] in _SPACE_CHARS:
            return key, value[:i].strip()
    return key, value


def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    sections: Dict[str, Dict[str, str]] = {}
    current = ""

    for lineno, raw_line in enumerate(text.split("\n"), 1):
        line = raw_line[:-1] if raw_line.endswith("\r") else raw_line
        stripped = line.strip()

        if not stripped:
            continue
        if stripped[0] in _COMMENT_CHARS:
            continue

        if stripped[0] == "[":
            current = _parse_section_header(stripped, lineno)
            sections.setdefault(current, {})
            continue

        key, value = _parse_key_value(line, lineno)
        section = sections.get(current)
        if section is None:
            section = sections[current] = {}
        section[key] = value

    return sections
