from typing import Union


def evaluate(expr: str) -> Union[int, float]:
    """Evaluate an arithmetic expression given as a string.

    Grammar (recursive descent, evaluated in-line):

        expr  := term  (('+' | '-') term)*
        term  := unary (('*' | '/') unary)*
        unary := '-' unary | power
        power := atom ('^' unary)?
        atom  := NUMBER | '(' expr ')'

    This yields the required precedence ('+'/'-' < '*'/'/' < '^') and
    associativity ('^' right-associative, the rest left-associative).
    Unary minus binds less tightly than '^' on its left ('-2 ^ 2' == -4)
    but is allowed in the exponent ('2 ^ -1' == 0.5).

    Raises ValueError for malformed input and for division by zero.
    """
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    # ---- Tokenizer ------------------------------------------------------
    tokens = []  # ints/floats for numbers, 1-char strings for symbols
    i, n = 0, len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():                       # ignore whitespace anywhere
            i += 1
        elif ch in "+-*/^()":
            tokens.append(ch)
            i += 1
        elif "0" <= ch <= "9":                 # integer or decimal literal
            start = i
            while i < n and "0" <= expr[i] <= "9":
                i += 1
            if i < n and expr[i] == ".":       # optional fractional part
                i += 1
                if i >= n or not "0" <= expr[i] <= "9":
                    raise ValueError(f"malformed number at position {start}")
                while i < n and "0" <= expr[i] <= "9":
                    i += 1
                tokens.append(float(expr[start:i]))
            else:
                tokens.append(int(expr[start:i]))
        else:
            raise ValueError(f"unexpected character {ch!r} at position {i}")

    if not tokens:
        raise ValueError("empty expression")

    # ---- Parser ----------------------------------------------------------
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expr():
        value = parse_term()
        while peek() in ("+", "-"):
            if advance() == "+":
                value = value + parse_term()
            else:
                value = value - parse_term()
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ("*", "/"):
            if advance() == "*":
                value = value * parse_unary()
            else:
                value = value / parse_unary()
        return value

    def parse_unary():
        if peek() == "-":
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == "^":
            advance()
            # Exponent is parsed as a unary so '2 ^ -1' works; recursing
            # through parse_unary -> parse_power makes '^' right-associative.
            return base ** parse_unary()
        return base

    def parse_atom():
        token = peek()
        if isinstance(token, (int, float)):
            return advance()
        if token == "(":
            advance()
            value = parse_expr()
            if peek() != ")":
                raise ValueError("unbalanced parentheses: expected ')'")
            advance()
            return value
        if token is None:
            raise ValueError("unexpected end of expression: operand expected")
        raise ValueError(f"unexpected token {token!r}: operand expected")

    try:
        result = parse_expr()
    except ZeroDivisionError:
        raise ValueError("division by zero") from None

    if pos != len(tokens):  # trailing junk: '2 3', '2(3)', '1+2)', ...
        raise ValueError(f"unexpected token {peek()!r} after expression end")

    return result
