from typing import List, Tuple, Union

Number = Union[int, float]


def _tokenize(expr: str) -> List[Tuple[str, Number]]:
    """Split the input into (kind, value) tokens.

    kind is 'num' (value: int or float) or one of '+', '-', '*', '/', '^',
    '(', ')' (value: the same character). Raises ValueError for any
    character that cannot appear in a valid token.
    """
    tokens: List[Tuple[str, Number]] = []
    i = 0
    length = len(expr)
    while i < length:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if '0' <= ch <= '9':  # ASCII digits only
            j = i
            while j < length and '0' <= expr[j] <= '9':
                j += 1
            if j < length and expr[j] == '.':
                k = j + 1
                if k < length and '0' <= expr[k] <= '9':
                    while k < length and '0' <= expr[k] <= '9':
                        k += 1
                    tokens.append(('num', float(expr[i:k])))
                    i = k
                else:
                    raise ValueError("malformed number: expected a digit after '.'")
            else:
                tokens.append(('num', int(expr[i:j])))
                i = j
            continue
        if ch in '+-*/^()':
            tokens.append((ch, ch))
            i += 1
            continue
        raise ValueError(f"unknown character {ch!r} at position {i}")
    return tokens


def evaluate(expr: str) -> Number:
    """Evaluate an arithmetic expression given as a string.

    Grammar (recursive descent, one token of lookahead):

        expression := term (('+' | '-') term)*      left-associative
        term       := unary (('*' | '/') unary)*    left-associative
        unary      := '-' unary | power             unary minus (looser than '^')
        power      := primary ('^' unary)?          right-associative
        primary    := NUMBER | '(' expression ')'
    """
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")
    pos = 0
    count = len(tokens)

    def peek():
        return tokens[pos][0] if pos < count else None

    def advance():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    def parse_expression():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()[0]
            right = parse_term()
            value = value + right if op == '+' else value - right
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ('*', '/'):
            op = advance()[0]
            right = parse_unary()
            if op == '*':
                value = value * right
            else:
                if right == 0:
                    raise ValueError("division by zero")
                value = value / right
        return value

    def parse_unary():
        if peek() == '-':
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_primary()
        if peek() == '^':
            advance()
            exponent = parse_unary()  # right-associative; may start with '-'
            return base ** exponent
        return base

    def parse_primary():
        kind = peek()
        if kind == 'num':
            return advance()[1]
        if kind == '(':
            advance()
            value = parse_expression()
            if peek() != ')':
                raise ValueError("unbalanced parentheses: expected ')'")
            advance()
            return value
        if kind is None:
            raise ValueError("unexpected end of input: operand expected")
        raise ValueError(f"unexpected token {kind!r}: operand expected")

    try:
        result = parse_expression()
    except ZeroDivisionError:
        # Covers cases like 0 ^ -1, where Python raises ZeroDivisionError.
        raise ValueError("division by zero") from None
    if pos != count:
        raise ValueError(f"unexpected token {tokens[pos][0]!r} after end of expression")
    return result
