import re

_DECIMAL_RE = re.compile(r"-?[0-9]+(?:\.[0-9]+)?")


def round_half_up(x: str, ndigits: int) -> str:
    """Round the exact decimal string x to ndigits places, ties away from zero."""
    if not isinstance(x, str):
        raise ValueError("x must be a string")
    if not isinstance(ndigits, int):
        raise ValueError("ndigits must be an integer")
    if ndigits < 0:
        raise ValueError("ndigits must be non-negative")
    if _DECIMAL_RE.fullmatch(x) is None:
        raise ValueError("invalid decimal format: %r" % (x,))

    neg = x.startswith("-")
    body = x[1:] if neg else x
    if "." in body:
        int_part, frac_part = body.split(".", 1)
    else:
        int_part, frac_part = body, ""

    frac_len = len(frac_part)
    # Exact absolute value as an integer numerator over 10**frac_len.
    n = int(int_part + frac_part)

    if ndigits >= frac_len:
        # No rounding needed; just scale up exactly.
        scaled = n * 10 ** (ndigits - frac_len)
    else:
        # Round n / 10**(frac_len - ndigits) with ties away from zero.
        divisor = 10 ** (frac_len - ndigits)
        q, r = divmod(n, divisor)
        if 2 * r >= divisor:
            q += 1
        scaled = q

    # Suppress negative zero.
    sign = "-" if neg and scaled != 0 else ""
    if ndigits == 0:
        return sign + str(scaled)

    digits = str(scaled)
    if len(digits) <= ndigits:
        digits = "0" * (ndigits + 1 - len(digits)) + digits
    return sign + digits[:-ndigits] + "." + digits[-ndigits:]
