    at_index = authority.rfind("@")
    if at_index != -1:
        userinfo = authority[:at_index]
        hostport = authority[at_index + 1:]
    else:
        userinfo = ""
        hostport = authority

    # Host and optional port.
    if hostport.startswith("["):
        close_index = hostport.find("]")
        if close_index == -1:
            raise ValueError("IPv6 literal in host is missing ']'")
        host = hostport[1:close_index].lower()
        if not host or "[" in host:
            raise ValueError("empty or invalid IPv6 literal in host")
        tail = hostport[close_index + 1:]
        if not tail:
            port = None
        elif tail.startswith(":"):
