        host = host_raw.lower()

    # Fragment starts at the first '#' (may itself contain '?');
    # before that, query starts at the first '?'; the rest is the path.
    hash_index = remainder.find("#")
    if hash_index != -1:
        fragment = remainder[hash_index + 1:]
        before_fragment = remainder[:hash_index]
    else:
        fragment = ""
        before_fragment = remainder

    question_index = before_fragment.find("?")
    if question_index != -1:
        path = before_fragment[:question_index]
        query = before_fragment[question_index + 1:]
    else:
        path = before_fragment
        query = ""

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
