    for raw_line in text.split("\n"):
        # Ignore a single trailing '\r' (Windows line endings).
        line = raw_line[:-1] if raw_line.endswith("\r") else raw_line
        stripped = line.strip()

        # Blank lines and whole-line comments are skipped.
        if not stripped or stripped[0] in ";#":
            continue

        # Section header.
        if stripped[0] == "[":
            close = stripped.find("]")
            if close == -1:
                raise ValueError(f"unterminated section header: {stripped!r}")
            name = stripped[1:close].strip()
            if not name:
                raise ValueError(f"empty section name: {stripped!r}")
            tail = stripped[close + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected content after section header: {stripped!r}")
            if name not in sections:
                sections[name] = {}
            current_section = name
            continue

        # Key/value line: split on the FIRST '='.
        if "=" not in line:
            raise ValueError(f"invalid line (missing '='): {line!r}")
        key_part, _, value_part = line.partition("=")
        key = key_part.strip()
        if not key:
            raise ValueError(f"empty key: {line!r}")

        trimmed_value = value_part.strip()
        if trimmed_value.startswith('"'):
            # Quoted value: literal content up to the next '"'.
            close = trimmed_value.find('"', 1)
            if close == -1:
                raise ValueError(f"missing closing quote: {line!r}")
            value = trimmed_value[1:close]
            tail = trimmed_value[close + 1:].strip()
            if tail and tail[0] not in ";#":
                raise ValueError(f"unexpected content after closing quote: {line!r}")
        else:
            # Inline comment starts at ';'/ '#' preceded by a space or tab.
            # A ';'/'#' not preceded by a space or tab is part of the value.
            cut = len(value_part)
            for i in range(1, len(value_part)):
                if value_part[i] in ";#" and value_part[i - 1] in " \t":
                    cut = i
                    break
            value = value_part[:cut].strip()

        target = current_section if current_section is not None else ""
        if target not in sections:
            sections[target] = {}
        sections[target][key] = value

    return sections
