def parse_ini(text: str) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    current_section: str | None = None

    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]

        stripped = line.strip()
        if not stripped or stripped[0] in ";#":
            continue

        if stripped.startswith("["):
            closing = stripped.find("]")
            if closing == -1:
                raise ValueError("Invalid section header")

            name = stripped[1:closing].strip()
            if not name:
                raise ValueError("Section name must not be empty")

            trailing = stripped[closing + 1:].strip()
            if trailing and trailing[0] not in ";#":
                raise ValueError("Invalid section header")

            current_section = name
            result.setdefault(current_section, {})
            continue

        if "=" not in line:
            raise ValueError("Invalid key/value line")

        raw_key, raw_value = line.split("=", 1)
        key = raw_key.strip()
        if not key:
            raise ValueError("Key must not be empty")

        if current_section is None:
            current_section = ""
            result.setdefault(current_section, {})

        value_text = raw_value.strip()

        if value_text.startswith('"'):
            closing = value_text.find('"', 1)
            if closing == -1:
                raise ValueError("Missing closing quote")

            value = value_text[1:closing]
            trailing = value_text[closing + 1:].strip()
            if trailing and trailing[0] not in ";#":
                raise ValueError("Invalid trailing content")
        else:
            comment_at = None
            for index, character in enumerate(raw_value):
                if (
                    character in ";#"
                    and index > 0
                    and raw_value[index - 1] in " \t"
                ):
                    comment_at = index
                    break

            if comment_at is not None:
                value = raw_value[:comment_at].strip()
            else:
                value = raw_value.strip()

        result[current_section][key] = value

    return result
