from typing import List, Tuple, Union

_DIGITS = "0123456789"
_OPERATORS = "+-*/^()"


def evaluate(expr: str) -> Union[int, float]:
    """Evaluate an arithmetic expression string and return a number.

    Grammar (recursive descent):
        expr  := term  (('+' | '-') term)*          left-associative
        term  := unary (('*' | '/') unary)*         left-associative
        unary := '-' unary | power                  unary minus (looser than '^')
        power := atom ('^' unary)?                  right-associative
        atom  := NUMBER | '(' expr ')'
    """
    tokens = _tokenize(expr)
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] == "op" and tok[1] in "+-":
                advance()
                rhs = parse_term()
                value = value + rhs if tok[1] == "+" else value - rhs
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            tok = peek()
            if tok is not None and tok[0] == "op" and tok[1] in "*/":
                advance()
                rhs = parse_unary()
                value = value * rhs if tok[1] == "*" else value / rhs
            else:
                return value

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == "op" and tok[1] == "-":
            advance()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        tok = peek()
        if tok is not None and tok[0] == "op" and tok[1] == "^":
            advance()
            exponent = parse_unary()  # allows 2 ^ -1; recursion makes ^ right-associative
            return base ** exponent
        return base

    def parse_atom():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        kind, value = tok
        if kind == "num":
            advance()
            return value
        if kind == "op" and value == "(":
            advance()
            inner = parse_expr()
            closing = peek()
            if closing is None or closing != ("op", ")"):
                raise ValueError("unbalanced parentheses")
            advance()
            return inner
        raise ValueError("malformed expression")

    try:
        result = parse_expr()
    except ZeroDivisionError as exc:
        raise ValueError("division by zero") from exc
    if pos != len(tokens):
        raise ValueError("unexpected token after end of expression")
    return result


def _tokenize(expr: str) -> List[Tuple[str, object]]:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
            continue
        if ch in _DIGITS:
            j = i
            while j < n and expr[j] in _DIGITS:
                j += 1
            if j < n and expr[j] == "." and j + 1 < n and expr[j + 1] in _DIGITS:
                j += 1
                while j < n and expr[j] in _DIGITS:
                    j += 1
                tokens.append(("num", float(expr[i:j])))
            else:
                tokens.append(("num", int(expr[i:j])))
            i = j
            continue
        if ch in _OPERATORS:
            tokens.append(("op", ch))
            i += 1
            continue
        raise ValueError("unexpected character: " + repr(ch))
    return tokens
