"""Strict URL splitter using only the Python standard library."""

import ipaddress
import re

_SCHEME_RE = re.compile(r"[A-Za-z][A-Za-z0-9.+-]*://")  # scheme + "://"
_AUTHORITY_END_RE = re.compile(r"[/?#]")                # characters ending the authority
_PORT_RE = re.compile(r"[0-9]{1,5}")                    # 1 to 5 ASCII digits (fullmatch)
_FORBIDDEN_HOST_CHARS = frozenset(" /?#:@[]")

_MIN_PORT = 1
_MAX_PORT = 65535


def parse_url(url: str) -> dict:
    """Split *url* into its components.

    Returns a dict with exactly the keys ``scheme``, ``userinfo``,
    ``host``, ``port``, ``path``, ``query`` and ``fragment``.

    Raises ``ValueError`` for any input violating the grammar: the URL
    must start with ``scheme://``; the authority must be non-empty; the
    host must be an IPv6 literal in square brackets or a non-empty run
    of characters containing none of space, ``/``, ``?``, ``#``, ``@``,
    ``:``, ``[``, ``]``; an explicit port must be 1-5 ASCII digits with
    a value from 1 to 65535.
    """
    scheme_match = _SCHEME_RE.match(url)
    if scheme_match is None:
        raise ValueError(
            f"URL must start with a scheme followed by '://': {url!r}"
        )
    scheme = url[: scheme_match.end() - 3].lower()

    rest = url[scheme_match.end():]

    end_match = _AUTHORITY_END_RE.search(rest)
    if end_match is None:
        authority, tail = rest, ""
    else:
        authority, tail = rest[: end_match.start()], rest[end_match.start():]

    if not authority:
        raise ValueError(f"URL has an empty authority: {url!r}")

    at_sign = authority.rfind("@")
    if at_sign < 0:
        userinfo, hostport = "", authority
    else:
        userinfo, hostport = authority[:at_sign], authority[at_sign + 1:]

    if hostport.startswith("["):
        host, port = _parse_bracketed_hostport(hostport, url)
    else:
        host, port = _parse_plain_hostport(hostport, url)

    hash_pos = tail.find("#")
    if hash_pos < 0:
        fragment, before_fragment = "", tail
    else:
        fragment, before_fragment = tail[hash_pos + 1:], tail[:hash_pos]

    question_pos = before_fragment.find("?")
    if question_pos < 0:
        path, query = before_fragment, ""
    else:
        path, query = (
            before_fragment[:question_pos],
            before_fragment[question_pos + 1:],
        )

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }


def _parse_port(port_text: str, url: str) -> int:
    """Return *port_text* as an int (1-5 ASCII digits, value 1..65535)."""
    if _PORT_RE.fullmatch(port_text) is None:
        raise ValueError(f"invalid port {port_text!r} in URL: {url!r}")
    port = int(port_text)
    if not _MIN_PORT <= port <= _MAX_PORT:
        raise ValueError(f"port {port} out of range in URL: {url!r}")
    return port


def _parse_bracketed_hostport(hostport: str, url: str):
    """Parse ``[ipv6-literal][:port]`` and return ``(host, port)``."""
    closing = hostport.find("]")
    if closing < 0:
        raise ValueError(f"unterminated IPv6 literal in URL: {url!r}")
    literal = hostport[1:closing]
    try:
        ipaddress.IPv6Address(literal)
    except ValueError:
        raise ValueError(
            f"invalid IPv6 literal {literal!r} in URL: {url!r}"
        ) from None
    remainder = hostport[closing + 1:]
    if not remainder:
        return literal.lower(), None
    if remainder.startswith(":"):
        return literal.lower(), _parse_port(remainder[1:], url)
    raise ValueError(
        f"unexpected characters after IPv6 literal in URL: {url!r}"
    )


def _parse_plain_hostport(hostport: str, url: str):
    """Parse ``hostname[:port]`` and return ``(host, port)``."""
    colon = hostport.find(":")
    if colon < 0:
        host_text, port_text = hostport, None
    else:
        host_text, port_text = hostport[:colon], hostport[colon + 1:]
    if not host_text:
        raise ValueError(f"URL has an empty host: {url!r}")
    if _FORBIDDEN_HOST_CHARS.intersection(host_text):
        raise ValueError(
            f"invalid character in host {host_text!r} in URL: {url!r}"
        )
    host = host_text.lower()
    if port_text is None:
        return host, None
    return host, _parse_port(port_text, url)
