        return _cmp(ver, bound) >= 0 and _cmp(ver, upper) < 0
    c = _cmp(ver, bound)
    if op == "=":
        return c == 0
    if op == ">":
        return c > 0
    if op == ">=":
        return c >= 0
    if op == "<":
        return c < 0
    if op == "<=":
        return c <= 0
    raise ValueError("invalid comparator: %r" % (op,))


