# (low, high) for each cron field: minute, hour, day-of-month, month, day-of-week
_FIELD_SPECS = (
    (0, 59),
    (0, 23),
    (1, 31),
    (1, 12),
    (0, 6),
)


def _parse_number(token):
    """Parse a strictly non-negative decimal integer token."""
    if not token or any(ch not in "0123456789" for ch in token):
        raise ValueError("invalid number in cron expression: %r" % (token,))
    return int(token)


def _parse_field(text, lo, hi):
    """Parse one cron field into the set of allowed integer values."""
    values = set()
    for item in text.split(","):
        if not item:
            raise ValueError("malformed cron item in field: %r" % (text,))
        has_step = "/" in item
        if has_step:
            base, _, step_str = item.partition("/")
            step = _parse_number(step_str)
            if step < 1:
                raise ValueError("step must be >= 1 in cron item: %r" % (item,))
        else:
            base = item
            step = 1
        if base == "*":
            start, end = lo, hi
        else:
            if "-" in base:
                a_str, _, b_str = base.partition("-")
                start = _parse_number(a_str)
                end = _parse_number(b_str)
            else:
                start = _parse_number(base)
                # 'a/n' means from a up to the field's maximum
                end = hi if has_step else start
            if not (lo <= start <= hi) or not (lo <= end <= hi):
                raise ValueError(
                    "value out of range %d-%d in cron item: %r" % (lo, hi, item))
            if end < start:
                raise ValueError("invalid range in cron item: %r" % (item,))
        values.update(range(start, end + 1, step))
    return values


