    """dt + 5 years; clamp Feb 29 to Feb 28 when needed, and cap at datetime.max."""
    y = dt.year + 5
    if y > datetime.max.year:
        return datetime.max
    try:
        return dt.replace(year=y)
    except ValueError:
        return dt.replace(year=y, day=28)


def _earliest_minute_of_day(hours, minutes, low):
    """Earliest minute-of-day value (0..1439) formed by hour/minute sets that is >= low."""
    low_val = low.hour * 60 + low.minute
    best = None
    for h in hours:
        for m in minutes:
            v = h * 60 + m
            if v >= low_val and (best is None or v < best):
                best = v
    return best


