    first_day = start.date()
    limit_date = limit.date()
    start_tod = start.time()

    dom_restricted = fields[2] != "*"
    dow_restricted = fields[4] != "*"

    for offset in range((limit_date - first_day).days + 1):
        day = first_day + timedelta(days=offset)
        if day.month not in months:
            continue
        dom_match = day.day in doms
        # Cron day-of-week: 0 = Sunday ... 6 = Saturday.
        dow_match = (day.weekday() + 1) % 7 in dows
        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        elif dom_restricted:
            day_ok = dom_match
        elif dow_restricted:
            day_ok = dow_match
        else:
            day_ok = True
        if not day_ok:
            continue
        low = start_tod if day == first_day else time(0, 0)
        v = _earliest_minute_of_day(hours, minutes, low)
        if v is None:
            continue
        if datetime(day.year, day.month, day.day) + timedelta(minutes=v) > limit:
            break  # match exists only beyond the 5-year window
        return "%04d-%02d-%02d %02d:%02d" % (
            day.year, day.month, day.day, v // 60, v % 60)

    raise ValueError("no matching time within 5 years after %s" % (after,))
