"""Tiny INI parser (Python 3.9, standard library only)."""

from typing import Dict

_COMMENT_CHARS = ";#"
_BLANK_CHARS = " \t"


def _parse_value(raw: str, line: str) -> str:
    """Interpret the text to the right of the first ``=`` of ``line``."""
    stripped = raw.strip()

    if stripped.startswith('"'):
        start = raw.index('"')
        close = raw.find('"', start + 1)
        if close < 0:
            raise ValueError("unterminated quoted value in line: %r" % (line,))
        tail = raw[close + 1:].strip()
        if tail and tail[0] not in _COMMENT_CHARS:
            raise ValueError(
                "unexpected text after quoted value in line: %r" % (line,)
            )
        return raw[start + 1:close]

    for i in range(1, len(raw)):
        if raw[i] in _COMMENT_CHARS and raw[i - 1] in _BLANK_CHARS:
            return raw[:i].strip()
    return stripped


def parse_ini(text: str) -> Dict[str, Dict[str, str]]:
    """Parse a simple INI document into ``{section: {key: value}}``.

    Keys preceding the first header land in the ``""`` section, which is
    only created when at least one such key exists.  Malformed input
    raises :class:`ValueError`.
    """
    result: Dict[str, Dict[str, str]] = {}
    section = ""

    for raw_line in text.split("\n"):
        if raw_line.endswith("\r"):
            raw_line = raw_line[:-1]

        line = raw_line.strip()
        if not line or line[0] in _COMMENT_CHARS:
            continue

        if line[0] == "[":
            close = line.find("]")
            if close < 0:
                raise ValueError("unterminated section header: %r" % (raw_line,))
            name = line[1:close].strip()
            if not name:
                raise ValueError("empty section name: %r" % (raw_line,))
            tail = line[close + 1:].strip()
            if tail and tail[0] not in _COMMENT_CHARS:
                raise ValueError(
                    "unexpected text after section header: %r" % (raw_line,)
                )
            section = name
            result.setdefault(section, {})
            continue

        eq = line.find("=")
        if eq < 0:
            raise ValueError(
                "expected 'key = value' or '[section]', got: %r" % (raw_line,)
            )
        key = line[:eq].strip()
        if not key:
            raise ValueError("empty key: %r" % (raw_line,))
        result.setdefault(section, {})[key] = _parse_value(line[eq + 1:], raw_line)

    return result
