import re

_SCHEME_RE = re.compile(r"^([A-Za-z][A-Za-z0-9+\-.]*)://")


def parse_url(url: str) -> dict:
    m = _SCHEME_RE.match(url)
    if m is None:
        raise ValueError("URL must start with a scheme followed by '://'")
    scheme = m.group(1).lower()
    rest = url[m.end():]

    # Authority: everything up to the first '/', '?' or '#' (or end).
    cut = len(rest)
    for i, ch in enumerate(rest):
        if ch in "/?#":
            cut = i
            break
    authority = rest[:cut]
    remainder = rest[cut:]

    if not authority:
        raise ValueError("empty authority")

    if "@" in authority:
        userinfo, hostport = authority.rsplit("@", 1)
    else:
        userinfo, hostport = "", authority

    host, port = _parse_host_port(hostport)

    fragment = ""
    if "#" in remainder:
        remainder, fragment = remainder.split("#", 1)
    query = ""
    if "?" in remainder:
        remainder, query = remainder.split("?", 1)
    path = remainder

    return {
        "scheme": scheme,
        "userinfo": userinfo,
        "host": host,
        "port": port,
        "path": path,
        "query": query,
        "fragment": fragment,
    }


def _parse_host_port(hostport: str):
    if hostport.startswith("["):
        close = hostport.find("]")
        if close == -1:
            raise ValueError("unterminated IPv6 literal")
        host = hostport[1:close].lower()
        if not host:
            raise ValueError("empty IPv6 literal")
        tail = hostport[close + 1:]
        if tail:
            if not tail.startswith(":"):
                raise ValueError("invalid data after IPv6 literal")
            return host, _parse_port(tail[1:])
        return host, None

    colon = hostport.find(":")
    if colon == -1:
        host_part, port_str = hostport, None
    else:
        host_part, port_str = hostport[:colon], hostport[colon + 1:]
    if not host_part:
        raise ValueError("empty host")
    forbidden = " /?#@:[]"
    for ch in host_part:
        if ch in forbidden:
            raise ValueError("invalid character in host")
    host = host_part.lower()
    if port_str is None:
        return host, None
    return host, _parse_port(port_str)


def _parse_port(port_str: str) -> int:
    if not (1 <= len(port_str) <= 5) or any(c not in "0123456789" for c in port_str):
        raise ValueError("invalid port")
    port = int(port_str)
    if not (1 <= port <= 65535):
