# identifiers), optional +build metadata (validated per SemVer 2.0, then ignored).
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
)

_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


def _parse_version(text):
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError("invalid version: %r" % (text,))
    prerelease_text = match.group(4)
    prerelease = ()
    if prerelease_text is not None:
        identifiers = prerelease_text.split(".")
        for identifier in identifiers:
            # Numeric pre-release identifiers must not have leading zeros.
            if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
                raise ValueError("invalid version: %r" % (text,))
        prerelease = tuple(identifiers)
    return _Version(int(match.group(1)), int(match.group(2)), int(match.group(3)), prerelease)


def _identifier_key(identifier):
    # Numeric identifiers compare numerically and are lower than alphanumeric
    # ones; alphanumeric identifiers compare as ASCII strings.
    if identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _version_key(version):
    # A version with a pre-release tag sorts below the same version without one
    # (flag 0 < 1). Identifier tuples compare pairwise; when one is a prefix of
    # the other, the shorter tag is lower (standard tuple comparison).
    if version.pre:
        return (
            version.major,
            version.minor,
            version.patch,
            0,
            tuple(_identifier_key(i) for i in version.pre),
        )
    return (version.major, version.minor, version.patch, 1, ())


def _parse_comparator(token):
    """Parse one comparator token into a list of (operator, version) pairs."""
    if token == "*":
        return [("*", None)]
    for op in _OPERATORS:
        if token.startswith(op):
