            if op == "^":
                if bound.major > 0:
                    high = (bound.major + 1, 0, 0)
                elif bound.minor > 0:
                    high = (0, bound.minor + 1, 0)
                else:
                    high = (0, 0, bound.patch + 1)
                return [(">=", bound), ("<", _Version(high[0], high[1], high[2], ()))]
            if op == "~":
                return [
                    (">=", bound),
                    ("<", _Version(bound.major, bound.minor + 1, 0, ())),
                ]
            return [(op, bound)]
    return [("=", _parse_version(token))]


def _parse_constraint(text):
    groups = []
    for part in text.split("||"):
        tokens = part.split()
        if not tokens:
            raise ValueError("invalid constraint: %r" % (text,))
        comparators = []
        for token in tokens:
            comparators.extend(_parse_comparator(token))
        groups.append(comparators)
    return groups


def _group_satisfies(version, comparators):
    if version.pre:
        target = (version.major, version.minor, version.patch)
        # A pre-release version may only satisfy a group if some comparator in
        # that group was written with a pre-release tag on the same M.M.P.
        if not any(
            bound is not None
            and bound.pre
            and (bound.major, bound.minor, bound.patch) == target
            for _, bound in comparators
        ):
            return False
    key = _version_key(version)
    for op, bound in comparators:
        if op == "*":
            continue
        bound_key = _version_key(bound)
        if op == "=":
            ok = key == bound_key
        elif op == ">":
            ok = key > bound_key
        elif op == ">=":
            ok = key >= bound_key
        elif op == "<":
            ok = key < bound_key
        else:  # "<="
            ok = key <= bound_key
        if not ok:
            return False
    return True


def semver_satisfies(version: str, constraint: str) -> bool:
    parsed_version = _parse_version(version)
    for comparators in _parse_constraint(constraint):
        if _group_satisfies(parsed_version, comparators):
